#include <bits/stdc++.h>

using namespace std;

const int MaxN = 300 + 30;
const int MOD = 1e9 + 7;
const long long INF = 1e18;

int n, d1, d2;

vector <pair<int, int> > badV;

bool used[MaxN * 2][MaxN * 2];

int md, k;

bool cmp(pair<int, int> a, pair<int, int> b)
{
    int p1 = (a.first + k * a.second) % md;
    int p2 = (b.first + k * b.second) % md;

    if(p1 < 0)
        p1 += md;

    if(p2 < 0)
        p2 += md;

    return p1 < p2;
}

vector <pair<int, int> > solve(vector <pair<int, int> > v)
{
    memset(used, 0, sizeof(used));

    vector <pair<int, int> > ans;

    for(auto p : v)
    {
        int i = p.first;
        int j = p.second;
        if(!used[i][j])
        {
            ans.push_back({i, j});
            for(auto x : badV)
            {
                int xx = i + x.first;
                int yy = j + x.second;

                if(xx >= 0 && xx <= n + n && yy >= 0 && yy <= n + n)
                    used[xx][yy] = true;
            }
        }
    }

    return ans;
}

