int main(){
  ios::sync_with_stdio(0); cin.tie(0);
  lli n,d1,d2; cin>>n>>d1>>d2;

  vii A1, A2;
  FORU(i,-600,600) FORU(j,-600,600) if(i*i+j*j == d1) A1.eb(i,j);
  FORU(i,-600,600) FORU(j,-600,600) if(i*i+j*j == d2) A2.eb(i,j);

  min_queue<tpl<lli,lli,lli>> Q;
  FORU(i,0,2*n-1) FORU(j,0,2*n-1) {
    Q.push(mt(i*i+j*j,i,j));
  }
  vii ans;
  while(!Q.empty()) {
    lli i,j; tie(ignore,i,j) = Q.top(); Q.pop();
    if(E[i][j]) continue;
    ans.eb(i,j);
    for(auto p : A2) {
      int x,y; tie(x,y) = p;
      x+=i; y+=j;
      if(x<0||x>=2*n) continue;
      if(y<0||y>=2*n) continue;
      E[x][y] = 1;
    }
    for(auto p : A1) {
      int x,y; tie(x,y) = p;
      x+=i; y+=j;
      if(x<0||x>=2*n) continue;
      if(y<0||y>=2*n) continue;
      E[x][y] = 1;
    }
  }
  assert((lli)ans.size() >= n*n);
  ans.resize(n*n);
  for(auto p : ans) {
    lli x,y; tie(x,y) = p;
    cout << x << " " << y << endl;
  }
  return 0;
}

