    q.push({0, 0});
    q.push({0, 2*N-1});
    q.push({2*N-1, 0});
    q.push({2*N-1, 2*N-1});
    int res = 0;
    while(!q.empty()){
        int i = q.front().first;
        int j = q.front().second;
        q.pop();
        if(!ban[i][j]){
            res++;
            if(res <= N*N) x_res[res] = i, y_res[res] = j;
            for(int k=0; k<2*N-i; k++){
                int rem1 = D1-k*k;
