		for (int it = 0; it < 10; ++it) {
			cur.clear();
			for (int i = 0; i < v.size(); ++i) {
				int me = v[i];
				bool bad = false;
				for (auto v : g[me])
					if (take[v] == in) {
						bad = true;
						break;
					}
				if (!bad) {
					take[me] = in;
					cur.push_back(me);
				}
			}
			if (mx.size() < cur.size())
				mx.swap(cur);
			random_shuffle(v.begin(), v.end());
		}
		for (auto x : mx) {
			sol.push_back({ x / C,x%C });
			if (sol.size() == n*n)
				break;
		}
		if (sol.size() == n*n)
			break;
	}
	assert(sol.size() == n*n);
	for (auto x : sol)
		printf("%d %d\n", x.first, x.second);
	return 0;
}

