void build(int d, int cs) {
    vector<II> a;
    FOR(i,-n,n)
        FOR(j,-n,n)
            if (i * i + j * j == d) a.push_back(II(i, j));
    FOR(i,0,n-1)
        FOR(j,0,n-1)
            for (II x : a) {
                int u = i + x.FI, v = j + x.SE;
                if (u >= 0 && u < n && v >= 0 && v < n) edge[cs][n * i + j].push_back(n * u + v);
