            if (i * i + j * j == d) {
                go.eb(i, j);
                go.eb(-i, j);
                go.eb(i, -j);
                go.eb(-i, -j);
            }
    forn(i, 0, n)
        forn(j, 0, n)
            if (!u[i][j]) {
                dfs(n, i, j, val, 0);
            }
}

