    if(x==1) color[s][t].first = c;
    if(x==2) color[s][t].second = c;
    for(auto&& p :v){
    	for(int i=0;i<4;i++){
    		int nx = s + dx[i]*p.first, ny = t + dy[i]*p.second;
        	if(nx<0 || nx>=2*n || ny<0 || ny>=2*n || used[nx][ny]!=-1) continue;
        	dfs1(nx,ny,3-c,x);
    	}
    }
}

void dfs2(int d,int x){
    for(int i = 0;i*i<=d;i++){
        int k = d - i*i;
        for(int j = 0;j*j<=k;j++){
            if(j*j==k){
                v.push_back({i,j});
                if(i!=j) v.push_back({j,i});
            }
        }
    }
    for(int i=0;i<2*n;i++){
        for(int j=0;j<2*n;j++){
            used[i][j] = -1;
        }
    }
    for(int i=0;i<2*n;i++){
        for(int j=0;j<2*n;j++){
            if(used[i][j]==-1) dfs1(i,j,1,x);
        }
    }
	v.clear();
}

