const int MAX = 1e3 + 5;
int cant_use[MAX][MAX];
bool used[MAX][MAX];
int n, d1, d2;
vector<int> bad[MAX];

vector<ii> state;

void roll() {
	if((int) state.size() == n * n) {
		for(auto &each : state) {
			cout << each.first << " " << each.second << '\n';
		}
		exit(0);
	}

	fori(i, 0, 2 * n) {
		fori(j, 0, 2 * n) {
			if(!used[i][j] && !cant_use[i][j]) {
				used[i][j] = true;
				fori(k, 0, 2 * n - i) {
					for(auto &each : bad[k]) {
						if(j + each >= 2 * n) {
							break;
						}
						cant_use[i + k][j + each]++;		
					}
				}
				state.emplace_back(i, j);
				roll();
				used[i][j] = false;
				fori(k, 0, 2 * n - i) {
					for(auto &each : bad[k]) {
						if(j + each >= 2 * n) {
							break;
						}
						cant_use[i + k][j + each]--;	
					}
				}
				state.pop_back();
			}
		}
	}
}

