	cin >> n >> d1 >> d2;

	fori(i, 0, 2 * n) {
		fori(j, 0, 2 * n) {
			if((i * i + j * j) == d1 || (i * i + j * j) == d2) {
				bad[i].push_back(j);
			}
		}
	}

	roll();

	return 0;
}

