int id(int a, int b) {
	return a*C + b;
}
void addEdge(int a, int b, bool w) {
	g[w][a].push_back(b);
	g[w][b].push_back(a);
}
void DFS(int u, bool color, bool w) {
	clr[w][u] = color;
	for (auto v : g[w][u])
		if (clr[w][v] == -1)
			DFS(v, !color, w);
}
int main()
{
	memset(sqr, -1, sizeof(sqr));
	for (int i = 0; i*i <= 200000; ++i)
		sqr[i*i] = i;
	cin >> n >> a >> b;
	if (a > b)
		swap(a, b);
	R = n << 1;
	C = n << 1;
	g[0].resize(R*C);
	g[1].resize(R*C);
	for (int i = 0; i < 2 * n; ++i)
		for (int j = 0; j < 2 * n; ++j) {
			for (int d = 0; d*d <= b; ++d) {
				for (int it = 0; it < 2; ++it) {
					if (d*d <= a) {
						int w = it;
						int D = a - d*d;
						if (sqr[D] != -1) {
							D = sqr[D];
							for (int dx = -1; dx <= 1; ++dx) {
								for (int it = 0; it < 2; ++it) {
									int r = i + d*dx;
									int c = j + D;
									if (r < R && c < C && r >= 0 && c >= 0)
										addEdge(id(i, j), id(r, c), w);
									swap(d, D);
								}
							}
						}
					}
					swap(a, b);
				}
			}
		}
	memset(clr, -1, sizeof(clr));
	vector<pair<int, int> > sol;
	int in = 0;
	for (int w = 0; w < 2; ++w)
		for (int i = 0; i < g[w].size(); ++i) {
			if (clr[w][i] != -1)
				continue;
			DFS(i, 0, w);
		}
	vector<int> who[4];
	for (int i = 0; i < g[0].size(); ++i)
		who[clr[0][i] * 2 + clr[1][i]].push_back(i);
	for (int i = 0; i < 4; ++i)
		if (who[i].size() >= n*n) {
			for (int j = 0; j < n*n; ++j) {
				int x = who[i][j];
				sol.push_back(make_pair(x / C, x%C));
			}
			break;
		}
	for(auto x:sol)
		for (auto y : sol) {
			int dx = x.first - y.first;
			int dy = x.second - y.second;
			if (dx*dx + dy*dy == a || dx*dx + dy*dy == b)
				assert(false);
		}
	for (auto x : sol)
		printf("%d %d\n", x.first, x.second);
	return 0;
}

#include <stdio.h>
