using namespace std;

int ban[605][605];
int x_res[100000], y_res[100000];
int vs[605][605];
vector<int> ba1, ba2;

int main(){
    int N, D1, D2;
    scanf("%d%d%d", &N, &D1, &D2);
    queue<pair<int, int>> q;
    q.push({0, 0});
    q.push({0, 2*N-1});
    q.push({2*N-1, 0});
    q.push({2*N-1, 2*N-1});
    for(int i=0; i<2*N; i++){
        int rem1 = D1-i*i;
        int sq1 = round(sqrt(rem1));
        if(sq1*sq1 == rem1) ba1.push_back(i);
        int rem2 = D2-i*i;
        int sq2 = round(sqrt(rem1));
        if(sq2*sq2 == rem2) ba2.push_back(i);
    }
    int res = 0;
    while(!q.empty()){
        int i = q.front().first;
        int j = q.front().second;
        q.pop();
        if(!ban[i][j]){
            res++;
            if(res <= N*N) x_res[res] = i, y_res[res] = j;
            for(int k : ba1){
                int sq1 = round(sqrt(D1-k*k));
                if(i+k < 2*N){
                    if(j+sq1 < 2*N) ban[i+k][j+sq1] = 1;
                    if(j-sq1 >= 0) ban[i+k][j-sq1] = 1;
                }
                if(i-k >= 0){
                    if(j+sq1 < 2*N) ban[i-k][j+sq1] = 1;
                    if(j-sq1 >= 0) ban[i-k][j-sq1] = 1;
                }
            }
            for(int k : ba2){
                int sq2 = round(sqrt(D2-k*k));
                if(i+k < 2*N){
                    if(j+sq2 < 2*N) ban[i+k][j+sq2] = 1;
                    if(j-sq2 >= 0) ban[i+k][j-sq2] = 1;
                }
                if(i+k >= 0){
                    if(j+sq2 < 2*N) ban[i-k][j+sq2] = 1;
                    if(j-sq2 >= 0) ban[i-k][j-sq2] = 1;
                }
            }
        }
        if(i+1 < 2*N && vs[i+1][j] == 0) vs[i+1][j] = 1, q.push({i+1, j});
        if(j+1 < 2*N && vs[i][j+1] == 0) vs[i][j+1] = 1, q.push({i, j+1});
        if(i-1 >= 0 && vs[i-1][j] == 0) vs[i-1][j] = 1, q.push({i-1, j});
        if(j-1 >= 0 && vs[i][j-1] == 0) vs[i][j-1] = 1, q.push({i, j-1});
    }
    if(res < N*N) return 1;
    for(int i=1; i<=N*N; i++) printf("%d %d\n", x_res[i], y_res[i]);
    return 0;
}

