int isqrt(int _number) {
  int remainder = _number;
  if (remainder < 0) { return 0; }

  int place = int(1) <<(sizeof(int)*8 - 2);

  while (place > remainder) { place /= 4; }

  int root = 0;
  while (place) {
    if (remainder >= root + place) {
      remainder -= root + place;
      root += place*2;
    }
    root /= 2;
    place /= 4;
  }
  return root;
}

vector<vector<bool> > solve(int n, int a, int b) {
  vector<pair<int, int> > forbidden;
  for (int i=0; i<=max(a, b); ++i) {
    int j = isqrt(a*a - i*i);
    if (i*i + j*j == a ||
        i*i + j*j == b) {
      forbidden.emplace_back(i, j);
    }
    j = isqrt(b*b - i*i);
    if (i*i + j*j == a ||
        i*i + j*j == b) {
      forbidden.emplace_back(i, j);
    }
  }
  sort(forbidden.begin(), forbidden.end());
  forbidden.erase(unique(forbidden.begin(), forbidden.end()), forbidden.end());

  int cnt = 0;
  vector<vector<bool> > have(2*n+1, vector<bool>(2*n+1));
  for (int i=0; i<2*n; ++i)
    for (int j=0; j<2*n; ++j) {
      for (auto& x : forbidden) {
        if (i-x.first  >= 0 &&
            j-x.second >= 0 &&
            have[i-x.first][j-x.second]) {
          // cout << "can't go " << i << ' '<<j<< " because of " << x.first << ' ' <<x.second <<endl;
          goto try_next;
        }
      }
      have[i][j] = true;
      if (++cnt == n*n)
        return have;
    try_next:;
    }
  assert(false);
  throw 0;
}

