		int A = i;
		int B = D1 - i;
		int sqA = (int) sqrt(A);
		int sqB = (int) sqrt(B);
		if (A != sqA * sqA) continue;
		if (B != sqB * sqB) continue;
		koho.insert(make_pair(sqA, sqB));
		koho.insert(make_pair(-sqA, sqB));
		koho.insert(make_pair(sqA, -sqB));
		koho.insert(make_pair(-sqA, -sqB));
	}
	for (int i = 0; i <= D2; i++) {
		int A = i;
		int B = D2 - i;
		int sqA = (int) sqrt(A);
		int sqB = (int) sqrt(B);
		if (A != sqA * sqA) continue;
		if (B != sqB * sqB) continue;
		koho.insert(make_pair(sqA, sqB));
		koho.insert(make_pair(-sqA, sqB));
		koho.insert(make_pair(sqA, -sqB));
		koho.insert(make_pair(-sqA, -sqB));
	}

	for (auto itr : koho) {
		diff_cnd.push_back(itr);
	}

	REP(i,N * N) {
		used[i / N][i % N] = true;
		ans.push_back(make_pair(i / N, i % N));
	}

	REP(i,2*N) REP(j,2*N) {
		if (!used[i][j]) {
			non_used.push_back(make_pair(i, j));
		}
	}

	REP(i,ans.size()) {
		REP(j,diff_cnd.size()) {
			int x = ans[i].first + diff_cnd[j].first;
			int y = ans[i].second + diff_cnd[j].second;
			if (x < 0 || y < 0 || x >= 2 * N || y >= 2 * N) continue;
			if (used[x][y]) score++;
		}
	}

	score /= 2;
	best_score = score;
	best_ans = ans;

	simulated_annealing();

	REP(i,best_ans.size()) {
		cout << best_ans[i].first << " " << best_ans[i].second << endl;
	}

	return 0;
}

