bool sq(LL x)
{
    LL y=sqrt(x);
    if(y*y==x)return 1;
    return 0;
}

bool mark[605][605];

vector<PLL>ans;

void solve(int p,int q)
{
    memset(mark,0,sizeof mark);
    while(ans.size()>0)ans.pop_back();
    ans.clear();
    int cnt=0,x,y;
    for(int i=q;i<2*n;i++)
    {
        int j=0;
        if(i==q)j=p;
        for(;j<2*n;j++)
        {
            if(!mark[i][j])
            {
                ans.push_back(make_pair(i,j));
                cnt++;
                if(cnt==n*n)return;
                for(int k=0;k<vec.size();k++)
                {
                    x=i+vec[k].first;
                    y=j+vec[k].second;
                    if(x>=2*n || y>=2*n || y<0)continue;
                    mark[x][y]=1;
                }
            }
        }
    }
}

