				add_edge(i,j,i+x.F,j+x.S);
				add_edge(i,j,i+x.F,j-x.S);
				add_edge(i,j,i-x.F,j+x.S);
				add_edge(i,j,i-x.F,j-x.S);
			}
	fo(i,0,cnt)
	{
		deg[i] = sz(v[i]);
		pq.push({-deg[i],i});
	}
	while(!pq.empty())
	{
		a = pq.top().S;
		pq.pop();
		if(vis[a])
			continue;
		ans.pb(val[a]);
		vis[a] = 1;
		for(auto x : v[a])
		{
			if(!vis[x])
				for(auto y : v[x])
				{
					deg[y]--;
					pq.push({-deg[y],y});
				}
			vis[x] = 1;
		}
	}
	assert(sz(ans) >= n*n);
	fo(i,0,n*n)
		cout << ans[i].F << " " << ans[i].S << '\n';
	return;
}

