set<pii> bans;

void solve(int d) {
    for (int i = 0; i*i <= d; i++) {
        int tmp = sqrt(d - i*i);
        if (tmp*tmp + i*i == d) {
            bans.insert({min(tmp, i), max(tmp, i)});
        }
    }
}
void change(int a, int b, int n) {
    if (a < 0 || a >= n) return;
    if (b < 0 || b >= n) return;
    assert(mat[a][b] != 1);
    mat[a][b] = -1;
}





