int mySqrt(int x) {
    if (x < 0) return -1;
    int y = sqrt(x);
    while (y * y < x) y++;
    while (y * y > x) y--;
    if (y * y != x) return -1;
    return y;
}

vector<pair<int, int>> solve(int n, int d1, int d2) {
    vector<pair<int, int>> v;
    for (int i = -n * 2; i <= n * 2; i++) {
        int j = mySqrt(d1 - i * i);
        if (j != -1) {
            v.push_back({i, j});
            if (j != 0) v.push_back({i, -j});
        }

        j = mySqrt(d2 - i * i);
        if (j != -1) {
            v.push_back({i, j});
            if (j != 0) v.push_back({i, -j});
        }
    }
    sort(v.begin(), v.end());

    vector<pair<int, int>> p;
    for (int i = 0; i < n * 2; i++) for (int j = 0; j < n * 2; j++) p.push_back({i, j});
    while (1) {
        vector<vector<char>> taken(n * 2, vector<char>(n * 2));
        vector<pair<int, int>> ans;
        for (auto o : p) {
            bool ok = 1;
            for (auto d : v) {
                int x = o.first + d.first;
                int y = o.second + d.second;
                if (0 <= x && x < 2 * n && 0 <= y && y < 2 * n) {
                    if (taken[x][y]) {
                        ok = 0;
                        break;
                    }
                }
            }
            if (ok) {
                taken[o.first][o.second] = 1;
                ans.push_back(o);
            }
        }
        if (ans.size() >= n * n) {
            ans.resize(n * n);
            return ans;
        }
        random_shuffle(p.begin(), p.end());
    }
}

