const int N=600;/// 2 * 300

int n,d[3];

struct point
{
    int r,c;
};
vector<point>v[3][N+5][N+5];
int col[3][N+5][N+5];

vector<point>nu[3];

void build_nu()
{
    for(int k=1;k<=2;k++)
        for(int i=0;i<2*n;i++)
            for(int j=0;j<2*n;j++)
            {
                int sum=i*i+j*j;
                if(sum==d[k])
                    nu[k].push_back({i,j});
            }
}

bool valid(int r,int c)
{
    if(0<=r && 0<=c && r<2*n && c<2*n)
        return 1;
    return 0;
}

void build_graf()
{
    for(int k=1;k<=2;k++)
        for(int i=0;i<2*n;i++)
            for(int j=0;j<2*n;j++)
            {
                for(int who=0;who<nu[k].size();who++)
                {
                    int x=nu[k][who].r;
                    int y=nu[k][who].c;
                    if(valid(i-x,j-y)==1)
                        v[k][i][j].push_back({i-x,j-y});
                    if(valid(i-x,j+y)==1)
                        v[k][i][j].push_back({i-x,j+y});
                    if(valid(i+x,j-y)==1)
                        v[k][i][j].push_back({i+x,j-y});
                    if(valid(i+x,j+y)==1)
                        v[k][i][j].push_back({i+x,j+y});
                }
            }
}

void dfs(int k,int r,int c)
{
    for(auto nou:v[k][r][c])
    {
        int rn=nou.r;
        int cn=nou.c;
        if(col[k][rn][cn]==0)
        {
            col[k][rn][cn]=3-col[k][r][c];
            dfs(k,rn,cn);
        }
    }
}

int cnt[3][3];

