    for(int k=1;k<=2;k++)
        for(int i=0;i<2*n;i++)
            for(int j=0;j<2*n;j++)
            {
                if(col[k][i][j]==0)
                {
                    col[k][i][j]=1;
                    dfs(k,i,j);
                }
            }
    for(int i=0;i<2*n;i++)
        for(int j=0;j<2*n;j++)
        {
            cnt[col[1][i][j]][col[2][i][j]]++;
        }
    for(int i=1;i<=2;i++)
