int col[605][605];

void Solve(int n, int k) {
  int t = 0;
  while (!(k % 4)) k >>= 2, ++t;
  for (RI i = 0; i < 2 * n; ++i)
    for (RI j = 0; j < 2 * n; ++j) {
      if (k % 4 == 1) {
        if (((i >> t) + (j >> t)) & 1)
          col[i][j] = 1;
      }
      else
        if ((i >> t) & 1)
          col[i][j] = 1;
    }
  // if t % 2 == 0 then t^2 % 4 = 0
  // if t % 2 == 1 then t^2 % 4 = 1
  // so if k = a^2 + b^2 then k % 4 != 3
}

