void solve() {
  int n, a, b; cin >> n >> a >> b;

  int two = 1;
  while (a % 4 == 0 && b % 4 == 0) {
    a /= 4, b /= 4;
    two *= 2;
  }

  if (b % 4 == 0) swap(a, b);

  int cnt = n * n;

  if (a % 4) {
    for (int x = 0; x < 2*n; x += two * 2) {
      rep(i,two) {
        if (x + i >= 2*n) break;
        for (int y = 0; y < 2*n; y += two * 2) {
          rep(j,two) {
            if (y + j >= 2*n) break;
            cout << pii(x + i, y + j) << '\n';
            if (--cnt == 0) return;
          }
        }
      }
    }
  }

  int dual = two;
  while (a % 4 == 0) {
    a /= 4;
    dual *= 2;
  }

  int d = a % 4 == 1 ? dual : 0;
  int t = b % 4 == 1 ? two : 0;

  rep(p,2) {
    rep(q,2) {
      for (int x = p * dual; x < 2*n; x += dual * 2) {
        for (int u = q * two; u < dual; u += two * 2) {
          if (x + u >= 2*n) break;
          rep(i,two) {
            if (x + u + i >= 2*n) break;
            for (int y = p * d; y < 2*n; y += dual * 2) {
              for (int v = q * t; v < dual; v += two * 2) {
                if (y + v >= 2*n) break;
                rep(j,two) {
                  if (y + v + j >= 2*n) break;
                  cout << pii(x + u + i, y + v + j) << '\n';
                  if (--cnt == 0) return;
                }
              }
            }
          }
        }
      }
    }
  }
}


