int sz = 0;
void build(int n, int d, vector<int> adj[]) {
    vector<pair<int, int>> v;

    for (int dx=0; dx*dx <= d; dx++) {
        int dy = sqrt(d-dx*dx);
        if (dx*dx+dy*dy != d)   continue;

        v.emplace_back(dx, dy);
        if (dx) v.emplace_back(-dx, dy);
        if (dy) v.emplace_back(dx, -dy);
        if (dx && dy) v.emplace_back(dx, dy);
    }

    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            for (auto pr: v) {
                int nx = i+pr.first;
                int ny = j+pr.second;
                if (0<=nx && nx<n && 0<=ny && ny<n) {
                    adj[i*n+j].push_back(nx*n+ny);
                    sz++;
                }
            }
        }
    }
}

