    if (!bad[u])    cnt[col[u]]++;
    for (int v: adj[u]) {
        if (col[v] == -1)   {
            col[v] = !col[u];
            dfs(v, adj);
        }
    }
}

void bicolor(int n, vector<int> adj[]) {
    memset(col, -1, sizeof col);
    cnt[0] = cnt[1] = 0;

    for (int i=0; i<n*n; i++)
        if (col[i] == -1) {
            col[i] = 0;
            dfs(i, adj);
        }

    bool big = cnt[1] > cnt[0];
    for (int i=0; i<n*n; i++)
        if (col[i] != big)
            bad[i] = 1;
}

