queue < pair <int, int> > q;

vector < pair <int, int> > Dir;

void prework(int D) {
  for(int i = 0; i < n * 2; ++ i) {
	for(int j = 0; j < n * 2; ++ j) {
	  if(i * i + j * j == D) {
		Dir.push_back(make_pair(i, j));
		Dir.push_back(make_pair(-i, j));
		Dir.push_back(make_pair(i, -j));
		Dir.push_back(make_pair(-i, -j));
	  }
	}
  }
}

void solve(int x, int y, int A[N][N]) {
  q.push(make_pair(x, y));
  vis[x][y] = 1;
  A[x][y] = 0;
  while(!q.empty()) {
	pair <int, int> ind = q.front();
	q.pop();
	for(int i = 0; i < (int) Dir.size(); ++ i) {
	  int nx = ind.first + Dir[i].first, ny = ind.second + Dir[i].second;
	  if(nx < 0 || ny < 0 || nx >= 2 * n || ny >= 2 * n) continue;
	  if(vis[nx][ny]) continue;
	  vis[nx][ny] = 1;
	  A[nx][ny] = A[ind.first][ind.second] ^ 1;
	  q.push(make_pair(nx, ny));
	}
  }
}

void solve(int D, int A[N][N]) {
  memset(A, 0, sizeof(A));
  Dir.clear();
  prework(D);
  memset(vis, 0, sizeof(vis));
  for(int i = 0; i < 2 * n; ++ i) {
	for(int j = 0; j < 2 * n; ++ j) {
	  if(!vis[i][j]) {
		solve(i, j, A);
	  }
	}
  }
}

