void Dfs(int x, int y, int D, int C[maxn][maxn]) {
  for (int dx = 0; dx * dx <= D; ++dx) {
    int tmp = D - dx * dx;
    int dy = (int)round(sqrt(tmp));
    if (dy * dy + dx * dx == D) {
      for (int sx = -1; sx <= 1; sx += 2) {
        for (int sy = -1; sy <= 1; sy += 2) {
          int x2 = x + dx * sx, y2 = y + dy * sy;
          if (x2 >= 0 && x2 < N && y2 >= 0 && y2 < N) {
            if (C[x2][y2] == -1) {
              C[x2][y2] = !C[x][y];
              Dfs(x2, y2, D, C);
            }
          }
        }
      }
    }
  }
}

void Color(int D, int C[maxn][maxn]) {
  for (int x = 0; x < N; ++x) {
    for (int y = 0; y < N; ++y) {
      if (C[x][y] == -1) {
        C[x][y] = 0;
        Dfs(x, y, D, C);
      }
    }
  }
}

