void solve(int x, int y)
{
    if(x < 0 || x >= n + n || y < 0 || y >= n + n || used[x][y] == 2)
        return;

    queue <pair<int, int> > bfs;

    bfs.push({x, y});

    used[x][y] = 1;

    while(!bfs.empty())
    {
        int x = bfs.front().first;
        int y = bfs.front().second;
        bfs.pop();

        if(used[x][y] == 1)
        {
            ans.push_back({x, y});
            for(auto p : badV)
            {
                int xx = x + p.first;
                int yy = y + p.second;
                if(xx >= 0 && xx < n + n && yy >= 0 && yy < n + n)
                {
                    if(!used[xx][yy])
                        bfs.push({xx, yy});
                    used[xx][yy] = 2;
                }
            }

        }else
        {
            for(auto p : badV)
            {
                int xx = x + p.first;
                int yy = y + p.second;
                if(xx >= 0 && xx < n + n && yy >= 0 && yy < n + n)
                {
                    if(!used[xx][yy])
                    {
                        bfs.push({xx, yy});
                        used[xx][yy] = 1;
                    }
                }
            }
        }
        used[x][y] = 2;
    }
}

