#include <bits/stdc++.h>
using namespace std;

int N, D1, D2;
using P = pair<int, int>;

void dfs(int i, int j, vector<P> NG, vector<vector<int> >& color)
{
    queue<P> list;
    list.push(make_pair(i*(2*N)+j, color[i][j]));
    while (!list.empty())
    {
        P p = list.front();
        list.pop();
        for (auto ng : NG)
        {
            int x = p.first / (2*N) + ng.first;
            int y = p.first % (2*N) + ng.second;
            if (x < 0 || x >= 2*N || y < 0 || y >= 2*N) continue;
            if (color[x][y] < 0)
            {
                color[x][y] = 1 - p.second;
                list.push(make_pair(x*(2*N)+y, color[x][y]));
            }
        }
    }
    return;
}

int main()
{
    cin >> N >> D1 >> D2;

    vector<P> NG1, NG2;
    for (int i = 0; i < 2 * N; i++)
    {
        int e1 = sqrt(D1 - i * i);
        if (e1 * e1 + i * i == D1)
        {
            NG1.push_back(make_pair(i, e1));
            NG1.push_back(make_pair(i, -e1));
            NG1.push_back(make_pair(-i, e1));
            NG1.push_back(make_pair(-i, -e1));
        }
        int e2= sqrt(D2 - i * i);
        if (e2 * e2 + i * i == D2)
        {
            NG2.push_back(make_pair(i, e2));
            NG2.push_back(make_pair(i, -e2));
            NG2.push_back(make_pair(-i, e2));
            NG2.push_back(make_pair(-i, -e2));
        }
    }
    vector<vector<int> >color1(2 * N, vector<int>(2 * N, -1));
    vector<vector<int> >color2(2 * N, vector<int>(2 * N, -1));

    for (int i = 0; i < 2 * N; i++)
    {
        for (int j = 0; j < 2 * N; j++)
        {
            if (color1[i][j] == -1)
            {
                color1[i][j] = 0;
                dfs(i, j, NG1, color1);
            }
            if (color2[i][j] == -1)
            {
                color2[i][j] = 0;
                dfs(i, j, NG2, color2);
            }
        }
    }

    int count1 = 0;
    int count2 = 0;
    for (int i=0; i<2*N; i++)
    {
        for (int j=0; j<2*N; j++)
        {
            if (color1[i][j] == 1) count1++;
            if (color2[i][j] == 1) count2++;
        }
    }
    int pick1 = (count1>=2*N*N) ? 1 : 0;
    int pick2 = (count2>=2*N*N) ? 1 : 0;

    int points = 0;
    for (int i=0; i<2*N; i++)
    {
        for (int j=0; j<2*N; j++)
        {
            if (color1[i][j] == pick1 && color2[i][j] == pick2)
            {
                cout << i << " " << j << endl;
                // cout << color1[i][j] << " " << color2[i][j] << endl;
                points++;
                if (points == N*N) return 0;
            }
        }
    }
    return 0;
}

