    auto isOutOfRange = [](int h, int w, int H, int W) {
        return h < 0 || h >= H || w < 0 || w >= W;
    };
    rep(y, 2 * MAX_N) rep(x, 2 * MAX_N) {
        used[y][x] = false;
    }
    vector<P> v;
    int x = 0, y = 0, dir = 0;
    rep(_, 2 * n * n) {
        v.push_back({y, x});
        used[y][x] = true;
        int nx = x + dx[dir];
        int ny = y + dy[dir];
        if (isOutOfRange(ny, nx, 2 * n, 2 * n) || used[ny][nx]) {
            dir++;
            dir %= 4;
            nx = x + dx[dir];
            ny = y + dy[dir];
        }
        x = nx;
