void construct(int n, int d1, int dep) {

	if (d1 % 4 != 0) {
		for (int i = 0; i < 2 * n; i++)
			for (int j = 0; j < 2 * n; j++)
				if ((i + j) % 2 == 0)
					d[dep][i][j] = 1;
				else
					d[dep][i][j] = 0;
	}else {
		construct(n, d1 / 4, dep + 1);
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				for (int k = 0; k <= 1; k++)
					for (int  p = 0; p <= 1; p++)
						d[dep][i * 2 + k][j * 2 + p] = d[dep + 1][i][j];
	}
}

int dis(pair <int, int> x, pair <int, int> y) {
	return (x.first - y.first) * (x.first - y.first) + (x.second - y.second) * (x.second - y.second);
}

