bool oor(ll n,ll i,ll j) {
	return !(0 <= i && i < n * 2 && 0 <= j && j < n * 2);
}

void drw(ll n, ll k, ll si, ll sj) {
	stack<ll> sti, stj, col;
	sti.push(si);
	stj.push(sj);
	color[si][sj][k] = 0;
	while (!sti.empty()) {
		ll curi = sti.top();
		ll curj = stj.top();
		ll nexcol = (color[curi][curj][k] + 1) % 2;
		sti.pop(); stj.pop(); 
		REP(iii, 0, SIZE(vi[k])-1) {
			ll nexi = curi + vi[k][iii];
			ll nexj = curj + vj[k][iii];
			if (oor(n, nexi, nexj)) { continue; }
			if (color[nexi][nexj][k] == -1) {
				color[nexi][nexj][k] = nexcol;
				sti.push(nexi);
				stj.push(nexj);
			}
		}
	}
}

void f(ll n, ll d, ll k) {
	REP(i, -n * 2, n * 2) {
		REP(j, -n * 2, n * 2) {
			if (i*i + j * j == d) {
				vi[k].push_back(i);
				vj[k].push_back(j);
			}
		}
	}
	REP(i, 0, 2 * n - 1) {
		REP(j, 0, 2 * n - 1) {
			color[i][j][k] = -1;
		}
	}

	REP(i, 0, 2 * n - 1) {
		REP(j, 0, 2 * n - 1) {
			if (color[i][j][k] == -1) {
				drw(n, k, i, j);
			}
		}
	}
}

void prnt(ll n,ll ii,ll jj) {
	ll cnt = 0;
	REP(i, 0, 2 * n - 1) {
		REP(j, 0, 2 * n - 1) {
			if (color[i][j][0] == ii && color[i][j][1] == jj) {
				cout << i << " " << j << endl;
				cnt++;
				if (cnt == n * n) {
					return;
				}
			}
		}
	}
}

