struct point_t {
  int y, x;
};

vector<point_t> solve_half(int n, int d) {
  int r = d % 4;
  vector<point_t> result;
  if (r == 2 || r == 3 || d == 0) {
    for (int y = 0; y < n; ++y)
      for (int x = 0; x < n; x += 2)
        result.push_back({y, x});
  } else if (r == 1) {
    for (int y = 0; y < n; ++y)
      for (int x = y % 2; x < n; x += 2)
        result.push_back({y, x});
  } else {
    for (const point_t &p : solve_half((n + 1) / 2, d / 4))
      for (int dy = 0; dy <= 1; ++dy)
        for (int dx = 0; dx <= 1; ++dx) {
          int y2 = 2 * p.y + dy, x2 = 2 * p.x + dx;
          if (max(y2, x2) < n)
            result.push_back({y2, x2});
        }
  }
  assert((int)result.size() >= (n * n + 1) / 2);
  result.resize((n * n + 1) / 2);
  return result;
}

vector<point_t> solve_quarter(int n, int d1, int d2) {
  int r1 = d1 % 4, r2 = d2 % 4;
  if (r1 > r2) return solve_quarter(n, d2, d1);

  vector<point_t> result;
  if (r1 >= 1 || (d1 == 0 && d2 == 0)) {
    for (int y = 0; y < n; y += 2)
      for (int x = 0; x < n; x += 2)
        result.push_back({y, x});
  } else if (r2 == 3) {
    return solve_quarter(n, d1, d1);
  } else if (r2 == 2) {
    for (point_t p : solve_half((n + 1) / 2, d1 / 4)) {
      result.push_back({2 * p.y, 2 * p.x});
      if (2 * p.y + 1 < n)
        result.push_back({2 * p.y + 1, 2 * p.x});
    }
  } else if (r2 == 1) {
    for (point_t p : solve_half((n + 1) / 2, d1 / 4)) {
      result.push_back({2 * p.y, 2 * p.x});
      if (2 * max(p.y, p.x) + 1 < n)
        result.push_back({2 * p.y + 1, 2 * p.x + 1});
    }
  } else {
    for (point_t p : solve_quarter((n + 1) / 2, d1 / 4, d2 / 4))
      for (int dy = 0; dy <= 1; ++dy)
        for (int dx = 0; dx <= 1; ++dx) {
          int y2 = 2 * p.y + dy, x2 = 2 * p.x + dx;
          if (max(y2, x2) < n)
            result.push_back({y2, x2});
        }
  }
  assert((int)result.size() >= (n * n + 3) / 4);
  result.resize((n * n + 3) / 4);
  return result;
}

int main() {
  int n, d1, d2;
  scanf("%d %d %d", &n, &d1, &d2);
  n *= 2;
  for (const point_t &p : solve_quarter(n, d1, d2)) {
    printf("%d %d\n", p.y, p.x);
  }
  return 0;
}

