bool isInField(int x, int y){
    return x >= 0 && x <= 2*N && y >= 0 && y <= 2*N;
}

void dfs1(P p, int c){
    int x = p.first, y = p.second;
    // cout << x << ' ' << y << ' ' << c << endl;
    used1[x][y] = true;
    col1[x][y] = c;
    for(int i = 0; i < G1[x][y].size(); i++){
        int s = G1[x][y][i].first;
        int t = G1[x][y][i].second;
        if(!used1[s][t]) dfs1(P(s, t), c^1);
    }
}

void dfs2(P p, int c){
