int n;
#define MAXN (610)
bool vis[MAXN][MAXN]={};
bool inside(int i,int j) {return 0<=i&&i<2*n&&0<=j&&j<2*n;}
bool ok(int i,int j) {
	for(pi p:v) {
		int ni=i-p.fi,nj=j-p.se;
		if(inside(ni,nj)&& vis[ni][nj]) return 0;
		ni=i-p.fi,nj=j+p.se;
		if(inside(ni,nj)&& vis[ni][nj]) return 0;
		ni=i+p.fi,nj=j-p.se;
		if(inside(ni,nj)&& vis[ni][nj]) return 0;
	}
	return 1;
}
