int n,m,d1,d2,cnt,vis[305][305];

void solve(int d){
	int tim=0; while(d%4==0) d/=4,++tim;
	if(d&1){
		for(int i=0;i<m;++i) for(int j=0;j<m;++j){
			if(((i>>tim)+(j>>tim))&1) vis[i][j]=1;
		}
	}
	else{
		for(int i=0;i<m;++i) for(int j=0;j<m;++j){
			if((i>>tim)&1) vis[i][j]=1;
		}
	}
}

