	REP(l,0,1) REP(i,0,2*n-1) REP(j,0,2*n-1) co[l][i][j]=-1;
	REP(i,1,2*n-1) REP(j,0,2*n-1) if(co[0][i][j]==-1) co[0][i][j]=0,dfs(i,j,0);
	tmp=0;
	for(int i=0;i*i<=d2;++i){
		int j=sqrt(d2-i*i);
		while(j*j+i*i>d2) --j;
		while(j*j+i*i<d2) ++j;
		if(i*i+j*j!=d2) continue;
		li[++tmp]=(point){i,j};
		li[++tmp]=(point){-i,j};
		li[++tmp]=(point){i,-j};
		li[++tmp]=(point){-i,-j};
	}
	REP(i,0,2*n-1) REP(j,0,2*n-1) if(co[1][i][j]==-1) co[1][i][j]=0,dfs(i,j,1);
	REP(u,0,1) REP(v,0,1){
		int sum=0;
		REP(i,0,2*n-1) REP(j,0,2*n-1) if(co[0][i][j]==u && co[1][i][j]==v) ++sum;
		if(sum>=n*n){
			sum=n*n;
			REP(i,0,2*n-1) REP(j,0,2*n-1) if(co[0][i][j]==u && co[1][i][j]==v){
				printf("%d %d\n",i,j);
				--sum;
				if(!sum) return 0;
			}
		}
	}
	return 0;
}

