typedef long long li;

const li mod = 1e9 + 7;

li cnt(li d) {
    li ret = 0;
    while (d % 2 == 0) {
        ret++;
        d /= 2;
    }
    return ret;
}

bool ok(li x, li y, li c) {
    li par = c % 2;
    li unit = 1LL << (c / 2);

    li target = par ? x : (x + y);
    return target % (unit * 2) < unit;
}

int main() {
    li n, d1, d2;
    cin >> n >> d1 >> d2;

    li c1 = cnt(d1), c2 = cnt(d2);

