        for (int j = 0; j < 2 * n; ++j) {
            if (cnt >= n * n) {
                continue;
            }
            if (ok(i, j, c1) && ok(i, j, c2)) {
                cout << i << " " << j << endl;
                cnt++;
            }
        }
    }
    return 0;
}

