inline int solve()
{
	cnt=0; memset(sign,0,sizeof sign);
	for(int i=0;i<2*n;i++) for(int j=0;j<2*n;j++) if(!sign[x[i]][y[j]])
	{
		++cnt; Ans[cnt]=make_pair(x[i],y[j]);
		if(cnt==n*n) return cnt;
		for(int t=0;t<V1.size();t++) for(int k=0;k<4;k++)
		{
			int vx=dir[k][0]*V1[t].first+x[i];
			int vy=dir[k][1]*V1[t].second+y[j];
			if(vx<0||vy<0||vx>2*n||vy>2*n) continue;
			sign[vx][vy]=1;
		}
		for(int t=0;t<V2.size();t++) for(int k=0;k<4;k++)
		{
			int vx=dir[k][0]*V2[t].first+x[i];
			int vy=dir[k][1]*V2[t].second+y[j];
			if(vx<0||vy<0||vx>2*n||vy>2*n) continue;
			sign[vx][vy]=1;
		}
	}	
	return cnt;
}
