    vector<pair<int,int> > P[2];
    rep(j,2){
        int D = d[j];
        rep(i,2*n){
            if(i*i>D)break;
            int s = D - (i*i);
            rep(k,2*n){
                if(k*k==s){
                    P[j].push_back(MP(i,k));
                    P[j].push_back(MP(i,-k));
                    P[j].push_back(MP(-i,k));
                    P[j].push_back(MP(-i,-k));
                }
                if(k*k>s)break;
            }
        }
    }
    rep(k,2){
        vector<bool> flag(2*n*2*n);
        rep(i,2*n){
            rep(j,2*n){
                if(flag[id_calc(i,j)])continue;
                flag[id_calc(i,j)] = true;
                queue<pair<int,int> >q;
                q.push(MP(i,j));
                c[id_calc(i,j)][k] = 1;
                while(!q.empty()){
                    auto y = q.front();
                    q.pop();
                    flag[id_calc(y.first,y.second)] = true;
                    for(auto x:P[k]){
                        int nxt = id_calc(y.first+x.first,y.second+x.second);
                        if(nxt==-1)continue;
                        if(flag[nxt])continue;
                        c[nxt][k] = 3 - c[id_calc(y.first,y.second)][k];
                        q.push(MP(y.first+x.first,y.second+x.second));
                    }
                }
            }
        }
