const int N = 310;

typedef pair<int, int> P;
typedef long long LL;

int G[2][N * 2][N * 2], n;

vector<P> dir;

void dfs(int x, int y, int t) {
    for (auto v : dir) {
        int tx = x + v.first, ty = y + v.second;
        if (tx > n * 2 || ty > n * 2 || tx < 1 || ty < 1 || G[t][tx][ty]) continue;
        G[t][tx][ty] = 3 - G[t][x][y], dfs(tx, ty, t);
    }
}

void Just_DOIT(int t, int d) {
    dir.clear();
    for (int i = 0; i < 2 * n; i++)
        for (int j = 0; j < 2 * n; j++)
            if ((LL)i * i + (LL)j * j == (LL)d * d) 
                for (int t = 0; t < 4; t++) 
                    dir.push_back(P(t & 1 ? i : -i, t & 2 ? j : -j));
    for (int i = 1; i <= n * 2; i++)
        for (int j = 1; j <= n * 2; j++) if (!G[t][i][j]) 
            G[t][i][j] = 1, dfs(i, j, t);
}

