        dy=sqrt(d*d-dx*dx);
        if(dy!=(int)dy)
            continue;
        nextcolumn=c+dy;
        if(nextcolumn<2*n)
            if(a[i][nextcolumn])
            {
                nr--;
                a[i][nextcolumn]=0;
            }
        nextcolumn=c-dy;
        if(nextcolumn>=0)
            if(a[i][nextcolumn])
            {
                nr--;
                a[i][nextcolumn]=0;
            }
    }
}
