vector<pii> solve(int d) {
	vector<pii> ans;
	for (int i = 0; i <= int(sqrt(d)); i++) {
		int j = int(sqrt(d - i * i));
		if (i * i + j * j == d) {
			ans.push_back({ i, j });
		}
	}
	return ans;
}

