const int MAXN=605;

int n,d1,d2,m;
int dx[MAXN*8],dy[MAXN*8];
bool c[MAXN][MAXN];
int a[MAXN][MAXN],cnt=0;
pii q[MAXN*MAXN];
bool vis[MAXN][MAXN];
void work(int d)
{
	for(int i=-n;i<=n;++i)
		for(int j=-n;j<=n;++j)
			if(i*i+j*j==d)
				dx[++m]=i,dy[m]=j;
}
void bfs()
{
	int front=1,rear=0;
	q[++rear]=mp(n/2,n/2);
	vis[n/2][n/2]=1;
	while(front<=rear)
	{
		pii p=q[front++];
		for(int i=1;i<=m;++i)
			if(p.x+dx[i]>=0 && p.x+dx[i]<n && p.y+dy[i]>=0 && p.y+dy[i]<n && !vis[p.x+dx[i]][p.y+dy[i]])
			{
				vis[p.x+dx[i]][p.y+dy[i]]=1;
				q[++rear]=mp(p.x+dx[i],p.y+dy[i]);
			}
	}
}
void dfs(int k)
{
	int x=q[k].x,y=q[k].y;
	if(cnt*4==n*n)
	{
		for(int i=0;i<n;++i)
			for(int j=0;j<n;++j)
				if(c[i][j])printf("%d %d\n",i,j);
		exit(0);
	}
	if(k>n*n)return;
	if(a[x][y])return dfs(k+1);
	for(int i=1;i<=m;++i)
		if(x+dx[i]>=0 && x+dx[i]<n && y+dy[i]>=0 && y+dy[i]<n)
			++a[x+dx[i]][y+dy[i]];
	c[x][y]=1;
	++cnt;
	dfs(k+1);
	for(int i=1;i<=m;++i)
		if(x+dx[i]>=0 && x+dx[i]<n && y+dy[i]>=0 && y+dy[i]<n)
			--a[x+dx[i]][y+dy[i]];
	c[x][y]=0;
	--cnt;
	dfs(k+1);
}

