int board[610][610], N;
void coor_insert(vector<int> &X, vector<int> &Y, int D) {
    for(int r=-D; r<=D; r++) {
        if(r*r > D) continue;
        int rest = D - r*r;
        int tmp = sqrt(rest), c = -INF;
        for(int k=tmp-1; k<=tmp+1; k++) {
            if(k*k == rest) {
                c = k;
                break;
            }
        }

        if(c == -INF) continue;

        // r, c が決定した
        X.push_back(r);
        Y.push_back(c);

        if(c != 0) {
            X.push_back(r);
            Y.push_back(-c);
        }
    }
}

void paint_board(vector<int> &X, vector<int> &Y, int r, int c) {
    int M = X.size();

    for(int i=0; i<M; i++) {
        int nr = r + X[i], nc = c + Y[i];
        if(nr < 0 || nr >= 2*N || nc < 0 || nc >= 2*N) continue;
        board[nr][nc] = 1;
    }
}

signed main() {
    int D1, D2; cin >> N >> D1 >> D2;
    vector<int> X, Y;
    coor_insert(X, Y, D1);
    coor_insert(X, Y, D2);

    vector<int> ans_X, ans_Y;
    for(int i=0; i<2*N; i++) {
        for(int j=0; j<2*N; j++) {
            if(board[i][j] == 1 || ans_X.size() == N*N) continue;
            // printf("valid: %lld, %lld\n", i, j);
            ans_X.push_back(i);
            ans_Y.push_back(j);
            paint_board(X, Y, i, j);
        }
    }

    assert(ans_X.size() == N*N);
    for(int i=0; i<N*N; i++) {
        printf("%lld %lld\n", ans_X[i], ans_Y[i]);
    }
    return 0;
}

