random_device rd;
mt19937 mt(rd());

long long n, sq[N], d1, d2;
vector <pair <int, int>> v, ans;
bool is[N], in[2 * M][2 * M];

bool valid (int x) {
    if (x >= 0 && x < 2 * n)
        return true;
    return false;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
    cin >> n >> d1 >> d2;
    for (int i = 0; i * i < N; i++)
        is[i * i] = true, sq[i * i] = i;
    for (int i = 0; i <= d1; i++) {
        if (is[i] && is[d1 - i]) {
            v.push_back ({sq[i], sq[d1 - i]});
            v.push_back ({sq[i], -sq[d1 - i]});
            v.push_back ({-sq[i], sq[d1 - i]});
            v.push_back ({-sq[i], -sq[d1 - i]});
        }
    }
    for (int i = 0; i <= d2; i++) {
        if (is[i] && is[d2 - i]) {
            v.push_back ({sq[i], sq[d2 - i]});
            v.push_back ({-sq[i], sq[d2 - i]});
            v.push_back ({sq[i], -sq[d2 - i]});
            v.push_back ({-sq[i], -sq[d2 - i]});
        }
    }
    while ((int)ans.size() != (n * n)) {
        int i = mt() % (2 * n);
        int j = mt() % (2 * n);
        if (i < 0)
            i = -i;
        if (j < 0)
            j = -j;
        if (in[i][j])
            continue;
        bool can = true;
        for (auto k : v) {
            if (valid (i + k.first) && valid (j + k.second) && in[i + k.first][j + k.second])
            can = false;
            if (!can)
                break;
        }
        if (can) {
            ans.push_back ({i, j});
            in[i][j] = true;
        }
    }
    for (int i = 0; i < n * n; i++)
        cout << ans[i].first << ' ' << ans[i].second << '\n';
    return 0;
}

