#define makr(x,y) make_pair(x,y)

const int N=666;

int n,m,d1,d2;

bool mp[N][N];

void check(int x,int y,int d)
{
	int b=-2*y,c,t,t2;
	for(int i=0;i<=m;++i)
	{
		c=y*y-d-2*i*x+i*i+x*x;
		t=b*b-4*c;
		if(t<0)
			continue;
		t2=sqrt(t);
		if(t2*t2!=t)
			continue;
		t=-b+t2;
		if(0<=t&&!(t&1)&&(t>>=1)<=m)
			mp[i][t]=false;
		t=-b-t2;
		if(0<=t&&!(t&1)&&(t>>=1)<=m)
			mp[i][t]=false;
	}
}

vector<pii> v,res;

signed main()
{
	scanf("%lld%lld%lld",&n,&d1,&d2);
	m=(n<<1)-1;
	for(int i=0;i<=m;++i)
		for(int j=0;j<=m;++j)
			v.push_back(makr(i,j));
	while((int)res.size()<n*n)
	{
		memset(mp,1,sizeof mp);
		random_shuffle(v.begin(),v.end());
		res.clear();
		for(pii p:v)if(mp[p.fir][p.sec])
		{
			res.push_back(p);
			check(p.fir,p.sec,d1);
			check(p.fir,p.sec,d2);
			if((int)res.size()>=n*n)
				break;
		}
	}
	for(pii p:res)
		printf("%lld %lld\n",p.fir,p.sec);
	return 0;
}

