int n, d1, d2;

bool norm(pii a, pii b) {
	int _a = a.x - b.x;
	int _b = a.y - b.y;
	if (_a * _a + _b * _b == d1) return false;
	if (_a * _a + _b * _b == d2) return false;
	return true;
}

vector<pii> tryCock() {
	vector<pii> free;
	vector<pii> rez;
	f(i, 2 * n) {
		f(j, 2 * n) {
			free.emplace_back(i, j);
		}
	}	
	while (!free.empty()) {
		int best = -1;
		int best_kill = 1e9;
		f(i, len(free)) {
			int cur_kill = 0;
			for (pii sub : free) {
				if (!norm(free[i], sub)) {
					cur_kill++;
				}
			}
			if (cur_kill < best_kill) {
				best_kill = cur_kill;
				best = i;
			}
		}
		pii base = free[best];
		rez.pb(base);
		swap(free[best], free.back());
		free.pop_back();
		set<int> to_del;
		f(i, len(free)) {
			if (!norm(base, free[i])) {
				to_del.insert(i);	
			}
		}
		vector<pii> _filt;
		f(i, len(free)) {
			if (to_del.count(i)) continue;
			_filt.pb(free[i]);
		}
		free = _filt;
	}	
	return rez;
}

