const int mod=1000000007,MAX=400005,INF=1<<30;
vector<int> G[MAX][2];
int color[MAX][2];

void DFS(int u,int p,int k){
    for(int to:G[u][k]){
        if(to==p) continue;
        if(color[to][k]) continue;

        color[to][k]=3-color[u][k];
        DFS(to,u,k);
    }
}

