        sq[i*i]=i;
    }

    for(int i=0;i<2*N;i++){
        for(int j=0;j<2*N;j++){
            for(int to=0;to<2*N;to++){
                int ra=A-(i-to)*(i-to),rb=B-(i-to)*(i-to);

                if(ra>=0){
                    if(sq[ra]!=-1){
                        if(j-sq[ra]>=0){
                            G[i*(2*N)+j][0].push_back(to*(2*N)+j-sq[ra]);
