                        if(j+sq[ra]<2*N){
                            G[i*(2*N)+j][0].push_back(to*(2*N)+j+sq[ra]);
                        }
                    }
                }

                if(rb>=0){
                    if(sq[rb]!=-1){
                        if(j-sq[rb]>=0){
                            G[i*(2*N)+j][1].push_back(to*(2*N)+j-sq[rb]);
