                if(color[i*(2*N)+j][k]==0){
                    color[i*(2*N)+j][k]=1;
                    DFS(i*(2*N)+j,-1,k);
                }
            }
        }
    }

    for(int i=0;i<2*N;i++){
        for(int j=0;j<2*N;j++){
            ans[color[i*(2*N)+j][0]][color[i*(2*N)+j][1]].push_back({i,j});
