		return;
	}
	if(d % 4 == 2)
	{
		for(int i=0;i<n2;++i)
		  for(int j=0;j<n2;++j)
		    vis[i][j] |= ((i / siz) & 1);
		return;
	}
	solve(d / 4,siz * 2);
}
int main()
{
