const int N=2e5+10;
struct T
{
	int x,y;
	bool operator<(T b)const 
	{
		if(x!=b.x)return x<b.x;
		else return y<b.y;
	}
};
map<T,int>Q;
vector<T>G,H;
bool has[N];
void Init()
{
	for(int i=0;i*i<N;i++)has[i*i]=true;
}
const double eps=1e-9;
void f(int u)
{
	int op=sqrt(u);
	for(int i=0;i<=op;i++){
		int p=u-i*i;
		if(has[p]){
			int j=sqrt(p)+eps;
			T g={i,j},g1={j,i};
			Q[g]=Q[g1]=1;
		//	cerr<<i<<' '<<j<<'\n';
		}
	}
}
int vis[600][600];
int dir[4][2]={{1,0},{-1,0},{0,1},{0,-1}};
