	int n,a,b;scanf("%d%d%d",&n,&a,&b);
	Init();
	f(a),f(b);
	for(auto k:Q)G.push_back(k.first);//cout<<k.first.x<<' '<<k.first.y<<'\n';
	int cnt=n*n,idx=0;
	for(int i=0;i<2*n;i++)
		for(int j=0;j<2*n;j++)H.push_back({i,j});
	int l=4*n*n;
	while(cnt--){
		while(idx<l&&vis[H[idx].x][H[idx].y])idx++;
		T p=H[idx];
		cout<<p.x<<' '<<p.y<<'\n';
		for(auto k:G){
			for(int i=0;i<4;i++){
				int x=p.x+dir[i][0]*k.x,y=p.y+dir[i][1]*k.y;
				if(x<0||y<0||x>=2*n||y>=2*n)continue;
				vis[x][y]=true;
			}
		}idx++;
	}
}

