int sqr(int x){
	return x * x;
}

void solve(int d, int vis[N][N]){
	memset(vis, -1, (N * N) << 2);
	sz[0] = sz[1] = 0;
	for(int i = 0; i < 2 * n; ++i)
		for(int j = 0; j < 2 * n; ++j)
			if(vis[i][j] == -1) vis[i][j] = 0, dfs(i, j, d, vis);
	int p = 0;
	if(sz[0] < sz[1]) p = 1;
	for(int i = 0; i < 2 * n; ++i)
		for(int j = 0; j < 2 * n; ++j)
			if(vis[i][j] == p) vis[i][j] = 1;
			else vis[i][j] = 0;
	return ;
}

void dfs(int x, int y, int d, int vis[N][N]){
	++sz[vis[x][y]];
	for(int i = 0; i < 2 * n; ++i){
		int dy = d - sqr(i - x), sy = sqrt(dy);
		if(sqr(sy) != dy) continue;
		if(y - dy >= 0 && vis[i][y - dy] == -1)
			vis[i][y - dy] = vis[x][y] ^ 1, dfs(i, y - dy, d, vis);
		if(y + dy < 2 * n && vis[i][y + dy] == -1)
			vis[i][y + dy] = vis[x][y] ^ 1, dfs(i, y + dy, d, vis);
	}
	return ;
}

