				if(i-a>=0 && j-b>=0) mp[mpi][i-a][j-b] = 3-mp[mpi][i][j];
				if(i+a<n && j-b>=0) mp[mpi][i+a][j-b] = 3-mp[mpi][i][j];
				if(i-a>=0 && j+b<n) mp[mpi][i-a][j+b] = 3-mp[mpi][i][j];
				if(i+a<n && j+b<n) mp[mpi][i+a][j+b] = 3-mp[mpi][i][j];
