  n *= 2;
  for(int i = -n+1; i < n; ++i) {
    for(int j = -n+1; j < n; ++j) {
      if(i*i + j*j == d1) {
        dir[0].emplace_back(i, j);
      }
      if(i*i + j*j == d2) {
        dir[1].emplace_back(i, j);
      }
    }
  }

  for(layer = 0; layer < 2; layer++) {
    memset(vis, 0, sizeof vis);
    for(int i = 0; i < n; ++i) {
      for(int j = 0; j < n; ++j) {
        if(!vis[i][j]) {
          dfs(i, j);
        }
      }
    }
  }
  vi cnt(4);
  for(int i = 0; i < n; ++i) {
    for(int j = 0; j < n; ++j) {
      cnt[(col[1][i][j] << 1) | (col[0][i][j])]++;
    }
  }
  ii opt = {-1, 0};
  for(int i = 0; i < 4; ++i) {
    opt = max(opt, {cnt[i], i});
  }
  int c0 = opt.se & 1;
  int c1 = opt.se >> 1 & 1;
  vector<ii> S;
  for(int i = 0; i < n; ++i) {
    for(int j = 0; j < n; ++j) {
      if(col[0][i][j] == c0 && col[1][i][j] == c1) {
        S.emplace_back(i, j);
      }
    }
  }
  while((int)S.size() > n * n / 4) S.pop_back();
  for(ii& p : S) {
    cout << p.fi << ' ' << p.se << '\n';
  }
  return 0;
  for(int i = 0; i < (int)S.size(); ++i) {
    for(int j = i+1; j < (int)S.size(); ++j) {
      int x = dist2(S[i], S[j]);
      assert(x != d1 and x != d2);
