int get_root(int n) {
    int x = sqrt(n);
    while (x * x < n)
        x++;
    while (x * x > n)
        x--;
    if (x * x != n)
        return -1;
    return x;
}

vector<pii> get_pairs(int n) {
    vector<pii> ans;
    for (int a = 0; a * a <= n; a++) {
        int b = get_root(n - a * a);
        if (b != -1) {
            assert(a * a + b * b == n);
            ans.emplace_back(a, b);
         }
    }
    return ans;
}

