	return x >= 0 && y >= 0 && x < n+n && y < n+n;
}

void mark( int x, int y, int dx, int dy ) {
	int nx = x + dx;
	int ny = y + dy;
	if( inside(nx, ny) ) vis[nx][ny] = 1;
}

void solve() {
	for( int i = 0; i < n+n; ++i )
		for( int j = 0; j < n+n; ++j )
			if( !vis[i][j] ) {
				ans[an++] = pii(i, j);
				for( int t = 0; t < dn; ++t )
					mark(i, j, d[t].first, d[t].second);
			}
	assert( an >= n*n );
	for( int i = 0; i < n*n; ++i )
		printf( "%d %d\n", ans[i].first, ans[i].second );
}

