  }

}

int frame[2] = {-1,1};

vector<int> nbh(int ni,int nj,int gn){
  vector<int> ret;
  REP(k,points[gn].size()){
    REP(i,2){
      REP(j,2){
	pair<int,int> p = points[gn][k];
	if(ni+frame[i]*p.first >= 0 && ni+frame[i]*p.first < 2*n &&
	   nj+frame[j]*p.second >= 0 && nj+frame[j]*p.second < 2*n){
	  auto p_tmp = make_pair(ni+frame[i]*p.first
				 ,nj+frame[j]*p.second);
	  ret.push_back(p2i(p_tmp.first,p_tmp.second));
	}
      }
    }
  }
  return ret;
}

