using namespace std;
typedef pair <int, int> pi;

const int N = 605;

int n, d1, d2, m;
int flag[N][N], vis[N][N], ok[N][N];
vector < pair <int, int> > lis;

void dfs (int x, int y) {
	vis[x][y] = true;
	for (auto &t : lis) {
		int dx = x + t.fi, dy = y + t.se;
		if (dx < 0 || dx >= n || dy < 0 || dy >= n || !ok[dx][dy]) continue;
		if (vis[dx][dy]) assert (flag[dx][dy] ^ flag[x][y]);
		else flag[dx][dy] = !flag[x][y], dfs (dx, dy);
	}
}

void solve (int D) {
	lis.clear();
	memset (vis, 0, sizeof(vis));
	memset (flag, 0, sizeof(flag));
	int x, y;
	for (x = 0; x * x <= D; x ++) {
		y = sqrt(D - x * x + 0.5);
		if (x * x + y * y == D) {
			lis.push_back (pair <int, int> (x, y));
			lis.push_back (pair <int, int> (-x, y));
			lis.push_back (pair <int, int> (x, -y));
			lis.push_back (pair <int, int> (-x, -y));
		}
	}
	for (x = 0; x < n; x ++) for (y = 0; y < n; y ++) if (ok[x][y] && !vis[x][y]) dfs (x, y);
}

int main () {
	int x, y, a, b, cnt;
	scanf ("%d%d%d", &n, &d1, &d2);
	m = n * n, n <<= 1;
	for (x = 0; x < n; x ++) for (y = 0; y < n; y ++) ok[x][y] = true;
	solve (d1);
	for (cnt = x = 0; x < n; x ++) for (y = 0; y < n; y ++) if (flag[x][y]) cnt ++;
	if (cnt < m * 2) for (x = 0; x < n; x ++) for (y = 0; y < n; y ++) flag[x][y] ^= 1;
	for (x = 0; x < n; x ++) for (y = 0; y < n; y ++) ok[x][y] = flag[x][y];
	solve (d2);
	for (cnt = x = 0; x < n; x ++) for (y = 0; y < n; y ++) if (flag[x][y]) cnt ++;
	if (cnt < m) for (x = 0; x < n; x ++) for (y = 0; y < n; y ++) if (ok[x][y]) flag[x][y] ^= 1;
	for (x = 0; x < n; x ++) for (y = 0; y < n; y ++) if (flag[x][y]) {
		printf ("%d %d\n", x, y);
		m --;
		if (m == 0) return 0;
	}
	return 0;
}

