	for(int i=0;i*i<=dis;++i)if(Is[dis-i*i]){
		int j=(int)sqrt(.5+dis-i*i);
		dfs(x+i,y+j,dis,3-c,ned);
		dfs(x+i,y-j,dis,3-c,ned);
		dfs(x-i,y+j,dis,3-c,ned);
		dfs(x-i,y-j,dis,3-c,ned);
	}
}

void dfs2(int x,int y,int dis,int c){
	if(x<0||x>=N*2||y<0||y>=N*2||can[x][y]!=1)return;
	if(col[x][y]){
		assert(col[x][y]==c);
		return;
	}
	col[x][y]=c;
	if(c==1)tot1++;else tot0++;
	for(int i=0;i*i<=dis;++i)if(Is[dis-i*i]){
		int j=(int)sqrt(.5+dis-i*i);
		dfs2(x+i,y+j,dis,3-c);
		dfs2(x+i,y-j,dis,3-c);
		dfs2(x-i,y+j,dis,3-c);
		dfs2(x-i,y-j,dis,3-c);
	}
}

void dfs2(int x,int y,int dis,int c,int ned){
	if(x<0||x>=N*2||y<0||y>=N*2||can[x][y]!=1)return;
	if(can2[x][y]){
		return;
	}
	if(c==ned)can2[x][y]=1;else can2[x][y]=-1;
	for(int i=0;i*i<=dis;++i)if(Is[dis-i*i]){
		int j=(int)sqrt(.5+dis-i*i);
		dfs2(x+i,y+j,dis,3-c,ned);
		dfs2(x+i,y-j,dis,3-c,ned);
		dfs2(x-i,y+j,dis,3-c,ned);
		dfs2(x-i,y-j,dis,3-c,ned);
	}
}

void Work(){
	REP(i,0,N*2-1)REP(j,0,N*2-1)if(!col[i][j]){
		tot0=tot1=0;
		dfs(i,j,A,1);
		if(tot0>=tot1){
			dfs(i,j,A,1,2);
		}
		else dfs(i,j,A,1,1);
	}
	REP(i,0,N*2-1)REP(j,0,N*2-1)col[i][j]=0;
	REP(i,0,N*2-1)REP(j,0,N*2-1)if(!col[i][j]&&can[i][j]==1){
		tot0=tot1=0;
		dfs2(i,j,B,1);
		if(tot0>=tot1){
			dfs2(i,j,B,1,2);
		}
		else dfs2(i,j,B,1,1);
	}
	int now=N*N;
	REP(i,0,N*2-1)REP(j,0,N*2-1)if(can2[i][j]==1&&now){
		printf("%d %d\n",i,j);
		now--;
	}
}

void Init(){
	read(N,A,B);
	REP(i,0,1000)if(i*i<=200000)Is[i*i]=1;
}

int main(){
	Init();
	Work();
	return 0;
}

