vector<pair<int, int>> calc(int D) {
	vector<pair<int, int>> ret;

	int limit = sqrt(D);
	rep(i, limit + 1) {
		int tmp = D - i * i;
		int tmp2 = sqrt(tmp);
		if (tmp2 * tmp2 == tmp) {
			ret.push_back(mp(i, tmp2));
		}
	}

	int n = ret.size();
	rep(i, n) {
		ret.push_back(mp(-ret[i].first, ret[i].second));
		ret.push_back(mp(ret[i].first, -ret[i].second));
		ret.push_back(mp(-ret[i].first, -ret[i].second));
	}

	return ret;
}

int N;

vector<pair<int, int>> ret;
set<pair<int, int>> st;

bool inBoard(int x, int y) {
	return x >= 0 && x < 2 * N && y >= 0 && y < 2 * N;
}

void put(int x, int y) {
	if (board[y][x]) {
		cerr << "(" << x << ", " << y << ") damehaiti!!" << endl;
		throw "dame";
	}

	ret.push_back(mp(x, y));

	board[y][x] = 1;

	for (auto &pr : st) {
		int nx = x + pr.first;
		int ny = y + pr.second;
		if (!inBoard(nx, ny)) continue;
		board[ny][nx] = 2;
	}
}

char hoge(int num) {
	if (num == 0) return '.';
	if (num == 1) return 'o';
	return 'x';
}

void display() {
	cerr << "--" << endl;
	rep(y, 2 * N) {
		rep(x, 2 * N) cerr << hoge(board[y][x]);
		cerr << endl;
	}
}

void solve() {
	int haba = 1;
	while (true) {
		bool ok = true;
		rep(x, haba + 1) {
			if (board[haba][x]) {
				ok = false;
				break;
			}
		}
		if (!ok) break;
		haba++;
		if (haba == N) break;
	}

	cerr << "haba:" << haba << endl;

	rep(y, haba) rep(x, haba) {
		int tx = x;
		int ty = y;
		if (tx + ty == 0) continue;
		put(tx, ty);
	}

	int val = 0;
	{
		int x = haba;
		bool flag;
		do {
			flag = true;
			rep(y, haba) {
				cerr << "(" << x << ", " << y << ") " << board[y][x] << endl;
				if (board[y][x]) {
					flag = false;
					break;
				}
			}
			if (!flag) x++;
		} while (!flag);
		val = x - haba;
	}

	display();

	cerr << "val:" << val << endl;

	for (int by = 0; by < 2 * N; by += haba + val) {
		for (int bx = 0; bx < 2 * N; bx += haba + val) {
			if (bx + by == 0) continue;
			rep(y, haba) rep(x, haba) {
				int tx = x + bx;
				int ty = y + by;
				if (tx + ty == 0) continue;
				put(tx, ty);
			}
		}
	}
}

void dfs(int x, int y) {
	if (board[y][x]) return;

	put(x, y);

	rep(dir, 4) {
		int nx = x + dx[dir];
		int ny = y + dy[dir];
		if (!inBoard(nx, ny)) continue;
		if (board[ny][nx]) continue;
		dfs(nx, ny);
	}
}

