			if (j != -1 && (Exist(r - i, c - j) || Exist(r - i, c + j) || Exist(r + i, c - j) || Exist(r + i, c + j)))
				return false;
		}
		if (i * i <= d2) {
			int j = sqr[d2 - i * i];
			if (j != -1 && (Exist(r - i, c - j) || Exist(r - i, c + j) || Exist(r + i, c - j) || Exist(r + i, c + j)))
				return false;
		}
	}
	return true;
}

bool Check()
{
	for (int i = 0; int(gen.size()) - i + slen > n * n && slen < n * n && i < gen.size(); i++)
		if (Check(gen[i].first, gen[i].second)) {
			seq[slen++] = gen[i]; tk[gen[i].first][gen[i].second] = true;
		}
	if (slen >= n * n) {
		for (int i = 0; i < slen; i++)
			printf("%d %d\n", seq[i].first, seq[i].second);
		return true;
	} else {
		for (int i = 0; i < slen; i++)
			tk[seq[i].first][seq[i].second] = false;
		slen = 0;
		return false;
	}
}

int main()
{
	fill(sqr, sqr + Maxn, -1);
	for (int i = 0; i * i < Maxn; i++)
		sqr[i * i] = i;
	cin >> n >> d1 >> d2;
	for (int i = 0; i < n; i++)
