					if (d*d <= a) {
						int D = a - d*d;
						if (sqr[D] != -1) {
							D = sqr[D];
							for (int dx = -1; dx <= 1; ++++dx) {
								for (int it = 0; it < 2; ++it) {
									int r = i + d*dx;
									int c = j + D;
									if (r < R && c < C && r >= 0 && c >= 0)
										addEdge(id(i, j), id(r, c));
									swap(d, D);
								}
							}
						}
