#include<bits/stdc++.h>
using namespace std;
int vis[603][603][2];
int col[603][603][2];
vector<pair<int,int> > adj[603][603][2];
vector<pair<int,int> > vec[4];
int dx[4]={1,1,-1,-1};
int dy[4]={1,-1,1,-1};

int n;

bool check(int a)
{
	return ((a<(2*n))&&(a>=0));
}

void ret(int a,int b,int ind,int d)
{
	int lim=sqrt(d);
	for(int i=0;i<=lim;i++)
	{
		int j=(i*i);
		int x=sqrt(d-j);
		if((x*x)==(d-j))
		{
			for(int j=0;j<4;j++)
			{
				if(check(a+(dx[j]*i))&&check(b+(dy[j]*x)))
				{
					adj[a][b][ind].push_back(make_pair(a+(dx[j]*i),b+(dy[j]*x)));
				}
			}
			if(x!=i)
			{
				for(int j=0;j<4;j++)
				{
					if(check(a+(dx[j]*x))&&check(b+(dy[j]*i)))
					{
						adj[a][b][ind].push_back(make_pair(a+(dx[j]*x),b+(dy[j]*i)));
					}
				}
			}
		}
	}
}

void dfs(int x,int y,int ind)
{
	vis[x][y][ind]=1;
	for(int i=0;i<adj[x][y][ind].size();i++)
	{
		pair<int,int> tmp=adj[x][y][ind][i];
		if(!vis[tmp.first][tmp.second][ind])
		{
			col[tmp.first][tmp.second][ind]=col[x][y][ind]^1;
			dfs(tmp.first,tmp.second,ind);
		}
	}
}


int main()
{	
	int d1,d2;
	scanf("%d %d %d",&n,&d1,&d2);

	for(int i=0;i<(2*n);i++)
	{
		for(int j=0;j<(2*n);j++)
		{
			ret(i,j,0,d1);
			ret(i,j,1,d2);
		}
	}
	for(int i=0;i<(2*n);i++)
	{
		for(int j=0;j<(2*n);j++)
		{
			if(!vis[i][j][0])
			{
				dfs(i,j,0);
			}
		}
	}

	for(int i=0;i<(2*n);i++)
	{
		for(int j=0;j<(2*n);j++)
		{
			if(!vis[i][j][1])
			{
				dfs(i,j,1);
			}
		}
	}
	// for(int i=0;i<adj[0][0][1].size();i++)
	// {
	// 	printf("%d %d\n",adj[0][0][1][i].first,adj[0][0][1][i].second);
	// }

	for(int i=0;i<(2*n);i++)
	{
		for(int j=0;j<(2*n);j++)
		{
			int msk=(col[i][j][0]*2)+col[i][j][1];
			vec[msk].push_back(make_pair(i,j));
		}
	}
	for(int i=0;i<4;i++)
	{
		if(vec[i].size()>=(n*n))
		{
			for(int j=0;j<min((int)vec[i].size(),n*n);j++)
			{
				printf("%d %d\n",vec[i][j].first,vec[i][j].second);
			}
			break;
		}
	}
}

