const int maxn = 1010;
int n,D1,D2,head[maxn],to[5 * maxn * maxn],nextt[5 * maxn * maxn],tot = 1,cnt,flag[maxn][maxn];

void add(int x,int y)
{
    to[tot] = y;
    nextt[tot] = head[x];
    head[x] = tot++;
}

int id(int x,int y)
{
    return (x - 1) * n + y;
}

void jieid(int v,int &x,int &y)
{
    x = (v - 1) / n + 1;
    y = v - (x - 1) * n;
}

int main()
{
    scanf("%d%d%d",&n,&D1,&D2);
    n *= 2;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
        {
            for (int k = 0; k * k <= D1 && i + k <= n; k++)
            {
                int l = D1 - k * k;
                int temp = sqrt(l);
                if (temp * temp != l || j + l > n)
                    continue;
                add(id(i,j),id(i + k,j + l));
            }
            for (int k = 0; k * k <= D2 && i + k <= n; k++)
            {
                int l = D2 - k * k;
                int temp = sqrt(l);
                if (temp * temp != l || j + l > n)
                    continue;
                add(id(i,j),id(i + k,j + l));
            }
        }
    for (int i = 1; i <= n; i++)
    {
        if(cnt == (n / 2) * (n / 2))
            break;
        for (int j = 1; j <= n; j++)
        {
            if (cnt == (n / 2) * (n / 2))
                break;
            if (flag[i][j])
                continue;
            flag[i][j] = 1;
            printf("%d %d\n",i - 1,j - 1);
            cnt++;
            int temp = id(i,j);
            for (int k = head[temp];k;k = nextt[k])
            {
                int v = to[k];
                int tx,ty;
                jieid(v,tx,ty);
                flag[tx][ty] = 1;
            }
        }
    }

    return 0;
}

