int n, d1, d2;
vector<pair<int,int>> bad;
set<pair<int,int>> s;

int check(const state& s, pair<int,int> p) {
  for (auto& b: bad) {
    pair<int,int> pt = {p.first-b.first, p.second-b.second};
    if (s.count(pt))
      return 0;
  }
  return 1;
}

void prepare() {
  for (int x = -600; x <= 600; ++x) {
    for (int y = -600; y <= 600; ++y) {
      if (x*x + y*y == 1LL*d1*d1 || x*x + y*y == 1LL*d2*d2) {
        bad.emplace_back(x, y);
      }
    }
  }
}

void perform(const vector<pair<int,int>>& pts) {
  s.clear();
  for (auto& p: pts) {
    if ((int)s.size() == n*n)
      break;
    if (check(s, p))
      s.insert(p);
  }
}

void easy() {
  if ((int)s.size() == n*n)
    return;

  vector<pair<int,int>> pts;

  for (int i = 0; i < 2*n; ++i) 
    for (int j = 0; j < 2*n; ++j) 
      pts.emplace_back(i, j);

  perform(pts);
}

int main() {
  cin >> n >> d1 >> d2;

  prepare();
  easy();

  assert((int)s.size() == n*n);

  for (auto& p: s) {
    cout << p.first << ' ' << p.second << '\n';
  }

}

