int n, d1, d2;
vector <pair <int, int> > v1;
vector <pair <int, int> > v2;
vector <pair <int, int> > Sol;
bool f[605][605];
inline void smecherie(int i, int j){
    if(f[i][j]) return ;
    bool ok = 1;
    for(auto it : v1){
        int x = i - it.first;
        int y = j - it.second;
        if(x >= 0 && y >= 0)
            if(f[x][y]){ok = 0; break ;}

        x = i + it.first;
        y = j + it.second;
        if(x < 2 * n && y < 2 * n)
            if(f[x][y]){ok = 0; break ;}

        x = i - it.first;
        y = j + it.second;
        if(x >= 0 && y < 2 * n)
            if(f[x][y]){ok = 0; break ;}

        x = i + it.first;
        y = j - it.second;
        if(x < 2 * n && y >= 0)
            if(f[x][y]){ok = 0; break ;}

    }
    if(ok == 0) return ;

    for(auto it : v2){
        int x = i - it.first;
        int y = j - it.second;
        if(x >= 0 && y >= 0)
            if(f[x][y]){ok = 0; break ;}

        x = i + it.first;
        y = j + it.second;
        if(x < 2 * n && y < 2 * n)
            if(f[x][y]){ok = 0; break ;}

        x = i - it.first;
        y = j + it.second;
        if(x >= 0 && y < 2 * n)
            if(f[x][y]){ok = 0; break ;}

        x = i + it.first;
        y = j - it.second;
        if(x < 2 * n && y >= 0)
            if(f[x][y]){ok = 0; break ;}
    }
    if(ok == 0) return ;
    f[i][j] = 1;
    Sol.push_back({i, j});
}

int main()
{
    scanf("%d%d%d", &n, &d1, &d2);
    for(int i = 0; i <= sqrt(d1); ++i){
        int x = i * i;
        int y = d1 - i * i;
        int rad = sqrt(y);
        if(rad * rad == y) v1.push_back({sqrt(x), sqrt(y)}), v1.push_back({sqrt(y), sqrt(x)});
    }
    for(int i = 0; i <= sqrt(d2); ++i){
        int x = i * i;
        int y = d2 - i * i;
        int rad = sqrt(y);
        if(rad * rad == y) v2.push_back({sqrt(x), sqrt(y)}), v2.push_back({sqrt(y), sqrt(x)});
    }
    for(int k = 1; k < n ; ++k){
        int i = k;
        for(int j = k; j <= 2 * n - k + 1 ; ++j)
            smecherie(i - 1, j - 1);
        i = 2 * n - k + 1;
        for(int j = k; j <= 2 * n - k + 1 ; ++j)
            smecherie(i - 1, j - 1);

        int j = k;
        for(int i = k; i <= 2 * n - k + 1 ; ++i)
            smecherie(i - 1, j - 1);
        j = 2 * n - k + 1;
        for(int i = k; i <= 2 * n - k + 1 ; ++i)
            smecherie(i - 1, j - 1);
    }
    for(int i = 0; i < n * n ; ++i)
        printf("%d %d\n", Sol[i].first, Sol[i].second);
    return 0;
}

