	// (x,y) -> (-x,y), (x,-y), (-x,-y)
	// も追加
	vector<pii> outList;
	for (auto it : out) {
		outList.push_back(it);
		outList.push_back(mp(-it.first, it.second));
		outList.push_back(mp(it.first, -it.second));
		outList.push_back(mp(-it.first, -it.second));
	}
	int cnt = 0;
	rep(i, m) {
		rep(j, m) {
			bool ok = true;
			for (auto it : outList) {
				int tx = i + it.first;
				int ty = j + it.second;
				if (tx < 0 || m <= tx || ty < 0 || m <= ty)	continue;
				if (used[tx][ty]) {
					ok = false;
					break;
				}
			}
			if (ok) {
				used[i][j] = true;
				cnt++;
				if (cnt == n * n)	break;
			}
		}
		if (cnt == n * n)	break;
	}
	rep(i, m)	rep(j, m) {
		if (used[i][j]) {
			cout << i << " " << j << endl;
		}
	}
	return 0;
}

/*题目大意
你要找到 n*n 个整点 x, y 满足 0 ≤ x, y < 2n。并且找到的任意两个点距离，既不是 √d1，也不是 √d2。

解题思路:二分图

根据a*a+b*b=c*c 得出x*x+y*y≠d1,d2
将d1,d2分开讨论
当d1≡0（mod 4）时，x,y≡0 (mod 2)
所以可以进行缩点。d1/=4;
当d1≡1（mod 4）时，x,y一奇一偶，可以进行黑白方格染色。只要两个格子为同色即成立
当d1≡2（mod 4）时，x,y≡1（mod 2），对于任意的两点间x1-x2≡0（mod 2）均成立
d2一样

调试记录
无
*/
#include<cstdio>
#include<iostream>
using namespace std;
int map[800][800],n,d1,d2,z;
void expt(int d)
{
	int now=0;
	while(d%4==0){
		d/=4;//如果整除4，则x,y均为偶数，可以缩点。 
		//now++;
	}
	if(d&1){//除二余一，x,y一奇一偶。可以黑白染色 
		for(int i=0;i<2*n;i++)
			for(int j=0;j<2*n;j++)
				if((i>>now)+(j>>now)&1)
				map[i][j]=1;
	}
	else//除四余二，x,y均为奇数 
	{
		for(int i=0;i<2*n;i++)
			for(int j=0;j<2*n;j++)
			if((i>>now)&1)
			map[i][j]=1;
	}
}
int main()
{
	scanf("%d%d%d",&n,&d1,&d2);
	expt(d1);
	expt(d2);
	for(int i=0;i<2*n;i++)
		for(int j=0;j<2*n;j++)
		if(z<n*n && !map[i][j])
		{
			printf("%d %d\n",i,j);
			z++; 
		}
}

