    {
        for (int y=0; y<2*N; y++)
        for (int x=0; x<2*N; x++)
            if (x*x+y*y==D[i])
            {
                Dx.push_back(x);
                Dy.push_back(y);
                if (y>0)
                {
                    Dx.push_back(x);
                    Dy.push_back(-y);
                }
                if (x>0)
                {
                    Dx.push_back(-x);
                    Dy.push_back(y);
                }
                if (x>0 && y>0)
                {
                    Dx.push_back(-x);
                    Dy.push_back(-y);
                }
            }
    }

    vector<int> ax, ay;
    vector<vector<bool>> F(2*N, vector<bool>(2*N));
    vector<int> cx, cy;

    auto put = [&](int x, int y)
    {
        ax.push_back(x);
        ay.push_back(y);
        F[y][x] = true;
        for (int d=0; d<(int)Dx.size(); d++)
        {
            int dx = x+Dx[d];
            int dy = y+Dy[d];
            if (0<=dx && dx<2*N &&
                0<=dy && dy<2*N &&
                !F[dy][dx])
            {
                F[dy][dx] = true;
                for (int d2=0; d2<(int)Dx.size(); d2++)
                {
                    int dx2 = dx+Dx[d2];
                    int dy2 = dy+Dy[d2];
                    if (0<=dx2 && dx2<2*N &&
                        0<=dy2 && dy2<2*N &&
                        !F[dy2][dx2])
                    {
                        cx.push_back(dx2);
                        cy.push_back(dy2);
                    }
                }
            }
        }
    };

    put(0, 0);
    int c = 0;
    int p = 0;

    while ((int)ax.size()<N*N)
    {
        while (c<(int)cx.size() && F[cy[c]][cx[c]])
            c++;
        if (c<(int)cx.size())
        {
            put(cx[c], cy[c]);
        }
        else
        {
            while (p<4*N*N && F[p/(2*N)][p%(2*N)])
                p++;
            if (p >= 4*N*N)
                return 0;
            put(p%(2*N), p/(2*N));
        }
    }

    for (int i=0; i<N*N; i++)
        cout<<ax[i]<<" "<<ay[i]<<endl;
}

