using std::pair;
typedef pair<int,int> pii;
const int N = 600;
const int D = 200000;
int _w;

int n, d1, d2, dn, an;
pii d[N], ans[N*N];

void prelude() {
	for( int i = 0; i*i <= D; ++i )
		for( int j = 0; i*i+j*j <= D; ++j ) {
			int x = i*i+j*j;
			if( x == d1 || x == d2 ) {
				d[dn++] = pii(i, j);
				d[dn++] = pii(i, -j);
				d[dn++] = pii(-i, j);
				d[dn++] = pii(-i, -j);
			}
		}
}

int vis[N][N];

bool inside( int x, int y ) {
	return x >= 0 && y >= 0 && x < n+n && y < n+n;
}

void mark( int x, int y, int dx, int dy ) {
	int nx = x + dx;
	int ny = y + dy;
	if( inside(nx, ny) ) vis[nx][ny] = 1;
}

pii q[N*N];
int qn;

void solve() {
	for( int i = 0; i < n+n; ++i )
		for( int j = 0; j < n+n; ++j )
			q[qn++] = pii(i, j);
	while(1) {
		random_shuffle(q, q+qn);
		an = 0;
		memset(vis, 0, sizeof vis);
		for( int i = 0; i < qn; ++i ) {
			int x = q[i].first;
			int y = q[i].second;
			if( !vis[x][y] ) {
				ans[an++] = pii(x, y);
				for( int t = 0; t < dn; ++t )
					mark(x, y, d[t].first, d[t].second);
			}
		}
		if( an >= n*n ) {
			for( int i = 0; i < n*n; ++i )
				printf( "%d %d\n", ans[i].first, ans[i].second );
			break;
		}
	}
}

int main() {
	_w = scanf( "%d%d%d", &n, &d1, &d2 );
	prelude(), solve();
	return 0;
}

