  for (auto t : fact[id]) {
    int delta_y = Sqrt[D[id] - t * t];
    int x_1 = x - t, y_1 = y - delta_y;
    int x_2 = x + t, y_2 = y + delta_y;
    if (x_1 >= 0 && y_1 >= 0 && col[x_1][y_1] == empty)
      dfs(id, x_1, y_1, color ^ 1, empty);
    if (x_1 >= 0 && y_2 < N && col[x_1][y_2] == empty)
      dfs(id, x_1, y_2, color ^ 1, empty);
    if (x_2 < N && y_1 >= 0 && col[x_2][y_1] == empty)
      dfs(id, x_2, y_1, color ^ 1, empty);
    if (x_2 < N && y_2 < N && col[x_2][y_2] == empty)
      dfs(id, x_2, y_2, color ^ 1, empty);
  }
}

int main() {
  scanf("%d%d%d", &N, &D[0], &D[1]), N <<= 1;
  for (int i = 0; i * i <= 200000; i++) Sqrt[i * i] = i;
  for (int x = 0; x * x <= D[0] && x <= N; x++)
    if (Sqrt[D[0] - x * x] || D[0] == x * x) fact[0].push_back(x);
  for (int x = 0; x * x <= D[1] && x <= N; x++)
    if (Sqrt[D[1] - x * x] || D[1] == x * x) fact[1].push_back(x);
  memset(col, -1, sizeof(col));
  for (int i = 0; i < N; i++)
    for (int j = 0; j < N; j++)
      if (col[i][j] == -1) dfs(0, i, j, 0, -1);
  if (Cnt[0] >= Cnt[1]) {
    for (int i = 0; i < N; i++)
      for (int j = 0; j < N; j++)
        if (col[i][j] == 0) dfs(1, i, j, 2, 0);
  } else {
    for (int i = 0; i < N; i++)
      for (int j = 0; j < N; j++)
        if (col[i][j] == 1) dfs(1, i, j, 2, 1);
  }
  int Need = (N >> 1) * (N >> 1);
  if (Cnt[2] >= Cnt[3]) {
    for (int i = 0; i < N && Need; i++)
      for (int j = 0; j < N && Need; j++)
        if (col[i][j] == 2) printf("%d %d\n", i, j), Need--;
  } else {
    for (int i = 0; i < N && Need; i++)
      for (int j = 0; j < N && Need; j++)
        if (col[i][j] == 3) printf("%d %d\n", i, j), Need--;
  }
  return 0;
}

