bool solve(vector<int> &X, vector<int> &Y) {
    vector<int> ans_X, ans_Y;
    vector<int> cand_X, cand_Y, ok(4*N*N, 1);
    for(int i=0; i<2*N; i++) {
        for(int j=0; j<2*N; j++) {
            cand_X.push_back(i);
            cand_Y.push_back(j);
        }
    }

    fill(board[0], board[610], 0);
    int rest = N*N, amount = 4*N*N;
    while(rest--) {
        int idx = rnd.NextInt(0, 4*N*N-1);
        if(!ok[idx]) {rest++; continue;}

        int i = cand_X[idx], j = cand_Y[idx];
        if(board[i][j] == 1) {rest++; continue;}

        // printf("valid: %lld, %lld\n", i, j);
        ok[idx] = 0;
        ans_X.push_back(i);
        ans_Y.push_back(j);
        paint_board(X, Y, i, j, amount);

        if(amount == 0) break;
    }

    // printf("size = %zu, amount = %lld\n", ans_X.size(), amount);

    if(ans_X.size() != N*N) return false;
    for(int i=0; i<N*N; i++) {
        printf("%lld %lld\n", ans_X[i], ans_Y[i]);
    }
    return true;
}

