        {
            vc.push_back({i,x});
            vis[i][x]=vis[x][i]=true;
        }
    }
    for(int i=0;i*i<=d2;i++)
    {
        int x=sqrt(d2-i*i);
        if(x*x==d2-i*i&&!vis[i][x])
        {
            vc.push_back({i,x});
            vis[i][x]=vis[x][i]=true;
        }
