const size_t N = 6E2 + 5;

int n, m;
vector<P> g[N][N];
bool ok[N][N];
int col[N][N];

void dfs(int i, int j, int c = 1) {
    if (!ok[i][j]) return;
    if (col[i][j]) {
        assert(col[i][j] == c);
        return;
    }
    col[i][j] = c;
    for (auto &pr : g[i][j]) {
        dfs(pr.fi, pr.se, c ^ 3);
    }
}

vector<P> doit(const vector<P> &vc) {
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= m; ++j) {
            g[i][j].clear();
            col[i][j] = 0;
            for (auto &p : vc) {
                for (int di = -1; di <= 1; di += 2) {
                    for (int dj = -1; dj <= 1; dj += 2) {
                        int ti = i + di * p.fi;
                        int tj = j + dj * p.se;
                        if (1 <= ti && ti <= m && 1 <= tj && tj <= m) {
                            g[i][j].emplace_back(ti, tj);
                        }
                    }
                }
            }
        }
    }
    int cnt[3] = {0, 0, 0};
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (ok[i][j]) {
                if (!col[i][j]) {
                    dfs(i, j);
                }
                ++cnt[col[i][j]];
            }
        }
    }
    int c = 1 + (cnt[2] > cnt[1]);
    vector<P> ret;
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (col[i][j] == c) {
                ret.emplace_back(i, j);
            }
        }
    }
    return ret;
}

vector<P> get_vc(int d) {
    vector<P> vc;
    for (int i = 0; i <= m && i * i <= d; ++i) {
        int j = round(sqrt(d - i * i));
        if (i * i + j * j == d) {
            vc.emplace_back(i, j);
        }
    }
    return vc;
}

