int vis[605][605];
int n,d1,d2;
inline void deal(int d)
{
    int gs=0,i,j;
    while((d&3)==0)++gs,d>>=2;
    if(d&1)
    {
        for(i=0;i<=n;++i)for(j=0;j<=n;++j)
            if(((i>>gs)+(j>>gs))&1)vis[i][j]=1;
    }
    else
    {
        for(i=0;i<=n;++i)for(j=0;j<=n;++j)
            if((i>>gs)&1)vis[i][j]=1;
    }
}
int main()
{
    n=read(),d1=read(),d2=read();
    reg int i,j,need=n*n,gs=0;
    n<<=1;deal(d1);deal(d2);
    for(i=0;i<=n;++i)for(j=0;j<=n;++j)
    {
        if(!vis[i][j])printf("%d %d\n",i,j),++gs;
        if(gs==need)return 0;
    }
	return 0;
}

