#include<bits/stdc++.h>
using namespace std;

using Graph = vector<vector<int>>;

int to_v(auto x, auto y, auto N) {return N * y + x;}
int to_x(auto v, auto N) {return v % N;}
int to_y(auto v, auto N) {return v / N;}
void paint(const auto& G, auto& color, auto v) {
  function<void(int)> dfs = [&](auto cur) {
    for(auto nex: G[cur]) if(!color[nex]) {
      color[nex] = 3 - color[cur];
      dfs(nex);
    }
  };
  color[v] = 1;
  dfs(v);
}

int main() {
  int N, D1, D2;
  cin >> N >> D1 >> D2;

  vector<pair<int, int>> d1, d2;
  for(auto x=0; x<2*N; ++x) for(auto y=0; y<2*N; ++y) {
    if(x*x+y*y == D1) d1.emplace_back(x, y);
    if(x*x+y*y == D2) d2.emplace_back(x, y);
  }

  Graph G1(4*N*N), G2(4*N*N);
  for(auto x=0; x<2*N; ++x) for(auto y=0; y<2*N; ++y) {
    for(auto d: d1) {
      auto nx = x + d.first;
      auto ny = y + d.second;
      if(2*N<=nx || 2*N<=ny) continue;
      auto u = to_v(x, y, 2*N);
      auto v = to_v(nx, ny, 2*N);
      G1[u].emplace_back(v);
      G1[v].emplace_back(u);
    }
    for(auto d: d2) {
      auto nx = x + d.first;
      auto ny = y + d.second;
      if(2*N<=nx || 2*N<=ny) continue;
      auto u = to_v(x, y, 2*N);
      auto v = to_v(nx, ny, 2*N);
      G2[u].emplace_back(v);
      G2[v].emplace_back(u);
    }
  }

  vector<int> color1(4*N*N), color2(4*N*N);
  for(auto v=0; v<4*N*N; ++v) {
    if(!color1[v]) paint(G1, color1, v);
    if(!color2[v]) paint(G2, color2, v);
  }

  for(auto c1: {1, 2}) for(auto c2: {1, 2}) {
    auto n = 0;
    for(auto v=0; v<4*N*N; ++v) if(color1[v]==c1 && color2[v]==c2) ++n;
    if(n < N*N) continue;

    auto V = 0;
    for(auto v=0; v<4*N*N; ++v)
      if(color1[v]==c1 && color2[v]==c2)
        if(V++ < N*N)
          cout << to_x(v, 2*N) << " " << to_y(v, 2*N) << endl;

    return 0;
  }
}

