using namespace std;

typedef long long lint;

void dfs(int v, int color_v, vector<int> &colors,
         const vector<vector<int>> &adj) {
  if (colors[v] != -1) {
    assert(colors[v] == color_v);
    return;
  }
  colors[v] = color_v;
  for (int u : adj[v])
    dfs(u, 1 - color_v, colors, adj);
}

vector<vector<int>> get_colors(int n, int d) {
  vector<vector<int>> adj(n * n);
  for (int y = 0; y < n; ++y)
    for (int x = 0; x < n; ++x) {
      int y_low = y, y_high = y;
      for (int x2 = n - 1; x2 >= x; --x2) {
        while (y_low >= 0 &&
               (x2 - x) * (x2 - x) + (y_low - y) * (y_low - y) < d)
          --y_low;
        while (y_high < n &&
               (x2 - x) * (x2 - x) + (y_high - y) * (y_high - y) < d)
          ++y_high;

        if (x2 > x && y_low >= 0 &&
            (x2 - x) * (x2 - x) + (y_low - y) * (y_low - y) == d) {
          adj[y * n + x].push_back(y_low * n + x2);
          adj[y_low * n + x2].push_back(y * n + x);
        }
        if (y_high < n &&
            (x2 - x) * (x2 - x) + (y_high - y) * (y_high - y) == d) {
          adj[y * n + x].push_back(y_high * n + x2);
          adj[y_high * n + x2].push_back(y * n + x);
        }
      }
    }

  vector<int> colors(n * n, -1);
  for (int v = 0; v < n * n; ++v)
    if (colors[v] == -1)
      dfs(v, 0, colors, adj);

  vector<vector<int>> result(n, vector<int>(n));
  for (int y = 0; y < n; ++y)
    for (int x = 0; x < n; ++x)
      result[y][x] = colors[y * n + x];
  return result;
}

int main() {
  int n, d1, d2;
  scanf("%d %d %d", &n, &d1, &d2);
  n *= 2;
  vector<vector<int>> colors_d1 = get_colors(n, d1);
  vector<vector<int>> colors_d2 = get_colors(n, d2);

  map<pair<int, int>, vector<pair<int, int>>> points_with_colors;
  for (int y = 0; y < n; ++y)
    for (int x = 0; x < n; ++x)
      points_with_colors[{colors_d1[y][x], colors_d2[y][x]}].emplace_back(y, x);

  vector<pair<int, int>> result =
    max_element(points_with_colors.begin(), points_with_colors.end(),
                [](const auto &kv1, const auto &kv2) {
                  return kv1.second.size() < kv2.second.size();
                })->second;

  assert((int)result.size() >= n * n / 4);
  result.resize(n * n / 4);

  for (const pair<int, int> &point : result)
    printf("%d %d\n", point.first, point.second);

  return 0;
}

