int n, d1, d2;

void rip(int x, int y) {
    if (x < 0 || x >= n * 2) {
        return;
    }

    if (y < 0 || y >= n * 2) {
        return;
    }

    good[x][y] = 0;
}

void solve() {                   
    scanf("%d %d %d", &n, &d1, &d2);
    vector<pair<int, int>> vv, ans;

    for (int a = 0; a <= 500; ++a) {
        for (int b = 0; b <= 500; ++b) {
            int cur = a * a + b * b;

            if (cur == d1 || cur == d2) {
                vv.pb(mp(a, b));
            }
        }
    }

    for (int x = 0; x < n * 2; ++x) {
        for (int y = 0; y < n * 2; ++y) {
            good[x][y] = 1;
        }
    }

    for (int x = 0; x < n * 2; ++x) {
        for (int y = 0; y < n * 2; ++y) {
