vector<array<int, 2>>MakeD(const int N, const int D) {

	vector<array<int, 2>>diff;
	rep(i, 2 * N)rep(j, 2 * N)if (i*i + j*j == D)diff.push_back({ i,j });
	return diff;
}

signed main()
{
	std::cin.sync_with_stdio(false);
	std::cin.tie(0);


	int N, D1, D2;
	cin >> N >> D1 >> D2;

	auto m1 = MakeD(N, D1);
	auto m2 = MakeD(N, D2);

	vector<vector<int>>color1(N * 2, vector<int>(N * 2, 0));
	vector<vector<int>>color2(N * 2, vector<int>(N * 2, 0));

	int count[4] = { 0 };
	const int dir[5] = { 1,1,-1,-1,1 };
	rep(i, N * 2)rep(j, N * 2) {

		if (color1[i][j] == 0) {
			stack<pair<int, int>>dfs;
			color1[i][j] = 1;
			dfs.push(make_pair(i, j));
			while (!dfs.empty()) {
				auto x = dfs.top();
				dfs.pop();
				for (auto k : m1) {
					rep(l, 4) {
						int ii = x.first + k[0] * dir[l];
						int jj = x.second + k[1] * dir[l+1];
						if (0 <= ii && ii < 2 * N && 0 <= jj && jj < 2 * N && color1[ii][jj] == 0) {
							color1[ii][jj] = 3 ^ color1[x.first][x.second];
							dfs.push(make_pair(ii, jj));
						}
					}
				}
			}
		}

		if (color2[i][j] == 0) {
			stack<pair<int, int>>dfs;
			color2[i][j] = 1;
			dfs.push(make_pair(i, j));
			while (!dfs.empty()) {
				auto x = dfs.top();
				dfs.pop();
				for (auto k : m2) {
					rep(l, 4) {
						int ii = x.first + k[0] * dir[l];
						int jj = x.second + k[1] * dir[l + 1];
						if (0 <= ii && ii < 2 * N && 0 <= jj && jj < 2 * N && color2[ii][jj] == 0) {
							color2[ii][jj] = 3 ^ color2[x.first][x.second];
							dfs.push(make_pair(ii, jj));
						}
					}
				}
			}
		}

		count[color1[i][j] == 1 ? 0 : 1]++;
		count[color2[i][j] == 1 ? 2 : 3]++;
	}

	int ans1 = count[0] > count[1] ? 1 : 2;
	int ans2 = count[2] > count[3] ? 1 : 2;

	int x = 0;
	rep(i, N * 2)rep(j, N * 2) {
		if(color1[i][j] == ans1 && color2[i][j] == ans2) {
			if(x++ < N*N)cout << i << " " << j << endl;
		}
	}

	return 0;
}

