int cnt[605][605],tot,dx[] = {1,-1,-1,1},dy[] = {1,1,-1,-1};
vector<pii > pass[605][605];
bool vis[605][605];
priority_queue<pii > Q;
int N;
int64 D[2];
bool cmp(pii a,pii b) {
	return cnt[a.fi][a.se] < cnt[b.fi][b.se];
}
int main() {
#ifdef ivorysi
	freopen("f1.in","r",stdin);
#endif
	read(N);read(D[0]);read(D[1]);
	for(int t = 0 ; t <= 1 ; ++t) {
		for(int64 x = 0 ; x < 2 * N ; ++x) {
			if(D[t] < x * x) break;
			int64 y = sqrt(D[t] - x * x);
			if(y * y != D[t] - x * x) continue;
			if(y >= 2 * N) continue;
			for(int i = 0 ; i < 2 * N ; ++i) {
				for(int j = 0 ; j < 2 * N ; ++j) {
					for(int k = 0 ; k < 4 ; ++k) {
						int tx = i + dx[k] * x,ty = j + dy[k] * y;
						if(!x && (k == 1 || k == 3))  continue;
						if(!y && (k == 0 || k == 1)) continue;
						if(tx >= 0 && tx < 2 * N && ty >= 0 && ty < 2 * N) {
							cnt[tx][ty]++;
							pass[tx][ty].pb(mp(i,j));
						}
					}
				}
			}
		}
	}
	for(int i = 0 ; i < 2 * N ; ++i) {
		for(int j = 0 ; j < 2 * N ; ++j) {
			Q.push(mp(-cnt[i][j],i * 2 * N + j));
		}
	}
	int a = N * N;
	while(!Q.empty()) {
		pii t = Q.top();Q.pop();
		int y = t.se % (2 * N),x = t.se / (2 * N);
		if(vis[x][y]) continue;
		vis[x][y] = 1;
		out(x);space;out(y);enter;
		--a;
		if(!a) break;
		for(auto t : pass[x][y]) {
			if(!vis[t.fi][t.se]) {
				for(auto k : pass[t.fi][t.se]) {
					--cnt[k.fi][k.se];
					Q.push(mp(-cnt[k.fi][k.se],k.fi * 2 * N + k.se));
				}
				vis[t.fi][t.se] = 1;
			}
		}

	}
}

