int N, D1, D2;


void dfs(int i, int j, bool stat) {
    // cout << i << " " << j << endl;
    vis[i][j] = true;
    usable[i][j] = stat;
    for (const auto& dd : diff) {
        int x = i + dd.first;
        int y = j + dd.second;
        if (x < 0 or x >= 2*N or y < 0 or y >= 2*N) continue;

        // cout << x << " " << y << " " << vis[x][endl;
        if (!vis[x][y]) dfs(x, y, !stat);
        if (stat == true) assert(!usable[x][y]);
    }
}

