    ios::sync_with_stdio(false);
    cin.tie(0); // Remove in problems with online queries!

    cin >> N >> D1 >> D2;
    set<pair<int,int>> diffS;
    for (int i = 0; i < 2*N; i++) for (int j = 0; j < 2*N; j++) {
        usable[i][j] = true;
        vis[i][j] = false;
        if (i*i + j*j == D1) {
            diffS.insert({i, j});
            diffS.insert({-i, j});
            diffS.insert({i, -j});
            diffS.insert({-i, -j});
