using namespace std;
long long int N, D1, D2;
set<pair<long long int, long long int>>X;

vector<pair<long long int, long long int>>recursive(long long int now, long long int count, vector<vector<int>>mapv){
	if( count >= N*N ){
		return vector<pair<long long int, long long int>>();
	}
	/*
	cout << now << " " << count << endl;

	for( auto x : mapv ){
		for( auto y : x ){
			cout << y;
		}
		cout << endl;
	}
	cout << endl;
	*/
	for( long long int idx = now + 1; idx < ( 2 * N )*( 2 * N ); idx++ ){
		long long int i = idx / ( 2 * N );
		long long int j = idx % ( 2 * N );
		if( mapv[i][j] == 0 ){
			auto cpmapv = mapv;
			cpmapv[i][j] = 1;
			for( auto s : X ){
				long long int i_ = i + s.first;
				long long int j_ = j + s.second;
				if( 0 <= i_ && i_ < 2 * N && 0 <= j_ && j_ < 2 * N ){
					cpmapv[i_][j_] = 1;
				}
			}
			auto ret = recursive(idx, count + 1, cpmapv);
			ret.push_back(make_pair(i, j));
			//cout << ret.size() + count << endl;
			if( ret.size() + count >= N*N ){
				return ret;
			}
		}
	}
	return vector<pair<long long int, long long int>>();
}

int main(){
	cin >> N >> D1 >> D2;
	for( long long int i = 0; i*i <= D1; i++ ){
		long long int j = sqrtl(D1 - i * i);
		if( j*j + i * i == D1 ){
			X.insert(make_pair(i, j));
			X.insert(make_pair(i, -j));
		}
	}
	for( long long int i = 0; i*i <= D2; i++ ){
		long long int j = sqrtl(D2 - i * i);
		if( j*j + i * i == D2 ){
			X.insert(make_pair(i, j));
			X.insert(make_pair(i, -j));
		}
	}

	auto ret = recursive(-1, 0, vector<vector<int>>(2 * N, vector<int>(2 * N)));
	for( auto r : ret ){
		cout << r.first << " " << r.second << endl;
	}
}

