// oo or ox or xo or xx

int main()
{
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n,d1,d2;
  cin>>n>>d1>>d2;
  vector<vector<int> > gr(2 * n, vector<int>(2 * n, 0));
  vector<vector<int> > alive(2 * n, vector<int>(2 * n, 1));
  vector<int> SQRT(4*n*n+1,-1);
  FOR(i,0,2*n+1){
    SQRT[i * i] = i;
  }
  FOR(t,0,2){
    int d = (t == 0 ? d1 : d2);
    FOR(i,0,2*n){
      FOR(j,0,2*n){
        if(gr[i][j] || alive[i][j] == 0) continue;
        gr[i][j] = 1; // 1:白,2:黒
        vector<P> que(1, P(i, j));
        FOR(k,0,que.size()){
          int x = que[k].first;
          int y = que[k].second;
          // 距離^2=dになる点を探す
          FOR(xx, 0, 2 * n){
            int dx = d1 - (x - xx) * (x - xx);
            if(dx >= 0 && dx <= 4 * n * n && SQRT[dx] != -1){
              dx = SQRT[dx];
              int yy = y - dx;
              if(yy >= 0 && yy < 2 * n && alive[xx][yy] && gr[xx][yy] == 0){
                gr[xx][yy] = 3 - gr[x][y];
                que.push_back(P(xx, yy));
              }
              yy = y + dx;
              if(yy >= 0 && yy < 2 * n && alive[xx][yy] && gr[xx][yy] == 0){
                gr[xx][yy] = 3 - gr[x][y];
                que.push_back(P(xx, yy));
              }
            }
          }
        }
        vector<int> cc(3, 0);
        for(auto p : que){
          cc[gr[p.first][p.second]]++;
        }
        int best = (cc[1] > cc[2] ? 1 : 2);
        for(auto p : que){
          if(gr[p.first][p.second] != best){
            alive[p.first][p.second] = 0;
          }
        }
      }
    }
  }

  int cc = n * n;
  FOR(i,0,2*n){
    FOR(j,0,2*n){
      if(alive[i][j]){
        cout << i << " " << j << endl;
        cc--;
        if(cc==0) return 0;
      }
    }
  }
}

