				if(d2-a[j-i]>=0&&ok[d2-a[j-i]]){
					int g=b[d2-a[j-i]];
					if(p>=g) vis[j][p-g]=1;
					if(p+g<n+n) vis[j][p+g]=1;
				}
			}
		}
	}
	return 0;
}

