using namespace std;
struct edge {
	int x, y, tp;
	edge() : x(-1), y(-1), tp(-1) {};
	edge(int x_, int y_, int tp_) : x(x_), y(y_), tp(tp_) {};
};
int main() {
	int N, D1, D2;
	cin >> N >> D1 >> D2;
	vector<vector<vector<edge> > > g(2 * N, vector<vector<edge> >(2 * N));
	for (int i = -2 * N; i <= 2 * N; ++i) {
		for (int j = -2 * N; j <= 2 * N; ++j) {
			int tp = -1;
			if (i * i + j * j == D1) tp = 0;
			if (i * i + j * j == D2) tp = 1;
			if (tp != -1) {
				for (int k = 0; k < 2 * N; ++k) {
					for (int l = 0; l < 2 * N; ++l) {
						if (0 <= k + i && k + i < 2 * N && 0 <= l + j && l + j < 2 * N) {
							g[k][l].push_back(edge(k + i, l + j, tp));
						}
					}
				}
			}
		}
	}
	vector<vector<int> > col(2 * N, vector<int>(2 * N));
	for (int i = 0; i < 2; ++i) {
		vector<vector<int> > dist(2 * N, vector<int>(2 * N, -1));
		for (int j = 0; j < 2 * N; ++j) {
			for (int k = 0; k < 2 * N; ++k) {
				if (dist[j][k] == -1) {
					dist[j][k] = 0;
					int c0 = 1, c1 = 0;
					queue<pair<int, int> > que; que.push(make_pair(j, k));
					vector<pair<int, int> > lis;
					while (!que.empty()) {
						pair<int, int> u = que.front(); que.pop();
						lis.push_back(u);
						for (edge e : g[u.first][u.second]) {
							if (e.tp == i && dist[e.x][e.y] == -1) {
								dist[e.x][e.y] = dist[u.first][u.second] ^ 1;
								que.push(make_pair(e.x, e.y));
								if (dist[e.x][e.y] == 0) ++c0;
								else ++c1;
							}
						}
					}
					for (pair<int, int> l : lis) {
						if ((dist[l.first][l.second] == 1) ^ (c0 > c1)) {
							col[l.first][l.second] |= 1 << i;
						}
					}
				}
			}
		}
	}
	int cnt = 0;
	for (int i = 0; i < 2 * N; ++i) {
		for (int j = 0; j < 2 * N; ++j) {
			if (col[i][j] == 0 && cnt++ < N * N) {
				cout << i << ' ' << j << '\n';
			}
		}
	}
	return 0;
}

