int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << setprecision(20);

    int n;
    V<int> dv(2);
    cin >> n >> dv[0] >> dv[1];
    int base = 1;
    VV<int> col2(2*n, V<int>(2*n));
    using P = pair<int, int>;
    for (int d: dv) {
        V<P> v;
        for (int h = -2*n; h <= 2*n; h++) {
            int rm = d - h*h;
            if (rm < 0) continue;
            int r = int(sqrt(rm) + 1e-9);
            if (h*h + r*r != d) continue;
            v.push_back(P(h, r));
            v.push_back(P(-h, r));
            v.push_back(P(h, -r));
            v.push_back(P(-h, -r));
        }
        sort(begin(v), end(v));
        v.erase(unique(begin(v), end(v)), end(v));
        g = VV<int>(4*n*n);
        for (int h = 0; h < 2*n; h++) {
            for (int r = 0; r < 2*n; r++) {
                for (auto p: v) {
                    int nh = h + p.first, nr = r + p.second;
                    if (!(0 <= nh && nh < 2*n && 0 <= nr && nr < 2*n)) continue;
                    int id1 = h*(2*n) + r;
                    int id2 = nh*(2*n) + nr;
                    g[id1].push_back(id2);
                }
            }
        }
        mark();
        for (int h = 0; h < 2*n; h++) {
            for (int r = 0; r < 2*n; r++) {
                int id = h*(2*n) + r;
                if (col[id]) col2[h][r] += base;
            }
        }
        base *= 2;
    }

    VV<P> pots(4);
    for (int h = 0; h < 2*n; h++) {
        for (int r = 0; r < 2*n; r++) {
            pots[col2[h][r]].push_back(P(h, r));
        }
    }
    sort(begin(pots), end(pots), [&](const V<P> &l, const V<P> &r){
        return l.size() > r.size();
    });
    auto ans = pots[0];
    assert(ans.size() >= n*n);
    ans.resize(n*n);
    for (auto p: ans) {
        cout << p.first << " " << p.second << '\n';
    }
    return 0;
}

