			for(auto k : sols) {
				if(i + k.first < 2*n && j + k.second < 2*n) {
					col[id(i + k.first, j + k.second)] = 3^col[id(i, j)];
				}
				if(k.second && i + k.first < 2*n && j - k.second >= 0) {
					col[id(i + k.first, j + k.second)] = 3^col[id(i, j)];
				}
			}
		}
	}
	if(l.size() < r.size()) swap(l, r);
	assert(l.size()>=n*n);
	for(int i = 0; i < n*n; i++)
		cout << l[i]/(2*n) << " " << l[i]%(2*n) << '\n';
}

