int N;
void fil(int i, int j){
	if(i < 0 || i >= 2 * N || j < 0 || j >= 2 * N)return;
	ban[i][j] = true;
}
int main(){
	int D1, D2;
	scanf("%d %d %d", &N, &D1, &D2);

	for(int i = 0; i < 2 * N; i += 1){
		if(i * i > D1) continue;
		int j = sqrt(D1 - i * i);
		if(j * j + i * i == D1)
			d.push_back({i, j}), d.push_back({i, -j}),
			d.push_back({-i, j}), d.push_back({-i, -j});
	}

	for(int i = 0; i < 2 * N; i += 1){
		if(i * i > D2) continue;
		int j = sqrt(D2 - i * i);
		if(j * j + i * i == D2)
			d.push_back({i, j}), d.push_back({i, -j}),
			d.push_back({-i, j}), d.push_back({-i, -j});
	}
	for(int he = 0; he < 2 * N; he += 1){
		for(int i = 0; i < 2 * N; i += 1)
			for(int j = 0; j < 2 * N ; j += 1)
				ans[i][j] = ban[i][j] = false;
		int c = 0;
		for(int i = 0; i < 2 * N; i += 1)
			for(int j = i ? 0 : he; j < 2 * N ; j += 1)
				if(ban[i][j] == false){
					ans[i][j] = true;
					for(int k = 0; k < d.size(); k += 1)
						fil(i + d[k].first, j + d[k].second);
					c += 1;
				}
		if(c < N * N) continue;
		int t = 0;
		for(int i = 0; i < 2 * N; i += 1)
			for(int j = 0; j < 2 * N ; j += 1)
				if(ans[i][j]){
					printf("%d %d\n", i, j);
					t += 1;
					if(t == N * N) return 0;
				}
	}
	assert(0);
	return 0;
}

