bool isSquare(int n) {
    int m = floor(sqrt(n));
    return (n == m * m);
}

int main() {
    int N, D1, D2;
    cin >> N >> D1 >> D2;
    int dl = min(D1, D2);
    int dh = max(D1, D2);
    bool lok = isSquare(dl);
    bool hok = isSquare(dh);
    int res = N * N;
    if (lok && hok) {
        int lsq = floor(sqrt(dl));
        int hsq = floor(sqrt(dh));
        int num = 0;
        for (int k = 0; k < N; k++) {
            for (int j = 0; j < lsq; j++) {
                for (int i = 0; i < 2 * N; i++) {
                    cout << i << " " << (i + num) % (2 * N) << endl;
                    res--;
                    num++;
                }
                if (res == 0) {
                    return 0;
                }
            }
            num += lsq;
            if (num >= hsq - lsq) {
                num += hsq;
                num = ((num + lsq - 1) / lsq) * lsq;
            }
        }
    }
}

