bool tk[Maxm][Maxm];
ii seq[Maxn];
int slen;
bool found;

bool Exist(int r, int c)
{
	return 0 <= r && r < 2 * n && 0 <= c && c < 2 * n && tk[r][c];
}

bool Check(int r, int c)
{
	for (int i = 0; i * i <= d1 || i * i <= d2; i++) {
		if (i * i <= d1) {
			int j = sqr[d1 - i * i];
			if (j != -1 && (Exist(r - i, c - j) || Exist(r - i, c + j) || Exist(r + i, c - j) || Exist(r + i, c + j)))
				return false;
		}
		if (i * i <= d2) {
			int j = sqr[d2 - i * i];
			if (j != -1 && (Exist(r - i, c - j) || Exist(r - i, c + j) || Exist(r + i, c - j) || Exist(r + i, c + j)))
				return false;
		}
	}
	return true;
}

void Gen(int r, int c)
{
	int lft = (2 * n - r - 1) * (2 * n) + 2 * n - c;
	if (slen + lft < n * n) return;
	if (slen >= n * n) {
		found = true;
		for (int i = 0; i < slen; i++)
			printf("%d %d\n", seq[i].first, seq[i].second);
		return;
	}
	if (c >= 2 * n) Gen(r + 1, 0);
	else if (r >= 2 * n) return;
	else {
		if (Check(r, c)) {
			seq[slen++] = ii(r, c); tk[r][c] = true;
			Gen(r, c + 1);
			slen--; tk[r][c] = false;
		}
		if (!found) Gen(r, c + 1);
	}
}

