        rep(k,dys.size()){
            int y=i+dys[k];
            int x=j+dxs[k];
            if(y<0||y>=2*N||x<0||x>=2*N)continue;
            int a=i*2*N+j;
            int b=y*2*N+x;
            uf.unite(2*a,2*b+1);
            uf.unite(2*a+1,2*b);
        }
    }
    set<int>rs;
    vint col(4*N*N);
