vector<P> enumerate(int D) {
  vector<P> ret;
  for (int x=0; x*x<=D; x++) {
    for (int y=0; y*y<=D; y++) {
      if (x*x+y*y != D) continue;
      ret.pb(P(x, y));
    }
  }
  return ret;
}

