vector<vector<bool>> go(int n, int d) {
    vector<vector<bool>> a(2 * n, vector<bool>(2 * n));
    if (d % 2 == 1) {
        for (int i = 0; i < 2 * n; i++) {
            for (int j = 0; j < 2 * n; j++) {
                if ((i + j) % 2) {
                    a[i][j] = true;
                }
            }
        }
    } else {
        if (d % 4 != 0) {
            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    if (i % 2) {
                        a[i][j] = true;
                    }
                }
            }
        } else {
            auto aa = go(n / 2, d / 4);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (aa[i][j]) {
                        for (int ii = 0; ii < 2; ii++) {
                            for (int jj = 0; jj < 2; jj++) {
                                a[2 * i + ii][2 * j + jj] = true;
                            }
                        }
                    }
                }
            }

        }
    }
    return a;
}

