int square_root[200005];
vector<pair<int, int>> v;

int chosen = 0;

bool inrange(int x, int y) {
  return 0 <= x && x < n*2 && 0 <= y && y < n*2;
}

void dfs(int x, int y) {
  printf("%d %d\n", x, y);
  if (++chosen == n*n) exit(0);
  vis[x][y] = true;

  for (pair<int, int> p: v) {
    int nx = x + p.first;
    int ny = y + p.second;

    if (inrange(nx, ny)) vis[nx][ny] = true;
  }

  for (pair<int, int> p: v) {
    int nx = x + p.first;
    int ny = y + p.second;

    if (!inrange(nx, ny)) continue;

    for (pair<int, int> q: v) {
      int nnx = nx + q.first;
      int nny = ny + q.second;

      if (inrange(nnx, nny) && !vis[nnx][nny]) dfs(nnx, nny);
    }
  }
}

