    }
  }
  ii opt = {-1, 0};
  for(int i = 0; i < 4; ++i) {
    opt = max(opt, {cnt[i], i});
  }
  int c0 = opt.se & 1;
  int c1 = opt.se >> 1 & 1;
  vector<ii> S;
  for(int i = 0; i < n; ++i) {
