int color[600][600][2];
const int dx[4] = {-1,-1,1,1};
const int dy[4] = {-1,1,1,-1};
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);

    auto calc=[](ll x, ll D) {
        if (x*x > D) return -1LL;
        ll ng = -1;
        ll ok = D+1;
        while (abs(ng-ok)>1) {
            ll mid = (ng+ok)/2;
            if (mid*mid+x*x>=D) ok = mid;
            else ng = mid; 
        }
        if (x*x+ok*ok==D) return ok;
        return -1LL;
    };

    ll N,D1,D2; cin >> N >> D1 >> D2;
    vector<vector<pll>> d(2);
    rep(i,N*2) {
        ll val = calc(i,D1);
        if (val != -1) d[0].emplace_back(i,val);
        val = calc(i,D2);
        if (val != -1) d[1].emplace_back(i,val);
    }

    rep(i,N*2) rep(j,N*2) rep(k,2) color[i][j][k] = -1;
    queue<pll> que;
    rep(i,N*2) {
        rep(j,N*2) {
            rep(k,2) {
                if (color[i][j][k]!=-1) continue;
                color[i][j][k] = 0;
                que.emplace(i,j);
                while (!que.empty()) {
                    auto[x,y] = que.front(); que.pop();
                    for (auto[ddx,ddy] : d[k]) {
                        rep(l,4) {
                            ll nx = x+ddx*dx[l];
                            ll ny = y+ddy*dy[l];
                            if (nx < 0 or nx >= N*2 or ny < 0 or ny >= N*2) continue;
                            if (color[nx][ny][k]!=-1) continue;
                            color[nx][ny][k] = 1 - color[x][y][k];
                            que.emplace(nx,ny);
                        }
                    }
                } 
            }
        }
    }

    vector<int> cnt(4);
    rep(i,N*2) {
        rep(j,N*2) {
            cnt[color[i][j][1]*2+color[i][j][0]]++;
        }
    }
    int n = max_element(all(cnt)) - cnt.begin();
    vector<pii> ans;
    rep(i,N*2) {
        rep(j,N*2) {
            if (color[i][j][0]==(n&1) and color[i][j][1]==((n>>1)&1)) {
                ans.emplace_back(i,j);
            }
        }
    }

    ans.resize(N*N);
    for (auto i : ans) print(i.first,i.second);
}

