void dfs(int n,int d,int id){
	for(int i=0;i<2*n;i++){
		for(int j=0;j<2*n;j++){
			used[i][j]=false;
		}
	}
	vector<pair<int,int>> vec;
	for(int i=0;i<2*n;i++){
		for(int j=0;j<2*n;j++){
			if(i*i+j*j==d){
				vec.push_back(make_pair(i,j));
				vec.push_back(make_pair(-i,j));
				vec.push_back(make_pair(i,-j));
				vec.push_back(make_pair(-i,-j));
			}
		}
	}
	sort(vec.begin(), vec.end());
	vec.erase(unique(vec.begin(), vec.end()),vec.end());
	for(int i=0;i<2*n;i++){
		for(int j=0;j<2*n;j++){
			if(used[i][j])continue;
			used[i][j]=1;
			queue<pair<int,int>> q;
			q.push(make_pair(i,j));
			while(q.size()){
				auto p=q.front(); q.pop();
				for(auto t:vec){
					int x=p.first+t.first,y=p.second+t.second;
					//cout << x << " " << y << endl;
					if(0<=x&&x<2*n&&0<=y&&y<2*n){
						if(used[x][y])continue;
						else{
							used[x][y]=1;
							col[id][x][y]=col[id][p.first][p.second]^1;
							q.push(make_pair(x,y));
						}
					}
				}
			}
		}
	}
}

