int N, D1, D2;
std::vector<int> G[360001];
short col[2][360001];
int cnt[4];

void mkG( int D )
{
  rep( i, 2*N ) rep( j, 2*N )
    G[i*2*N+j].clear();

  rep( i, 2*N ) rep( j, 2*N ) rep( k, 2*N ) if( (i-k)*(i-k) < D*D )
  {
    double d = sqrt( D-(i-k)*(i-k) );

    if( floor(d) == d )
    {
      int l;

      if( j+d < 2*N && !(i == k && j == j+d) )
      {
        l = j+d;
        G[i*2*N+j].push_back( k*2*N+l );
        G[k*2*N+l].push_back( i*2*N+j );
      }

      if( j-d >= 0 && !(i == k && j == j-d) )
      {
        l = j-d;
        G[i*2*N+j].push_back( k*2*N+l );
        G[k*2*N+l].push_back( i*2*N+j );
      }
    }
  }

  return;
}

void dfs( int v, int c, int idx )
{
  col[idx][v] = c;

  for( auto u : G[v] ) if( !col[idx][u] )
    dfs( u, -c, idx );

  return;
}

int main()
{
  scanf( "%d%d%d", &N, &D1, &D2 );

  mkG( D1 );
  rep( i, 2*N ) rep( j, 2*N ) if( !col[0][i*2*N+j] )
    dfs( i*2*N+j, 1, 0 );

  mkG( D2 );
  rep( i, 2*N ) rep( j, 2*N ) if( !col[1][i*2*N+j] )
    dfs( i*2*N+j, 1, 1 );

  rep( i, 2*N ) rep( j, 2*N ) 
  {
    int v = i*2*N+j;
    int kind = 0;

    rep( k, 2 ) rep( l, 2 )
    {
      if( col[0][v] == pow( -1, k ) && col[1][v] == pow( -1, l ) )
        ++cnt[kind];

      ++kind;
    }
  }

  int mkind = std::max_element( cnt, cnt+4 )-cnt;

  int sum = 0;

  rep( i, 2*N ) rep( j, 2*N ) 
  {
    int v = i*2*N+j;
    int kind = 0;

    rep( k, 2 ) rep( l, 2 )
    {
      if( col[0][v] == pow( -1, k ) && col[1][v] == pow( -1, l ) && kind == mkind && sum < N*N )
        printf( "%d %d\n", i, j ), ++sum;

      ++kind;
    }
