bool solve(vector<pair<int,int>> ord) {
    // static int hope = 0;
    // hope++;
    // cout << hope << endl;
    // dbg_var(ord);
    int cc = 0;
    vector<pair<int,int>> res;
    for (const auto pp : ord) {
        if (cc == N*N) break;
        int i = pp.first, j = pp.second;
        if (occ[i][j]) continue;
        occ[i][j] = true;
        cc++;
        res.push_back({i, j});
        for (const auto& dd : diff) {
            int x = i + dd.first;
            int y = j + dd.second;
            if (x < 0 or x >= 2*N or y < 0 or y >= 2*N) continue;
            occ[x][y] = true;
        }
    }
    if (cc == N*N) {
        for (auto pp : res) cout << pp.first << " " << pp.second << "\n";
        return true;
    }
    return false;
}

