constexpr int N = 3e5 + 10;
constexpr int M = 310;
constexpr int MOD = 998244353;

long long n, sq[N], d1, d2;
vector <pair <int, int>> v, ans, p;
bool is[N], in[2 * M][2 * M];

bool valid (int x) {
    if (x >= 0 && x < 2 * n)
        return true;
    return false;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
    srand (time(0));
    cin >> n >> d1 >> d2;
    for (int i = 0; i < 2 * n; i++)
        for (int j = 0; j < 2 * n; j++)
            p.push_back ({i, j});
    for (int i = 0; i * i < N; i++)
        is[i * i] = true, sq[i * i] = i;
    for (int i = 0; i <= d1; i++) {
        if (is[i] && is[d1 - i]) {
            v.push_back ({sq[i], sq[d1 - i]});
            v.push_back ({sq[i], -sq[d1 - i]});
            v.push_back ({-sq[i], sq[d1 - i]});
            v.push_back ({-sq[i], -sq[d1 - i]});
        }
    }
    for (int i = 0; i <= d2; i++) {
        if (is[i] && is[d2 - i]) {
            v.push_back ({sq[i], sq[d2 - i]});
            v.push_back ({-sq[i], sq[d2 - i]});
            v.push_back ({sq[i], -sq[d2 - i]});
            v.push_back ({-sq[i], -sq[d2 - i]});
        }
    }
    while ((int)ans.size() != (n * n)) {
        int id = rand() % ((int)p.size());
        if (id < 0)
            id = -id;
        int i = p[id].first;
        int j = p[id].second;
        bool can = true;
        for (auto k : v) {
            if (valid (i + k.first) && valid (j + k.second) && in[i + k.first][j + k.second])
            can = false;
            if (!can)
                break;
        }
        if (can) {
            ans.push_back ({i, j});
            in[i][j] = true;
        }
        swap (p[id], p.back());
        p.pop_back();
    }
    for (int i = 0; i < n * n; i++)
        cout << ans[i].first << ' ' << ans[i].second << '\n';
    return 0;
}

