    SimpleAdjacencyList g_2(4 * N * N);

    auto to_id = [N](auto x, auto y ) { return 2 * N * x + y; };
    auto to_p = [N](auto id) -> pair<i64, i64> {
        i64 y = id % (2 * N);
        i64 x = (id - y) / (2 * N);
        return make_pair(x, y);
    };

    // グラフの構築
    REP (x, 2 * N) {
        REP (y, 2 * N) {
            auto id1 = to_id(x, y);
            FOR (i, x, 2 * N) {
                i64 j_1 = std::sqrt(D1 - i * i);
                i64 j_2 = std::sqrt(D2 - i * i);

                if (i * i + j_1 * j_1 == D1) {
                    g_1.add_edge(make_tuple(id1, to_id(i, j_1)));
                }
                if (i * i + j_2 * j_2 == D2) {
                    g_2.add_edge(make_tuple(id1, to_id(i, j_2)));
                }
            }
        }
    }

    // 彩色
    OrderedSet<i64> V11, V12;
    REP (id, 4 * N * N) {
        std::stack<pair<i64, i64>> s;
        s.emplace(-1, id);
        while (!s.empty()) {
            auto elem = s.top();
            s.pop();
            auto prev = elem.first;
            auto x = elem.second;

            if (V11.find(x) != V11.end() || V12.find(x) != V12.end()) {
                continue;
            }

            if (prev == -1 || V12.find(prev) != V12.end()) {
                V11.emplace(x);
            } else {
                V12.emplace(x);
            }

            EACH_V (edge, g_1.outgoings(x)) {
                s.emplace(get<0>(edge), get<1>(edge));
            }
        }
    }

    OrderedSet<i64> V21, V22;
    REP (id, 4 * N * N) {
        std::stack<pair<i64, i64>> s;
        s.emplace(-1, id);
        while (!s.empty()) {
            auto elem = s.top();
            s.pop();
            auto prev = elem.first;
            auto x = elem.second;

            if (V21.find(x) != V21.end() || V22.find(x) != V22.end()) {
                continue;
            }

            if (prev == -1 || V22.find(prev) != V22.end()) {
                V21.emplace(x);
            } else {
                V22.emplace(x);
            }

            EACH_V (edge, g_2.outgoings(x)) {
                s.emplace(get<0>(edge), get<1>(edge));
            }
        }
    }

    // よい集合の抽出
    {
        // V11-V21の組み合わせ
        OrderedSet<pair<i64, i64>> ps;
        EACH (v, V11) {
            if (V21.find(v) != V21.end()) {
                ps.insert(to_p(v));
            }
        }
        if (ps.size() >= N * N) {
            int cnt = 0;
            EACH (p, ps) {
                cout << p.first << " " << p.second << endl;
                cnt += 1;
                if (cnt >= N * N) break;
            }
            return ;
        }
    }
    {
        // V11-V22の組み合わせ
        OrderedSet<pair<i64, i64>> ps;
        EACH (v, V11) {
            if (V22.find(v) != V22.end()) {
                ps.insert(to_p(v));
            }
        }
        if (ps.size() >= N * N) {
            int cnt = 0;
            EACH (p, ps) {
                cout << p.first << " " << p.second << endl;
                cnt += 1;
                if (cnt >= N * N) break;
            }
            return ;
        }
    }

    {
        // V12-V21の組み合わせ
        OrderedSet<pair<i64, i64>> ps;
        EACH (v, V12) {
            if (V21.find(v) != V21.end()) {
                ps.insert(to_p(v));
            }
        }
        if (ps.size() >= N * N) {
            int cnt = 0;
            EACH (p, ps) {
                cout << p.first << " " << p.second << endl;
                cnt += 1;
                if (cnt >= N * N) break;
            }
            return ;
        }
    }
    {
        // V12-V22の組み合わせ
        OrderedSet<pair<i64, i64>> ps;
        EACH (v, V12) {
            if (V22.find(v) != V22.end()) {
                ps.insert(to_p(v));
            }
        }
        if (ps.size() >= N * N) {
            int cnt = 0;
            EACH (p, ps) {
                cout << p.first << " " << p.second << endl;
                cnt += 1;
                if (cnt >= N * N) break;
            }
            return ;
        }
    }
}

