int N, D1, D2;
void dfs(int x, int y, vi &col, set<pii> &dir, int a=0) {
    if (x < 0 || x >= 2 * N || y < 0 || y >= 2 * N)return;
    if (col[x * 2 * N + y] != -1)return;
    col[x * 2 * N + y] = a;
    each(d, dir) {
        dfs(x + d.first, y + d.second, col, dir, 1 - a);
    }
}

void solve() {
    cin >> N >> D1 >> D2;

    map<int, int> S;
    for (int i = 0; i < 2 * N; ++i) {
        S[i*i] = i;
    }
    auto f = [&](int D) {
        set<pii> dir;
        for (int i = 0; i < 2 * N; ++i) {
            int jj = D - i*i;
            if (S.count(jj)) {
                int j = S[jj];
                for (int a : {-1, 1})for (int b : {-1, 1}) {
                    dir.insert({ a*i, b*j });
                }
            }
        }
        vi col(2 * N * 2 * N, -1);
        rep(x, 2 * N)rep(y, 2 * N) {
            if (col[x * 2 * N + y] == -1) {
                dfs(x, y, col, dir);
            }
        }
        return col;
    };

    auto C1 = f(D1);
    auto C2 = f(D2);

    int cnt[2][2] = {};
    rep(i, 2 * N * 2 * N) {
        cnt[C1[i]][C2[i]]++;
    }

    rep(i, 2)rep(j, 2) {
        if (cnt[i][j] >= N * N) {
            int z = 0;
            rep(x, 2 * N)rep(y, 2 * N) {
                int k = x * 2 * N + y;
                if (C1[k] == i && C2[k] == j) {
                    z++;
                    cout << x << ' ' << y << endl;
                    if (z == N * N) {
                        return;
                    }
                }
            }
        }
    }
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

