            if(y<0||y>=2*N||x<0||x>=2*N)continue;
            int a=i*2*N+j;
            int b=y*2*N+x;
            uf.unite(2*a,2*b+1);
            uf.unite(2*a+1,2*b);
        }
    }
    set<int>rs;
    vint col(4*N*N);
    rep(i,4*N*N){
        if(rs.find(uf.find(2*i+1))!=rs.end()){
            col[i]=1;
            continue;
        }
        col[i]=0;
        rs.insert(uf.find(2*i));
    }
    return col;
}

