set<pair<int, pair<int, int>>> s;

bool valid(int i, int j)
{
	if (i < 0)
		return false;
	if (j < 0)
		return false;
	if (i >= 2 * n)
		return false;
	if (j >= 2 * n)
		return false;
	return true;
}

int main()
{
	ios::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	cin >> n >> d1 >> d2;
	for (int i = 0; i * i <= MAXN; i++)
	{
		for (int j = 0; j * j <= MAXN; j++)
		{
			int val = (i * i + j * j);
			if (val == d1 || val == d2)
			{
				go.push_back({i, j});
			}
		}
	}
	for (int i = 0; i < 2 * n; i++)
	{
		for (int j = 0; j < 2 * n; j++)
		{
			for (auto e : go)
			{
				if (valid(i + e.first, j + e.second))
					badi[i][j]++;
				if (valid(i - e.first, j + e.second))
					badi[i][j]++;
				if (valid(i + e.first, j - e.second))
					badi[i][j]++;
				if (valid(i - e.first, j - e.second))
					badi[i][j]++;
			}
			if (badi[i][j])
				s.insert({-badi[i][j], {i, j}});
		}
	}
	while (s.size())
	{
		auto tp = *s.begin();
		s.erase(s.begin());
		int x = tp.second.first;
		int y = tp.second.second;
		dead[x][y] = true;
		for (auto e : go)
		{
			int i = 0, j = 0;
			i = x + e.first;
			j = y + e.second;
			if (valid(i, j) && !dead[i][j])
			{
				s.erase({-badi[i][j], {i, j}});
				badi[i][j]--;
				if (badi[i][j])
					s.insert({-badi[i][j], {i, j}});
			}
			i = x + e.first;
			j = y - e.second;
			if (valid(i, j) && !dead[i][j])
			{
				s.erase({-badi[i][j], {i, j}});
				badi[i][j]--;
				if (badi[i][j])
					s.insert({-badi[i][j], {i, j}});
			}
			i = x - e.first;
			j = y + e.second;
			if (valid(i, j) && !dead[i][j])
			{
				s.erase({-badi[i][j], {i, j}});
				badi[i][j]--;
				if (badi[i][j])
					s.insert({-badi[i][j], {i, j}});
			}
			i = x - e.first;
			j = y - e.second;
			if (valid(i, j) && !dead[i][j])
			{
				s.erase({-badi[i][j], {i, j}});
				badi[i][j]--;
				if (badi[i][j])
					s.insert({-badi[i][j], {i, j}});
			}
		}
	}
	int cnt = 0;
	for (int i = 0; cnt < n * n && i < 2 * n; i++)
	{
		for (int j = 0; cnt < n * n && j < 2 * n; j++)
		{
			if (!dead[i][j])
			{
				cout << i << ' ' << j << '\n';
				cnt++;
			}
		}
	}
	return 0;
}

