int root(int x)
{
	if (pa[x]==x) return x;
	int rt=root(pa[x]);
	val[x]^=val[pa[x]];
	return pa[x]=rt;
}
void Union(int x,int y)
{
	int rx=root(x),ry=root(y);
	if (rx==ry) return;
	pa[rx]=ry;val[rx]=(1^val[x]^val[y]);
}
void Init()
{
	memset(sq,-1,sizeof(sq));
	for (int i=0;i<=500;i++) sq[i*i]=i;
}
int get(int x,int y)
{
	return (x-1)*n+y;
}
bool In(int x,int y)
{
	return (x>=1 && x<=n && y>=1 && y<=n);
}
void addedge(int x,int y)
{
	Union(x,y);
}
