using namespace std;
typedef pair<llint, llint> P;

llint n;
llint d1, d2;
llint color1[605][605], color2[605][605];
llint cnt[2][2];
vector<P> G[605][605];
int sq[400005];

void make(llint x, llint y, llint d)
{
	for(int i = -605; i <= 605; i++){
		if(x+i < 0 || x+i >= 2*n) continue;
		int j = d-i*i;
		if(j < 0 || sq[j] == -1) continue;

		int nx = x+i, ny = y + sq[j];
		if(ny < 0 || ny >= 2*n) continue;
		G[x][y].push_back(make_pair(nx, ny));

		nx = x+i, ny = y - sq[j];
		if(ny < 0 || ny >= 2*n) continue;
		G[x][y].push_back(make_pair(nx, ny));
	}
}

void dfs(int x, int y, int c, llint color[605][605])
{
	color[x][y] = c;
	for(int i = 0; i < G[x][y].size(); i++){
		P u = G[x][y][i];
		if(color[u.first][u.second]) continue;
		dfs(u.first, u.second, -c, color);
	}
}

void solve(llint d, llint color[605][605])
{
	for(int i = 0; i < 2*n; i++){
		for(int j = 0; j < 2*n; j++){
			G[i][j].clear();
		}
	}
	for(int i = 0; i < 2*n; i++){
		for(int j = 0; j < 2*n; j++){
			make(i, j, d);
		}
	}
	/*for(int i = 0; i < 2*n; i++){
		for(int j = 0; j < 2*n; j++){
			cout << "(" << i << "," << j << ") :";
			for(int k = 0; k < G[i][j].size(); k++) cout << "(" << G[i][j][k].first << "," << G[i][j][k].second << ") "; cout <<endl;
		}
	}
	cout << endl;*/
	for(int i = 0; i < 2*n; i++){
		for(int j = 0; j < 2*n; j++){
			if(color[i][j] == 0) dfs(i, j, 1, color);
		}
	}
	for(int i = 0; i < 2*n; i++){
		for(int j = 0; j < 2*n; j++){
			if(color[i][j] == -1) color[i][j] = 0;
		}
	}
}

int main(void)
{
	cin >> n >> d1 >> d2;

	for(int i = 0; i < 400005; i++) sq[i] = -1;
	for(int i = 0; i < 605; i++) sq[i*i] = i;

	solve(d1, color1);
	solve(d2, color2);

	for(int i = 0; i < 2*n; i++){
		for(int j = 0; j < 2*n; j++){
			cnt[color1[i][j]][color2[i][j]]++;
		}
	}
	for(int i = 0; i < 2; i++){
		for(int j = 0; j < 2; j++){
