			int rem = n*n;
			for(int k = 0; k < 2*n; k++){
				for(int l = 0; l < 2*n; l++){
					if(rem > 0 && color1[k][l] == i && color2[k][l] == j){
						cout << k << " " << l << endl;
						rem--;
					}
				}
			}
