    for(ll i=0;i<maxn;i++){
        ll aa=a-i*i;
        ll bb=b-i*i;
        if(aa>=0){
            if(sq[aa]!=0){
                vec.pb(mp(i,sq[aa]-1));
                vec.pb(mp(-i,sq[aa]-1));
                vec.pb(mp(i,-(sq[aa]-1)));
                vec.pb(mp(-i,-(sq[aa]-1)));
            }
        }
        if(bb>=0){
            if(sq[bb]!=0){
                vec.pb(mp(i,sq[bb]-1));
                vec.pb(mp(-i,sq[bb]-1));
                vec.pb(mp(i,-(sq[bb]-1)));
                vec.pb(mp(-i,-(sq[bb]-1)));
