vector< pair<int, int> > solve(int N, int D[2]) {
	vector< pair<int, int> > ret;
	if(D[0]%4 != 0 && D[1]%4 != 0) {
		for(int i = 0; i < 2*N; i += 2) for(int j = 0; j < 2*N; j += 2)
			ret.push_back({i, j});
		return ret;
	}
	if(D[0]%4 == 0 && D[1]%4 == 0) {
		if(N%2 == 0) {
			int Dh[2] = {D[0]/4, D[1]/4};
			vector< pair<int, int> > reth = solve(N/2, Dh);
			ALL_THE(reth, it) for(int i = 0; i < 2; i++) for(int j = 0; j < 2; j++)
				ret.push_back({it->ff*2+i, it->ss*2+j});
			return ret;
		}
		else {
			if(N == 1) return {{0, 0}};
			int Dh[2] = {D[0]/4, D[1]/4};
			vector< pair<int, int> > reth = solve(N/2+1, Dh);
			for(int i = 0; i < 2; i++) for(int j = 0; j < 2; j++) {
				int cnt[4] = {};
				ALL_THE(reth, it) for(int k = 0; k < 4; k++) {
					int x = it->ff, y = it->ss;
					if(k&1) x = N-x;
					if(k&2) y = N-y;
					if(x*2+i < 2*N && y*2+j < 2*N) cnt[k]++;
				}
				int mx = 0;
				for(int k = 0; k < 4; k++) mx = max(mx, cnt[k]);
				for(int k = 0; k < 4; k++) if(mx == cnt[k]) {
					ALL_THE(reth, it) {
						int x = it->ff, y = it->ss;
						if(k&1) x = N-x;
						if(k&2) y = N-y;
						if(x*2+i < 2*N && y*2+j < 2*N) ret.push_back({x*2+i, y*2+j});
					}
					break;
				}
			}
			assert(ret.size() >= N*N);
			ret.resize(N*N);
			return ret;
		}
	}
	if(D[0]%4 != 0) swap(D[0], D[1]);
	vector< pair<int, int> > V;
	for(int i = -N; i <= N; i++) for(int j = -N; j <= N; j++)
		if(i*i+j*j == D[0]/4) V.push_back({i, j});
	vector< vector<int> > lbl(N, vector<int>(N, -1));
	queue< pair<int, int> > q;
	for(int i = 0; i < N; i++) for(int j = 0; j < N; j++) if(lbl[i][j] == -1) {
		q.push({i, j});
		lbl[i][j] = 0;
		while(!q.empty()) {
			ALL_THE(V, it) if(q.front().ff+it->ff >= 0 && q.front().ss+it->ss >= 0) {
				if(q.front().ff+it->ff >= N || q.front().ss+it->ss >= N) continue;
				if(lbl[q.front().ff+it->ff][q.front().ss+it->ss] == -1) {
					lbl[q.front().ff+it->ff][q.front().ss+it->ss] = 1-lbl[q.front().ff][q.front().ss];
					q.push({q.front().ff+it->ff, q.front().ss+it->ss});
				}
			}
			q.pop();
		}
	}
	for(int i = 0; i < N; i++) for(int j = 0; j < N; j++) {
		int x = 2*i, y = 2*j;
		if(D[1]%4 != 2) x += lbl[i][j], y += lbl[i][j];
		else x += lbl[i][j];
		ret.push_back({x, y});
	}
	return ret;
}

