int Id(int x,int y)
{
	return x*2*n+y+1;
}
void Addedge(int u,int v)
{
	Adj[++l]=v;
	Nxt[l]=Head[u];
	Head[u]=l;
	Adj[++l]=u;
	Nxt[l]=Head[v];
	Head[v]=l;
}
int main()
{
	scanf("%d%d%d",&n,&d1,&d2);
	if(d1>d2)
		swap(d1,d2);
	for(i=0;i*i<=d1;++i)
	{
		j=(int)sqrt(d1-i*i);
		if(i*i+j*j!=d1)
			continue;
		for(x=0;x<2*n;++x)
			for(y=0;y<2*n;++y)
			{
				if(i==0)
				{
					if(y+j<2*n)
						Addedge(Id(x,y),Id(x,y+j));
				}
				else
				{
					if(x+i<2*n)
					{
						if(y+j<2*n)
							Addedge(Id(x,y),Id(x+i,y+j));
						if(y-j>=0&&j)
							Addedge(Id(x,y),Id(x+i,y-j));
					}
				}
			}
	}
	for(i=0;i*i<=d2;++i)
	{
		j=(int)sqrt(d2-i*i);
