						Addedge(Id(x,y),Id(x,y+j));
					}
				}
				else
				{
					if(x+i<2*n)
					{
						if(y+j<2*n)
							Addedge(Id(x,y),Id(x+i,y+j));
						if(y-j>=0&&j)
							Addedge(Id(x,y),Id(x+i,y-j));
					}
				}
			}
	}
	for(x=2*n-1;x>=0&&cnt<n*n;--x)
