vector<PII> greedy() {
	vector<PII> w;
	vector<PII> v;
	FOR(i,0,2*n) FOR(j,0,2*n) v.pb(mp(i,j));
	vector<pair<int,PII>> vv;
	FOR(i,0,2*n) FOR(j,0,2*n) vv.pb(mp(abs(n-i)+abs(n-j),mp(i,j)));
	sort(all(vv));
	FOR(i,0,2*n*2*n) {
		v[i] = vv[i].nd;
	}
	while (1) {
		w.clear();
		FOR(i,0,2*n) FOR(j,0,2*n) dobre[i][j] = 0;
		int kutas = 0;
		FOR(ii,0,4*n*n) {
			int i = v[ii].st;
			int j = v[ii].nd;
			if (dobre[i][j] == -1) continue;
			w.pb(mp(i,j));
			dobre[i][j] = 1;
			FOR(u,0,2) FOR(w,0,2) {
				FORE(z, zle) { 
						int ni = (2*u-1)*z->st + i;
						int nj = (2*w-1)*z->nd + j;
						if (ni >= 0 && nj >= 0 && ni<2*n && nj<2*n) {
							if (dobre[ni][nj] != -1) kutas++;
