using namespace std;

int N, D1, D2, dp[609][609]; bool used[609][609]; vector<pair<int, int>>v1, v2, p1, p2;
vector<pair<int, int>>x[609][609];

void dfs(int px, int py, int depth) {
	if (dp[px][py] >= 0) return;
	dp[px][py] = depth;
	if (depth == 0) p1.push_back(make_pair(px, py));
	else p2.push_back(make_pair(px, py));

	for (int i = 0; i < x[px][py].size(); i++) {
		dfs(x[px][py][i].first, x[px][py][i].second, depth ^ 1);
	}
}

int main() {
	cin >> N >> D1 >> D2;
	for (int i = -2 * N; i <= 2 * N; i++) {
		for (int j = -2 * N; j <= 2 * N; j++) {
			if (i*i + j*j == D1) v1.push_back(make_pair(i, j));
			if (i*i + j*j == D2) v2.push_back(make_pair(i, j));
		}
	}
	for (int i = 0; i < 2 * N; i++) {
		for (int j = 0; j < 2 * N; j++) {
			dp[i][j] = -1;
			for (int k = 0; k < v1.size(); k++) {
				int cx = i + v1[k].first, cy = j + v1[k].second;
				if (cx < 0 || cy < 0 || cx >= 2 * N || cy >= 2 * N) continue;
				x[i][j].push_back(make_pair(cx, cy));
			}
		}
	}
	vector<pair<int, int>>V;
	for (int i = 0; i < 2 * N; i++) {
		for (int j = 0; j < 2 * N; j++) {
			if (dp[i][j] != -1) continue;
			p1.clear(); p2.clear();
			dfs(i, j, 0);
			if (p1.size() > p2.size()) swap(p1, p2);
			for (int k = 0; k < p2.size(); k++) V.push_back(p2[k]);
		}
	}
	for (int i = 0; i < V.size(); i++) used[V[i].first][V[i].second] = true;

	for (int i = 0; i < 2 * N; i++) { for (int j = 0; j < 2 * N; j++) { dp[i][j] = -1; x[i][j].clear(); } }

	for (int i = 0; i < 2 * N; i++) {
		for (int j = 0; j < 2 * N; j++) {
			if (used[i][j] == false) continue;
			for (int k = 0; k < v2.size(); k++) {
				int cx = i + v2[k].first, cy = j + v2[k].second;
				if (cx < 0 || cy < 0 || cx >= 2 * N || cy >= 2 * N || used[cx][cy] == false) continue;
				x[i][j].push_back(make_pair(cx, cy));
			}
		}
	}
	vector<pair<int, int>>W;
	for (int i = 0; i < 2 * N; i++) {
		for (int j = 0; j < 2 * N; j++) {
			if (dp[i][j] != -1 || used[i][j] == false) continue;
			p1.clear(); p2.clear();
			dfs(i, j, 0);
			if (p1.size() > p2.size()) swap(p1, p2);
			for (int k = 0; k < p2.size(); k++) W.push_back(p2[k]);
		}
	}
	for (int i = 0; i < N*N; i++) {
		cout << W[i].first << " " << W[i].second << endl;
	}
	return 0;
}

