#include <bits/stdc++.h>
#define pb  push_back
#define mp  make_pair
#define v1  first
#define v2  second
using namespace std;

typedef pair <int,int>  PII;
const int N=605;
int n,d1,d2,vis[N][N];
vector <PII> V;

void dfs(int x,int y)
{
	for (auto d:V)
		if ((0<=x+d.v1)&&(x+d.v1<2*n)&&(0<=y+d.v2)&&(y+d.v2<2*n))
			if (!vis[x+d.v1][y+d.v2])
				{
					vis[x+d.v1][y+d.v2]=vis[x][y]^1;
					dfs(x+d.v1,y+d.v2);
				}
}

void solve(int d)
{
	V.clear();
	for (int i=-2*n+1; i<2*n; i++)
		for (int j=-2*n+1; j<2*n; j++)
			if (i*i+j*j==d)
				V.pb(mp(i,j));
	for (int i=0; i<2*n; i++)
		for (int j=0; j<2*n; j++)
			if (!vis[i][j])
				vis[i][j]=2,dfs(i,j);
	int cnt2=0,cnt3=0;
	for (int i=0; i<2*n; i++)
		for (int j=0; j<2*n; j++)
			{
				cnt2+=(vis[i][j]==2);
				cnt3+=(vis[i][j]==3);
			}
	if (cnt2<cnt3)
		{
			for (int i=0; i<2*n; i++)
				for (int j=0; j<2*n; j++)
					if (vis[i][j]>1)
						vis[i][j]^=1;
		}
	for (int i=0; i<2*n; i++)
		for (int j=0; j<2*n; j++)
			if (vis[i][j]>1)
				vis[i][j]-=2;
}

void work()
{
	scanf("%d %d %d",&n,&d1,&d2);
	solve(d1),solve(d2);
	for (int i=0,k=n*n; i<2*n; i++)
		for (int j=0; j<2*n; j++)
			if ((!vis[i][j])&&(k>0))
				printf("%d %d\n",i,j),k--;
}

int main()
{
	work();
	return 0;
}

