const int N=360005;
int n,d1,d2,col[N],ans[N],t[4],dx[]={1,1,-1,-1},dy[]={1,-1,1,-1};
vector<int>E[N];
int p(int x,int y){
	return x*n*2+y;
}
void dfs(int u,int c){
	col[u]=c;
	for(int v:E[u])if(!~col[v])dfs(v,c^1);
}
void solve(int d,int v){
	for(int i=0;i<4*n*n;++i)E[i].clear(),col[i]=-1;
	for(int x=0;x<n+n;++x){
		if(x*x>d)continue;
		int y=sqrt(d-x*x);
		if(x*x+y*y!=d)continue;
		for(int i=0;i<n+n;++i)
			for(int j=0;j<n+n;++j)
				for(int k=0;k<4;++k){
					int ii=i+dx[k]*x,jj=j+dy[k]*y;
					if(ii<0||ii>=n+n||jj<0||jj>=n+n)continue;
					E[p(i,j)].push_back(p(ii,jj));
				}
	}
	for(int i=0;i<4*n*n;++i){
		if(col[i]==-1)dfs(i,0);
		ans[i]|=col[i]<<v;
	}
}
int main(){
	scanf("%d%d%d",&n,&d1,&d2);
	solve(d1,0);solve(d2,2);
	for(int i=0;i<4*n*n;++i)++t[ans[i]];
	for(int c=0;c<4;++c)
		if(t[c]>=n*n)
			for(int i=0,cnt=n*n;i<4*n*n;++i)
					if(ans[i]==c){
						printf("%d %d\n",i/(n+n),i%(n+n));
						if(!--cnt)return 0;
					}
}

