void make_forbid(int X)
{
  for (int i = 0; i <= 2 * N; i++)
  {
    int j = round(sqrt(X - i * i));
    if (i * i + j * j == X)
    {
      F.push_back(P(i, j));
      F.push_back(P(-i, j));
      F.push_back(P(i, -j));
      F.push_back(P(-i, -j));
      F.push_back(P(j, i));
      F.push_back(P(j, -i));
      F.push_back(P(-j, i));
      F.push_back(P(-j, -i));
    }
  }
}

bool valid(P p)
{
  int x = p.real();
  int y = p.imag();
  return (0 <= x && x < 2 * N) && (0 <= y && y < 2 * N);
}

