#define pii pair<int,int>
#define fir first
#define sec second
#define makr(x,y) make_pair(x,y)

const int N=666;

int n,m,d1,d2,wt;

bool mp[N][N];

void check(int x,int y,int d)
{
	int b=-2*y,c,t,t2;
	for(int i=0;i<=m;++i)
	{
		c=y*y-d-2*i*x+i*i+x*x;
		t=b*b-4*c;
		if(t<0)
			continue;
		t2=sqrt(t);
		if(t2*t2!=t)
			continue;
		t=-b+t2;
		if(0<=t&&!(t&1)&&(t>>=1)<=m)
			mp[i][t]=false;
		t=-b-t2;
		if(0<=t&&!(t&1)&&(t>>=1)<=m)
			mp[i][t]=false;
	}
}

vector<pii> res;

int main()
{
	scanf("%d%d%d",&n,&d1,&d2);
	m=(n<<1)-1;
	wt=n*n;
	memset(mp,1,sizeof mp);
	bool fl=true;
	for(int i=0;i<=m&&fl;++i)
		for(int j=0;j<=m;++j)if(mp[i][j])
		{
			res.push_back(makr(i,j));
			if((int)res.size()==wt)
			{
				fl=false;
				break;
			}
			check(i,j,d1);
			check(i,j,d2);
		}
	if(fl)
	{
		res.clear();
		for(int i=0;i<=m;++i)
			for(int j=0;j<=m;++j)if(!mp[i][j])
			{
				memset(mp,1,sizeof 1);
				res.push_back(makr(i,j));
				check(i,j,d1);
				check(i,j,d2);
				mp[i][j]=false;
			}
		for(int i=0;i<=m&&fl;++i)
			for(int j=0;j<=m;++j)if(mp[i][j])
			{
				res.push_back(makr(i,j));
				if((int)res.size()==wt)
				{
					fl=false;
					break;
				}
				check(i,j,d1);
				check(i,j,d2);
			}
	}
	for(pii p:res)
		printf("%d %d\n",p.fir,p.sec);
	return 0;
}

