#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>

using namespace std;

vector<vector<int>> make_graph(int n, int d) {
  int N = n * 2;
  vector<vector<int>> ans(N * N);
  for (int i = 0; i * i <= d; i = -i + (i <= 0)) {
    for (int j = 0; i * i + j * j <= d; j = -j + (j <= 0)) {
      if (i * i + j * j == d) {
        for (int y = 0; y < N; y++) {
          for (int x = 0; x < N; x++) {
            int yy = y + i;
            int xx = x + j;
            if (yy < 0 || xx < 0 || yy >= N || xx >= N) continue;
            ans[y * N + x].push_back(yy * N + xx);
          }
        }
      }
    }
  }
  return ans;
}

vector<int> coloring(vector<vector<int>> g) {
  vector<int> ans(g.size(), 2);
  for (int i = 0; i < g.size(); i++) {
    if (ans[i] != 2) continue;
    ans[i] = 0;
    queue<int> q;
    q.push(i);
    while (!q.empty()) {
      int u = q.front(); q.pop();
      for (int v : g[u]) {
        if (ans[v] == 2) {
          ans[v] = ans[u] ^ 1;
          q.push(v);
        }
      }
    }
  }
  return ans;
}

int main() {
  int n, d1, d2;
  cin >> n >> d1 >> d2;
  int N = n * 2;
  auto g1 = make_graph(n, d1);
  auto g2 = make_graph(n, d2);
  vector<int> c1 = coloring(g1);
  vector<int> c2 = coloring(g2);
  vector<int> cnt(4);
  for (int i = 0; i < c1.size(); i++) {
    cnt[c1[i] << 1 | c2[i]]++;
  }
  int k = max_element(cnt.begin(), cnt.end()) - cnt.begin();
  int left = n * n;
  for (int i = 0; i < n * 2; i++) {
    for (int j = 0; j < n * 2; j++) {
      int u = i * n * 2 + j;
      if ((c1[u] << 1 | c2[u]) == k && left > 0) {
        left--;
        cout << i << ' ' << j << endl;
      }
    }
  }
}

