int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N, R[2];
    cin >> N >> R[0] >> R[1];

    set<P<ll, ll>> taboo;
    REP(i, 2) {
        for (ll x = 0; sq(x) <= R[i]; x++) {
            ll y = sqrt(R[i] - sq(x)) + EPS;
            if (sq(x) + sq(y) == R[i]) {
                REP(j, 4) {
                    taboo.insert(mp(x * six[j], y * siy[j]));
                }
            }
        }
    }

    V<V<bool>> ok(N * 2, V<bool>(N * 2, true));
    V<V<bool>> used(N * 2, V<bool>(N * 2, false));
    ll cnt = 0;
    while (cnt < sq(N)) {
        ll x = rand() % (N * 2);
        ll y = rand() % (N * 2);
        if (!used[x][y] && ok[x][y]) {
            cnt++;
            used[x][y] = true;
            cout << x << " " << y << endl;

            for (auto p : taboo) {
                ll sx = x + p.fst;
                ll sy = y + p.snd;
                if (sx < 0 || sx >= N * 2 || sy < 0 || sy >= N * 2) continue;
                ok[sx][sy] = false;
            }
        }
    }
    return 0;
}

