		int t=a[i].t;
		if(col[t]==1&&xx==1)
			xx=2;
	}
	col[d]=xx;
	for(i=head[d];i!=0;i=a[i].next)
	{
		int t=a[i].t;
		if(col[t]==0)
			dfs(t,3-xx);
	}
}
