void dfs(int x , int y , int w) {
    if (x < 0 || x >= n + n || y < 0 || y >= n + n) return;
    if (d[x][y]) return;
    p[w].emplace_back(x , y); d[x][y] = w;
    for (int k = 0 ; k < dx.size() ; ++ k) {
        dfs(x + dx[k] , y + dy[k] , 3 - w);
    }
}

