    for (int i = 0 ; i < 2 * n ; ++ i) {
        for (int j = 0 ; j < 2 * n ; ++ j) {
            if (!d[i][j]) {
                p[1].clear();
                p[2].clear();
                dfs(i , j , 1);
                if (p[1].size() > p[2].size()) {
                    swap(p[1] , p[2]);
