#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
typedef pair<LL,LL> PLL;

LL n,d1,d2;
vector<PLL> vec;

bool sq(LL x)
{
    LL y=sqrt(x);
    if(y*y==x)return 1;
    return 0;
}

bool mark[605][605];

vector<PLL>ans;

void solve(int p,int q)
{
    memset(mark,0,sizeof mark);
    while(ans.size()>0)ans.pop_back();
    ans.clear();
    int cnt=0,x,y;
    for(int i=q;i<2*n;i++)
    {
        int j=0;
        if(i==q)j=p;
        for(;j<2*n;j++)
        {
            if(!mark[i][j])
            {
                ans.push_back(make_pair(i,j));
                cnt++;
                if(cnt==n*n)return;
                for(int k=0;k<vec.size();k++)
                {
                    x=i+vec[k].first;
                    y=j+vec[k].second;
                    if(x>=2*n || y>=2*n || y<0)continue;
                    mark[x][y]=1;
                }
            }
        }
    }
}

int main()
{
    cin>>n>>d1>>d2;
    for(LL i=0;i<=d1;i++)
    {
        if(sq(i) && sq(d1-i))vec.push_back(make_pair(sqrt(i),sqrt(d1-i)));
    }
    for(LL i=0;i<=d2;i++)
    {
        if(sq(i) && sq(d2-i))vec.push_back(make_pair(sqrt(i),sqrt(d2-i)));
    }
    int sz=vec.size();
    for(int i=0;i<sz;i++)vec.push_back(make_pair(vec[i].first,-vec[i].second));
    if(!vec.empty())
    {
        sort(vec.begin(),vec.end());
        vec.erase(unique(vec.begin(),vec.end()),vec.end());
    }
    for(int j=0;j<2*n;j++)
    {for(int i=0;i<min(20,2*n);i++)
    {
        solve(i,j);
        if(ans.size()==n*n)
        {
            for(int j=0;j<ans.size();j++)cout<<ans[j].first<<" "<<ans[j].second<<"\n";
            return 0;
        }

    }
    }


    return 0;
}

