pair<int,int> q[MN+5];
int n,d,D,s[MN+5][MN+5],vis[MN+5][MN+5],num[4],top;
void Solve(int d,int c)
{
    top=0;
    for(int i=0;i*i<=d;++i)
    {
        int j=d-i*i,k=int(sqrt(j+0.05));
        if(k*k==j) q[++top]=make_pair(i,k);
    }
    for(int i=1;i<=n<<1;++i) for(int j=1;j<=n<<1;++j)
        for(int k=1;k<=top;++k)
        {
            int th=(s[i][j]&c)^c;
            if(i+q[k].first<=n<<1&&j+q[k].second<=n<<1) s[i+q[k].first][j+q[k].second]|=th;
            if(i+q[k].first<=n<<1&&j-q[k].second>0) s[i+q[k].first][j-q[k].second]|=th;
        }
}
int main()
{
    n=read();d=read();D=read();
    Solve(d,1);Solve(D,2);
    for(int i=1;i<=n<<1;++i) for(int j=1;j<=n<<1;++j) ++num[s[i][j]];
    for(int k=0;k<4;++k) if(num[k]>=n*n)
    {
        int left=n*n;
        for(int i=1;i<=n<<1;++i) for(int j=1;j<=n<<1;++j)
            if(s[i][j]==k&&left) --left,printf("%d %d\n",i-1,j-1);
        return 0;
    }
    return 0;
}

#include <bits/stdc++.h>
