// #define int long long
int dx[2] = {1, -1}, dy[2] = {1, -1};

struct P {
  int x, y;  
};

int N, D1, D2;
vector<P> G1[601][601];
bool color1[601][601];
bool used1[601][601];
vector<P> G2[601][601];
bool color2[601][601];
bool used2[601][601];

void dfs1(int x, int y) {
  if ( used1[y][x] ) return;
  used1[y][x] = true;  
  for ( P p : G1[y][x] ) {
    int nx = p.x, ny = p.y;
    if ( used1[ny][nx] ) continue;    
    color1[ny][nx] = !color1[y][x];
    dfs1(nx, ny);    
  }
}

void dfs2(int x, int y) {
  if ( used2[y][x] ) return;
  used2[y][x] = true;  
  for ( P p : G2[y][x] ) {
    int nx = p.x, ny = p.y;
    if ( used2[ny][nx] ) continue;    
    color2[ny][nx] = !color2[y][x];
    dfs2(nx, ny);    
  }
}

signed main() {
  int SQRT[300000];  
  for ( int i = 0; i < 300000; i++ ) SQRT[i] = sqrt(i);  
  cin >> N >> D1 >> D2;

