void color(vector<PI> &points, vector<int> &c, int D) {
	if (D % 2 == 1) {
		for (PI p : points) {
			c[p.second] = (p.first.first + p.first.second) % 2;
		}
	}
	else if (D % 4 == 2) {
		for (PI p : points) {
			c[p.second] = p.first.first % 2;
		}
	}
	else {
		vector<PI> v[2][2];
		for (PI p : points) {
			v[p.first.first % 2][p.first.second % 2].emplace_back(P(p.first.first / 2, p.first.second / 2), p.second);
		}
		for (int i = 0; i < 2; i++) {
			for (int j = 0; j < 2; j++) color(v[i][j], c, D / 4);
		}
	}
}
