int f[N][N];

int d1,d2, n, cnt;
vector < pii > v;

void compute(){
    for(int i = 0;i<=n;i++){
        int j1 = (int)sqrt(d1 - i * i);
        int j2 = (int)sqrt(d2 - i * i);
        if(j1 * j1 + i * i == d1 && j1 <= 2 * n){
            v.PB(MP(i, j1));
        }
        if(j2 * j2 + i * i == d2 && j2 <= 2 * n){
            v.PB(MP(i, j2));
        }
    }
}

void sett(int x,int y){
    if(x < 0 || y < 0 || x >= 2 * n || y >= 2 * n) return;
    f[x][y] = 1;
}

int check(int x, int y){
    if(x < 0 || y < 0 || x >= 2 * n || y >= 2 * n) return 0;
    return (f[x][y] == 2);

}

void dfs(int x,int y, int b){
    if(x < 0 || y < 0 || x >= 2 * n || y >= 2 * n) return;
    if(f[x][y]) return;
    if(cnt == n * n) return;
    f[x][y] = 1;
    if(b == 0){
        int can = 1;
        for(int k = 0;k<v.size();k++){
            if(check(x + v[k].X, y + v[k].Y)) can = 0;
            if(check(x + v[k].X, y - v[k].Y)) can = 0;
            if(check(x - v[k].X, y + v[k].Y)) can = 0;
            if(check(x - v[k].X, y - v[k].Y)) can = 0;
        }
        if(can){
            printf("%d %d\n", x, y);
            cnt++;
            f[x][y] = 2;
        }
        else{
            b = 1;
        }
    }
    for(int k = 0;k<v.size();k++){
        dfs(x + v[k].X, y + v[k].Y, !b);
        dfs(x + v[k].X, y - v[k].Y, !b);
        dfs(x - v[k].X, y + v[k].Y, !b);
        dfs(x - v[k].X, y - v[k].Y, !b);
    }
}

int main(){
    scanf("%d%d%d",&n,&d1,&d2);
    compute();
    for(int x = 0;x<4*n;x++){
        for(int y = 0;y<=x;y++){
            int i = y;
            int j = x - y;
            if(i >= 2 * n || i < 0) continue;
            if(j >= 2 * n || j < 0) continue;
            if(f[i][j]) continue;
            dfs(i, j, 0);
        }

    }
   // printf("%d\n", cnt);
    return 0;
}

