	for (int i = 0; i < 2 * n; ++i)
		for (int j = 0; j < 2 * n; ++j) {
			for (int d = 0; d*d <= b; ++d) {
				for (int it = 0; it < 2; ++it) {
					if (d*d <= a) {
						int D = a - d*d;
						if (sqr[D] != -1) {
							D = sqr[D];
							int rr = i;
							int cc = j;
							for (int it = 0; it < 2; ++it) {
								int r = rr + d;
								int c = cc + D;
								if (r < R && c < C)
									addEdge(id(i, j), id(r, c));
								swap(R, C);
							}
						}
					}
					swap(a, b);
				}
			}
		}
