inline void add_edge(int a, int b, int x, int y)
{
	if(x < 0 || x >= n+n || y < 0 || y >= n+n)
		return;
	v[node[a][b]].pb(node[x][y]);
	return;
}

void solve()
{
	int d1, d2, i, j, d, cnt = 0, a;
	cin >> n >> d1 >> d2;
	fo(i,0,n+n)
		fo(j,0,n+n)
		{
			int d = i*i + j*j;
			if(d == d1 || d == d2)
				arr.pb({i,j});
		}
	for(auto x : arr)
		cerr << x.F << "," << x.S << '\n';
	fo(i,0,n+n)
		fo(j,0,n+n)
		{
			node[i][j] = cnt;
			val[cnt] = {i,j};
			cnt++;
		}
	fo(i,0,n+n)
		fo(j,0,n+n)
			for(auto x : arr)
			{
				add_edge(i,j,i+x.F,j+x.S);
				add_edge(i,j,i+x.F,j-x.S);
				add_edge(i,j,i-x.F,j+x.S);
				add_edge(i,j,i-x.F,j-x.S);
			}
	fo(i,0,cnt)
	{
		deg[i] = sz(v[i]);
		pq.push({-deg[i],i});
	}
	while(!pq.empty())
	{
		a = pq.top().S;
		pq.pop();
		if(vis[a])
			continue;
		ans.pb(val[a]);
		vis[a] = 1;
		for(auto x : v[a])
		{
			if(!vis[x])
				for(auto y : v[x])
				{
					deg[y]--;
					pq.push({-deg[y],y});
				}
			vis[x] = 1;
		}
	}
	assert(sz(ans) >= n*n);
	fo(i,0,n*n)
		cout << ans[i].F << " " << ans[i].S << '\n';
	return;
}

