V solve(V a,int d1,int d2){
	if (d1>d2) swap(d1,d2);
	if (d1==0 && d2==0) return a;
	if (d1==0){
		if (d2&1){
			int cnt[2];
			cnt[0]=cnt[1]=0;
			FOR(i,0,SZ(a)-1) ++cnt[O(a[i])];
			int t=((cnt[0]>=cnt[1])?0:1);
			V ans;
