			FOR(i,0,SZ(a)-1)
				if (O(a[i])==0) a0.pb(r45(a[i]));
				else a1.pb(r45(a[i]));
			V ans0=solve(a0,d1,d2/2);
			V ans1=solve(a1,d1,d2/2);
			V ans;
			ans.clear();
			FOR(i,0,SZ(ans0)-1) ans.pb(r045(ans0[i]));
			FOR(i,0,SZ(ans1)-1) ans.pb(r145(ans1[i]));
			return ans;
		}
	}
	if (d1%2==1 && d2%2==1){
		int cnt[2];
		cnt[0]=cnt[1]=0;
		FOR(i,0,SZ(a)-1) ++cnt[O(a[i])];
		int t=((cnt[0]>=cnt[1])?0:1);
		V ans;
		ans.clear();
		FOR(i,0,SZ(a)-1) if (O(a[i])==t) ans.pb(a[i]);
		return ans;
	}
	if (d1%2==0 && d2%2==0){
		V a0,a1;
		a0.clear();
		a1.clear();
		FOR(i,0,SZ(a)-1)
			if (O(a[i])==0) a0.pb(r45(a[i]));
			else a1.pb(r45(a[i]));
		V ans0=solve(a0,d1,d2/2);
		V ans1=solve(a1,d1,d2/2);
		V ans;
		ans.clear();
		FOR(i,0,SZ(ans0)-1) ans.pb(r045(ans0[i]));
		FOR(i,0,SZ(ans1)-1) ans.pb(r145(ans1[i]));
		return ans;
	}
	if (d2%2!=0) swap(d1,d2);
	V a0,a1;
	a0.clear();
