void dfs(int x, bitset<600> row, bitset<600> col) {

    if (row.count() * col.count() < N * N)
        return;

    if (x >= items.size()) {
        if (row.count() * col.count() >= N * N) {
            int K = N * N;
            for (int i = 0; i < 2 * N; i++) {
                for (int j = 0; j < 2 * N; j++) {
                    if (K == 0) break;
                    if (row[i] && col[j]) {
                        cout << i << " " << j << endl;
                        K--;
                    }
                }
            }
            exit(0);
        }
    } else {

        {
            int h = items[x].first;
            if (h) {
                for (int s = 0; s < 1; s++) {
                    bitset<600> nextRow = row;
                    for (int i = s; i < 2 * N; i += 2 * h) {
                        for (int j = 0; j < h; j++) {
                            if (i + h + j >= 2 * N) break;
                            nextRow[i + h + j] = 0;
                        }
                    }
                    dfs(x + 1, nextRow, col);
                }
            }
        }

        {

            int h = items[x].second;
            if (h) {
                for (int s = 0; s < 1; s++) {
                    bitset<600> nextCol = col;
                    for (int i = s; i < 2 * N; i += 2 * h) {
                        for (int j = 0; j < h; j++) {
                            if (i + h + j >= 2 * N) break;
                            nextCol[i + h + j] = 0;
                        }
                    }
                    dfs(x + 1, row, nextCol);
                }
            }
        }
    }

}

