using namespace std;

int n, d1, d2;
vector<pair<int, int>> V1, V2;
bool vis[1300][1300];

int main() {
    scanf("%d %d %d", &n, &d1, &d2);
    for (int i = 0; i * i <= d1; i++) {
        int t = sqrt(d1 - i * i);
        if (i * i + t * t == d1) V1.push_back({i, t});
    }
    for (int i = 0; i * i <= d2; i++) {
        int t = sqrt(d2 - i * i);
        if (i * i + t * t == d2) V2.push_back({i, t});
    }
    vector<pair<int, int>> orz;
    for (int i = 0; i < 2 * n; i++) {
        for (int j = 0; j < 2 * n; j++) {
            orz.push_back({i, j});
        }
    }
    vector<pair<int, int>> ans;
    int tot = 0;
    auto clear = [&]() {
        tot = 0, memset(vis, 0, sizeof(vis)), ans.clear();
    };
    auto solve = [&]() {
        for (int k = 0; k < orz.size(); k++) {
            int i = orz[k].first, j = orz[k].second;
            if (vis[i][j]) continue;
            vis[i][j] = 1;
            for (auto p : V1) {
                vis[i + p.first][j + p.second] = 1;
                if (i >= p.first) vis[i - p.first][j + p.second] = 1;
                if (j >= p.second) vis[i + p.first][j - p.second] = 1;
                if (i >= p.first && j >= p.second) vis[i - p.first][j - p.second] = 1;
            }
            for (auto p : V2) {
                vis[i + p.first][j + p.second] = 1;
                if (i >= p.first) vis[i - p.first][j + p.second] = 1;
                if (j >= p.second) vis[i + p.first][j - p.second] = 1;
                if (i >= p.first && j >= p.second) vis[i - p.first][j - p.second] = 1;
            }
            ans.push_back({i, j});
            if (++tot == n * n) {
                for (auto p : ans) printf("%d %d\n", p.first, p.second);
                exit(0);
            }
        }
    };
    solve();
    sort(orz.begin(), orz.end(), [&](pair<int, int> x, pair<int, int> y) {
        int i = x.first + 1, j = x.second + 1, c1 = 0, c2 = 0;
        while (i && !(i & 1)) c1++, i >>= 1;
        while (j && !(j & 1)) c2++, j >>= 1;
        pair<int, int> p1 = {c1, c2};
        i = y.first + 1, j = y.second + 1, c1 = 0, c2 = 0;
        while (i && !(i & 1)) c1++, i >>= 1;
        while (j && !(j & 1)) c2++, j >>= 1;
        pair<int, int> p2 = {c1, c2};
        return p1 > p2;
    });
    clear(), solve();
    sort(orz.begin(), orz.end(), [&](pair<int, int> x, pair<int, int> y) {
        int i = x.first + 1, j = x.second + 1, c1 = 0, c2 = 0;
        while (i && !(i & 1)) c1++, i >>= 1;
        while (j && !(j & 1)) c2++, j >>= 1;
        int p1 = min(c1, c2);
        i = y.first + 1, j = y.second + 1, c1 = 0, c2 = 0;
        while (i && !(i & 1)) c1++, i >>= 1;
        while (j && !(j & 1)) c2++, j >>= 1;
        int p2 = min(c1, c2);
        return p1 < p2;
    });
    clear(), solve();
    sort(orz.begin(), orz.end(), [&](pair<int, int> x, pair<int, int> y) {
        int i = x.first + 1, j = x.second + 1, c1 = 0, c2 = 0;
        while (i && !(i & 1)) c1++, i >>= 1;
        while (j && !(j & 1)) c2++, j >>= 1;
        int p1 = max(c1, c2);
        i = y.first + 1, j = y.second + 1, c1 = 0, c2 = 0;
        while (i && !(i & 1)) c1++, i >>= 1;
        while (j && !(j & 1)) c2++, j >>= 1;
        int p2 = max(c1, c2);
        return p1 < p2;
    });
    clear(), solve();
    srand(19260817), random_shuffle(orz.begin(), orz.end());
    clear(), solve();
    assert(0);
    return 0;
}

#include <iostream>
