#define abs(a,b) ((a)-(b)>0?(a)-(b):(b)-(a))

using vec_t = std::vector<int>;
using vec_vec_t = std::vector<std::vector<int>>;

void get_ij(int N,int idx,int& i,int& j){
	i = idx/N;
	j = idx%N;
}

int D1,D2,N;

void print(vec_t& ar,int idx)
{
	std::cout<<std::setw(2)<<idx;
	for(auto i=0;i<2*N;++i)
		std::cout<<i<<" ";
	std::cout<<std::endl;
	for(auto i=0;i<2*N;++i){
		std::cout<<i<<" ";
		for(auto j=0;j<2*N;++j){
			if(ar[i*2*N+j]==0)
				std::cout<<"- ";
			else if(ar[i*2*N+j]==2)
				std::cout<<"x ";
			else
				std::cout<<"o ";
		}
		std::cout<<std::endl;
	}
	std::cout<<std::endl;
}

bool f(vec_t& ar,vec_vec_t& vec,int idx=0,int depth=0){
	//print(ar,idx);
	if(depth==N*N)return true;
	for(int ij=idx;ij<4*N*N;++ij){
		int i,j;
		get_ij(N*2,ij,i,j);
		if(ar[ij])continue;
		ar[ij]=1;
		vec.push_back(vec_t{});
		auto& last=vec[vec.size()-1];
		for(int ij2=ij+1;ij2<4*N*N;++ij2){
			int i2,j2;
			get_ij(N*2,ij2,i2,j2);
			auto idist = abs(i,i2);
			auto jdist = abs(j,j2);
			auto dist = idist*idist+jdist*jdist;
			//std::cout<<i<<","<<j<<","<<i2<<","<<j2<<":"<<idist<<","<<jdist<<","<<dist<<std::endl;
			if(dist==D1||dist==D2){
				ar[ij2]|=2;
				last.push_back(ij2);
			}
		}
		auto result = f(ar,vec,ij+1,depth+1);
		if(result)return true;
		ar[ij]&=2;
		for(auto ij2:last)
			ar[ij2]&=1;
	}
	return false;
}


int main()
{
	std::cin>>N>>D1>>D2;
	vec_t ar(4*N*N,0);
	vec_vec_t vec;
	f(ar,vec);

	int idx=0;
	for(auto& val:ar){
		if(val%2){
			int i,j;
