using namespace std;

int solve(int n, int d1, int d2) {
    int m[2*n][2*n];
    memset(m, 0, sizeof(m));
    map<int, int> v;
    for (int i = 0; i * i <= 200010; i++) {
        v[i*i] = i;
    }
    vector<pair<int, int>> u;
    auto f = [&](int d) {
        for (int i = 0; i * i <= d; i++) {
            if (v.count(d-i*i)) {
                u.emplace_back(i, v[d-i*i]);
                u.emplace_back(i, -v[d-i*i]);
                u.emplace_back(-i, v[d-i*i]);
                u.emplace_back(-i, -v[d-i*i]);
            }
        }
    };
    f(d1); f(d2);
    auto in = [&](int x, int y) {
        return 0 <= x && x < 2*n && 0 <= y && y < 2*n;
    };
    set<pair<int, pair<int, int>>> s;
    for (int i = 0; i < 2*n; i++) {
        for (int j = 0; j < 2*n; j++) {
            for (auto &z: u) {
                if (in(i+z.first, j+z.second)) m[i][j]++;
            }
            s.insert({m[i][j], {i, j}});
        }
    }
    int ans = 0;
    vector<int> x, y;
    while (!s.empty()) {
        auto it = *s.begin();
        s.erase(it);
        int i = it.second.first, j = it.second.second;
        if (m[i][j] < it.first) continue;
        ans++;
        x.emplace_back(i), y.emplace_back(j);
        if (ans == n * n) break;
        for (auto &z: u) {
            if (in(i+z.first, j+z.second)) {
                if (m[i+z.first][j+z.second] < 0) continue;
                m[i+z.first][j+z.second] = -1;
                for (auto &p: u) {
                    if (in(i+z.first+p.first, j+z.second+p.second)) {
                        m[i+z.first+p.first][j+z.second+p.second]--;
                        if (m[i+z.first+p.first][j+z.second+p.second] >= 0) {
                            s.insert({m[i+z.first+p.first][j+z.second+p.second], {i+z.first+p.first, j+z.second+p.second}});
                        }
                    }
                }
            }
        }
    }
    //cout << ans << endl;
    assert(ans == n * n);
    for (int i = 0; i < n * n; i++) {
        cout << x[i] << " " << y[i] << "\n";
    }
}

