		if(ceil(sqrt((float)a)) == floor(sqrt((float)a))){
			a = (int)sqrt((float)a);
			if((y+a)>=0 && (y+a)<2*n){
				if(!mark[(2*n*(x+i))+(y+a)]){dfs(x+i,y+a,1-t);}
