inline int Sqrt(ll x)
{	if(x<0) return -1;
	int l=0,r=x;
	while(l<=r)
	{	int mid=(l+r)>>1;
		if((ll)mid*mid==x) return mid;
		if((ll)mid*mid<x) l=mid+1;
		else r=mid-1;
	}
	return -1;
}
