struct GRAPH
{
	int fst[ME], nxt[ME], v[ME], lnum;

	void addeg(int nu, int nv)
	{
		nxt[++lnum] = fst[nu];
		fst[nu] = lnum;
		v[lnum] = nv;
		nxt[++lnum] = fst[nv];
		fst[nv] = lnum;
		v[lnum] = nu;
	}

	int col[ME], num[3];

	void dfs(int x, int c)
	{
		assert(!col[x] || col[x]==c);
		if(col[x]) return;
		else col[x] = c, num[c]++;
		for(int i=fst[x]; i; i=nxt[i])
			dfs(v[i], 3-c);
	}

	void color()
	{
		for(int i=0; i<n*n*4; i++)
			if(!col[i])
				dfs(i, 1);
	}
} G1, G2;

int id(int x, int y)
{
	assert(x>=0 && x<n*2);
	assert(y>=0 && y<n*2);
	return x*(n*2) + y;
}

