{
	for(int i=0; i*i<=d; i++)
		for(int j=0; j*j<=d; j++)
			if(i*i + j*j == d)
				for(int x=0; x<n*2; x++)
					for(int y=0; y<n*2; y++)
					{
						if(x+i<n*2 && y+j<n*2) g.addeg(id(x, y), id(x+i, y+j));
						if(x+i<n*2 && y-j>=0) g.addeg(id(x, y), id(x+i, y-j));
					}
}

