int r[400050][2];
int root(int x) {
	if (x == r[x][0]) return x;

	int t = r[x][0];
	r[x][0] = root(t);
	r[x][1] ^= r[t][1];
	return r[x][0];
}
void mymerge(int x, int y) {
	int r1 = root(x), r2 = root(y);
	int t = r[x][1] ^ r[y][1] ^ 1;
	if (r1 == r2) return;
	r[r1][0] = r2, r[r1][1] = t;
}

void getgroup(int N, int D, int G[605][605]) {
	int i, j, k;
	vector <pii> Vl;

	for (i = 0; i < 4 * N*N; i++) r[i][0] = i, r[i][1] = 0;

	for (i = 0; i*i <= D; i++) {
		int x = (int)(sqrt(D - i*i) + 0.5);
		if (i*i + x*x != D) continue;

		if (i > x) break;
		Vl.emplace_back(i, x);
		if (i != x) Vl.emplace_back(x, i);
	}
	for (i = 0; i < 2 * N; i++) {
		for (j = 0; j < 2 * N; j++) {
			for (auto it : Vl) {
				int x = i + it.first, y = j + it.second;
				if (x < 2 * N && y < 2 * N && x >= 0 && y >= 0) mymerge(i * 2 * N + j, x * 2 * N + y);

				x = i + it.first, y = j - it.second;
				if (x < 2 * N && y < 2 * N && x >= 0 && y >= 0) mymerge(i * 2 * N + j, x * 2 * N + y);
			}
		}
	}
	for (i = 0; i < 2 * N; i++) {
		for (j = 0; j < 2 * N; j++) {
			int t = i * 2 * N + j;
			int ro = root(t);
			if (r[t][1] == 1) G[i][j] = -1;
			else G[i][j] = 1;
		}
	}
}

