void try_try(int x,int y){
    FOR(i,0,2*N){
        REP(k,2){
            if((x-i)*(x-i)>d[k])continue;
            int j=sqrt(d[k]-(x-i)*(x-i)+0.1);
            if(j*j+(x-i)*(x-i)!=d[k])continue;
            if(H.count(MP(i,y-j))||H.count(MP(i,y+j)))return;
        }
    }
    H.insert(MP(x,y));
    if(SZ(H)==N*N){
        for(auto v: H){
            W(v);
        }
        exit(0);
    }
}
