  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int n, d1, d2;
  cin >> n >> d1 >> d2;

  function<vector<pii>(int, int, int)> gpts = [&](int n, int d1, int d2) {
    if (d2 & 1) swap(d1, d2);
    if (d1 & 1) {
      if (d2 & 1) {
        vector<pii> ret;
        for (int i = -n; i <= n; ++i)
          for (int j = -n + ((i ^ n) & 1); j <= n; j += 2)
            ret.emplace_back(i, j);
        return ret;
      } else {
        vector<pii> mid = gpts(n, d2 / 2, d2 / 2);
        vector<pii> ret;
        for (const auto& pr : mid) {
          int x, y;
          tie(x, y) = pr;
          if ((x + y) <= n && (x + y) >= -n && (x - y) <= n && (x - y) >= -n)
            ret.emplace_back(x + y, x - y);
        }
        return ret;
      }
    } else {
      vector<pii> mid = gpts(n + 1, d1 / 2, d2 / 2);
      vector<pii> ret;
      int c1 = 0, c2 = 0;
      for (const auto& pr : mid) {
        int x, y;
        tie(x, y) = pr;
        if ((x + y) <= n && (x + y) >= -n && (x - y) <= n && (x - y) >= -n)
          ret.emplace_back(x + y, x - y);
        if ((x + y + 1) <= n && (x + y + 1) >= -n && (x - y) <= n && (x - y) >= -n)
          ++c1;
        if ((x + y) <= n && (x + y) >= -n && (x - y + 1) <= n && (x - y + 1) >= -n)
          ++c2;
      }
      int dx = 0, dy = 0;
      if (c1 >= c2) dx = 1;
      else dy = 1;
      for (const auto& pr : mid) {
        int x, y;
        tie(x, y) = pr;
        if ((x + y + dx) <= n && (x + y + dx) >= -n && (x - y + dy) <= n && (x - y + dy) >= -n)
          ret.emplace_back(x + y + dx, x - y + dy);
      }
      return ret;
    }
  };

  vector<pii> ans = gpts(n, d1, d2);
  vector<vi> cn(2, vi(2)); 
  for (const auto& pr : ans) {
    int x, y;
    tie(x, y) = pr;
    x += n; y += n;
    for (int i = 0; i < 2; ++i) for (int j = 0; j < 2; ++j)
    if (x - i >= 0 && x - i < n * 2 && y - j >= 0 && y - j < n * 2)
      ++cn[i][j];
  }
  pair<int, pii> res;
  for (int i = 0; i < 2; ++i) for (int j = 0; j < 2; ++j)
    res = max(res, make_pair(cn[i][j], make_pair(i, j)));
  assert(res.first >= n * n);
  int dx = n - res.second.first, dy = n - res.second.second;
  int cnt = 0;
  for (const auto& pr : ans) {
    int x, y;
    tie(x, y) = pr;
    x += dx; y += dy;
    if (x >= 0 && x < n * 2 && y >= 0 && y < n * 2) {
      ++cnt;
      cout << x << ' ' << y << '\n';
      if (cnt == n * n) break;
    }
  }

#ifdef LBT
  LOG("Time: %dms\n", int ((clock()
          -nol_cl) / (double)CLOCKS_PER_SEC * 1000));
#endif
  return 0;
}

