vector<pii> ans[4], dir;

bool inside( int x, int y ) {
	return x >= 0 && x < n+n && y >= 0 && y < n+n;
}

void dfs( int i, int j, int c[N][N] ) {
	for( int d = 0; d < (int)dir.size(); ++d ) {
		int x = i + dir[d].first;
		int y = j + dir[d].second;
		if( inside(x, y) && !c[x][y] ) {
			c[x][y] = 3 - c[i][j];
			dfs(x, y, c);
		}
	}
}

void solve( int d, int c[N][N] ) {
	dir.clear();
	for( int i = 0; i*i <= d; ++i )
		for( int j = 0; j*j+i*i <= d; ++j )
			if( i*i+j*j == d ) {
				dir.push_back( pii(i, j) );
				dir.push_back( pii(-i, j) );
				dir.push_back( pii(i, -j) );
				dir.push_back( pii(-i, -j) );
			}
	for( int i = 0; i < n+n; ++i )
		for( int j = 0; j < n+n; ++j )
			if( !c[i][j] ) {
				c[i][j] = 1;
				dfs(i, j, c);
			}
}

int getid( int x, int y ) {
	int t1 = c1[x][y];
	int t2 = c2[x][y];
	if( t1 == 1 ) {
		return t2 == 1 ? 0 : 1;
	} else {
		return t2 == 1 ? 2 : 3;
	}
}

