	for( int i = 0; i < n+n; ++i )
		for( int j = 0; j < n+n; ++j ) {
			int id = getid(i, j);
			ans[id].push_back( pii(i, j) );
		}
	for( int i = 0; i < 4; ++i ) {
		int m = (int)ans[i].size();
		if( m >= n*n ) {
			for( int j = 0; j < n*n; ++j )
				printf( "%d %d\n", ans[i][j].first, ans[i][j].second );
			break;
		}
	}
	return 0;
}

