using namespace std;

int board[610][610];
int board2[610][610];

int N, D1, D2;

bool inBoard(int x, int y) {
	return x >= 0 && x < 2 * N && y >= 0 && y < 2 * N;
}

int main() {
	cin >> N >> D1 >> D2;

	vector<pair<int, int>> P1, P2;

	for (int d = 0; d <= sqrt(D1); d++) {
		int a = D1 - d * d;
		int b = sqrt(a);
		if (b * b != a) continue;
		P1.push_back(make_pair(d, b));
	}

	for (int d = 0; d <= sqrt(D2); d++) {
		int a = D2 - d * d;
		int b = sqrt(a);
		if (b * b != a) continue;
		P2.push_back(make_pair(d, b));
	}

	// D1 
	for (int y = 0; y < 2 * N; y++) {
		for (int x = 0; x < 2 * N; x++) {
			if (board[y][x] == 0) {
				board[y][x] = 1;
				for (auto pr : P1) {
					int nx = x + pr.first;
					int ny = y + pr.second;
					if (!inBoard(nx, ny)) continue;
					board[ny][nx] = 2;
				}
			}
		}
	}

	// D2 
	for (int y = 0; y < 2 * N; y++) {
		for (int x = 0; x < 2 * N; x++) {
			if (board2[y][x] == 0) {
				board2[y][x] = 1;
				for (auto pr : P2) {
					int nx = x + pr.first;
					int ny = y + pr.second;
					if (!inBoard(nx, ny)) continue;
					board2[ny][nx] = 2;
				}
			}
		}
	}

	vector<pair<int, int>> v[4];
	for (int y = 0; y < 2 * N; y++) {
		for (int x = 0; x < 2 * N; x++) {
			pair<int, int> p(x, y);
			if (board[y][x] == 1 && board2[y][x] == 1) v[0].push_back(p);
			if (board[y][x] == 1 && board2[y][x] == 2) v[1].push_back(p);
			if (board[y][x] == 2 && board2[y][x] == 1) v[2].push_back(p);
			if (board[y][x] == 2 && board2[y][x] == 2) v[3].push_back(p);
		}
	}

	for (int i = 0; i < 4; i++) {
		if (v[i].size() < N * N) continue;

		for (int j = 0; j < N * N; j++) {
			cout << v[i][j].first << " " << v[i][j].second << endl;
		}

		break;
	}

	return 0;
}

