struct node
{
	int x,y;
	node(int x=0,int y=0):x(x),y(y){}
	bool operator < (const node &rhs) const
	{
		if (x+y==rhs.x+rhs.y) return x<rhs.x;
		return x+y<rhs.x+rhs.y;
	}
};
set<node> S;
int dx[10005],dy[10005],cnt=0;
void calc(int x)
{
	for (int i=-600;i<=600;++i)
	{
		for (int j=-600;j<=600;++j)
		{
			if (i*i+j*j==x)
