void crossAll(VVI &M, int N, int D1, int D2) {
	int sx[] = {-1, -1, 1,  1};
	int sy[] = { 1, -1, 1, -1};
	vector<PII> deltas;
	for (int x = 0; x*x <= D1; ++x) {
		int rN = D1 - x*x;
		int y = sqrt(rN) + 1e-9;
		if (y * y != rN) continue;
//		cout << x << " " << y << endl;
		deltas.push_back(PII(x, y));
	}
	for (int x = 0; x*x <= D2; ++x) {
		int rN = D2 - x*x;
		int y = sqrt(rN) + 1e-9;
		if (y * y != rN) continue;
//		cout << x << " " << y << endl;
		deltas.push_back(PII(x, y));
	}

	for (int i = 0; i < 2*M.size() - 1; ++i) {
		for (int j = -2*int(M.size()); j < 2*int(M.size()); ++j) {
			int ri = i - j;
			int rj = i + j;
			if (ri < 0 || rj < 0 || ri >= M.size() || rj >= M.size()) continue;
			if (!M[ri][rj]) continue;
			for (PII d : deltas) {
				for (int k = 0; k < 4; ++k) {
					int nx = rj + sx[k] * d.first;
					int ny = ri + sy[k] * d.second;
					if (nx < 0 || nx >= M[0].size()) continue;
					if (ny < 0 || ny >= M.size()) continue;
					M[ny][nx] = 0;
				}
			}

		}
	}
}


