using P = pair<int, int>;
vector<P> getSqSum(int d) {
    vector<P> ret;
    for(auto& sq : sqs) {
        if(d - sq < 0) break;
        if(isSq[d - sq] != -1) {
            ret.push_back(make_pair(isSq[sq], isSq[d-sq]));
        }
    }
    return ret;
}

