		for(auto && e: se[k]) {
			mp[MP(i + e.FI, j + e.SE)] = -1;
		}
		}
		c++;
	}
	}

	assert(c == n * n);

	inc(i, 2 * n) {
	inc(j, 2 * n) {
		if(mp[MP(i, j)] == 1) { cout << i << " " << j << "\n"; }
	}
	}

