#include <bits/stdc++.h>
using namespace std;

typedef pair <int, int> ii;

const int Maxm = 605;
const int Maxn = 3000005;

int sqr[Maxn];
int n, d1, d2;
bool tk[Maxm][Maxm];
vector <ii> gen;
ii seq[Maxn];
int slen;
bool found;

bool Exist(int r, int c)
{
	return 0 <= r && r < 2 * n && 0 <= c && c < 2 * n && tk[r][c];
}

bool Check(int r, int c)
{
	for (int i = 0; i * i <= d1 || i * i <= d2; i++) {
		if (i * i <= d1) {
			int j = sqr[d1 - i * i];
			if (j != -1 && (Exist(r - i, c - j) || Exist(r - i, c + j) || Exist(r + i, c - j) || Exist(r + i, c + j)))
				return false;
		}
		if (i * i <= d2) {
			int j = sqr[d2 - i * i];
			if (j != -1 && (Exist(r - i, c - j) || Exist(r - i, c + j) || Exist(r + i, c - j) || Exist(r + i, c + j)))
				return false;
		}
	}
	return true;
}

void Gen(int lvl)
{
	int lft = int(gen.size()) - lvl;
	if (slen + lft < n * n) return;
	if (slen >= n * n) {
		found = true;
		for (int i = 0; i < slen; i++)
			printf("%d %d\n", seq[i].first, seq[i].second);
		return;
	}
	if (Check(gen[lvl].first, gen[lvl].second)) {
		seq[slen++] = gen[lvl]; tk[gen[lvl].first][gen[lvl].second] = true;
		Gen(lvl + 1);
		slen--; tk[gen[lvl].first][gen[lvl].second] = false;
	}
	if (!found) Gen(lvl + 1);
}

int main()
{
	fill(sqr, sqr + Maxn, -1);
	for (int i = 0; i * i < Maxn; i++)
		sqr[i * i] = i;
	cin >> n >> d1 >> d2;
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++)
			gen.push_back(ii(i, j));
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++)
			gen.push_back(ii(i, j + n));
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++)
			gen.push_back(ii(i + n, j));
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++)
			gen.push_back(ii(i + n, j + n));
	Gen(0);
	return 0;
}

