using namespace std;

const int MAX_N = 1e3;

int N, D1, D2, color1[MAX_N][MAX_N], color2[MAX_N][MAX_N];
vector<pair<int, int>> delta1, delta2;
vector<pair<int, int>> cp[2][2];

vector<pair<int, int>> get_delta(int x) {
    vector<pair<int, int>> res;
    for (int i = -2 * N; i <= 2 * N; i++)
        for (int j = -2 * N; j <= 2 * N; j++)
            if (i * i + j * j == x) res.emplace_back(i, j);
    return res;
}

void color_dfs(int res[MAX_N][MAX_N], vector<pair<int, int>> &delta, int x, int y, int c) {
    res[x][y] = c;
    for (auto i : delta) {
        int nx = x + i.first, ny = y + i.second;
        if (nx < 0 || nx >= 2 * N || ny < 0 || ny >= 2 * N) continue;
        if (res[nx][ny] != -1) continue;
        color_dfs(res, delta, nx, ny, c ^ 1);
    }
}

void color(int res[MAX_N][MAX_N], vector<pair<int, int>> &delta) {
    for (int i = 0; i < 2 * N; i++)
        for (int j = 0; j < 2 * N; j++)
            if (res[i][j] == -1) {
                color_dfs(res, delta, i, j, 0);
            }
}

int main() {
    scanf("%d%d%d", &N, &D1, &D2);
    delta1 = get_delta(D1);
    delta2 = get_delta(D2);
    memset(color1, -1, sizeof(color1));
    memset(color2, -1, sizeof(color2));
    color(color1, delta1);
    color(color2, delta2);
    for (int i = 0; i < 2 * N; i++)
        for (int j = 0; j < 2 * N; j++)
