			OK[i][j] = 1;
			// printf("%d %d\n",i,j);
			for(int x = 0;x < n + n;++x) {
				if((x - i) * (x - i) > D2) continue;
				int t = D2 - (x - i) * (x - i);
				if(cf[t] == -1) continue;
				if(j - cf[t] >= 0 && col[p(x,j - cf[t])] == color) {
					// printf("%d %d %d %d\n",i,j,x,j - cf[t]);
					add(p(x,j - cf[t]),p(i,j));

				}
				if(j + cf[t] < n + n && col[p(x,j + cf[t])] == color && cf[t]) {
					// printf("%d %d %d %d\n",i,j,x,j + cf[t]);
					add(p(x,j + cf[t]),p(i,j));

				}
			}
		}
	}

	memset(vis,0,sizeof(vis));
	cnt[0] = cnt[1] = 0;

	memset(col,-1,sizeof(col));

	for(int i = 0;i < n + n;++i) {
		for(int j = 0;j < n + n;++j) {
			if(OK[i][j] && !vis[p(i,j)]) {
				col[p(i,j)] = 0;
				dfs(p(i,j));
			}
		}
	}

	color = 0;

	if(cnt[1] > cnt[0]) color = 1;

	int tot = n * n;
	for(int i = 0;i < n + n;++i) {
		for(int j = 0;j < n + n;++j) {
			if(col[p(i,j)] == color && tot) {
				tot--;
				printf("%d %d\n",i,j);
				if(!tot) return 0;
			} 
		}
	}

	return 0;
}

