const int N=520;

int n,m,d1,d2;

bool mp[N][N];

void check(int x,int y,int d)
{
	int b=-2*y,c,t,t2;
	for(int i=0;i<=m;++i)
	{
		c=y*y-d-2*i*x+i*i+x*x;
		t=b*b-4*c;
		if(t<0)
			continue;
		t2=sqrt(t);
		if(t2*t2!=t)
			continue;
		t=-b+t2;
		if(0<=t&&!(t&1)&&(t>>=1)<=m)
			mp[i][t]=false;
		t=-b-t2;
		if(0<=t&&!(t&1)&&(t>>=1)<=m)
			mp[i][t]=false;
	}
}

int main()
{
	scanf("%d%d%d",&n,&d1,&d2);
	m=(1<<n)-1;
	for(int i=0;i<=m;++i)
		for(int j=0;j<=m;++j)
			mp[i][j]=true;
	int cnt=0;
	for(int i=0;i<=m;++i)
		for(int j=0;j<=m;++j)if(mp[i][j])
		{
			printf("%d %d\n",i,j);
			++cnt;
			if(cnt>=n*n)
				return 0;
			check(i,j,d1);
			check(i,j,d2);
		}
	return 0;
}

