void dfs(int x, int y, int co, int o) {
	if(y < 0 or y >= n * 2 or c[o][x][y] or
			(o == 1 and !mark[0][c[0][x][y]])) return;
	c[o][x][y] = co;
	++ tot[o][co];
	for(int tx = 0; tx < n * 2; tx ++) {
		int dx = std::abs(x - tx);
		dfs(tx, y - sq(dis[o] - dx * dx), co ^ 1, o);
		dfs(tx, y + sq(dis[o] - dx * dx), co ^ 1, o);
	}
}

