                    proc(i, j, p, 0);
                else
                    if(dif > 0 && pp[dif])
                        proc(i, j, p, pp[dif]);
                dif = b - p * p;
                if(dif == 0)
                    proc(i, j, p, 0);
                else
                    if(dif > 0 && pp[dif])
                        proc(i, j, p, pp[dif]);
            }
        }
        --stp;
        if(dir == 0)
        {
            if(j == n+n-1 || viz[i][j+1])
                dir = 1, ++i;
            else
                ++j;
        }
        else
            if(dir == 1)
            {
                if(i == n+n-1 || viz[i+1][j])
                    dir = 2, --j;
                else
                    ++i;
            }
            else
                if(dir == 2)
                {
                    if(j == 0 || viz[i][j-1])
                        dir = 3, --i;
                    else
