int board[610][610];

vector<pair<int, int>> calc(int D) {
	vector<pair<int, int>> ret;

	int limit = sqrt(D);
	rep(i, limit + 1) {
		int tmp = D - i * i;
		int tmp2 = sqrt(tmp);
		if (tmp2 * tmp2 == tmp) {
			ret.push_back(mp(i, tmp2));
		}
	}

	int n = ret.size();
	rep(i, n) {
		ret.push_back(mp(-ret[i].first, ret[i].second));
		ret.push_back(mp(ret[i].first, -ret[i].second));
		ret.push_back(mp(-ret[i].first, -ret[i].second));
	}

	return ret;
}

int N;

vector<pair<int, int>> ret;
set<pair<int, int>> st;

bool inBoard(int x, int y) {
	return x >= 0 && x < 2 * N && y >= 0 && y < 2 * N;
}

bool put(int x, int y) {
	if (board[y][x]) {
		return false;
	}

	ret.push_back(mp(x, y));

	board[y][x] = 1;

	for (auto &pr : st) {
		int nx = x + pr.first;
		int ny = y + pr.second;
		if (!inBoard(nx, ny)) continue;
		board[ny][nx] = 2;
	}

	return true;
}

