int root(int x){
    int left=0,right =x+1;
    while(left +1 < right ){
        int mid = (left + right ) /2;
        if( mid * mid <= x) left = mid;
        else right = mid;
    }
    return left;
}

void mk_graph(int D, vector<pair<int,int>> graph1[MAX][MAX]){
    REP(i,2*n){
        REP(j,2*n){
            REP(x,2*n){
                int tmp = D - (x-i)*(x-i);
                if(tmp < 0) continue;
                int y = root(D);
                if(y*y == tmp or (y+1)*(y+1)==tmp){
                    if(j-y >=0) graph1[i][j].push_back( make_pair(x,j-y));
                    if(j+y < 2*n) graph1[i][j].push_back( make_pair(x,j+y));
            }
            }
        }
    }
}


