int dfs(int x, int y, int col, int n, int d, vector<vector<bool>>& used, vector<vector<int>>& f, vector<pii> const& shifts) {
	used[x][y] = true;
	f[x][y] = col;
	for (auto s : shifts) {
		int nx = x + s.ff;
		int ny = y + s.ss;
		if (0 <= nx && nx < n * 2 && 0 <= ny && ny < n * 2 && !used[nx][ny]) {
			dfs(nx, ny, 1 - col, n, d, used, f, shifts);
		}
	}
	return 0;
}

void solve() {
	int n, d1, d2;
	cin >> n >> d1 >> d2;
	vector<pii> shifts1, shifts2;
	for (int i = -n * 2 + 1; i < n * 2; ++i) {
		for (int j = -n * 2 + 1; j < n * 2; ++j) {
			if (i * i + j * j == d1) {
				shifts1.push_back({i, j});
			}
			if (i * i + j * j == d2) {
				shifts2.push_back({i, j});
			}
		}
	}

	vector<vector<int>> f1(n * 2, vector<int>(n * 2));
	vector<vector<bool>> used(n * 2, vector<bool>(n * 2));
	for (int i = 0; i < n * 2; ++i) {
		for (int j = 0; j < n * 2; ++j) {
			if (!used[i][j]) {
				dfs(i, j, 0, n, d1, used, f1, shifts1);
			}
		}
	}
	used = vector<vector<bool>>(n * 2, vector<bool>(n * 2));
	vector<vector<int>> f2(n * 2, vector<int>(n * 2));	
	for (int i = 0; i < n * 2; ++i) {
		for (int j = 0; j < n * 2; ++j) {
			if (!used[i][j]) {
				dfs(i, j, 0, n, d2, used, f2, shifts2);
			}
		}
	}

	vector<pii> res[2][2];
	for (int i = 0; i < n * 2; ++i) {
		for (int j = 0; j < n * 2; ++j) {
			res[f1[i][j]][f2[i][j]].push_back({i, j});
		}
	}

	for (int i = 0; i < 2; ++i) {
		for (int j = 0; j < 2; ++j) {
			if (szof(res[i][j]) >= n * n) {
				for (int k = 0; k < n * n; ++k) {
					cout << res[i][j][k].ff + 1 << " " << res[i][j][k].ss + 1 << "\n";
				}
				return;
			}
		}
	}
}


