using namespace std;

struct BipartiteMatching
{
  int n, m;
  vector<vector<int> > graph;
  vector<int> matched, match;
  vector<int> edgeview;
  vector<int> level;
  vector<int> reached[2];
  BipartiteMatching(int n, int m) : n(n), m(m), graph(n), matched(m, -1), match(n, -1) {}

  bool assignLevel()
  {
    bool reachable = false;
    level.assign(n, -1);
    reached[0].assign(n, 0);
    reached[1].assign(m, 0);
    queue<int> q;
    for (int i = 0; i < n; i++) {
      if (match[i] == -1) {
        level[i] = 0;
        reached[0][i] = 1;
        q.push(i);
      }
    }
    while (!q.empty()) {
      auto cur = q.front(); q.pop();
      for (auto adj : graph[cur]) {
        reached[1][adj] = 1;
        auto next = matched[adj];
        if (next == -1) {
          reachable = true;
        }
        else if (level[next] == -1) {
          level[next] = level[cur] + 1;
          reached[0][next] = 1;
          q.push(next);
        }
      }
    }
    return reachable;
  }

  int findpath(int nod) {
    for (int &i = edgeview[nod]; i < graph[nod].size(); i++) {
      int adj = graph[nod][i];
      int next = matched[adj];
      if (next >= 0 && level[next] != level[nod] + 1) continue;
      if (next == -1 || findpath(next)) {
        match[nod] = adj;
        matched[adj] = nod;
        return 1;
      }
    }
    return 0;
  }

  int solve()
  {
    int ans = 0;
    while (assignLevel()) {
      edgeview.assign(n, 0);
      for (int i = 0; i < n; i++)
        if (match[i] == -1)
          ans += findpath(i);
    }
    return ans;
  }
};


pair<int,int> par[602][602];
bool valid[602][602];
int linkc[602][602];
int colorindex[602][602];
int n, d1, d2;

pair<pair<int, int>, int> findroot(int a, int b) {
  int la = a, lb = b;
  int c = 0;
  while (make_pair(a, b) != par[a][b]) {
    c ^= linkc[a][b];
    tie(a, b) = par[a][b];
  }
  int c2 = 0;
  while (make_pair(la, lb) != par[la][lb]) {
    int x, y;
    tie(x, y) = par[la][lb];
    par[la][lb] = make_pair(a, b);
    int olc = linkc[la][lb];
    linkc[la][lb] = (c ^ c2);
    c2 ^= olc;
    la = x; lb = y;
  }
  return make_pair(make_pair(a, b), c);
}

void merge(int a, int b, int c, int d) {
  auto rr1 = findroot(a, b);
  auto pos1 = rr1.first; auto c1 = rr1.second;
  auto rr2 = findroot(c, d);
  auto pos2 = rr2.first; auto c2 = rr2.second;
  if (pos1 == pos2)
    return;
  par[pos1.first][pos1.second] = pos2;
  linkc[pos1.first][pos1.second] = (c1 ^ c2 ^ 1);
}

void process(int r, int c, int r2, int c2) {
  if (r2 < 0 || c2 < 0 || r2 >= 2 * n || c2 >= 2 * n)
    return;
  if (!valid[r][c]) return;
  if (!valid[r2][c2]) return;
  merge(r, c, r2, c2);
}

void addedge(BipartiteMatching &bp, int left, pair<int, int> other) {
  int r2 = other.first, c2 = other.second;
  if (r2 < 0 || c2 < 0 || r2 >= 2 * n || c2 >= 2 * n)
    return;
  if (!valid[r2][c2]) return;
  int right = colorindex[r2][c2];
  bp.graph[left].push_back(right);
}

void init_mark() {
  for (int i = 0; i < 2 * n; i++) {
    for (int j = 0; j < 2 * n; j++) {
      par[i][j] = make_pair(i, j);
      linkc[i][j] = 0;
    }
  }
}

void color_adj(vector<pair<int,int>> &v1) {
  for (int i = 0; i < 2 * n; i++) {
    for (int j = 0; j < 2 * n; j++) {
      if (!valid[i][j]) continue;
      for (auto v : v1) {
        process(i, j, i + v.first, j + v.second);
        process(i, j, i + v.first, j - v.second);
        process(i, j, i - v.first, j + v.second);
        process(i, j, i - v.first, j - v.second);
      }
    }
  }
}

void erase_valid(vector<pair<int,int>> &v1) {
  int n1 = 0, n2 = 0;
  for (int i = 0; i < 2 * n; i++) {
    for (int j = 0; j < 2 * n; j++) {
      if (!valid[i][j]) continue;
      auto res = findroot(i, j); // compress
      if (res.second == 0) {
        colorindex[i][j] = n1;
        n1++;
      }
      else {
        colorindex[i][j] = n2;
        n2++;
      }
    }
  }
  BipartiteMatching bp(n1, n2);
  for (int i = 0; i < 2 * n; i++) {
    for (int j = 0; j < 2 * n; j++) {
      if (!valid[i][j]) continue;
      if (linkc[i][j] == 0) {
        int left = colorindex[i][j];
        for (auto v : v1) {
          addedge(bp, left, make_pair(i + v.first, j + v.second));
          addedge(bp, left, make_pair(i + v.first, j - v.second));
          addedge(bp, left, make_pair(i - v.first, j + v.second));
          addedge(bp, left, make_pair(i - v.first, j - v.second));
        }
      }
    }
  }
  int result = bp.solve();
  for (int i = 0; i < 2 * n; i++) {
    for (int j = 0; j < 2 * n; j++) {
      if (!valid[i][j]) continue;
      if (linkc[i][j] == 0) {
        int left = colorindex[i][j];
        if (bp.reached[0][left] == 0) {
          valid[i][j] = false;
        }
        else {
        }
      }
      else {
        int right = colorindex[i][j];
        if (bp.reached[1][right] == 1) {
          valid[i][j] = false;
        }
        else {
        }
      }
    }
  }
}

