int n, d1, d2;
bool L[602][602];
vector<Point>vec;
void add(Point p) {
   L[p.x][p.y] = 1;
   vec.push_back(p);
}

bool perf(int x) {
   if(x == 0)return 1;
   int val = sqrt(x);
   return val * val == x;
}
bool march(int x, int y) {
   if(x >= 0 && y >= 0 && x < 2 * n && y < 2 * n)L[x][y] = 0;
}
int main() {


   cin >> n >> d1 >> d2;
   for(int i = 0; i < 2 * n; ++i) {
      for(int j = 0; j < 2 * n; ++j)add(Point(i, j));
   }
   srand(time(0));
   for(int q=0;q<5;++q)random_shuffle(vec.begin(),vec.end());

   for(auto i : vec) {
      if(!L[i.x][i.y])continue;
      int val = max(d1, d2);
      for(int jj = 0; jj * jj <= val; ++jj) {
         int k = d2 - jj * jj;
         int j = jj * jj;
         if(perf(k)) {
            march(i.x + j, i.y + k);
            march(i.x - j, i.y + k);
            march(i.x - j, i.y - k);
            march(i.x + j, i.y - k);

            march(i.x + k, i.y + j);
            march(i.x - k, i.y + j);
            march(i.x - k, i.y - j);
            march(i.x + k, i.y - j);
         }
         k = d1 - jj * jj;
         if(k >= 0 && perf(k)) {
         march(i.x + j, i.y + k);
            march(i.x - j, i.y + k);
            march(i.x - j, i.y - k);
            march(i.x + j, i.y - k);

            march(i.x + k, i.y + j);
            march(i.x - k, i.y + j);
            march(i.x - k, i.y - j);
            march(i.x + k, i.y - j);
         }


      }
   }
   int cnt = 0;
   for(int i = 0; i < 2 * n; ++i)
      for(int j = 0; j < 2 * n; ++j)
         if(L[i][j] && cnt < n * n) {
            cout << i << ' ' << j << '\n';
            ++cnt;
            if(cnt == n * n)break;
         }assert(cnt==n*n);
}

