V<pin> ret(int n, int d1, int d2) {
	if (d1 % 4 != 0 and d2 % 4 != 0) {
		if (d1 % 4 != d2 % 4) {
			V<pin> ans(0);
			for (int i = 0; i * 2 < n; i++) {
				for (int j = 0; j * 2 < n; j++) {
					ans.push_back(mkp(2 * i, 2 * j));
				}
			}
			return ans;
		}
		if (d1 % 4 == 1) {
			V<pin> ans(0);
			for (int i = 0; i * 2 < n; i++) {
				for (int j = 0; j * 2 < n; j++) {
					ans.push_back(mkp(2 * i, 2 * j));
					if (i * 2 + 1 < n and j * 2 + 1 < n) {
						ans.push_back(mkp(2 * i + 1, 2 * j + 1));
					}
				}
			}
			return ans;
		}
		V<pin> ans(0);
		for (int i = 0; i * 2 < n; i++) {
			for (int j = 0; j< n; j++) {
				ans.push_back(mkp(2 * i, j));
			}
		}
		return ans;
	}
	if (d1 % 4 == 0 and d2 % 4 == 0) {
		V<pin> ans = ret((n + 1) / 2, d1/4, d2/4);
		int sz = ans.size();
		V<pin> r_ans;
		rep(i, sz) {
			pin ans1 = ans[i];
			ans1.first *= 2;
			ans1.second *= 2;
			r_ans.push_back(ans1);
			ans1.second++;
			r_ans.push_back(ans1);
			ans1.first++;
			r_ans.push_back(ans1);
			ans1.second--;
			r_ans.push_back(ans1);
		}
		return r_ans;
	}
	if (d1 % 4 == 0) { swap(d1, d2); }
	V<pin> ans = ret((n + 1) / 2, d2/4, d2/4);
	int sz = ans.size();
	V<pin> r_ans;
	if (d1 % 4 == 1) {
		rep(i, sz) {
			pin ans1 = ans[i];
			ans1.first *= 2;
			ans1.second *= 2;
			r_ans.push_back(ans1);
			ans1.second++;
			ans1.first++;
			r_ans.push_back(ans1);
		}
	}
	else {
		rep(i, sz) {
			pin ans1 = ans[i];
			ans1.first *= 2;
			ans1.second *= 2;
			r_ans.push_back(ans1);
			ans1.second++;
			r_ans.push_back(ans1);
		}
	}
	return r_ans;
}
