using P = pair<int, int>;

bool mp[1000][1000];

V<P> solve(int n, int d1, int d2) {
    V<P> er;
    int N = 2*n+3;
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) mp[i][j] = false;
    for (int i = -N; i <= N; i++) {
        for (int j = -N; j <= N; j++) {
            if (i*i + j*j == d1 || i*i + j*j == d2) {
                er.push_back(P(i, j));
            }
        }
    }

    V<P> pred;
    for (int i = 0; i < 2*n; i++) {
        for (int j = 0; j < 2*n; j++) {
            pred.push_back(P(i, j));
        }
    }

    for (int ph = 0; ph < 1000; ph++) {
        random_shuffle(begin(pred), end(pred));
        if (ph == 0) {
            sort(begin(pred), end(pred), [&](P a, P b){
                int ad = a.first%2 + a.second%2;
                int bd = b.first%2 + b.second%2;
                return ad < bd;
            });
        }

        V<P> res;
        for (auto pr: pred) {
            int i, j;
            tie(i, j) = pr;
            bool ok = true;
            for (auto p: er) {
                int ni = i + p.first;
                int nj = j + p.second;
                if (!(0 <= ni && ni < 1000 && 0 <= nj && nj < 1000)) continue;
                if (mp[ni][nj]) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                res.push_back(P(i, j));
                mp[i][j] = true;
            }
        }
        for (auto p: res) mp[p.first][p.second] = false;
        if (int(res.size()) < n*n) continue;
        res.resize(n*n);
        return res;
    }
    assert(false);
}


