        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second));
        v = solve((n1) / 2, (n2) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first + 1, 2 * p.second + 1));
    } else if (d2 % 4 == 2) {
        v = solve((n1 + 1) / 2, (n2 + 1) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second));
        v = solve((n1) / 2, (n2 + 1) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second + 1));
    } else if (d2 % 4 == 3) {
        v = solve((n1 + 1) / 2, (n2 + 1) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second));
        v = solve((n1 + 1) / 2, (n2) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second + 1));
        v = solve((n1) / 2, (n2 + 1) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first + 1, 2 * p.second));
        v = solve((n1) / 2, (n2) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first + 1, 2 * p.second + 1));
    }
    return ret;
}

