void solve() {
	int n, d1, d2;
	cin >> n >> d1 >> d2;
	vector<vector<bool>> used(n * 2, vector<bool>(n * 2));
	vector<pii> shifts;
	for (int i = -n * 2 + 1; i < n * 2; ++i) {
		for (int j = -n * 2 + 1; j < n * 2; ++j) {
			if (i * i + j * j == d1 || i * i + j * j == d2) {
				shifts.push_back({i, j});
			}
		}
	}

	vector<vector<int>> cnt(n * 2, vector<int>(n * 2));
	set<pair<int, pii>> st;
	for (int i = 0; i < n * 2; ++i) {
		for (int j = 0; j < n * 2; ++j) {
			for (auto p : shifts) {
				int nx = i + p.ff;
				int ny = j + p.ss;
				if (0 <= nx && nx < n * 2 && 0 <= ny && ny < n * 2) {
					++cnt[i][j];
				}
			}
			st.insert({cnt[i][j], {i, j}});
		}
	}

	vector<pii> arr;

	while (szof(st)) {
		int x, y;
		tie(x, y) = st.begin() -> ss;
		assert(!used[x][y]);
		st.erase(st.begin());
		used[x][y] = true;
		arr.push_back({x, y});
		if (szof(arr) == n * n) {
			break;
		}
		for (auto p : shifts) {
			int nx = x + p.ff;
			int ny = y + p.ss;
			if (0 <= nx && nx < n * 2 && 0 <= ny && ny < n * 2 && !used[nx][ny]) {
				used[nx][ny] = true;
				st.erase({cnt[nx][ny], {nx, ny}});
				for (auto t : shifts) {
					int nnx = nx + t.ff;
					int nny = ny + t.ss;
					if (0 <= nnx && nnx < n * 2 && 0 <= nny && nny < n * 2 && !used[nnx][nny]) {
						st.erase({cnt[nnx][nny], {nnx, nny}});
						--cnt[nnx][nny];
						st.insert({cnt[nnx][nny], {nnx, nny}});
					}
				}
			}
		}
	}
	assert(szof(arr) == n * n);
	for (auto p : arr) {
		cout << p.ff << " " << p.ss << "\n";
	}
}


