#include<bits/stdc++.h>
#pragma optimize "O3"
#define endl '\n'
const int MAXN=300017;
const long long MOD=998244353;
using namespace std;

long long fact[MAXN], inv[MAXN], n, A, B, k, ans=0, ac, bc;
long long poww(int i, long long p)
{
	if(p==0) return 1;
	int half=poww(i, p/2);
	if(p&1) return ((half*1ll*half)%MOD*i)%MOD;
	return (half*1ll*half)%MOD;
}
long long c(int i, int j)
{
	return ((fact[i]*1ll*inv[j])%MOD*1ll*inv[i-j])%MOD;
}
void mainp()
{
    cin>>n>>A>>B>>k;
    fact[0]=1ll;
    for(int i=1; i<MAXN; i++) fact[i]=(fact[i-1]*1ll*i)%MOD;
    for(int i=0; i<MAXN; i++) inv[i]=poww(fact[i], MOD-2);
    for(int i=0; i<=n; i++)
    {
		if((k-i*1ll*A)%B!=0) continue;
		ac=i, bc=(k-ac*1ll*A)/B;
		if(ac>n||bc>n) continue;
		long long mnc=max(0ll, ac+bc-n), mxc=min(n, min(ac, bc));
		if(mnc>n||ac-mnc<0||bc-mnc<0) continue;
		for(int j=mnc; j<=mxc; j++) ans+=((c(n, ac-j)*1ll*c(n-(ac-j), bc-j))%MOD*1ll*c(n-(ac-j+bc-j), j))%MOD, ans%=MOD;
	}
	cout<<ans<<endl;
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    mainp();
    return 0;
}

#include<cstdio>
