using namespace std;
#define maxn 1201
vector<pair<int, int> > d;
bool ban[maxn][maxn], ans[maxn][maxn];
int s[maxn];
int N;
void fil(int i, int j){
	if(i < 0 || i > 2 * N || j < 0 || j > 2 * N)return;
	ban[i][j] = true;
}
struct p{
	int x, y;
	bool operator < (const p &rhs)const{
		return x == rhs.x ? y < rhs.y : x < rhs.x;
	}
};
int main(){
	int D1, D2;
	scanf("%d %d %d", &N, &D1, &D2);
	for(int i = 0; i <= 2 * N; i += 1){
		int j = sqrt(D1 - i * i);
		if(j * j + i * i == D1)
			d.push_back({i, j}), d.push_back({i, -j}),
			d.push_back({-i, j}), d.push_back({-i, -j});
	}
	for(int i = 0; i <= 2 * N; i += 1){
		int j = sqrt(D2 - i * i);
		if(j * j + i * i == D2)
			d.push_back({i, j}), d.push_back({i, -j}),
			d.push_back({-i, j}), d.push_back({-i, -j});
	}
	for(int i = 0; i <= 4 * N; i += 1)
		for(int j = 0; j <= 2 * N; j += 1)
			if(ban[i][j] == false){
				ans[i][j] = true;
				for(int k = 0; k < d.size(); k += 1)
					fil(i + d[k].first, j + d[k].second);
			}
	for(int i = 0; i <= 4 * N; i += 1)
		for(int j = 0; j <= 2 * N - 1; j += 1){
			s[i] += ans[i][j];
		}
	int oi = -1;
	for(int i = 1; i <= 4 * N; i += 1) s[i] += s[i - 1];
	for(int i = 0; i + 2 * N - 1 <= 4 * N; i += 1){
		int sum = s[i + 2 * N - 1];
		if(i) sum -= s[i - 1];
		if(sum >= N * N){
			oi = i;
			break;
		}
	}
	assert(oi != -1);
	vector<p> a;
	int c = 0;
	for(int i = oi; i <= oi + 2 * N - 1 && c != N * N; i += 1)
		for(int j = 0; j <= 2 * N - 1 && c != N * N; j += 1)
			if(ans[i][j]){
				a.push_back({i - oi, j});
				c += 1;
			}
	sort(a.begin(), a.end());
	for(int i = 0; i < a.size(); i += 1)
		printf("%d %d\n", a[i].x, a[i].y);
	return 0;
}

