vector<pair<int, int> > dir;

int dx[] = {1, 1, -1, -1};
int dy[] = {-1, 1, -1, 1};

void add(pair<int, int> pr) {
    for (int i = 0; i < 4; ++i) {
        auto cur = pr;
        cur.first *= dx[i];
        cur.second *= dy[i];
        dir.push_back(cur);
    }
    swap(pr.first, pr.second);
    for (int i = 0; i < 4; ++i) {
        auto cur = pr;
        cur.first *= dx[i];
        cur.second *= dy[i];
        dir.push_back(cur);
    }   
}

pair<int, int> get_dir(int a) {
    for (int i = 0; i <= a; ++i) {
        if (i * 1ll * i + (a - i) * 1ll * (a - i) == a) {
            add({i, a - i});
        }
    }
}

int n;

void apply(int x, int y, pair<int, int> dir) {
    x += dir.first;
    y += dir.second;
    if (x < 0 || y < 0 || x >= 2 * n || y >= 2 * n) {
        return;
    }
    a[x][y] = -1;
}

