    sort(dir.begin(), dir.end());
    dir.resize(unique(dir.begin(), dir.end()) - dir.begin());

    for (int i = 0; i < 2 * n; ++i) {
        for (int j = 0; j < 2 * n; ++j) {
            if (a[i][j] == 0) {
                a[i][j] = 1;
                for (auto d : dir) {
                    apply(i, j, d);
                }
            }
        }
    }

    int have = 0;
    int need = n * n;
    for (int i = 0; i < 2 * n; ++i) {
        for (int j = 0; j < 2 * n; ++j) {
            if (a[i][j] == 1) {
                cout << i << ' ' << j << '\n';
                have++;
            }
            if (have == need) {
                return 0;
            }
        }
    }

    return 0;
}

