int col1[N][N],col2[N][N],vis[N][N],set[N][N],flag[N*N];
vector <pair <int,int> > T1,T2;
vector <pair <int,int> > G[N][N]; 

template <typename _Tp> inline void IN(_Tp&x) {
	char ch;bool flag=0;x=0;
	while(ch=getchar(),!isdigit(ch)) if(ch=='-') flag=1;
	while(isdigit(ch)) x=x*10+ch-'0',ch=getchar();
	if(flag) x=-x;
}

void dfs1(int x,int y,int now,int cnt) {
	col1[x][y]=now,set[x][y]=cnt,(now==1)?++qaq1:++qaq2;
	for(pair <int,int> v:G[x][y])
		if(!col1[v.first][v.second]) dfs1(v.first,v.second,3-now,cnt);
}
void dfs2(int x,int y,int now,int cnt) {
	col2[x][y]=now,set[x][y]=cnt,(now==1)?++qaq1:++qaq2;
	for(pair <int,int> v:G[x][y])
		if(!col2[v.first][v.second]) dfs2(v.first,v.second,3-now,cnt);
}

inline bool check(int x,int y) {return (x>0&&y>0&&x<=lim&&y<=lim);}
int main() {
	IN(n),IN(D1),IN(D2),lim=n<<1;
	for(int i=0;i<=lim;++i)
		for(int j=0;j<=lim;++j) {
			if(i*i+j*j==D1) T1.push_back(MKP(i,j));
			if(i*i+j*j==D2) T2.push_back(MKP(i,j));
		}
	for(int x=1;x<=lim;++x)
		for(int y=1;y<=lim;++y)
			for(pair <int,int> now:T1) {
				int dx=now.first,dy=now.second;
				if(check(x+dx,y+dy)) G[x][y].push_back(MKP(x+dx,y+dy));
				if(check(x-dx,y+dy)) G[x][y].push_back(MKP(x-dx,y+dy));
				if(check(x+dx,y-dy)) G[x][y].push_back(MKP(x+dx,y-dy));
				if(check(x-dx,y-dy)) G[x][y].push_back(MKP(x-dx,y-dy));
			}
	int cnt=0;
	for(int x=1;x<=lim;++x)
		for(int y=1;y<=lim;++y) if(!col1[x][y]) {
			qaq1=0,qaq2=0,dfs1(x,y,1,++cnt);
			if(qaq1<qaq2) swap(qaq1,qaq2),flag[cnt]=true;
		}
	for(int x=1;x<=lim;++x)
		for(int y=1;y<=lim;++y)
			if(flag[set[x][y]]) col1[x][y]=3-col1[x][y];
	for(int x=1;x<=lim;++x)
		for(int y=1;y<=lim;++y)
			G[x][y].clear();
	for(int x=1;x<=lim;++x)
		for(int y=1;y<=lim;++y)
			for(pair <int,int> now:T2) {
				int dx=now.first,dy=now.second;
				if(check(x+dx,y+dy)) G[x][y].push_back(MKP(x+dx,y+dy));
				if(check(x-dx,y+dy)) G[x][y].push_back(MKP(x-dx,y+dy));
				if(check(x+dx,y-dy)) G[x][y].push_back(MKP(x+dx,y-dy));
				if(check(x-dx,y-dy)) G[x][y].push_back(MKP(x-dx,y-dy));
			}
	cnt=0;
	memset(set,0,sizeof(set)),
	memset(flag,0,sizeof(flag));
	for(int x=1;x<=lim;++x)
		for(int y=1;y<=lim;++y) if(!col2[x][y]) {
			qaq1=0,qaq2=0,dfs2(x,y,1,++cnt);
			if(qaq1<qaq2) swap(qaq1,qaq2),flag[cnt]=true;
		}
	for(int x=1;x<=lim;++x)
		for(int y=1;y<=lim;++y)
			if(flag[set[x][y]]) col2[x][y]=3-col2[x][y];
	cnt=0;
	for(int x=1;x<=lim;++x)
		for(int y=1;y<=lim;++y)
			if(col1[x][y]==col2[x][y]&&col2[x][y]==1) {
				printf("%d %d\n",x-1,y-1),++cnt;
				if(cnt>=n*n) return 0;
			}
	return 0;
}

