const int MAX_D = 1e6 + 10;
int isSq[MAX_D];
vector<int> sqs;

void buildSq() {
    rep(i, MAX_D) isSq[i] = -1;
    for (int i = 0; (ll)i * i <= MAX_D; ++i) {
        isSq[i * i] = i;
        sqs.push_back(i * i);
    }
}

using P = pair<int, int>;
vector<P> getSqSum(int d) {
    vector<P> ret;
    for (auto& sq : sqs) {
        if (d - sq < 0) break;
        if (isSq[d - sq] != -1) {
            ret.push_back(make_pair(isSq[sq], isSq[d - sq]));
        }
    }
    return ret;
}

const int MAX_N = 310;
bool used[2 * MAX_N][2 * MAX_N];

bool check(int y, int x, int n) {
    if (y < 0 || y >= 2 * n || x < 0 || x >= 2 * n) return true;
    if (used[y][x]) return false;
    return true;
}
vector<P> dd[2];

vector<P> calc(int n) {
    rep(y, 2 * MAX_N) rep(x, 2 * MAX_N) {
        used[y][x] = false;
    }
    vector<P> ans;
    rep(y, 2 * n) rep(x, 2 * n) {
        bool f = true;
        rep(i, 2) {
            for (auto& p : dd[i]) {
                int a = p.fi;
                int b = p.se;
                f &= check(y + a, x + b, n);
                f &= check(y + a, x - b, n);
                f &= check(y - a, x + b, n);
                f &= check(y - a, x - b, n);
            }
        }
        if (f) {
            ans.push_back({y, x});
            used[y][x] = true;
        }
        if (ans.size() == n * n) {
            return ans;
        }
    }
    return {};
}

vector<P> calc2(int n, const vector<P>& v) {
    rep(y, 2 * MAX_N) rep(x, 2 * MAX_N) {
        used[y][x] = false;
    }
    vector<P> ans;
    rep(idx, v.size()) {
        int x = v[idx].se;
        int y = v[idx].fi;
        bool f = true;
        rep(i, 2) {
            for (auto& p : dd[i]) {
                int a = p.fi;
                int b = p.se;
                f &= check(y + a, x + b, n);
                f &= check(y + a, x - b, n);
                f &= check(y - a, x + b, n);
                f &= check(y - a, x - b, n);
            }
        }
        if (f) {
            ans.push_back({y, x});
            used[y][x] = true;
        }
        if (ans.size() == n * n) {
            return ans;
        }
    }
    return {};
}
void printAns(const vector<P>& ans) {
    rep(i, ans.size()) cout << ans[i].fi << " " << ans[i].se << endl;
}

int main() {
    buildSq();
    LINE;
    int n, d1, d2;
    cin >> n >> d1 >> d2;
    LINE;
    dd[0] = getSqSum(d1);
    dd[1] = getSqSum(d2);
    auto ans = calc(n);
    if (ans.size() > 0) {
        printAns(ans);
        return 0;
    }

    int dx[] = {1, 0, -1, 0};
    int dy[] = {0, 1, 0, -1};
    auto isOutOfRange = [](int h, int w, int H, int W) {
        return h < 0 || h >= H || w < 0 || w >= W;
    };
    rep(y, 2 * MAX_N) rep(x, 2 * MAX_N) {
        used[y][x] = false;
    }
    vector<P> v;
    int x = 0, y = 0, dir = 0;
    rep(_, 4 * n * n) {
        v.push_back({y, x});
        used[y][x] = true;
        int nx = x + dx[dir];
        int ny = y + dy[dir];
        if (isOutOfRange(ny, nx, 2 * n, 2 * n) || used[ny][nx]) {
            dir++;
            dir %= 4;
            nx = x + dx[dir];
            ny = y + dy[dir];
        }
        x = nx;
        y = ny;
    }


    ans = calc2(n, v);
    if (ans.size() > 0) {
        printAns(ans);
        return 0;
    }

    reverse(all(v));
    ans = calc2(n, v);
    if (ans.size() > 0) {
        printAns(ans);
        return 0;
    }

    v.clear();
    rep(y, 2 * n) rep(x, 2 * n) v.push_back({y, x});
    srand(time(NULL));
    rep(i, 60) {
        rep(i, 1010) {
            int x = rand() % v.size();
            int y = rand() % v.size();
            swap(v[x], v[y]);
        }
        ans = calc2(n, v);
        if (ans.size() > 0) {
            printAns(ans);
            return 0;
        }
    }


    // assert(false);
    return 0;
}

