#include <bits/stdc++.h>
using namespace std;

const int N = 6e2+5;

int n , d[2];
int vis[2][N][N] , cnt[3][3];
vector<pair<int , int> > v[2];

bool f(int x , int y){
	return (x > 0 and y > 0 and x <= 2 * n and y <= 2 * n);
}

void dfs(int fos , int i , int j , int col);

void g(int fos , int x , int y , int col){
	if(f(x , y) and vis[fos][x][y] == -1)dfs(fos , x , y , col);
}

void dfs(int fos , int i , int j , int col){
	vis[fos][i][j] = col;
	col ^= 1;
	for(auto it : v[fos]){
		g(fos , i + it.first , j + it.second , col);
		g(fos , i + it.first , j - it.second , col);
		g(fos , i - it.first , j + it.second , col);
		g(fos , i - it.first , j - it.second , col);
		if(it.first != it.second){
			g(fos , i + it.second , j + it.first , col);
			g(fos , i + it.second , j - it.first , col);
			g(fos , i - it.second , j + it.first , col);
			g(fos , i - it.second , j - it.first , col);
		}
	}
}

int main(){
	cin >> n >> d[0] >> d[1];
	for(int i = 0;i * i <= d[0]/2;i++){
		int j = d[0] - i * i;
