		if(j == k * k){
			v[0].push_back(make_pair(i , k));
		}
	}
	for(int i = 0;i * i <= d[1]/2;i++){
		int j = d[1] - i * i;
		int k = sqrt(j);
		if(j == k * k){
			v[1].push_back(make_pair(i , k));
		}
	}
	memset(vis , -1 , sizeof(vis));
	for(int i = 1;i <= 2 * n;i++){
		for(int j = 1;j <= 2 * n;j++){
			if(vis[0][i][j] == -1)dfs(0 , i , j , 0);
			if(vis[1][i][j] == -1)dfs(1 , i , j , 0);
		}
	}
	for(int i = 1;i <= 2 * n;i++){
		for(int j = 1;j <= 2 * n;j++){
			cnt[vis[0][i][j]][vis[1][i][j]]++;
		}
	}
	int a = 0 , b = 0 , c = 0;
	for(int i = 0;i < 2;i++)for(int j = 0;j < 2;j++)if(c < cnt[i][j]){
		a = cnt[i][j];
		a = i;
		b = j;
	}
	int ans = n * n;
	for(int i = 1;i <= 2 * n;i++){
		for(int j = 1;j <= 2 * n;j++){
			if(vis[0][i][j] == a and vis[1][i][j] == b and ans > 0){
