#define INF 1145141919
vector<P> group(vector<P> all, int D) {
  vector<P> ret;
  if (D%2) {
    // (x+y)%2
    for (P p : all) if ((p._1+p._2)%2 == 0) ret.pb(p);
  }
  else if (D%4 == 2) {
    // x%2
    for (P p : all) if (p._1%2 == 0) ret.pb(p);
  }
  else {
    rep(a, 2) rep(b, 2) {
      vector<P> seq;
      for (P p : all) if (p._1%2 == a && p._2%2 == b) seq.pb(P((p._1-a)/2, (p._2-b)/2));
      vector<P> q = group(seq, D/4);
      for (P p : q) ret.pb(P(p._1*2+a, p._2*2+b));
    }
  }
  return ret;
}

