}f[N];
struct MSolve
{
	int D,top=0,cnt=1;
	int cx[50],cy[50],col[N],vis[N];
	void dfs(int x,int y)
	{
		int id=p(x,y),i,v,t1,t2,nx,ny;
		vis[id]=1;
		//printf("P%d %d  %d\n",x,y,col[id]);
		f[tot].s[col[id]].pb(id);
		for(i=1;i<=top;i++)
		{
			for(t1=0;t1<2;t1++)
			{	
				for(t2=0;t2<2;t2++)
				{
					nx=x+(t1==0?cx[i]:-cx[i]);ny=y+(t2==0?cy[i]:-cy[i]);
					if(nx>=1&&nx<=n&&ny>=1&&ny<=n) 
					{
						v=p(nx,ny);col[v]=col[id]^1;
						if(!vis[v]) dfs(nx,ny);
					}
				}
			}
		}
	}
	void solve()
	{
		int i,j,w;
		cin>>D;
		if(D==las) return ;
		las=D;
		for(i=0;i<n&&i*i<=D;i++)
		{
			w=floor(sqrt(D-i*i)+0.5);
			if(i*i+w*w==D) 
			{
				top++;cx[top]=i;cy[top]=w;
			}
		}

        tot++;
		for(i=1;i<=n;i++)
		{
			for(j=1;j<=n;j++)
			{
				if(vis[p(i,j)]) continue;
				dfs(i,j);
			}
		}
		//en=clock();
		//printf("time%d\n",(int)(en-st));
	}
}h1,h2;
bool cmp(const int &a,const int &b){return f[a].s[0].size()+f[a].s[1].size()>f[b].s[0].size()+f[b].s[1].size();}
void dfs(int xh,int nas)
{
	if(nas<B) return ;
	if(xh==tot+1)
	{
		int num=0;
		for(int i=1;i<=n;i++)
		{
			for(int j=1;j<=n;j++)
			{
				if(del[p(i,j)]==0) num++,printf("%d %d\n",i-1,j-1);
				if(num==B) exit(0);
			}
		}
		return ;
	}
	int val,i,id;
	for(i=0;i<2;i++)
	{
		id=pl[xh];
		val=nas;
		for(int x:f[id].s[i])
		{
			if(!del[x]) val--;
			del[x]++;
		}
		dfs(xh+1,val);
		for(int x:f[id].s[i])
		{
			del[x]--;
			if(!del[x]) val++;
		}
	}
}
