{
	int i;
	cin>>n;n*=2;
	B=(n>>1)*(n>>1);
	h1.solve();h2.solve();
	for(i=1;i<=tot;i++) pl[i]=i;
	sort(pl+1,pl+tot+1,cmp);
	dfs(1,n*n);
	return 0;
}

