const int dx[4] = {1, 1, -1, -1}, dy[4] = {-1, 1, -1, 1};

int n, d1, d2;

vector <pii> c1, c2, ans;

int col[2][maxn][maxn], sum[4], tmp;

void dfs(int x, int y, int typ)
{
	if(col[0][x][y] != -1) return ;
	col[0][x][y] = typ;
	for(pii i : c1)
	{
		rep(j, 0, 3)
		{
			int tx = x + dx[j] * i.fi, ty = y + dy[j] * i.se;
			if(tx < 0 || ty < 0 || tx >= 2 * n || ty >= 2 * n) continue;
			dfs(tx, ty, typ ^ 1);
		}
	}
}

void dfs2(int x, int y, int typ)
{
	if(col[1][x][y] != -1) return ;
	col[1][x][y] = typ;
	for(pii i : c2)
	{
		rep(j, 0, 3)
		{
			int tx = x + dx[j] * i.fi, ty = y + dy[j] * i.se;
			if(tx < 0 || ty < 0 || tx >= 2 * n || ty >= 2 * n) continue;
			dfs(tx, ty, typ ^ 1);
		}
	}
}

int dis(pii a, pii b)
{
	return (a.fi - b.fi) * (a.fi - b.fi) + (a.se - b.se) * (a.se - b.se);
}

signed main()
{
	scanf("%d %d %d", &n, &d1, &d2);
	rep(i, 0, 2 * n) if((int)(sqrt(d1 - i * i)) * (int)(sqrt(d1 - i * i)) == d1 - i * i) c1.pb(mp(i, sqrt(d1 - i * i)));
	rep(i, 0, 2 * n) if((int)(sqrt(d2 - i * i)) * (int)(sqrt(d2 - i * i)) == d2 - i * i) c2.pb(mp(i, sqrt(d2 - i * i)));
	ass(col, -1);
	dfs(0, 0, 0), dfs2(0, 0, 0);
	rep(i, 0, 2 * n - 1) rep(j, 0, 2 * n - 1) sum[col[0][i][j] * 2 + col[1][i][j]] ++;
	rep(i, 0, 3) if(sum[i] >= n * n)
	{
		tmp = i;
		break;
	}
	rep(i, 0, 2 * n - 1) rep(j, 0, 2 * n - 1)
	{
		if(col[0][i][j] * 2 + col[1][i][j] == tmp) ans.pb(mp(i, j));
		if(siz(ans) == n * n) goto end;
	}
	end :;
	for(pii i : ans) for(pii j : ans) if(dis(i, j) == d1 || dis(i, j) == d2) puts("NMSL"), exit(0);
	assert(0);
	return 0;
}

