int main(){
    cin >> n >> p1 >> p2;
    //n=300; p1=5; p2=17;
    for (int i=0;i*i<=p1;i++){
        int j=sqrt(p1-i*i+0.5);
        if (i*i+j*j==p1){
            f.push_back({i,j});
            f.push_back({-i,-j});
            if (i&&j){
                f.push_back({-i,j});
                f.push_back({i,-j});
            }
        }
    }
    for (int i=0;i*i<=p2;i++){
        int j=sqrt(p2-i*i+0.5);
        if (i*i+j*j==p2){
