    }
    */
    for (int i=0;i<n;i++) for (int j=0;j<n;j++){
        for (int k=0;k<f.size();k++){
            int i2=i+f[k].F,j2=j+f[k].S;
            if (i2>=0&&i2<n&&j2>=0&&j2<n) h[i][j].push_back(i2*n+j2),b[i][j]--;
        }
