using namespace std;

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	int n,d1,d2;
	cin >> n >> d1 >> d2;
	vector<int> sqrt(4 * n * n,-1);
	for (int i = 0;i < 2 * n;i++) {
		sqrt[i * i] = i;
	}
	vector<vector<int>> alive(2 * n,vector<int>(2 * n,1));
	auto solve = [&](int d) {
		vector<vector<int>> dead(2 * n,vector<int>(2 * n,0));
		for (int i = 0;i < 2 * n;i++) {
			for (int j = 0;j < 2 * n;j++) {
				if (!alive[i][j] || dead[i][j]) continue;
				vector<pair<int,int>> pq = {make_pair(i,j)};
				dead[i][j] = 1;
				for (int i = 0;i < (int)pq.size();i++) {
					pair<int,int> now = pq[i];
					for (int nx = 0;nx < 2 * n;nx++) {
						int D = d - (now.first - nx) * (now.first - nx);
						if (D >= 0 && D < 4 * n * n && sqrt[D] != -1) {
							D = sqrt[D];
							int ny = now.second - D;
							if (ny >= 0 && ny < 2 * n && alive[nx][ny] && !dead[nx][ny]) {
								pq.emplace_back(nx,ny);
								dead[nx][ny] = 3 - dead[now.first][now.second];
							}
							if (D) {
								ny = now.second + D;
								if (ny >= 0 && ny < 2 * n && alive[nx][ny] && !dead[nx][ny]) {
									pq.emplace_back(nx,ny);
									dead[nx][ny] = 3 - dead[now.first][now.second];
								}
							}
						}
					}
				}
				vector<int> cnt(4);
				for (auto&x : pq) cnt[dead[x.first][x.second]]++;
				int cc = cnt[1] > cnt[2] ? 1 : 2;
				for (auto&x : pq) {
					if (dead[x.first][x.second] != cc) {
						alive[x.first][x.second] = 0;
					}
				}
			}
		}
	};
	solve(d1);solve(d2);
	int rem = n * n;
	for (int i = 0;i < 2 * n;i++) {
		for (int j = 0;j < 2 * n;j++) {
			//cout << alive[i][j] <<" ";
			if (alive[i][j] && rem) {
				--rem;
				cout << i <<" " << j <<"\n";
			}
		}
		//cout << endl;
	}
	assert(!rem);
}

