	int yy[(N*N)];
	bool pp[N];
	vector<int> np[N];
	int n, k;
	int x, y, z;
	int b, c;
	long long s, ans;
	bool v;
	s = 0;
	ans = 0;
	scanf("%d %d %d", &n,&b,&c);
	f(i, N)pp[i] = false;
	f(i, N){
		f(j, N){
			x = (i*i) + (j*j);
			if ((x == b) || (x == c)){
				pp[i] = true;
				pp[j] = true;
			}
		}
	}
	k = 0;
	f(i, (2*n)){
		f(j, k){
			if (pp[(i - xx[j])])np[i].push_back(j);
		}
		f(j, (2*n)){
			v = true;
			f(ii, np[i].size()){
				z = ((i - xx[np[i][ii]])*(i - xx[np[i][ii]]));
				z += ((j - yy[np[i][ii]])*(j - yy[np[i][ii]]));
				if (z == b)v = false;
				if (z == c)v = false;
			}
			if (v){
				xx[k] = i;
				yy[k] = j;
				if (pp[0])np[i].push_back(k);
				k++;
			}
			if (k >= (n*n))break;
		}
	}
	f(i, (n*n)){
		printf("%d %d\n", xx[i], yy[i]);
	}

	return 0;
}

