{
	edge[++ce] = (Edge){v,first[u]};
	first[u] = ce;
}

void work(int v)
{
	gg.clear();
	for (int i = 0;2 * i * i <= v;i++)
		for (int j = i;i * i + j * j <= v;j++)
			if (i * i + j * j == v)
			{
				gg.push_back(make_pair(i,j));
				gg.push_back(make_pair(j,i));
			}
}

void dfs(int u,int c,int tp)
{
	if (~col[tp][u])
		return;
	col[tp][u] = c;
	for (int i = first[u];i;i = edge[i].nxt)
		dfs(edge[i].to,c ^ 1,tp);
}

