#include<bits/stdc++.h>
#define ll unsigned long long
#define N 605
using namespace std;
int n,dx1,dy1,dx2,dy2,d1,d2,x[100000],y[100000];
bool vis[N][N];
void WORK(int x,int y){
	if (x<0||x>=2*n||y<0||y>=2*n) return;
	vis[x][y]=1;
}
void work(int x,int y){
	int tx,ty; 
	tx=x+dx1,ty=y+dy1;
	WORK(tx,ty);
	tx=x+dx1,ty=y-dy1;
	WORK(tx,ty);
	tx=x-dx1,ty=y+dy1;
	WORK(tx,ty);
	tx=x-dx1,ty=y-dy1;
	WORK(tx,ty);

	swap(dx1,dy1);

	tx=x+dx1,ty=y+dy1;
	WORK(tx,ty);
	tx=x+dx1,ty=y-dy1;
	WORK(tx,ty);
	tx=x-dx1,ty=y+dy1;
	WORK(tx,ty);
	tx=x-dx1,ty=y-dy1;
	WORK(tx,ty);

	tx=x+dx2,ty=y+dy2;
	WORK(tx,ty);
	tx=x+dx2,ty=y-dy2;
	WORK(tx,ty);
	tx=x-dx2,ty=y+dy2;
	WORK(tx,ty);
	tx=x-dx2,ty=y-dy2;
	WORK(tx,ty);

	swap(dx2,dy2);

	tx=x+dx2,ty=y+dy2;
	WORK(tx,ty);
	tx=x+dx2,ty=y-dy2;
	WORK(tx,ty);
	tx=x-dx2,ty=y+dy2;
	WORK(tx,ty);
	tx=x-dx2,ty=y-dy2;
	WORK(tx,ty);

	vis[x][y]=1;
}
int main(){
	scanf("%d%d%d",&n,&d1,&d2);
	for (int i=1;i*i<=d1;i++){
		int tmp=int(sqrt(d1-i*i)+0.5);
		if (tmp*tmp+i*i==d1){
			dx1=i;
			dy1=tmp;
			break;
		}
	}
	for (int i=1;i*i<=d2;i++){
		int tmp=int(sqrt(d2-i*i)+0.5);
		if (tmp*tmp+i*i==d2){
			dx2=i;
			dy2=tmp;
			break;
		}
	}
	//printf("%d %d %d %d\n",dx1,dy1,dx2,dy2);
