bool ca2(int x,int y,int d){
	if(d%4==0){
		return ca2(x/2,y/2,d/4);
	}
	if(d%2==0){
		if(x%2==0) return true;return false;
	}
	if((x+y)%2==0) return true;return false;
}
bool cal(int x,int y,int d1,int d2){
	if(d1%4!=0 && d2%4!=0){
		if(x%2==0 && y%2==0) return true;return false;
	}
	if(d1%4==0 && d2%4==0){
		return cal(x/2,y/2,d1/4,d2/4);
	}
	if(d1%4==0) swap(d1,d2);
	if(d1%2==0){
		if(x%2==0) return ca2(x/2,y/2,d2/4);return false;
	}
	if((x+y)%2==0) return ca2(x/2,y/2,d2/4);return false;
}
