void dfs(int si, int sj, int ind, int cl){
	col[ind][si][sj] = cl;
	//return;
	REP(k, 0, SZ(ee[ind])){
		int di = ee[ind][k]._1;
		int dj = ee[ind][k]._2;
		int i1 = si + di, j1 = sj + dj;
		if (i1 >= 0 && i1 < 2 * n && j1 >= 0 && j1 < 2 * n && !col[ind][i1][j1]){
			dfs(i1, j1, ind, 3 - cl);
		}
	}
}

void solve(){
	int d[2];
	cin >> n >> d[0] >> d[1];
	REP(i, -2 * n + 1, 2 * n){
		REP(j, -2 * n + 1, 2 * n){
			REP(k, 0, 2){
				if (i * i + j * j == d[k]){
					ee[k].pb(mp(i, j));
				}
			}
		}
	}

	REP(k, 0, 2){
		REP(i, 0, 2 * n){
			REP(j, 0, 2 * n){
				if (!col[k][i][j]){
					dfs(i, j, k, 1);
				}
			}
		}
	}

	REP(i, 0, 2 * n){
		REP(j, 0, 2 * n){
			col_cnt[col[0][i][j]][col[1][i][j]]++;
		}
	}

	int maxi = 1, maxj = 1;
	REPN(i, 1, 2){
		REPN(j, 1, 2){
			if (col_cnt[i][j] > col_cnt[maxi][maxj]){
				maxi = i;
				maxj = j;
			}
		}
	}

	int printed = 0;
	REP(i, 0, 2 * n){
		REP(j, 0, 2 * n){
			if (printed < n * n && col[0][i][j] == maxi && col[1][i][j] == maxj){
				printf("%d %d\n", i, j);
				printed++;
			}
		}
	}
}   

