ll modx(ll Base, ll exponent)
{
	ll ans = 1;
	if(Base == 1)
		return Base;
	while(exponent)
	{
		if(exponent & 1)
			ans = (ans * Base)%mod;
		Base = (Base * Base)%mod;
		exponent = exponent >> 1;
	}
	return ans;
}

ll inmodx(ll num)
{
	return (modx(num, mod-2LL));
}

bool cmp(pair < pii, int > a, pair < pii, int > b)//true for a before b
{
	if(a.F.F/300 < b.F.F/300)
		return 1;
	if(a.F.F/300 > b.F.F/300)
		return 0;
	if(a.F.S < b.F.S)
		return 1;
	if(a.F.S > b.F.S)
		return 0;
	if(a.F <= b.F)
		return 1;
	return 0;
}

const int N = (6e2) + 9;
const int M = (36e4) + 9;
const int LOGN = ((int)log2(N)) + 3;
const int LOGM = ((int)log2(M)) + 3;
const int BUCK = 2*550;
const int SQRT = BUCK+9;

vector < pii > arr, ans;
int node[N][N];
pii val[M];
vi v[M];
bool vis[M];
int deg[M];
priority_queue < pii > pq;

void solve()
{
	int n, d1, d2, i, j, d, cnt = 0, a;
	pii z;
	cin >> n >> d1 >> d2;
	fo(i,0,n+n)
		fo(j,0,n+n)
		{
			int d = i*i + j*j;
			if(d == d1 || d == d2)
				arr.pb({i,j});
		}
	fo(i,0,n+n)
		fo(j,0,n+n)
		{
			node[i][j] = cnt;
			val[cnt] = {i,j};
			cnt++;
		}
	fo(i,0,n+n)
		fo(j,0,n+n)
		{
			for(auto x : arr)
				if(i+x.F <= n+n && j+x.S <= n+n)
				{
					v[node[i][j]].pb(node[i+x.F][j+x.S]);
					v[node[i+x.F][j+x.S]].pb(node[i][j]);
				}
		}
	fo(i,0,cnt)
	{
		deg[i] = sz(v[i]);
		pq.push({-sz(v[i]),i});
	}
	while(!pq.empty())
	{
		z = pq.top();
		a = z.S;
		pq.pop();
		if(vis[a])
			continue;
		ans.pb(val[a]);
		vis[a] = 1;
		for(auto x : v[a])
		{
			if(!vis[x])
				for(auto y : v[x])
				{
					deg[y]--;
					pq.push({-deg[y],y});
				}
			vis[x] = 1;
		}
	}
	assert(sz(ans) >= n*n);
	fo(i,0,n*n)
		cout << ans[i].F << " " << ans[i].S << '\n';
	return;
}

