typedef long long ll;

const int ME = 20000500;

int n, d1, d2;

struct GRAPH
{
	int fst[ME], nxt[ME], v[ME], lnum;

	void addeg(int nu, int nv)
	{
		nxt[++lnum] = fst[nu];
		fst[nu] = lnum;
		v[lnum] = nv;
		nxt[++lnum] = fst[nv];
		fst[nv] = lnum;
		v[lnum] = nu;
	}

	int col[ME], num[3];

	void dfs(int x, int c)
	{
		assert(!col[x] || col[x]==c);
		if(col[x]) return;
		else col[x] = c, num[c]++;
		for(int i=fst[x]; i; i=nxt[i])
			dfs(v[i], 3-c);
	}

	void color()
	{
		for(int i=0; i<n*n*4; i++)
			if(!col[i])
				dfs(i, 1);
	}
} G1, G2;

int id(int x, int y)
{
	assert(x>=0 && x<n*2);
	assert(y>=0 && y<n*2);
	return x*(n*2) + y;
}

void build(GRAPH &g, int d)
{
	for(int i=0; i*i<=d; i++)
		for(int j=0; j*j<=d; j++)
			if(i*i + j*j == d)
				for(int x=0; x<n*2; x++)
					for(int y=0; y<n*2; y++)
					{
						if(x+i<n*2 && y+j<n*2) g.addeg(id(x, y), id(x+i, y+j));
						if(x+i<n*2 && y-j>=0) g.addeg(id(x, y), id(x+i, y-j));
					}
}

void print()
{
	int rem = n*n;
	int c1 = ((G1.num[1]>G1.num[2]) ? 1 : 2);
	int c2 = ((G2.num[1]>G2.num[2]) ? 1 : 2);
	for(int i=0; i<n*n*4; i++)
		if(rem && G1.col[i]==c1 && G2.col[i]==c2)
			printf("%d %d\n", i%(n*2), i/(n*2)), rem--;
	assert(!rem);
}

int main()
{
	scanf("%d%d%d", &n, &d1, &d2);
	build(G1, d1);
	build(G2, d2);
	G1.color();
	G2.color();
	print();
	return 0;
}

