	if (x%4==0){
		x/=4;
		c++;
	} 
	if (x & 1){
		for (int i=0;i<2*n;i++)
			for (int j=0;j<2*n;j++)
				if (((i>>c)+(j>>c)) & 1)
					a[i][j]=1;
	}
	else
	{
		for (int i=0;i<2*n;i++)
			for (int j=0;j<2*n;j++)
				if ((i>>c) & 1)
					a[i][j]=1;	
	} 
}

