int N,D1,D2;
vpi bad;
bool done[600][600];
int adj[600][600];
priority_queue<pair<int,pi>,vector<pair<int,pi>>,greater<pair<int,pi>>> bes;

void ad(int a, int b, int x) {
    for (auto z: bad) for (int i = -1; i <= 1; i += 2) for (int j = -1; j <= 1; j += 2) {
        pi Z = {a+z.f*i,b+z.s*j};
        if (Z.f < 0 || Z.f >= 2*N || Z.s < 0 || Z.s >= 2*N) continue;
        if (x == 1) adj[a][b] ++;
        else if (!done[Z.f][Z.s]) {
            adj[Z.f][Z.s] --;
            bes.push({adj[Z.f][Z.s],Z});
        }
    }
    if (x == 1) {
        bes.push({adj[a][b],{a,b}});
    } else done[a][b] = 1;
}

void process(pi x) {
    vpi al = {x};
    for (auto z: bad) for (int i = -1; i <= 1; i += 2) for (int j = -1; j <= 1; j += 2) {
        pi Z = {x.f+z.f*i,x.s+z.s*j};
        if (Z.f < 0 || Z.f >= 2*N || Z.s < 0 || Z.s >= 2*N) continue;
        if (!done[Z.f][Z.s]) al.pb(Z);
    }
    for (auto x: al) ad(x.f,x.s,-1);
}

void solve() {
    bad.clear();
    // F0R(i,600) F0R(j,600) adj[i][j].clear();
    if (D1 > D2) swap(D1,D2);
    for (int i = 0; i <= 500; ++i) for (int j = 0; j <= 500; ++j) 
        if (i*i+j*j == D1 || i*i+j*j == D2) bad.pb({i,j});

    F0R(i,2*N) F0R(j,2*N) ad(i,j,1);
    int lef = N*N, co = 0;
    while (lef && co < 100) {
        if (!sz(bes)) {
            cout << "OOPS " << D1 << " " << D2 << "\n";
            return;
        }
