using namespace std;

vector<vector<int>> color(int N, int D)
{
    vector<int> Dx, Dy;
    for (int y=0; y<2*N; y++)
    for (int x=0; x<2*N; x++)
    if (x*x+y*y==D)
    {
        Dx.push_back(x);
        Dy.push_back(y);
        if (y>0)
        {
            Dx.push_back(x);
            Dy.push_back(-y);
        }
        if (x>0)
        {
            Dx.push_back(-x);
            Dy.push_back(y);
        }
        if (x>0 && y>0)
        {
            Dx.push_back(-x);
            Dy.push_back(-y);
        }
    }

    vector<vector<int>> C(2*N, vector<int>(2*N, -1));

    function<void (int, int, int)> BT = [&](int x, int y, int c)
    {
        C[y][x] = c;
        for (int d=0; d<(int)Dx.size(); d++)
        {
            int dx = x + Dx[d];
            int dy = y + Dy[d];
            if (0<=dx && dx<2*N && 0<=dy && dy<2*N &&
                C[dy][dx] == -1)
                BT(dx, dy, 1-c);
        }
    };

    for (int y=0; y<2*N; y++)
    for (int x=0; x<2*N; x++)
    if (C[y][x]==-1)
        BT(x, y, 0);

    return C;
}

int main()
{
    int N, D1, D2;
    cin>>N>>D1>>D2;

    vector<vector<int>> C1 = color(N, D1);
