    vector<int> X[4], Y[4];
    for (int y=0; y<2*N; y++)
    for (int x=0; x<2*N; x++)
    {
        int c = C1[y][x] + 2*C2[y][x];
        X[c].push_back(x);
        Y[c].push_back(y);
    }

    for (int i=0; i<4; i++)
    if ((int)X[i].size() >= N*N)
    {
        for (int j=0; j<N*N; j++)
            cout<<X[i][j]<<" "<<Y[i][j]<<endl;
        break;
    }
}

