    for(auto x:prob)
    {
        ll a=k+x.fi,b=l+x.se;
        if(a>=0&&a<2*n&&b>=0&&b<2*n&&bomb[a][b]==0)bomb[a][b]=1,q.push(ii(a,b));
    }
