        q.pop();
        for(auto x:prob)
        {
            ll a=u.fi+x.fi,b=u.se+x.se;
            if(ans.size()==n*n)return;
            if(a>=0&&a<2*n&&b>=0&&b<2*n&&bomb[a][b]==0)
            {
                bomb[a][b]=1,ans.push_back(ii(a,b));
                for(auto x:prob)
                {
                    ll d=a+x.fi,c=b+x.se;
                    if(d>=0&&d<2*n&&c>=0&&c<2*n&&bomb[d][c]==0)bomb[d][c]=1,q.push(ii(d,c));
                }
            }
        }
    }
