{
    bfs(x.fi,x.se,ans,prob,n);
    for(int i=0;i<2*n;i++)
    {
        if(ans.size()==n*n)break;
        for(int j=0;j<2*n;j++)
        {
            if(ans.size()==n*n)break;
            if(bomb[i][j]==0)bfs(i,j,ans,prob,n);
        }
    }
}
