		int py = y + dy;

		if (px >= 0 && px < 2 * N && py >= 0 && py < 2 * N) {
			//cout << "px:" << px << " py:" << py << endl; 
			canSet[py][px] = false;
		} 
	}
}


vector<pair<int, int> > fillVec(int D) {
	vector<pair<int, int> > v;

	for (int dx = 0; dx < D ; dx++) {
		int dy2 = D - dx * dx;
		int isOK = false;
		int dy = 1;
		while(true) {
			int cur = dy * dy;
			if (cur == dy2) {
				isOK = true;
				v.push_back(make_pair(dx, dy));
			}
			if (cur > dy2) {
				break;
			}
			dy++;
		}
	}
	vector<pair<int, int> > result;

	for(auto cur : v) {
		int x = cur.first;
		int y = cur.second;
		result.push_back(make_pair(x, y));
		result.push_back(make_pair(-y, x));
		result.push_back(make_pair(-x, -y));
		result.push_back(make_pair( y, -x));
	}

	return result;
}


