int encode(int x, int y, int N) {
  return x * N + y;
}

void build_graph(int D, int N, vector<int> E[4*maxn*maxn]) {
for(int x = 0; x < 2 * N; x++) {
    for(int y = 0; y < 2 * N; y++) {
      for(int dx = 0; x + dx < 2 * N; dx++) {
        int X = x + dx;
        // (X - x)^2 + (Y - y)^2 = D1
        int dx2 = dx * dx;
        int dy2 = D - dx2;

        if(dy2 < 0) continue;

        int dy = sqr[dy2];

        if(dy < 0) continue;

        int Y = y + dy;

        if(Y >= 2 * N) continue;

        int u = encode(x, y, 2*N);
        int v = encode(X, Y, 2*N);

        assert( (X - x) * (X - x) + (Y - y) * (Y - y) == D);

        E[u].pb(v);
        E[v].pb(u);


        if(dy == 0) continue;

        Y = y - dy;
        assert( (X - x) * (X - x) + (Y - y) * (Y - y) == D);

        if(Y < 0) continue;

        v = encode(X, Y, 2 * N);

        E[u].pb(v);
        E[v].pb(u);
      }
    }
  }
}

