            if(f[k][ni][nj] != 0) continue;
            f[k][ni][nj] = 3 - f[k][ii][jj];
            q.emplace(ni, nj);
          }
        }
      }
    }
  }
  vector<pair<int, int>> ans;
  for(int k = 1; k <= 2; k++) for(int l = 1; l <= 2; l++) {
    ans.clear();
    for(int i = 0; i < 2*n; i++) for(int j = 0; j < 2*n; j++) {
      if(f[0][i][j] == k && f[1][i][j] == l) ans.emplace_back(i, j);
    }
    if(ans.size() >= n * n) goto out;
  }
  out:
  assert(0);
  assert(ans.size() >= n * n);
  for(int i = 0; i < n * n; i++) cout << ans[i].first << " " << ans[i].second << endl;
}

