template <typename T> inline void read(T &a)
{
    T x=0, flag=1;
    char ch = getchar();
    while(!isdigit(ch)){
        if(ch == '-') flag = -1;
        ch = getchar();
    }
    while(isdigit(ch)){
        x = (x<<1) + (x<<3) + ch - '0';
        ch = getchar();
    }
    a = flag * x;
}

int n, d1, d2;
bool vis[MAXN][MAXN];

void build(int d)
{
	int t = 0;
	while(d % 4 == 0){
		d /= 4;
		++t;
	}
	if(d%4 == 1){
		for(int i=0;i<=n;++i){
			for(int j=0;j<=n;++j){
				if(((i>>t) + (j>>t)) & 1) vis[i][j] = 1;
			}
		}
	}else{
		for(int i=0;i<=n;++i){
			for(int j=0;j<=n;++j){
				if((i>>t) & 1) vis[i][j] = 1;
			}
		}
	}
}

void solve()
{
	read(n); read(d1); read(d2);
	int cnt = n * n, out = 0;
	n <<= 1;
	build(d1); build(d2);
	for(int i=0;i<=n;++i){
		for(int j=0;j<=n;++j){
			if(!vis[i][j]){
				printf("%d %d\n", i, j);
				if(++out == cnt) return;
			}
		}
	}
}

int main()
{
	solve();
	return 0;
}

