struct node{int a, b;};
vector<node> ans[4];

bool vis[2][N][N];
int n, nn, t1, t2, t3, t4, d[2], col[2][N][N];

void Dfs(int x, int y, int o, int c){
	if(x > nn || y > nn || x < 0 || y < 0 || col[o][x][y]) return;
	vis[o][x][y] = true; col[o][x][y] = 3 - c;

	int a = -1;
	while(true){
		++a;
		if(a * a > d[o]) return;

		int b = sqrt(d[o] - a * a);
		if(a * a + b * b != d[o]) continue;

		Dfs(x + a, y + b, o, 3 - c); Dfs(x + a, y - b, o, 3 - c);
		Dfs(x - a, y - b, o, 3 - c); Dfs(x - a, y + b, o, 3 - c);
	}
}

