	For(i, 0, nn) For(j, 0, nn) if(!vis[1][i][j]) Dfs(i, j, 1, 2);

	For(i, 0, nn) For(j, 0, nn){
		node o = (node){i, j};

		if(col[0][i][j] == 1){
			if(col[1][i][j] == 1) ans[0].pb(o); else ans[1].pb(o);
