typedef pair<int,int> pii;
int mp[1005][1005];
int pre[maxn];
bool check(int x,int y){
	for(int i=x;i>=0;i--){
		int flag=0;
		{
			int j=d1-pf(x-i);
			if(pre[j]==-1||j<0){flag=1;}
			j=pre[j];
			j=y-j;
			if(j<0){flag=1;}
			if((!flag)&&mp[i][j])return false;
			j=y-j;
			j=j+y;
			if(j>=2*n){flag=1;}
			if((!flag)&&mp[i][j])return false;
		}
		flag=0;
		{
			int j=d2-pf(x-i);
			if(pre[j]==-1||j<0){flag=1;}
			j=pre[j];
			j=y-j;
			if(j<0){flag=1;}
			if(mp[i][j]&&(!flag))return false;
			j=y-j;
			j=j+y;
			if(j>=2*n)flag=1;
			if(mp[i][j]&&(!flag))return false;
		}
	}
	mp[x][y]=1;
	return true;
} 
