#include <bits/stdc++.h>
using namespace std;
typedef long double ld;
typedef long long ll;
int n;
const int maxN = 305;
int clr[2 * maxN][2 * maxN];
vector<pair<int,int>> shifts;
void dfs(int x, int y) {
    for (auto& it : shifts) {
        int nx = x + it.first;
        int ny = y + it.second;
        if (nx < 0 || nx >= 2 * n || ny < 0 || ny >= 2 * n) continue;
        if (clr[nx][ny] != -1) {
            assert(clr[nx][ny] == clr[x][y] ^ 1);
        }
        else {
            clr[nx][ny] = clr[x][y] ^ 1;
            dfs(nx, ny);
        }
    }
}
int tt[2 * maxN][2 * maxN][2];
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
//    freopen("input.txt", "r", stdin);
    int d1, d2;
    cin >> n >> d1 >> d2;
    vector<int> g = {d1, d2};

    for (int ptr = 0; ptr < 2; ptr++) {
        shifts.clear();
        int C = g[ptr];
        for (int a = -2 * n; a <= 2 * n; a++) {
            for (int b = -2 * n; b <= 2 * n; b++) {
                if (a * a + b * b == C) shifts.emplace_back(a, b);
            }
        }
        memset(clr, -1, sizeof clr);
        for (int i = 0; i < 2 * n; i++) {
            for (int j = 0; j < 2 * n; j++) {
                if (clr[i][j] == -1) {
                    clr[i][j] = 0;
                    dfs(i, j);
                }
            }
        }
        for (int i = 0; i < 2 * n; i++) {
            for (int j = 0; j < 2 * n; j++) {
                tt[i][j][ptr] = clr[i][j];
            }
        }
    }
    vector<pair<int,int>> x[2][2];
    for (int i = 0; i < 2 * n; i++) {
        for (int j = 0; j < 2 * n; j++) {
            x[tt[i][j][0]][tt[i][j][1]].emplace_back(make_pair(i, j));
        }
    }
    for (int r = 0; r < 2; r++) {
        for (int t = 0; t < 2; t++) {
            if (x[r][t].size() >= n * n) {
                x[r][t].resize(n * n);
                for (auto& it : x[r][t]) {
                    cout << it.first << " " << it.second << '\n';
                }
                exit(0);
            }
        }
    }
    assert(false);
    return 0;
}

