void dfs(int u) {
	vis[u] = 1;
	for(int i = head[u];i;i = e[i].nxt) {
		int v = e[i].v;
		if(vis[v]) continue;
		col[v] = col[u] ^ 1;
		dfs(v);
	}
}
int main() {
	n = read(),D1 = read(),D2 = read();

	memset(cf,-1,sizeof(cf));
	for(int i = 0;i <= n + n;++i) cf[i * i] = i;

	for(int i = 0;i < n + n;++i) {
		for(int j = 0;j < n + n;++j) {
			for(int x = 0;x < n + n;++x) {
				if((x - i) * (x - i) > D1) continue;
				int t = D1 - (x - i) * (x - i);
				if(cf[t] == -1) continue;

				if(j - cf[t] >= 0) {
					// printf("%d %d %d %d\n",i,j,x,j - cf[t]);
					add(p(x,j - cf[t]),p(i,j));
				}
				if(j + cf[t] < n + n && cf[t]) {
					// printf("%d %d %d %d\n",i,j,x,j + cf[t]);
					add(p(x,j + cf[t]),p(i,j));
				}
			}
		}
	}

	for(int i = 0;i <= p(n + n - 1,n + n - 1);++i) {
		if(!vis[i]) {
			dfs(i);
		}
	}

	int color = 0;
	if(cnt[1] > cnt[0]) color = 1;

	ejs = 0;memset(head,0,sizeof(head));

	for(int i = 0;i < n + n;++i) {
		for(int j = 0;j < n + n;++j) {
			if(col[p(i,j)] != color) continue;
			// printf("%d %d\n",i,j);
			for(int x = 0;x < n + n;++x) {
				if((x - i) * (x - i) > D2) continue;
				int t = D1 - (x - i) * (x - i);
				if(cf[t] == -1) continue;
				if(j - cf[t] >= 0 && col[p(x,j - cf[t])] == color)
					add(p(x,j - cf[t]),p(i,j));
				if(j + cf[t] < n + n && col[p(x,j + cf[t])] == color)
					add(p(x,j + cf[t]),p(i,j));
			}
		}
	}

	memset(vis,0,sizeof(vis));
	cnt[0] = cnt[1] = 0;
	for(int i = 0;i <= p(n + n - 1,n + n - 1);++i)
		if(!vis[i]) dfs(i);

	color = 0;
	if(cnt[1] > cnt[0]) color = 1;
	int tot = n * n;
	for(int i = 0;i < n + n;++i) {
		for(int j = 0;j < n + n;++j) {
			if(col[p(i,j)] == color && tot) {
				tot--;
				printf("%d %d\n",i,j);
				if(!tot) return 0;
			} 
		}
	}

	return 0;
}

