void crossAll(VVI &M, int N, int D1, int D2) {
	int sx[] = {-1, -1, 1,  1};
	int sy[] = { 1, -1, 1, -1};
	vector<PII> deltas;
	for (int x = 0; x*x <= D1; ++x) {
		int rN = D1 - x*x;
		int y = sqrt(rN) + 1e-9;
		if (y * y != rN) continue;
//		cout << x << " " << y << endl;
		deltas.push_back(PII(x, y));
	}
	for (int x = 0; x*x <= D2; ++x) {
		int rN = D2 - x*x;
		int y = sqrt(rN) + 1e-9;
		if (y * y != rN) continue;
//		cout << x << " " << y << endl;
		deltas.push_back(PII(x, y));
	}

	for (int i = 0; i < M.size(); ++i) {
		for (int j = 0; j < M[i].size(); ++j) {
			if (!M[i][j]) continue;
			for (PII d : deltas) {
				for (int k = 0; k < 4; ++k) {
					int nx = j + sx[k] * d.first;
					int ny = i + sy[k] * d.second;
					if (nx < 0 || nx >= M[i].size()) continue;
					if (ny < 0 || ny >= M.size()) continue;
					M[ny][nx] = 0;
				}
			}

		}
	}
}


