int sz = 0;
void build(int n, int d, vector<int> adj[]) {
    vector<pair<int, int>> v;

    for (int dx=0; dx*dx <= d; dx++) {
        int dy = sqrt(d-dx*dx);
        if (dx*dx+dy*dy != d)   continue;

        v.emplace_back(dx, dy);
        if (dx) v.emplace_back(-dx, dy);
        if (dy) v.emplace_back(dx, -dy);
        if (dx && dy) v.emplace_back(dx, dy);
    }

    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            for (auto pr: v) {
                int nx = i+pr.first;
                int ny = j+pr.second;
                if (0<=nx && nx<n && 0<=ny && ny<n) {
                    adj[i*n+j].push_back(nx*n+ny);
                    sz++;
                }
            }
        }
    }
}

bool bad[N];

int col[N];
int cnt[2];

void dfs(int u, vector<int> adj[]) {
    if (!bad[u])    cnt[col[u]]++;
    for (int v: adj[u]) {
        if (col[v] == -1)   {
            col[v] = !col[u];
            dfs(v, adj);
        }
        assert(col[v] == !col[u]);
    }
}

void bicolor(int n, vector<int> adj[]) {
    memset(col, -1, sizeof col);
    cnt[0] = cnt[1] = 0;

    for (int i=0; i<n*n; i++)
        if (col[i] == -1) {
            col[i] = 0;
            dfs(i, adj);
        }

    bool big = cnt[1] > cnt[0];
    for (int i=0; i<n*n; i++)
        if (col[i] != big)
            bad[i] = 1;
}

