					int Y=j+l*t;
					if(X>=2*a||Y>=2*a)continue;
					v[sz++]=make_pair(X,Y);
				}
			}
			for(int i=0;i<2*a;i++)for(int j=0;j<2*a;j++)p[i][j]=0;
