					cnt++;
					for(int k=0;k<ng.size();k++){
						int tr=i+ng[k].first;
						int tc=j+ng[k].second;
						if(tr<0||tc<0||tr>=a*2||tc>=a*2)continue;
						p[tr][tc]=-1;
					}
				}
			}
			if(cnt>=a*a){
				break;
			}
		}
	}
	if(cnt<a*a){
		assert(0);
	//	printf("NG %d %d %d %d %d\n",x,y,z,a*a,cnt);
	}
	vector<pair<int,int> > ans;
	for(int i=0;i<a*2;i++)for(int j=0;j<a*2;j++){
		if(p[i][j]==1)ans.push_back(make_pair(i,j));
	}
	//printf("OK %d %d %d\n",x,y,z);
	//for(int i=0;i<a*a;i++)printf("%d %d\n",ans[i].first,ans[i].second);
}
