const int MAXN=605;

int n,d1,d2,m;
int dx[MAXN*8],dy[MAXN*8];
bool c[MAXN][MAXN];
int a[MAXN][MAXN],cnt=0;
void work(int d)
{
	for(int i=0;i<=n;++i)
	{
		if(i*i>d)break;
		int j=sqrt(d-i*i);
		if((j+1)*(j+1)+i*i==d)++j;
		if(i*i+j*j==d)
		{
			++m,dx[m]=i,dy[m]=j;
			if(i)++m,dx[m]=-i,dy[m]=j;
			if(j)++m,dx[m]=i,dy[m]=-j;
			if(i&&j)++m,dx[m]=-i,dy[m]=-j;
		}
	}
}
void dfs(int x,int y)
{
	if(cnt*4==n*n)
	{
		for(int i=0;i<n;++i)
			for(int j=0;j<n;++j)
				if(c[i][j])printf("%d %d\n",i,j);
		exit(0);
	}
	if(y>=n)y=0,++x;
	if(x>=n)return;
	if(a[x][y])return dfs(x,y+1);
	for(int i=1;i<=m;++i)
		if(x+dx[i]>=0 && x+dx[i]<n && y+dy[i]>=0 && y+dy[i]<n)
			++a[x+dx[i]][y+dy[i]];
	c[x][y]=1;
	++cnt;
	dfs(x,y+1);
	for(int i=1;i<=m;++i)
		if(x+dx[i]>=0 && x+dx[i]<n && y+dy[i]>=0 && y+dy[i]<n)
			--a[x+dx[i]][y+dy[i]];
	c[x][y]=0;
	--cnt;
}

