struct edge{int to, cost;};

class Graph
{
public:
    int N;
    vector<vector<edge>> G;
    vec label;
    bools used;

    Graph(int N): N(N){
        G = vector<vector<edge>>(N, vector<edge>(0));
        label = vec(N, 0);
        used = bools(N, false);
    }

    void add_edge(int from, int to, int cost = 0){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost = 0){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    void dfs(int v, int l){
        used[v] = true;
        label[v] = l;
        for(auto e: G[v]) if(!used[e.to]) dfs(e.to, 1 - l);
    }

};

void makeGraph(Graph &G, int N, int D){
    pairs p;
    FOR(i, -600, 601) FOR(j, -600, 601) if(i * i + j * j == D) p.pb(Pii(i, j));
    REP(i, N) REP(j, N){
        for(Pii q: p){
            int i0 = i + q.f, j0 = j + q.s;
            if(i0 >= 0 && i0 < N && j0 >= 0 && j0 < N) G.add_edge(i * N + j, i0 * N + j0);
        }
    }
}

