int dy[] = {-1, 1, -1, 1};

const int maxn = 666;
vector<int> g[maxn * maxn];
bool used[maxn * maxn];
bool have[maxn * maxn];
int color[maxn * maxn];

void add_dir(int x, int y, vector<pair<int, int> > &dir) {
    for (int i = 0; i < 4; i++) {
        dir.push_back({x * dx[i], y * dy[i]});
        dir.push_back({y * dx[i], x * dy[i]});
    }
} 

void make_graph(int n, int d) {
    vector<pair<int, int> > dir;
    for (int i = 0; i <= d; i++) {
        if (i * 1ll * i + (d - i) * 1ll * (d - i) == d) {
            add_dir(i, d - i, dir);
        }
    }
    sort(dir.begin(), dir.end());
    dir.resize(unique(dir.begin(), dir.end()) - dir.begin());
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int v = i * n + j;
            g[v].clear();
            for (auto d : dir) {
                int x = i + d.first;
                int y = j + d.second;
                if (x >= 0 && y >= 0 && x < n && y < n) {
                    int u = x * n + y;
                    g[v].push_back(u);
                }
            }
        }
    }
}

int dfs(int v, int col, vector<int> &path) {
    if (used[v] || !have[v]) {
        return 0;
    }
    used[v] = 1;
    color[v] = col;
    path.push_back(v);
    int sum = 0;
    for (auto u : g[v]) {
        sum += dfs(u, col ^ 1, path);
    }
    return (col ^ 1) + sum;
}

vector<int> vert_good(vector<int> vert) {
    memset(used, 0, sizeof(used));
    memset(have, 0, sizeof(have));
    memset(color, -1, sizeof(color));

    for (auto v : vert) {
        have[v] = 1;
    }

    for (auto v : vert) {
        if (have[v] && !used[v]) {
            vector<int> path;
            int cnt = dfs(v, 0, path);
            if (cnt < path.size() - cnt) {
                for (auto u : path) {
                    color[u] ^= 1;
                }
            }           
        }

    }

    vector<int> res;
    for (auto v : vert) {
        if (color[v] == 0) {
            res.push_back(v);
        }
    }
    return res;
}

