unsigned long xor128(void){
    static unsigned long x=123456789,y=362436069,z=521288629,w=88675123;
    unsigned long t;
    t=(x^(x<<11));x=y;y=z;z=w; return( w=(w^(w>>19))^(t^(t>>8)) );
}

ll rand(ll x){
    return xor128() % x;
}
ll rand(ll x, ll y){
    return x + (xor128() % (y - x));
}

int main() {
    int n, d1, d2;
    cin >> n >> d1 >> d2;

    set<P> ng;
    REP(i,N){
        int y = sqrt(d1 - i * i) + EPS;
        if (i * i + y * y == d1){
            ng.insert(P(i, y));
        }
        y = sqrt(d2 - i * i) + EPS;
        if (i * i + y * y == d2){
            ng.insert(P(i, y));
        }
    }

    while (1) {
        int c = 0;
        REP(i,2*n) REP(j,2*n) a[i][j] = 0;
        int notfound = 0;
        int trying = 1;
        while (trying) {
            REP(i,2*n) REP(j,2*n){
                if (a[i][j]) continue;
                bool ok = true;
                for (P p : ng){
                    if (p.first <= i){
                        if (j - p.second >= 0 && a[i - p.first][j - p.second]) ok = false;
                        if (j + p.second < 2 * n && a[i - p.first][j + p.second]) ok = false;
                    }
                    if (i + p.first < 2 * n){
                        if (j - p.second >= 0 && a[i + p.first][j - p.second]) ok = false;
                        if (j + p.second < 2 * n && a[i + p.first][j + p.second]) ok = false;   
                    }
                }
                if (!ok){
                    notfound++;
                    if (notfound == 4 * n * n){
                        trying = 0;
                        i = 2 * n;
                        break;
                    }
                    continue;
                }
                notfound = 0;
                if (ok && rand(2) == 1) {
                    a[i][j] = 1;
                    c++;
                    if (c == n * n){
                        i = 2 * n;
                        j = 2 * n;
                        break;
                    }
                }
            }
        }
        if (c == n * n){
            REP(i,2*n) REP(j,2*n){
                if (a[i][j]) cout << i << " " << j << endl;
            }
            return 0;
        }
    }

    return 0;
}

