void dfs(int i, int j, int c, int col[maxn][maxn], int d) {
	if(i < 0 || j < 0 || i >= n || j >= n || col[i][j]) {
		return;
	}
	col[i][j] = c;
	c = -c;
	for (int x = 0; x * x <= d; ++x) {
		int y = round(sqrt((double)(d - x * x)));
		if(x * x + y * y == d) {
			dfs(i + x, j + y, c, col, d);
			dfs(i - x, j + y, c, col, d);
			dfs(i + x, j - y, c, col, d);
			dfs(i - x, j - y, c, col, d);
		}
	}
	return;
}

void work(int col[maxn][maxn], int d) {
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			if(!col[i][j]) {
				dfs(i, j, 1, col, d);
			}
		}
	}
}

