using Graph = vector<vector<int>>;

int to_v(auto x, auto y, auto N) {return N * x + y;}
int to_x(auto v, auto N) {return v / N;}
int to_y(auto v, auto N) {return v % N;}
int rt(auto d) {
  for(auto i=0; i*i<=d; ++i) if(i*i == d) return i;
  return -1;
}
void paint(const auto& G, auto& color, auto v) {
  function<void(int)> dfs = [&](auto cur) {
    for(auto nex: G[cur]) if(!color[nex]) {
      color[nex] = 3 - color[cur];
      dfs(nex);
    }
  };
  color[v] = 1;
  dfs(v);
}

int main() {
  int N, D1, D2;
  cin >> N >> D1 >> D2;

  vector<int> dx1, dy1, dx2, dy2;
  for(auto x=0; x<2*N; ++x) {
    auto y1 = rt(D1 - x * x);
    auto y2 = rt(D2 - x * x);
    if(y1 != -1) dx1.emplace_back(x), dy1.emplace_back(y1);
    if(y2 != -1) dx2.emplace_back(x), dy2.emplace_back(y2);
  }

  Graph G1(4*N*N), G2(4*N*N);
  for(auto x=0; x<2*N; ++x) for(auto y=0; y<2*N; ++y) {
    for(auto i=0; i<dx1.size(); ++i) {
      auto nx = x + dx1[i];
      auto ny = y + dy1[i];
      if(2*N<=nx || 2*N<=ny) continue;
      auto u = to_v(x, y, 2*N);
      auto v = to_v(nx, ny, 2*N);
      G1[u].emplace_back(v);
      G1[v].emplace_back(u);
    }
    for(auto i=0; i<dx2.size(); ++i) {
      auto nx = x + dx2[i];
      auto ny = y + dy2[i];
      if(2*N<=nx || 2*N<=ny) continue;
      auto u = to_v(x, y, 2*N);
      auto v = to_v(nx, ny, 2*N);
      G2[u].emplace_back(v);
      G2[v].emplace_back(u);
    }
  }

  vector<int> color1(4*N*N), color2(4*N*N);
  for(auto v=0; v<4*N*N; ++v) {
    if(!color1[v]) paint(G1, color1, v);
    if(!color2[v]) paint(G2, color2, v);
  }

  vector<int> count(5);
  for(auto v=0; v<4*N*N; ++v) {
    ++count[color1[v]];
    ++count[color2[v] + 2];
  }

  for(auto c1: {1, 2}) for(auto c2: {3, 4}) {
    if(count[c1] + count[c2] < N * N) continue;
    auto V = 0;
    for(auto v=0; v<4*N*N; ++v)
      if(color1[v]==c1 && color2[v]+2==c2)
        if(V++ < N*N)
          cout << to_x(v, 2*N) << " " << to_y(v, 2*N) << endl;
    return 0;
  }
}

