const int maxn = 300;

vector<int> E1[4*maxn*maxn];
vector<int> E2[4*maxn*maxn];
bool vis[4*maxn*maxn];
int color[4*maxn*maxn];

int encode(int x, int y, int N) {
  return x * N + y;
}

void build_graph(int D, int N, vector<int> E[4*maxn*maxn]) {
for(int x = 0; x < 2 * N; x++) {
    for(int y = 0; y < 2 * N; y++) {
      for(int X = x; X < 2 * N; X++) {
        // (X - x)^2 + (Y - y)^2 = D1
        int dx2 = (X - x) * (X - x);
        if(D < dx2) continue;
        int dy2 = D - dx2;

        int dy = sqrt(dy2);

        if(dy * dy != dy2) continue;

        int Y = y + dy;

        if(Y >= 2 * N) continue;

        int u = encode(x, y, 2*N);
        int v = encode(X, Y, 2*N);

        E[u].pb(v);
        E[v].pb(u);

      }
    }
  }
}

void dfs(int n, int c0, int c1, int c, vector<int> E[4*maxn*maxn]) {
  vis[n] = 1;
  if(c == 0) color[n] |= c0;
  else color[n] |= c1;
  for(auto to : E[n]) {
    if(vis[to]) continue;
    dfs(to, c0, c1, c ^ 1, E);
  }
}

int main() {
