typedef std::pair<int, int> ii;

const int ms = 606;

bool mat[ms][ms];

std::vector<int> evaluate(int n, const std::vector<ii> &points, const std::vector<ii> &forb) {
	std::vector<int> got;
	for(int i = 0; i < points.size() && got.size() < n; i++) {
		bool valid = true;
		for(auto d : forb) {
			int x = points[i].first + d.first;
			int y = points[i].second + d.second;
			if(x >= 0 && y >= 0 && x < ms && y < ms && mat[x][y]) {
				valid = false;
				break;
			}
		}
		if(valid) {
			got.push_back(i);
			mat[points[i].first][points[i].second] = true;
		}
	}
	for(auto i : got) {
		mat[points[i].first][points[i].second] = false;
	}
	return got;
}

int main() {
	std::ios_base::sync_with_stdio(false); std::cin.tie(NULL);
	int n, d[2];
	std::cin >> n >> d[0] >> d[1];
	std::vector<ii> forb, points;
	for(int i = -2*n + 1; i <= 2*n - 1; i++) {
		for(int j = -2*n + 1; j <= 2*n - 1; j++) {
			int val = i * i + j * j;
			if(val == d[0] || val == d[1]) {
				forb.emplace_back(i, j);
			}
		}
	}
	for(int i = 0; i < 2*n; i++) {
		for(int j = 0; j < 2*n; j++) {
			points.emplace_back(i, j);
		}
	}
	srand(time(0));
	auto v = evaluate(n * n, points, forb);
	while(v.size() < n * n) {
		std::random_shuffle(points.begin(), points.end());
		v = evaluate(n * n, points, forb);
	}
	for(int i = 0; i < n * n; i++) {
		std::cout << points[v[i]].first << ' ' << points[v[i]].second << std::endl;
	}
}

