int n, A, B, col[maxn][maxn], f[maxn][maxn];
vpi sols;
void dfs(int x, int y) {
	for(auto &i : sols) {
		int tx = x + i.first, ty = y + i.second;
		if(tx < 0 || tx >= 2*n || ty < 0 || ty >= 2*n || col[tx][ty] || f[tx][ty]) continue;
		col[tx][ty] = 3^col[x][y];
		dfs(tx, ty);
	}
}
void solve(vpi &a, int d) {
	memset(col, 0, sizeof col);
	memset(f, 0x69, sizeof f);
	sols.clear();
	for(int i = 0; i < 1000; i++)
		for(int j = 0; j < 1000; j++) {
			if(i*i + j*j == d) {
				sols.pb({i, j});
				sols.pb({-i, j});
				sols.pb({i, -j});
				sols.pb({-i, -j});
			}
		}
	for(auto i : a) f[i.first][i.second] = 0;
	vpi l, r;

	for(auto [i, j] : a) {
		if(!col[i][j]) {
			col[i][j] = 1;
			dfs(i, j);
		}
		(col[i][j] == 1 ? l : r).pb({i, j});
	}

	if(l.size() >= r.size())
		a = l;
	else
		a = r;
}
