using namespace std;

using ll = long long;
using pii = pair<int, int>;
using pll = pair<ll, ll>;
using ld = long double;

ll get_root(ll n) {
    assert(n >= 0);
    ll x = sqrt(n);
    while (x * x < n)
        x++;
    while (x * x > n)
        x--;
    if (x * x != n)
        return -1;
    return x;
}

vector<pii> get_pairs(ll n) {
    vector<pii> ans;
    for (ll a = 0; a * a <= n; a++) {
        ll b = get_root(n - a * a);
        if (b != -1) {
            assert(a * a + b * b == n);
            ans.emplace_back(a, b);
         }
    }
    return ans;
}

