typedef long long ll;

const int MX = 606;

int n, d1, d2;

struct GRAPH
{
	vector<pair<int, int> > dir;
	int col[MX][MX], num[3];

	void dfs(int x, int y, int c)
	{
		if(x<0 || x>=n*2 || y<0 || y>=n*2) return;
		if(col[x][y]) return;
		else col[x][y] = c, num[c]++;
		for(auto t : dir)
			dfs(x+t.first, y+t.second, 3-c);
	}

	void color()
	{
		for(int i=0; i<n*2; i++)
			for(int j=0; j<n*2; j++)
				if(!col[i][j])
					dfs(i, j, 1);
	}
} G1, G2;

int id(int x, int y)
{
	assert(x>=0 && x<n*2);
	assert(y>=0 && y<n*2);
	return x*(n*2) + y;
}

void build(GRAPH &g, int d)
{
	g.dir.clear();
	for(int i=0; i*i<=d; i++)
		for(int j=0; j*j<=d; j++)
			if(i*i + j*j == d)
			{
				g.dir.push_back(make_pair(i, j));
				g.dir.push_back(make_pair(i, -j));
				g.dir.push_back(make_pair(-i, j));
				g.dir.push_back(make_pair(-i, -j));
			}
}

