    for (int i = 0; i < 2 * N; i++)
    {
        for (int j = 0; j < 2 * N; j++)
        {
            if (color1[i][j] == -1)
            {
                color1[i][j] = 0;
                bfs(i, j, NG1, color1);
            }
            if (color2[i][j] == -1)
            {
                color2[i][j] = 0;
                bfs(i, j, NG2, color2);
