void crossAll(VVI &M, int N, int D1, int D2, int s1 = 1, int s2 = 1, int s3 = 1) {
	int sx[] = {-1, -1, 1,  1};
	int sy[] = { 1, -1, 1, -1};
	vector<PII> deltas;
	for (int x = 0; x*x <= D1; ++x) {
		int rN = D1 - x*x;
		int y = sqrt(rN) + 1e-9;
		if (y * y != rN) continue;
//		if (x < y) continue;
//		cout << x << " " << y << endl;
		deltas.push_back(PII(x, y));
	}
	for (int x = 0; x*x <= D2; ++x) {
		int rN = D2 - x*x;
		int y = sqrt(rN) + 1e-9;
		if (y * y != rN) continue;
//		if (y > x) continue;
//		cout << x << " " << y << endl;
		deltas.push_back(PII(x, y));
	}
	vector<PII> PTS;
	for (int i = 0; i < M.size(); ++i) {
		for (int j = 0; j < M.size(); ++j) {
			PTS.push_back(PII(i, j));
		}
	}
	int L = M.size();
	sort(PTS.begin(), PTS.end(), [&](PII a, PII b) {
		int va = min(a.first, L - 1 - a.first);
		int ha = min(a.second, L - 1 - a.second);
		int vb = min(b.first, L - 1 - b.first);
		int hb = min(b.second, L - 1 - b.second);
		int mna = min(va, ha), mnb = min(vb, hb);
		int mxa = max(va, ha), mxb = max(vb, hb);
		return PII(s1 * mna, s2 * mxa) < PII(s1 * mnb, s2 * mxb);
	});

	for(PII p : PTS) {
		int ri = p.first;
		int rj = p.second;
		if (M[ri][rj]) {
			M[ri][rj] = 2;
			for (PII d : deltas) {
				for (int k = 0; k < 4; ++k) {
					int nx = rj + sx[k] * d.first;
					int ny = ri + sy[k] * d.second;
					if (nx < 0 || nx >= M[0].size()) continue;
					if (ny < 0 || ny >= M.size()) continue;
					assert(M[ny][nx] != 2);
					M[ny][nx] = 0;
				}
			}
		}

	}
}

int CNT(VVI MAT) {
	int c = 0;
	for(VI V : MAT) {
		for (int v : V){
			c += v != 0;
		}
	}
	return c;
}

