void dfs1(int x,int y,int now)
{
	if (flag1[x][y]!=-1) return;
	flag1[x][y]=now;
	for (int j=0;j<2*n;j++)
	{
		long long del=1LL*d1-1LL*(x-j)*(x-j);
		if (del<0) continue;
		if (1LL*(int)sqrt(del)*(int)sqrt(del)!=del) continue;
		del=(int)sqrt(del);
		if (y-del>=0) dfs1(j,y-del,now^1);
		if (y+del<2*n) dfs1(j,y+del,now^1);
	}
}
void dfs2(int x,int y,int now)
{
	if (flag2[x][y]!=-1) return;
	flag2[x][y]=now;
	for (int j=0;j<2*n;j++)
