#include <bits/stdc++.h>

using namespace std;

const int N = 666;

bool can[N][N];

int n, a, b;
vector<pair<int, int> > hapus;
int cnt[N][N];
set<tuple<int, int, int > > st;
void sett(int x, int y, int v) {
  st.erase(make_tuple(cnt[x][y], x, y));
  cnt[x][y] = v;
  st.insert(make_tuple(v, x, y));
}

void rem(int x, int y) {
  if (!can[x][y]) return;
  can[x][y] = 0;
  st.erase(make_tuple(cnt[x][y], x, y));
  for (auto it : hapus) {
    int xx = x + it.first, yy = y + it.second;
    if (min(xx, yy) < 0 || max(xx, yy) >= 2 * n) continue;
    if (!can[xx][yy]) continue;
    sett(xx, yy, cnt[xx][yy]-1);
  }
}

int main() {
  scanf("%d %d %d", &n, &a, &b);
  for (int i = -2 * n; i < 2 * n; ++i) {
    for (int j = -2 * n; j < 2 * n; ++j) {
      int now = i * i + j * j;
      if (now != a && now != b) continue;
      hapus.emplace_back(i, j);
      int ra = 0, rb = 2 * n-1, ca = 0, cb = rb;
      ra = max(ra, ra-i);
      rb = min(rb, rb+i);
      ca = max(ca, ca-j);
      cb = min(cb, cb+j);
      if (ra <= rb && ca <= cb) {
        ++cnt[ra][ca];
        --cnt[ra][cb+1];
        --cnt[rb+1][ca];
        ++cnt[rb+1][cb+1];
      }
    }
  }
  for (int i = 0; i < 2 * n; ++i)
    for (int j = 0; j < 2 * n; ++j) {
      if (i > 0)
        cnt[i][j] += cnt[i-1][j];
      if (j > 0)
        cnt[i][j] += cnt[i][j-1];
      if (i > 0 && j > 0)
        cnt[i][j] -= cnt[i-1][j-1];
    }
  for (int i = 0; i < 2 * n; ++i) {
    for (int j = 0; j < 2 * n; ++j) {
      sett(i, j, cnt[i][j]);
      can[i][j] = 1;
    }
  }
  vector<pair<int, int> > ans;
  while (!st.empty() && (int)ans.size() < n * n) {
    auto it = st.begin();
    int x, y, v;
    tie(v, x, y) = *it; st.erase(it);
    if (!can[x][y]) continue;
    ans.emplace_back(x, y);
    can[x][y] = 0;
    for (auto it : hapus) {
      int xx = x + it.first, yy = y + it.second;
      if (min(xx, yy) < 0 || max(xx, yy) >= 2 * n) continue;
      rem(xx, yy);
    }
  }
  for (auto it : ans) {
    printf("%d %d\n", it.first, it.second);
  }
  return 0;
}

