      c = color[i];
      break;
    }
  }
  for(int i = 0, cnt = 0; cnt < N * N; i++) {
    if(color[i] == c) {
      printf("%d %d\n", i / (2*N), i % ( 2 * N ));
      cnt++;
    }
  }

	return 0;
}
