using namespace std;

int solve(int n, int d1, int d2) {
    bool m[2*n][2*n];
    memset(m, -1, sizeof(m));
    vector<int> v(2*n+1, -1);
    for (int i = 0; i * i <= 2*n; i++) {
        v[i*i] = i;
    }
    vector<pair<int, int>> u;
    auto f = [&](int d) {
        for (int i = 0; i * i <= d; i++) {
            if (v[d-i*i] != -1) u.emplace_back(i, v[d-i*i]);
        }
    };
    f(d1); f(d2);
    auto in = [&](int x, int y) {
        return 0 <= x && x < 2*n && 0 <= y && y < 2*n;
    };
    int ans = 0;
    vector<int> x, y;
    for (int i = 0; i < 2*n; i++) {
        for (int j = 0; j < 2*n; j++) {
            if (m[i][j]) {
                ans++, m[i][j] = 0;
                x.emplace_back(i), y.emplace_back(j);
                for (auto &iter: u) {
                    if (in(i+iter.first, j+iter.second)) {
                        m[i+iter.first][j+iter.second] = 0;
                    }
                }
            }
        }
    }
    assert(ans >= n * n);
    for (int i = 0; i < n * n; i++) {
        cout << x[i] << " " << y[i] << "\n";
    }
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n, d, e; cin >> n >> d >> e;
    solve(n, d, e);
    return 0;
}

