typedef long long ll;typedef vector<int> vi;typedef pair<int,int> pi;const int inf = (int)1e9;const double INF = 1e12, EPS = 1e-9;

int col[360000], tmp[360000];
void rec(const vector<vi> &g, int c, int p, int col){
	tmp[c] = col;
	for(int i : g[c]) if(i != p && !tmp[i]) rec(g, i, c, -col);
}
void graph(int n, int d, int c){
	vector<vi> g(4 * n * n);
	vector<pi> p;
	for(int i = 0; i * i <= d; i++){
		int r = d - i * i, j = sqrt(r) + EPS;
		if(j * j == r) p.emplace_back(i, j);
	}
	rep(i, 2 * n) rep(j, 2 * n){
		set<int> s;
		for(auto k : p){
			int a = i - k.first, b = j - k.second;
			if(a >= 0 && b >= 0) s.insert(a * 2 * n + b);
			b = j + k.second;
			if(a >= 0 && b < 2 * n) s.insert(a * 2 * n + b);
		}
		for(int k : s){
			g[i * 2 * n + j].pb(k);
			g[k].pb(i * 2 * n + j);
		}
	}
	memset(tmp, 0, sizeof(tmp));
	rep(i, 4 * n * n) if(!tmp[i]) rec(g, i, i, 1);
	rep(i, 4 * n * n) if(tmp[i] > 0) col[i] |= c;
}

