bool tk[Maxm][Maxm];
vector <iii> srt;
vector <ii> gen;
ii seq[Maxn];
int slen;
bool found;

bool Inbounds(int r, int c) { return 0 <= r && r < 2 * n && 0 <= c && c < 2 * n; }

bool Exist(int r, int c)
{
	return 0 <= r && r < 2 * n && 0 <= c && c < 2 * n && tk[r][c];
}

bool Check(int r, int c)
{
	for (int i = 0; i < delt.size(); i++)
		if (Exist(r + delt[i].first, c + delt[i].second))
			return false;
	return true;
}

int Neighbours(int r, int c)
{
	int res = 0;
	for (int i = 0; i < delt.size(); i++)
		if (Inbounds(r + delt[i].first, c + delt[i].second))
			res++;
	return res;
}

void Gen(int lvl)
{
	int lft = int(gen.size()) - lvl;
	if (slen + lft < n * n) return;
	if (slen >= n * n) {
		found = true;
		for (int i = 0; i < slen; i++)
			printf("%d %d\n", seq[i].first, seq[i].second);
		return;
	}
	if (Check(gen[lvl].first, gen[lvl].second)) {
		seq[slen++] = gen[lvl]; tk[gen[lvl].first][gen[lvl].second] = true;
		Gen(lvl + 1);
		slen--; tk[gen[lvl].first][gen[lvl].second] = false;
	}
	if (!found) Gen(lvl + 1);
}

