			for (int a = -1; a <= 1; a += 2)
				for (int b = -1; b <= 1; b += 2)
					delt.push_back(ii(a * i, b * j));
		}
	if (d1 != d2)
		for (int i = 0; i * i <= d2; i++)
			if (sqr[d2 - i * i] != -1) {
