    scanf("%d %d %d", &n, &d1, &d2);
    for (int i = 0; i * i <= d1; i++) {
        int t = sqrt(d1 - i * i);
        if (i * i + t * t == d1) V1.push_back({i, t});
    }
    for (int i = 0; i * i <= d2; i++) {
        int t = sqrt(d2 - i * i);
        if (i * i + t * t == d2) V2.push_back({i, t});
    }
    vector<pair<int, int>> orz;
