		}


	int oi = -1;
	for(int i = 1; i <= 4 * N; i += 1) s[i] += s[i - 1];

	for(int i = 0; i + 2 * N - 1 <= 4 * N; i += 1){
		int sum = s[i + 2 * N - 1];
		if(i) sum -= s[i - 1];
		if(sum >= N * N){
			oi = i;
			break;
		}
	}
	assert(oi != -1);
	vector<p> a;
	int c = 0;
	for(int i = oi; i <= oi + 2 * N - 1 && c != N * N; i += 1)
		for(int j = 0; j <= 2 * N - 1 && c != N * N; j += 1)
			if(ans[i][j]){
				printf("%d %d\n", i - oi, j);
				c += 1;
			}
