for(int x = 0; x < 2 * N; x++) {
    for(int y = 0; y < 2 * N; y++) {
      for(int dx = 0; x + dx < 2 * N; dx++) {
        int X = x + dx;
        // (X - x)^2 + (Y - y)^2 = D1
        int dx2 = dx * dx;
        int dy2 = D - dx2;

        if(dy2 < 0) continue;

        int dy = sqr[dy2];

        if(dy < 0) continue;

        int Y = y + dy;

        if(Y >= 2 * N) continue;

        int u = encode(x, y, 2*N);
        int v = encode(X, Y, 2*N);

        E[u].pb(v);
        E[v].pb(u);

        if(dy == 0) continue;

        Y = y - dy;

        if(Y < 0) continue;

        v = encode(X, Y, 2 * N);

        E[u].pb(v);
        E[v].pb(u);
      }
    }
  }
}

void dfs(int n, int c0, int c1, int c, vector<int> E[4*maxn*maxn]) {
  vis[n] = 1;
  if(c == 0) color[n] |= c0;
  else color[n] |= c1;
  for(auto to : E[n]) {
    if(vis[to]) {
      assert((color[to] & c1) != (color[n] & c1));
      continue;
    }
    dfs(to, c0, c1, c ^ 1, E);
  }
}

