    vector<pii> ret;
    for (int k = (n-1)*2; k >= 0; k--) {
        for (int j = 0; j <= min(k, 2*n-1); j++) {
            int i = k - j;
            if (i < 0 || i >= 2*n) continue;
            if (mat[i][j] != 0) continue;
            mat[i][j] = 1;
            ret.push_back({i, j});
            for (pii ban : bans) {
                change(i+ban.first, j+ban.second, 2*n);
                change(i+ban.first, j-ban.second, 2*n);
                change(i-ban.first, j+ban.second, 2*n);
                change(i-ban.first, j-ban.second, 2*n);
                change(i+ban.second, j+ban.first, 2*n);
                change(i+ban.second, j-ban.first, 2*n);
                change(i-ban.second, j+ban.first, 2*n);
                change(i-ban.second, j-ban.first, 2*n);
            }
        }
    }
    assert(ret.size() >= n*n);
    ret.resize(n*n);
    for (pii item : ret) {
        cout << item.first << ' ' << item.second << '\n';
    }



/*-------------------------------------coding area end------------------------------------------*/

