int main() {
  int n;
  vector<int> d(2);
  cin >> n >> d[0] >> d[1];

  vector<pair<int, int>> u, w;
  for (auto e : d) {
    for (int i = 0; i * i <= e; i++) {
      int j = sqrt(e - i * i);
      if (i * i + j * j == e) {
        w.push_back(make_pair(i, j));
      }
    }
  }
  for (auto e : w) {
    u.push_back(make_pair(e.first, e.second));
    u.push_back(make_pair(e.first, -e.second));
    u.push_back(make_pair(-e.first, e.second));
    u.push_back(make_pair(-e.first, -e.second));
  }

  int m = 6 * n;
  vector<vector<bool>> b(2 * m, vector<bool>(2 * m, true));
  for (int i = 0; i < 2 * m; i++) {
    for (int j = 0; j < 2 * m; j++) {
      if (b[i][j]) {
        for (auto e : u) {
          int y = i + e.first, x = j + e.second;
          if (0 <= y && y < 2 * m && 0 <= x && x < 2 * m) {
            b[y][x] = false;
          }
        }
      }
    }
  }

  vector<vector<int>> s(2 * m + 1, vector<int>(2 * m + 1));
  for (int i = 0; i < 2 * m; i++) {
    for (int j = 0; j < 2 * m; j++) {
      s[i + 1][j + 1] = s[i][j + 1] + s[i + 1][j] - s[i][j] + b[i][j];
    }
  }

  int p = -1, q = -1;
  for (int i = 0; i < 2 * m - 2 * n; i++) {
    for (int j = 0; j < 2 * m - 2 * n; j++) {
      int t =
          s[i + 2 * n][j + 2 * n] - s[i][j + 2 * n] - s[i + 2 * n][j] + s[i][j];
      if (t >= n * n) {
        p = i;
        q = j;
        break;
      }
    }
    if (p != -1) {
      break;
    }
  }

  if (p == -1) {
    return 1;
  }

  vector<pair<int, int>> v;
  for (int i = 0; i < 2 * n; i++) {
    for (int j = 0; j < 2 * n; j++) {
      if (b[p + i][q + j]) {
        v.push_back(make_pair(i, j));
      }
    }
  }
  for (int i = 0; i < n * n; i++) {
    cout << v[i].first << " " << v[i].second << endl;
  }
  return 0;
}

