{
	for(ll i=0; i<=d; i++)
		for(ll j=-d; j<=d; j++)
			if(i*i + j*j == d*d)
				for(int x=0; x<n*2; x++)
					for(int y=0; y<n*2; y++)
						if(x+i<n*2 && y+j>=0 && y+j<n*2)
						{
							g.addeg(id(x, y), id(x+i, y+j));
							g.addeg(id(x+i, y+j), id(x, y));
						}
}

