}

using P = pair<int, int>;
vector<P> getSqSum(int d) {
    vector<P> ret;
    for (auto& sq : sqs) {
        if (d - sq < 0) break;
        if (isSq[d - sq] != -1) {
            ret.push_back(make_pair(isSq[sq], isSq[d - sq]));
        }
    }
    return ret;
}

const int MAX_N = 310;
bool used[2 * MAX_N][2 * MAX_N];

bool check(int y, int x, int n) {
    if (y < 0 || y >= 2 * n || x < 0 || x >= 2 * n) return true;
    if (used[y][x]) return false;
    return true;
}
vector<P> dd[2];

vector<P> calc(int n) {
    rep(y, 2 * MAX_N) rep(x, 2 * MAX_N) {
        used[y][x] = false;
    }
    vector<P> ans;
    rep(y, 2 * n) rep(x, 2 * n) {
        bool f = true;
        rep(i, 2) {
            for (auto& p : dd[i]) {
                int a = p.fi;
                int b = p.se;
                f &= check(y + a, x + b, n);
                f &= check(y + a, x - b, n);
                f &= check(y - a, x + b, n);
                f &= check(y - a, x - b, n);
            }
        }
        if (f) {
            ans.push_back({y, x});
            used[y][x] = true;
        }
        if (ans.size() == n * n) {
            return ans;
        }
    }
    return {};
}

