using namespace std;
int N, D1, D2;
bool Matrix[605][605];
bool Choosed[605][605];
vector <pair <int, int> > V;
int cnt;
void precalcMatrix()
{
    for(int i = 0; i< N * 2; i++)
        for(int j = 0; j < N * 2; j++)
        {
            if(i * i + j * j == D1 || i * i + j * j == D2)
            {
                Matrix[i][j] = 1;
                V.push_back(make_pair(i, j));
            }

        }
}

void Solve()
{
    cnt = 0;
    for(int i = 0; i < N * 2; i++)
        for(int j = 0; j < N * 2; j++)
        {
            bool ok = 1;
            for(int k = 0; k < V.size(); k++)
            {
                int newi = i - V[k].first, newj = j - V[k].second;
                if(newi >= 0 && newj >= 0 && Choosed[newi][newj] == 1)
                {
                    ok = 0;break;
                }
                newj = j + V[k].second;
                if(newi >= 0 && newj >= 0 && newj < 2 * N && Choosed[newi][newj] == 1)
                {
                    ok = 0;
                    break;
                }
            }
            if(ok == 1)
            {
                Choosed[i][j] = 1;
                ++cnt;
                if(cnt <= N * N)
                    cout << i << " " << j << "\n";
            }

        }
}
int main()
{
    cin >> N >> D1 >> D2;
    precalcMatrix();
    Solve();
    //cout << cnt << "\n";
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int MaxN = 300 + 30;
const int MOD = 1e9 + 7;
const long long INF = 1e18;

int n, d1, d2;

vector <pair<int, int> > badV;

int used[MaxN * 2][MaxN * 2];

int cnt[MaxN * 2][MaxN * 2];

int f(pair<int, int> a)
{
    int k1 = 0;
    for(auto x : badV)
    {
        int xx = a.first + x.first;
        int yy = a.second + x.second;

        if(xx >= 0 && xx < n + n && yy >= 0 && yy < n + n && !used[xx][yy])
            ++k1;
    }
    return -k1;
}

bool cmp(pair<int, int> a, pair<int, int> b)
{
    return f(a) < f(b);
}

vector <pair<int, int> > ans;

void solve(int x, int y)
{
    if(x < 0 || x >= n + n || y < 0 || y >= n + n || used[x][y])
        return;

    queue <pair<int, int> > bfs;

    bfs.push({x, y});

    used[x][y] = 1;

    while(!bfs.empty())
    {
        int x = bfs.front().first;
        int y = bfs.front().second;
        bfs.pop();

        if(used[x][y] == 1)
        {
            ans.push_back({x, y});
            for(auto p : badV)
            {
                int xx = x + p.first;
                int yy = y + p.second;
                if(xx >= 0 && xx < n + n && yy >= 0 && yy < n + n)
                {
                    if(!used[xx][yy])
                        bfs.push({xx, yy});
                    used[xx][yy] = 2;
                }
            }
        }else
        {
            for(auto p : badV)
            {
                int xx = x + p.first;
                int yy = y + p.second;
                if(xx >= 0 && xx < n + n && yy >= 0 && yy < n + n)
                {
                    if(!used[xx][yy])
                    {
                        bfs.push({xx, yy});
                        used[xx][yy] = 1;
                    }
                }
            }
        }
    }
}

