        P p(i, j);
        ans.push_back(p);
        if (ans.size() == N * N)
        {
          flush();
          return 0;
        }
        for (auto q : F)
        {
          P r = p + q;
          if (valid(r))
          {
            B[r.real()][r.imag()] = false;
          }
        }
      }
    }
  }
  assert(false);
}

