void mkG( std::vector<int> *G, int D )
{
  rep( i, 2*N ) rep( j, 2*N )
    G[i*2*N+j].clear();

  rep( i, 2*N ) rep( j, 2*N ) rep( k, 2*N ) if( (i-k)*(i-k) < D*D )
  {
    double d = sqrt( D-(i-k)*(i-k) );

    if( floor(d) == d )
    {
      int l;

      if( j+d < 2*N && !(i == k && j == j+d) )
      {
        l = j+d;
        G[i*2*N+j].push_back( k*2*N+l );
        G[k*2*N+l].push_back( i*2*N+j );

      //  printf( "(%d,%d) -> (%d,%d)\n", i, j, k, l );
      }

      if( j-d >= 0 && !(i == k && j == j-d) )
      {
        l = j-d;
        G[i*2*N+j].push_back( k*2*N+l );
        G[k*2*N+l].push_back( i*2*N+j );

       // printf( "(%d,%d) -> (%d,%d)\n", i, j, k, l );
      }
    }
  }

  return;
}

