vector<pair<int, int>> ans[4];

int Sqrt(int x) {
	int y = sqrt(x);
	while (y * y <= x) ++y;
	while (y * y > x) --y;
	return y;
}

int find(int x) {
	if (fa[x] == x) return x;
	int ff = find(fa[x]);
	d[x] ^= d[fa[x]];
	return fa[x] = ff;
}
void merge(int x, int y) {
	int s = find(x), t = find(y);
	if (s == t) return;
	fa[s] = t, d[s] = d[x] ^ d[y] ^ 1;
}

