void fill(int d, int n) {
	int cnt = 0;
	while (d % 4 == 0) {
		d /= 4;
		cnt++;
	}
	int m = 1 << cnt;
	if (d % 4 == 1) {
		// 市松模様
		rep(i, n) {
			rep(j, n) {
				if (((i>>cnt)+(j>>cnt)) % 2 == 1) {
					use[i][j] = false;
				}
			}
		}
	}
	else if (d % 4 == 2) {
