// BFS求最短路小心vis可能访问过
const int maxn = 302;

vector<int> E1[4*maxn*maxn];
vector<int> E2[4*maxn*maxn];
bool vis[4*maxn*maxn];
int color[4*maxn*maxn];
int sqr[220001];

int encode(int x, int y, int N) {
  return x * N + y;
}

void build_graph(int D, int N, vector<int> E[4*maxn*maxn]) {
for(int x = 0; x < 2 * N; x++) {
    for(int y = 0; y < 2 * N; y++) {
      for(int X = x; X < 2 * N; X++) {
        // (X - x)^2 + (Y - y)^2 = D1
        int dx2 = (X - x) * (X - x);
        if(D < dx2) continue;
        int dy2 = D - dx2;

        int dy = sqr[dy2];

        if(dy < 0) continue;

        int Y = y + dy;

        if(Y >= 2 * N) continue;

        int u = encode(x, y, 2*N);
        int v = encode(X, Y, 2*N);

        E[u].pb(v);
        E[v].pb(u);

        Y = y - dy;

        if(Y < 0) continue;

        u = encode(x, y, 2 * N);
        v = encode(X, Y, 2 * N);

        E[u].pb(v);
        E[v].pb(u);
      }
    }
  }
}

void dfs(int n, int c0, int c1, int c, vector<int> E[4*maxn*maxn]) {
  vis[n] = 1;
  if(c == 0) color[n] |= c0;
  else color[n] |= c1;
  for(auto to : E[n]) {
    if(vis[to]) continue;
    dfs(to, c0, c1, c ^ 1, E);
  }
}

int main() {
  for(int i = 0; i < 200001;i++) sqr[i] = -1;
  for(int i = 0; i * i <= 200000; i++) sqr[i * i] = i;
  int N, D1, D2;
  scanf("%d%d%d", &N, &D1, &D2);
  build_graph(D1, N, E1);
  build_graph(D2, N, E2);
  rep(i,0,2) {
    memset(vis, 0, sizeof(vis));
    rep(n,0,4*N*N) {
      if(!vis[n]) {
        if(i == 0) dfs(n, 0, 1, 0, E1);
        else dfs(n, 0, 2, 0, E2);
      }
    }
  }

  int cnt[4] = {0, 0, 0, 0};

  int c = -1;
  for(int i = 0; i < 4*N*N; i++) {
    cnt[color[i]]++;
    if(cnt[color[i]] >= N * N) {
      c = color[i];
      break;
    }
  }
  for(int i = 0, cnt = 0; cnt < N * N; i++) {
    if(color[i] == c) {
      printf("%d %d\n", i / (2*N), i % ( 2 * N ));
      cnt++;
    }
  }

	return 0;
}
