vector<pair<int, int>> ans;

bool solve1() {
  ans.clear();
  while (!pq.empty()) {
    pq.pop();
  }
  for (int x = 0; x < 2 * n; x++) {
    for (int y = 0; y < 2 * n; y++) {
      used[x][y] = false;
      deg[x][y] = sz(g[x][y]);
      dist[x][y] = mrand();
      pq.push(make_pair(make_pair(deg[x][y], dist[x][y]), x * 2 * n + y));
    }
  }
  while (sz(ans) < n * n) {
    if (pq.empty()) {
      return false;
    }
    int id = pq.top().second;
    pq.pop();
    int x = id / (2 * n), y = id % (2 * n);
    if (used[x][y]) {
      continue;
    }
    ans.push_back(make_pair(x, y));
    used[x][y] = true;
    for (int i = 0; i < sz(g[x][y]); i++) {
      int nid = g[x][y][i];
      int nx = nid / (2 * n), ny = nid % (2 * n);
      if (!used[nx][ny]) {
        for (int j = 0; j < sz(g[nx][ny]); j++) {
          int nnid = g[nx][ny][j];
          int nnx = nnid / (2 * n), nny = nnid % (2 * n);
          if (!used[nnx][nny]) {
            deg[nnx][nny]--;
            pq.push(make_pair(make_pair(deg[nnx][nny], dist[nnx][nny]), nnid));
          }
        }
      }
      used[nx][ny] = true;
    }
  }
  return true;
}

