const int N = 605;

int n, d1, d2, m;
bool flag[N][N], vis[N][N], ok[N][N];
vector < pair <int, int> > lis;

void dfs (int x, int y, bool fl[N][N]) {
	vis[x][y] = true;
	for (auto &t : lis) {
		int dx = x + t.fi, dy = y + t.se;
		if (dx < 0 || dx >= n || dy < 0 || dy >= n || !ok[dx][dy]) continue;
		if (vis[dx][dy]) assert (fl[dx][dy] ^ fl[x][y]);
		else fl[dx][dy] = !fl[x][y], dfs (dx, dy, fl);
	}
}

void solve (int D, bool fl[N][N]) {
	lis.clear();
	memset (vis, 0, sizeof(vis));
	int x, y;
	for (x = 0; x * x <= D; x ++) {
		y = sqrt(D - x * x + 0.5);
		if (x * x + y * y == D) {
			lis.push_back (pair <int, int> (x, y));
			lis.push_back (pair <int, int> (-x, y));
			lis.push_back (pair <int, int> (x, -y));
			lis.push_back (pair <int, int> (-x, -y));
		}
	}
	for (x = 0; x < n; x ++) for (y = 0; y < n; y ++) if (ok[x][y] && !vis[x][y]) dfs (x, y, fl);
}

