int main() {
	IN(n),IN(D1),IN(D2),lim=n<<1;
	for(int i=0;i<=lim;++i)
		for(int j=0;j<=lim;++j) {
			if(i*i+j*j==D1) T1.push_back(MKP(i,j));
			if(i*i+j*j==D2) T2.push_back(MKP(i,j));
		}
	for(int x=1;x<=lim;++x)
		for(int y=1;y<=lim;++y)
			for(pair <int,int> now:T1) {
				int dx=now.first,dy=now.second;
				if(check(x+dx,y+dy)) G[x][y].push_back(MKP(x+dx,y+dy));
				if(check(x-dx,y+dy)) G[x][y].push_back(MKP(x-dx,y+dy));
				if(check(x+dx,y-dy)) G[x][y].push_back(MKP(x+dx,y-dy));
				if(check(x-dx,y-dy)) G[x][y].push_back(MKP(x-dx,y-dy));
			}
