typedef long long lint;

void dfs(int v, int color_v, vector<int> &colors,
         const vector<vector<int>> &adj) {
  if (colors[v] != -1) {
    assert(colors[v] == color_v);
    return;
  }
  colors[v] = color_v;
  for (int u : adj[v])
    dfs(u, 1 - color_v, colors, adj);
}

vector<vector<int>> get_colors(int n, int d) {
  vector<vector<int>> adj(n * n);
  for (int y = 0; y < n; ++y)
    for (int x = 0; x < n; ++x) {
      int y_low = y, y_high = y;
      for (int x2 = n - 1; x2 >= x; --x2) {
        while (y_low >= 0 &&
               (x2 - x) * (x2 - x) + (y_low - y) * (y_low - y) < d)
          --y_low;
        while (y_high < n &&
               (x2 - x) * (x2 - x) + (y_high - y) * (y_high - y) < d)
          ++y_high;

        if (x2 > x && y_low >= 0 &&
            (x2 - x) * (x2 - x) + (y_low - y) * (y_low - y) == d) {
          adj[y * n + x].push_back(y_low * n + x2);
          adj[y_low * n + x2].push_back(y * n + x);
        }
        if (y_high != y && y_high < n &&
            (x2 - x) * (x2 - x) + (y_high - y) * (y_high - y) == d) {
          adj[y * n + x].push_back(y_high * n + x2);
          adj[y_high * n + x2].push_back(y * n + x);
        }
      }
    }

