vpii cal(int d, int n) {
	vpii ret;
	int sd = sqrt(d);
	rep(dx, sd+1) {
		if (dx >= n*2) continue;
		int dy = sqrt(d - dx*dx);
		if (dy >= n*2) continue;
		if (dx > dy) break;
		if (dy * dy + dx * dx == d) {
			ret.emplace_back(dx, dy);
		}
	}
	return ret;
}

void pr(const vpii &ans) {
	forr(a, ans) {
		print(a.fst, a.snd);
	}
}

void Main() {
	int n = ri(), d1 = ri(), d2 = ri();

	vpii e1 = cal(d1, n);
	vpii e2 = cal(d2, n);

	vpii E;
	forr(e, e1) E.emplace_back(e);
	forr(e, e2) E.emplace_back(e);

	out(E);

	vvb dame(2*n, vb(2*n));

	auto check = [&dame, &n](int y, int x) {
		if (y < 0) return false;
		if (y >= n*2) return false;
		if (x < 0) return false;
		if (x >= n*2) return false;
		if (dame[y][x]) return false;
		return true;
	};

	auto daming = [&dame, &n](int y, int x) {
		if (y < 0) return;
		if (y >= n*2) return;
		if (x < 0) return;
		if (x >= n*2) return;
		dame[y][x] = 1;
	};


	vpii ans;

	queue<pii> Q;
	int py = 0, px = 0;

	while (1) {
		if (sz(Q) == 0) {
			while (dame[py][px]) {
				px++;
				if (px == 2*n) {
					px = 0;
					py++;
				}
			}
			Q.emplace(py, px);
		}

		int y, x;
		tie(y, x) = Q.front();
		Q.pop();

		out(y, x);

		if (!check(y, x)) continue;

		ans.emplace_back(y, x);
		dame[y][x] = 1;

		if (sz(ans) == n*n) {
			pr(ans);
			return;
		}

		forr(e, E) {
			int ey, ex;
			tie(ey, ex) = e;

			if (check(y+ey, x+ex)) {
				daming(y+ey, x+ex);
				daming(y+ex, x+ey);
				Q.emplace(y+ey+ex, x+ex+ey);
			}

			if (check(y+ey, x-ex)) {
				daming(y+ey, x-ex);
				daming(y+ex, x-ey);
				Q.emplace(y+ey+ex, x-ex-ey);
			}

			if (check(y-ey, x+ex)) {
				daming(y-ey, x+ex);
				daming(y-ex, x+ey);
				Q.emplace(y-ey-ex, x+ex+ey);
			}
		}
	}
}

