using namespace std;

int n,D1,D2,sign[700][700],cnt,x[700],y[700];
pair<int,int> Ans[100010];
int dir[4][2]={{1,-1},{1,1},{-1,1},{-1,-1}};
vector<pair<int,int> > V1,V2;
inline int solve()
{
	cnt=0; memset(sign,0,sizeof sign);
	for(int i=0;i<2*n;i++) for(int j=0;j<2*n;j++) if(!sign[x[i]][y[j]])
	{
		++cnt; Ans[cnt]=make_pair(x[i],y[j]);
		if(cnt==n*n) return cnt;
		for(int t=0;t<V1.size();t++) for(int k=0;k<4;k++)
		{
			int vx=dir[k][0]*V1[t].first+x[i];
			int vy=dir[k][1]*V1[t].second+y[j];
			if(vx<0||vy<0||vx>2*n||vy>2*n) continue;
			sign[vx][vy]=1;
		}
		for(int t=0;t<V2.size();t++) for(int k=0;k<4;k++)
		{
			int vx=dir[k][0]*V2[t].first+x[i];
			int vy=dir[k][1]*V2[t].second+y[j];
			if(vx<0||vy<0||vx>2*n||vy>2*n) continue;
			sign[vx][vy]=1;
		}
	}	
	return cnt;
}
int main()
{
	cin >> n >> D1 >> D2;
	for(int j=0;j*j<=D1;j++)
	{
		int t=D1-j*j;
		int x=sqrt(t);
		while((x+1)*(x+1)<=t) x++;
		while(x*x>t) x--;
		if(x*x==t) V1.push_back(make_pair(j,x));
	}
	for(int j=0;j*j<=D2;j++)
	{
		int t=D2-j*j;
		int x=sqrt(t);
		while((x+1)*(x+1)<=t) x++;
		while(x*x>t) x--;
		if(x*x==t) V2.push_back(make_pair(j,x));
	}
	for(int i=0;i<=2*n;i++) x[i]=y[i]=i;
	while(solve()!=cnt) random_shuffle(x,x+2*n),random_shuffle(y,y+2*n);
	sort(Ans+1,Ans+1+cnt);
	for(int i=1;i<=cnt;i++) printf("%d %d\n",Ans[i].first,Ans[i].second);
	return 0;
}

