#include <bits/stdc++.h>
using namespace std;

typedef pair <int, int> ii;

const int Maxm = 605;
const int Maxn = 3000005;

int sqr[Maxn];
int n, d1, d2;
vector <ii> delt1, delt2;
vector <ii> neigh1[Maxm][Maxm], neigh2[Maxm][Maxm];
int col1[Maxm][Maxm], col2[Maxm][Maxm];
vector <ii> colec[4];

bool Inbounds(int r, int c) { return 0 <= r && r < 2 * n && 0 <= c && c < 2 * n; }

void Traverse(ii v, int cand, vector <ii> neigh[][Maxm], int col[][Maxm])
{
	if (col[v.first][v.second] != -1) return;
	col[v.first][v.second] = cand;
	for (int i = 0; i < neigh[v.first][v.second].size(); i++)
		Traverse(neigh[v.first][v.second][i], 1 - cand, neigh, col);
}

int main()
{
	fill(sqr, sqr + Maxn, -1);
	for (int i = 0; i * i < Maxn; i++)
		sqr[i * i] = i;
	cin >> n >> d1 >> d2;
	for (int i = 0; i * i <= d1; i++)
		if (sqr[d1 - i * i] != -1) {
			int j = sqr[d1 - i * i];
			for (int a = -1; a <= 1; a += 2) if (a == -1 || i != 0)
				for (int b = -1; b <= 1; b += 2) if (b == -1 || j != 0)
					delt1.push_back(ii(a * i, b * j));
		}
	for (int i = 0; i * i <= d2; i++)
		if (sqr[d2 - i * i] != -1) {
			int j = sqr[d2 - i * i];
			for (int a = -1; a <= 1; a += 2) if (a == -1 || i != 0)
				for (int b = -1; b <= 1; b += 2) if (b == -1 || j != 0)
					delt2.push_back(ii(a * i, b * j));
		}
	for (int i = 0; i < 2 * n; i++)
		for (int j = 0; j < 2 * n; j++) {
			for (int z = 0; z < delt1.size(); z++)
				if (Inbounds(i + delt1[z].first, j + delt1[z].second))
					neigh1[i][j].push_back(ii(i + delt1[z].first, j + delt1[z].second));
			for (int z = 0; z < delt2.size(); z++)
				if (Inbounds(i + delt2[z].first, j + delt2[z].second))
					neigh2[i][j].push_back(ii(i + delt2[z].first, j + delt2[z].second));
			col1[i][j] = col2[i][j] = -1;
		}
	for (int i = 0; i < 2 * n; i++)
		for (int j = 0; j < 2 * n; j++) {
			Traverse(ii(i, j), 0, neigh1, col1);
			Traverse(ii(i, j), 0, neigh2, col2);
			colec[col1[i][j] | col2[i][j] << 1].push_back(ii(i, j));
		}
	int i = 0;
	while (colec[i].size() < n * n) i++;
	for (int j = 0; j < n * n; j++)
		printf("%d %d\n", colec[i][j].first, colec[i][j].second);
	return 0;
}

