void Solve() {
	int n, d1, d2;
	cin >> n >> d1 >> d2;

	auto s1 = solve(d1);
	auto s2 = solve(d2);
	for (auto& p : s2) s1.push_back(p);

	vector<vector<bool>> ng(n * 2, vector<bool>(n * 2, false));
	vector<pii> ans;

	vector<pii> xxx;
	xxx.reserve(4 * n * n);
	for (int i = 0; i < 2 * n; i++) for (int j = 0; j < 2 * n; j++) xxx.push_back({ i,j });
	std::random_device rd;
	std::mt19937 g(rd());
	std::shuffle(xxx.begin(), xxx.end(), g);

	for (int j = 0; j < (int)xxx.size() && (int)ans.size() < n * n; j++) {
		pii &p = xxx[j];
