int dx[2] = {1, -1}, dy[2] = {1, -1};

struct P {
  int x, y;  
};

int N, D1, D2;
vector<P> G1[301][301];
bool color1[301][301];
bool used1[301][301];
vector<P> G2[301][301];
bool color2[301][301];
bool used2[301][301];

void dfs1(int x, int y) {
  if ( used1[y][x] ) return;
  used1[y][x] = true;  
  for ( P p : G1[y][x] ) {
    int nx = p.x, ny = p.y;
    if ( used1[ny][nx] ) continue;    
    color1[ny][nx] = !color1[y][x];
    dfs1(nx, ny);    
  }
}

void dfs2(int x, int y) {
  if ( used2[y][x] ) return;
  used2[y][x] = true;  
  for ( P p : G2[y][x] ) {
    int nx = p.x, ny = p.y;
    if ( used2[ny][nx] ) continue;    
    color2[ny][nx] = !color2[y][x];
    dfs2(nx, ny);    
  }
}

signed main() {
  cin >> N >> D1 >> D2;

  for ( int i = 0; i < 2*N; i++ ) {
    for ( int j = 0; j < 2*N; j++ ) {
      for ( int x = 0; x <= sqrt(D1); x++ ) {
	int y = sqrt(D1-x*x);
	if ( x*x + y*y != D1 ) continue;
	for ( int a = 0; a < 2; a++ ) {
	  for ( int b = 0; b < 2; b++ ) {
	    int nx = j+dx[a]*x, ny = i+dy[b]*y;
	    if ( nx < 0 || ny < 0 || nx >= 2*N || ny >= 2*N ) continue;	    
	    G1[i][j].emplace_back(P{nx, ny});
	  }
	}
      }
    }
  }

  for ( int i = 0; i < 2*N; i++ ) {
    for ( int j = 0; j < 2*N; j++ ) {
      for ( int x = 0; x <= sqrt(D2); x++ ) {
	int y = sqrt(D2-x*x);
	if ( x*x + y*y != D2 ) continue;
	for ( int a = 0; a < 2; a++ ) {
	  for ( int b = 0; b < 2; b++ ) {
	    int nx = j+dx[a]*x, ny = i+dy[b]*y;
	    if ( nx < 0 || ny < 0 || nx >= 2*N || ny >= 2*N ) continue;	    
	    G2[i][j].emplace_back(P{nx, ny});
	  }
	}
      }
    }
  }

  for ( int i = 0; i < 2*N; i++ ) {
    for ( int j = 0; j < 2*N; j++ ) {
      if ( !used1[i][j] ) dfs1(j, i);
      if ( !used2[i][j] ) dfs2(j, i);      
