            can = false;
            if (!can)
                break;
        }
        if (can) {
            ans.push_back ({i, j});
            in[i][j] = true;
        }
        swap (p[id], p.back());
        p.pop_back();
    }
    for (int i = 0; i < n * n; i++)
        cout << ans[i].first << ' ' << ans[i].second << '\n';
    return 0;
}

