				int nx = x + check[i * 2 + 1];
				if (ny >= 0 && nx >= 0 && nx < 2 * N&&ny < 2 * N) {
					covered[ny][nx]++;
				}
				ny = y - check[i * 2];
				nx = x + check[i * 2 + 1];
				if (ny >= 0 && nx >= 0 && nx < 2 * N&&ny < 2 * N) {
					covered[ny][nx]++;
				}
				ny = y - check[i * 2];
				nx = x - check[i * 2 + 1];
				if (ny >= 0 && nx >= 0 && nx < 2 * N&&ny < 2 * N) {
					covered[ny][nx]++;
				}
				ny = y + check[i * 2];
				nx = x - check[i * 2 + 1];
				if (ny >= 0 && nx >= 0 && nx < 2 * N&&ny < 2 * N) {
					covered[ny][nx]++;
				}
			}
		}
	}
	for (int i = 0; i < N * 2; i++) {
		for (int j = 0; j < N * 2; j++) {
			if (field[i][j]) {
