void work(int mpi,int n,int d)
{
	for(int i = 0;i < n;++i) {
		for(int j = 0;j < n;++j) {
			if(mp[mpi][i][j] == 0) mp[mpi][i][j] = 1;
			for(int k = 0;k < n;++k) {
				int l = d-(i-k)*(i-k);
				if(l < 0) continue;
				int ll = sqrt(l);
				if(ll*ll!=l) continue;
				if(j-ll>=0) {
					mp[mpi][k][j-ll] = 3-mp[mpi][i][j];
				}
				if(j+ll<n) mp[mpi][k][j+ll] = 3-mp[mpi][i][j];
			}
		}
	}
}
