int n, d1, d2;

int dx[] = {-1, -1, 1, 1};
int dy[] = {-1, 1, -1, 1};

const int maxn = 666;
vector<int> g[maxn * maxn];
bool used[maxn * maxn];
bool have[maxn * maxn];
int color[maxn * maxn];

void add_dir(int x, int y, vector<pair<int, int> > &dir) {
    for (int i = 0; i < 4; i++) {
        dir.push_back({x * dx[i], y * dy[i]});
        dir.push_back({y * dx[i], x * dy[i]});
    }
} 

double eps = 1e-9;

bool good(int a, int c) {
    if (a * a > c) {
        return -1;
    }
    int b = sqrt(c - a * a) + eps;
    if (b * b + a * a == c) {
        return b;
    } else {
        return -1;
    }
}

void make_graph(int n, int d) {
    vector<pair<int, int> > dir;
    for (int i = 0; i <= d; i++) {
        int j = good(i, d);
        if (j != -1) {
            if (i < n && j < n) {
                add_dir(i, j, dir);
            }
        }
    }
    sort(dir.begin(), dir.end());
    //cerr << dir.size() << '\n';
    dir.resize(unique(dir.begin(), dir.end()) - dir.begin());
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int v = i * n + j;
            g[v].clear();
            for (auto d : dir) {
                int x = i + d.first;
                int y = j + d.second;
                if (x >= 0 && y >= 0 && x < n && y < n) {
                    int u = x * n + y;
                    g[v].push_back(u);
                }
            }
        }
    }
}

int dfs(int v, int col, vector<int> &path) {
    if (used[v] || !have[v]) {
        return 0;
    }
    used[v] = 1;
    color[v] = col;
    path.push_back(v);
    int sum = 0;
    for (auto u : g[v]) {
        sum += dfs(u, col ^ 1, path);
    }
    return (col ^ 1) + sum;
}

vector<int> vert_good(vector<int> vert) {
    memset(used, 0, sizeof(used));
    memset(have, 0, sizeof(have));
    memset(color, -1, sizeof(color));

    for (auto v : vert) {
        have[v] = 1;
    }

    for (auto v : vert) {
        if (have[v] && !used[v]) {
            vector<int> path;
            int cnt = dfs(v, 0, path);
            if (cnt < path.size() - cnt) {
                for (auto u : path) {
                    color[u] ^= 1;
                }
            }           
        }

    }

    vector<int> res;
    for (auto v : vert) {
        if (color[v] == 0) {
            res.push_back(v);
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.precision(10);
    cout << fixed;

    int n, d1, d2;
    cin >> n >> d1 >> d2;
    n *= 2;

    make_graph(n, d1);

    // for (int i = 0; i < n * n; i++) {
        // for (auto v : g[i]) {
            // cout << v << ' ';
        // }
        // cout << '\n';
    // }

    vector<int> vert;
    for (int i = 0; i < n * n; i++) {
        vert.push_back(i);
    }
    vert = vert_good(vert);
    make_graph(n, d2);
    vert = vert_good(vert);

    assert(vert.size() >= n * n / 4);
    for (int i = 0; i < n * n / 4; i++) {
        cout << vert[i] / n << ' ' << vert[i] % n << '\n';
    }

    return 0;
}

