using pii = pair<int,int>;
int n,used[700][700];
pii color[700][700];

void add(int i, int j, int x, int y,vector<vector<vector<pii>>> &G){
	if(x>=0 && x<2*n && y>=0 && y<2*n){
		G[i][j].push_back({x,y});
		G[x][y].push_back({i,j});
	}
}

void dfs1(int s,int t, int c,int x, vector<vector<vector<pii>>> &G ){
    used[s][t] = 1;
    if(x==1) color[s][t].first = c;
    if(x==2) color[s][t].second = c;
    for(auto&&p :G[s][t]){
        if(used[p.first][p.second]!=-1) continue;
        dfs1(p.first,p.second,3-c,x,G);
    }
}

void dfs2(int d,int x){
    vector<pii> v;
    vector<vector<vector<pii>>> G(2 * n, vector<vector<pii>>(2 * n));
    for(int i = 0;i*i<=d;i++){
        int k = d - i*i;
        for(int j = 0;j*j<=k;j++){
            if(j*j==k){
                v.push_back({i,j});
                if(i!=j) v.push_back({j,i});
            }
        }
    }
    for(int i=0;i<2*n;i++){
        for(int j=0;j<2*n;j++){
            for(int k = 0;k<v.size();k++){
                int y = i+v[k].first, z = j+v[k].second; add(i,j,y,z,G);
                y = i-v[k].first; add(i,j,y,z,G);
                z = j-v[k].second; add(i,j,y,z,G);
                y = i+v[k].first; add(i,j,y,z,G);
            }
        }
    }
    for(int i=0;i<2*n;i++){
        for(int j=0;j<2*n;j++){
            used[i][j] = -1;
        }
    }
    for(int i=0;i<2*n;i++){
        for(int j=0;j<2*n;j++){
            if(used[i][j]==-1) dfs1(i,j,1,x,G);
        }
    }
}

