int n, d1, d2;
vector<pair<int, int>> v;
vector<pair<int, int>> ans;

void dfs(int x, int y) {
    for (auto p : v) {
        if (x + p.first < 0 || y + p.second < 0 || x + p.first >= 2 * n || y + p.second >= 2 * n || kek[x + p.first][y + p.second] != 0) {
            continue;
        }
        kek[x + p.first][y + p.second] = 1;
    }
}

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cin >> n >> d1 >> d2;
    for (int i = 0; i * i <= d1; ++i) {
        int rt = sqrt(d1 - i * i);
        if (rt * rt + i * i == d1 && max(i, rt) < 2 * n) {
            v.push_back({i, rt});
            v.push_back({-i, rt});
            v.push_back({i, -rt});
            v.push_back({-i, -rt});
        }
    }
    for (int i = 0; i * i <= d2; ++i) {
        int rt = sqrt(d2 - i * i);
        if (rt * rt + i * i == d2 && max(i, rt) < 2 * n) {
            v.push_back({i, rt});
            v.push_back({-i, rt});
            v.push_back({i, -rt});
            v.push_back({-i, -rt});
        }
    }
    for (int sx = 0; sx < 2; ++sx) {
        for (int sy = 0; sy < 2; ++sy) {
            for (int i = sx; i < n * 2; i += 2) {
                for (int j = sy; j < n * 2; j += 2) {
                    if (ans.size() >= n * n) {
                        break;
                    }
                    if (kek[i][j] == 0) {
                        kek[i][j] = 1;
                        ans.push_back({i, j});
                        dfs(i, j);
                    }
                }
            }
        }
    }
    if (ans.size() < n * n) {
        cout << "ERR";
    } else {
        for (int i = 0; i < n * n; ++i) {
            cout << ans[i].first << ' ' << ans[i].second << '\n';
        }
    }
    return 0;
}

