					if (z.first + x < 2 * n && z.second + y < 2 * n && used[z.first + x][z.second + y]) {
						bad = true;
						break;
					}
					if (z.first + x < 2 * n && y - z.second >= 0 && used[z.first + x][-z.second + y]) {
						bad = true;
						break;
					}
					if (x - z.first >= 0 && z.second + y < 2 * n && used[-z.first + x][z.second + y]) {
						bad = true;
						break;
					}
					if (x - z.first >= 0 && y - z.second >= 0 && used[-z.first + x][-z.second + y]) {
						bad = true;
						break;
					}
				}
				if (bad) {
					break;
				}
			}
			if (!bad) {
				used[x][y] = true;
				st.pb({x, y});
				if (sz(st) == n * n) {
					break;
				}
			}
		}
		if (sz(st) == n * n) {
			break;
		}
	}
	if (sz(st) == n * n) {
		for (auto x: st) {
			cout << x.first << ' ' << x.second << '\n';
		} 
		break;
	}
	}
	return 0;
}

