const int N = 610;
int id[N][N], cnt, d1, d2, bel[2][N * N], num[2][2], n, rec[N * N];
int uni[N * N], dis[N * N];
int getfa(int pos) {
  if (pos == uni[pos]) return pos;
  int ret = getfa(uni[pos]);
  dis[pos] ^= dis[uni[pos]];
  return uni[pos] = ret;
}
void merge(int x,int y) {
  if (getfa(x) != getfa(y)) {
    int tmp = dis[x] ^ dis[y] ^ 1;
    x = getfa(x), y = getfa(y);
    dis[x] = tmp;
    uni[x] = y;
  }
}
void doit(int d,int *b) {
  rep (i, 1, cnt) uni[i] = i, dis[i] = 0;
  rep (i, 0, n-1) rep (j, 0, n-1) {
    rep (x, 0, n) if (x * x <= d && rec[d - x * x] != -1) {
      int y = rec[d - x * x];
      if (i+x < n && j+y < n) merge(id[i][j], id[i+x][j+y]);
      if (i+x < n && j-y >= 0) merge(id[i][j], id[i+x][j-y]);
      if (i+y < n && j+x < n) merge(id[i][j], id[i+y][j+x]);
      if (i+y < n && j-x >= 0) merge(id[i][j], id[i+y][j-x]);
    }
  }
  rep (i, 1, cnt) {
    getfa(i);
    b[i] = dis[i];
  }
}
