#include <bits/stdc++.h>
#define Maxn 607
using namespace std;
int n,d1,d2;
int flag1[Maxn][Maxn],flag2[Maxn][Maxn];
void dfs1(int x,int y,int now)
{
	if (flag1[x][y]!=-1) return;
	flag1[x][y]=now;
	for (int j=0;j<2*n;j++)
	{
		long long del=1LL*d1-1LL*(x-j)*(x-j);
		if (1LL*(int)sqrt(del)*(int)sqrt(del)!=del) continue;
		del=(int)sqrt(del);
		if (y-del>=0) dfs1(j,y-del,now^1);
		if (y+del<2*n) dfs1(j,y+del,now^1);
	}
}
void dfs2(int x,int y,int now)
{
	if (flag2[x][y]!=-1) return;
	flag2[x][y]=now;
	for (int j=0;j<2*n;j++)
	{
		long long del=1LL*d2-1LL*(x-j)*(x-j);
		if (1LL*(int)sqrt(del)*(int)sqrt(del)!=del) continue;
		del=(int)sqrt(del);
		if (y-del>=0) dfs2(j,y-del,now^1);
		if (y+del<2*n) dfs2(j,y+del,now^1);
	}
}
int main()
{
	scanf("%d%d%d",&n,&d1,&d2);
	memset(flag1,-1,sizeof(flag1));
	memset(flag2,-1,sizeof(flag2));
	for (int i=0;i<2*n;i++)
		for (int j=0;j<2*n;j++)
		{
			if (flag1[i][j]==-1) dfs1(i,j,0);
			if (flag2[i][j]==-1) dfs2(i,j,0);
		}
	int res1,res2;
	int cnt1=0,cnt2=0,cnt3=0,cnt4=0;
	for (int i=0;i<2*n;i++)
		for (int j=0;j<2*n;j++)
		{
			if (flag1[i][j]) ++cnt1; else ++cnt2;
			if (flag2[i][j]) ++cnt3; else ++cnt4;
		}
	if (cnt1>=n*n&&cnt3>=n*n) res1=1,res2=1;
	if (cnt1>=n*n&&cnt4>=n*n) res1=1,res2=0;
	if (cnt2>=n*n&&cnt3>=n*n) res1=0,res2=1;
	if (cnt2>=n*n&&cnt4>=n*n) res1=0,res2=0;
	int ans=0;
	for (int i=0;i<2*n;i++)
		for (int j=0;j<2*n;j++)
			if (flag1[i][j]==res1&&flag2[i][j]==res2) 
			{
				printf("%d %d\n",i,j);
				++ans;
				if (ans==n*n) return 0;
			}
	return 0;
}

