	vector<pii> shifts;
	for (int i = -n * 2 + 1; i < n * 2; ++i) {
		for (int j = -n * 2 + 1; j < n * 2; ++j) {
			if (i * i + j * j == d1 || i * i + j * j == d2) {
				shifts.push_back({i, j});
			}
		}
	}

	vector<vector<int>> cnt(n * 2, vector<int>(n * 2));
	//set<pair<int, pii>> st;
	vector<vector<pii>> here(szof(shifts) + 1);
	for (int i = 0; i < n * 2; ++i) {
		for (int j = 0; j < n * 2; ++j) {
			for (auto p : shifts) {
				int nx = i + p.ff;
				int ny = j + p.ss;
				if (0 <= nx && nx < n * 2 && 0 <= ny && ny < n * 2) {
					++cnt[i][j];
				}
			}
			cnt[i][j] = max(0, cnt[i][j] - (int) rnd(0, 1));
			here[cnt[i][j]].push_back({i, j});
		}
	}

	set<int> have;
	for (int i = 0; i < szof(here); ++i) {
		//shuffle(here[i].begin(), here[i].end(), tw);
		if (szof(here[i])) {
			have.insert(i);
		}
	}

	vector<pii> arr;

	while (szof(have)) {
		int lvl = *have.begin();
		int x, y;
		tie(x, y) = here[lvl].back();
		here[lvl].pop_back();
		if (!szof(here[lvl])) {
			have.erase(lvl);
		}
		if (used[x][y]) {
			continue;
		}
		used[x][y] = true;
		arr.push_back({x, y});
		if (szof(arr) == n * n) {
			break;
		}
		for (auto p : shifts) {
			int nx = x + p.ff;
			int ny = y + p.ss;
			if (0 <= nx && nx < n * 2 && 0 <= ny && ny < n * 2 && !used[nx][ny]) {
				used[nx][ny] = true;
				for (auto t : shifts) {
					int nnx = nx + t.ff;
					int nny = ny + t.ss;
					if (0 <= nnx && nnx < n * 2 && 0 <= nny && nny < n * 2 && !used[nnx][nny]) {
						--cnt[nnx][nny];
						if (!szof(here[cnt[nnx][nny]])) {
							have.insert(cnt[nnx][nny]);
						}
						here[cnt[nnx][nny]].push_back({nnx, nny});
					}
				}
			}
		}
	}
	assert(szof(arr) == n * n);
	for (auto p : arr) {
		cout << p.ff << " " << p.ss << "\n";
	}
}


