	if(used[k]){
	  ll dx = abs(i-(k/n/2));
	  ll dy = abs(j-(k%(n*2)));
	  bool ch = check(dp1, dx, dy) && check(dp2, dx, dy);
	  if(!ch){
	    ok = false;
