void coor_insert(vector<int> &X, vector<int> &Y, int D) {
    int cnt = 0;
    for(int r=-D; r<=D; r++) {
        if(r*r > D) continue;
        int rest = D - r*r;
        int tmp = sqrt(rest), c = -INF;
        for(int k=tmp-1; k<=tmp+1; k++) {
            if(k*k == rest) {
                c = k;
                break;
            }
        }

        if(c == -INF) continue;

        // r, c が決定した
        X.push_back(r);
        Y.push_back(c);
        cnt++;

        if(c != 0) {
            X.push_back(r);
            Y.push_back(-c);
            cnt++;
        }
    }
    fprintf(stderr, "insert cnt = %lld\n", cnt);
}

void paint_board(vector<int> &X, vector<int> &Y, int r, int c, int &amount) {
    int M = X.size();

    for(int i=0; i<M; i++) {
        int nr = r + X[i], nc = c + Y[i];
        if(nr < 0 || nr >= 2*N || nc < 0 || nc >= 2*N) continue;
        if(board[nr][nc] == 0) amount--;
        board[nr][nc] = 1;
    }
}

