void addpii(int x)
{
    for(int i = 0; i * i <= x; i++)
    {
        int t = x - i * i;
        int u = sqrt(t) + 0.5;
        if(u * u == t)
        {
            ban.pb(mk(i, u));
            ban.pb(mk(-i, u));
        }
    }
}

void work()
{
    read(n);
    read(A);
    read(B);
    addpii(A);
    addpii(B);

    int nn = n << 1;
    for(int j = 0; j < nn; j++)
    {
        for(int i = 0; i < nn * 2; i++)
        {
            if(vis[i][j]) continue;
            for(int k = 0; k < ban.size(); k++)
            {
                pii p = ban[k];

                int u = i + p.fi;
                int v = j + p.se;

                if(0 <= u && u < nn * 2 && v < nn) vis[u][v] = 1;
            }
        }
    }

    for(int i = 0; i < nn * 2; i++)
    {
        for(int j = 0; j < nn; j++) counter[i] += !vis[i][j];
    }

    int tar = n * n;
    int sum = 0;
    int pos;
    for(int i = 0; i < nn; i++) sum += counter[i];
    for(pos = 0; pos < nn && sum < tar; pos++)
    {
        sum += counter[pos + nn];
        sum -= counter[pos];
    }

    if(sum < tar) while(1);

    int cnt = 0;
    for(int i = 0; i < nn; i++)
    {
        for(int j = 0; j < nn; j++)
        {
            if(vis[i + pos][j]) continue;

            cnt++;

            printf("%d %d\n", i, j);

            if(cnt == tar) break;
        }
        if(cnt == tar) break;
    }

//    cout <<cnt <<endl;
}

