#include<bits/stdc++.h>
using namespace std;

int n,d1,d2,cnt;
bool bo[610][610];

void solve(int xl,int yl,int len,int n,int m,int d1,int d2)
{
	if (m==1)
	{
		for (int x=xl,i=1; i<=n; i++,x+=len) 
		{
			bo[x][yl]=1;
			for (int X=xl,j=1; j<i; j++,X+=len)
				if (bo[X][yl]&&((i-j)*(i-j)==d1||(i-j)*(i-j)==d2)) {bo[x][yl]=0; break;}
		}
		return;
	}
	if (n==1)
	{
		for (int y=yl,i=1; i<=m; i++,y+=len) 
		{
			bo[xl][y]=1;
			for (int Y=yl,j=1; j<i; j++,Y+=len)
				if (bo[xl][Y]&&((i-j)*(i-j)==d1||(i-j)*(i-j)==d2)) {bo[xl][y]=0; break;}
		}
		return;
	}
	if ((d1&1)&&(d2&1))
	{
		for (int i=0; i<n; i++)
			for (int j=(i&1); j<m; j+=2)
				bo[xl+i*len][yl+j*len]=1;
		return;
	}
	if (d1&1)
	{
		if ((d2&3)==2)
		{
			for (int i=0; i<n; i+=2)
				for (int j=0; j<m; j+=2)
					bo[xl+i*len][yl+j*len]=1;
			return;
		}
		solve(xl,yl,len<<1,n+1>>1,m+1>>1,d2>>2,-1);
		solve(xl+len,yl+len,len<<1,n>>1,m>>1,d2>>2,-1);
		return;
	}
	if (d2&1)
	{
		if (d2==-1)
		{
			if ((d1&3)==2)
			{
				for (int i=0; i<n; i+=2)
					for (int j=0; j<m; j++)
						bo[xl+i*len][yl+j*len]=1;
				return;
			}
			solve(xl,yl,len<<1,n+1>>1,m+1>>1,d1>>2,-1);
			solve(xl,yl+len,len<<1,n+1>>1,m>>1,d1>>2,-1);
			solve(xl+len,yl,len<<1,n>>1,m+1>>1,d1>>2,-1);
			solve(xl+len,yl+len,len<<1,n>>1,m>>1,d1>>2,-1);
			return;
		}
		if ((d1&3)==2)
		{
			for (int i=0; i<n; i+=2)
				for (int j=0; j<m; j+=2)
					bo[xl+i*len][yl+j*len]=1;
			return;
		}
		solve(xl,yl,len<<1,n+1>>1,m+1>>1,d1>>2,-1);
		solve(xl+len,yl+len,len<<1,n>>1,m>>1,d1>>2,-1);
		return;
	}
	if ((d2&3)==2) swap(d1,d2);
	if ((d1&3)==2)
	{
		if ((d2&3)==2)
		{
			for (int i=0; i<n; i+=2)
				for (int j=0; j<m; j+=2)
					bo[xl+i*len][yl+j*len]=1;
			return;
		}
		if ((n>>1)*(m+1>>1)>(n+1>>1)*(m>>1)) solve(xl+len,yl,len<<1,n>>1,m+1>>1,d2>>2,-1);
		else solve(xl,yl+len,len<<1,n+1>>1,m>>1,d2>>2,-1);
		solve(xl,yl,len<<1,n+1>>1,m+1>>1,d2>>2,-1);
		return;
	}
	solve(xl,yl,len<<1,n+1>>1,m+1>>1,d1>>2,d2>>2);
	solve(xl+len,yl,len<<1,n>>1,m+1>>1,d1>>2,d2>>2);
	solve(xl,yl+len,len<<1,n+1>>1,m>>1,d1>>2,d2>>2);
	solve(xl+len,yl+len,len<<1,n>>1,m>>1,d1>>2,d2>>2);
}

int main()
{
	scanf("%d%d%d",&n,&d1,&d2);
	memset(bo,0,sizeof(bo)),cnt=0;
	solve(0,0,1,n<<1,n<<1,d1,d2);
	for (int i=0; i<2*n&&cnt<n*n; i++)
		for (int j=0; j<2*n&&cnt<n*n; j++)
			if (bo[i][j]) cnt++,printf("%d %d\n",i,j);
	return 0;
}

