#include <bits/stdc++.h>

const int MAXN = 610;
int A[MAXN][MAXN];
int to[MAXN * MAXN], n;
typedef std::pair<int, int> PII;
typedef std::vector<PII> VI;
VI V, out[MAXN][MAXN], ori[MAXN][MAXN];
int cnt[MAXN][MAXN];
int d1, d2;
void set(int x, int y) {
	if (x < 0 || y < 0 || x >= n || y >= n) return ;
	V.emplace_back(x, y);
}
void clr(int x, int y, int d) {
	for (int i = 0; i <= n; ++i) {
		int t = d - i * i;
		if (t < 0 || !to[t]) continue;
		int dx = i, dy = to[t];
		set(x + dx, y + dy);
		set(x + dx, y - dy);
		set(x - dx, y + dy);
		set(x - dx, y - dy);
		std::swap(dx, dy);
		set(x + dx, y + dy);
		set(x + dx, y - dy);
		set(x - dx, y + dy);
		set(x - dx, y - dy);
	}
}
struct cmp {
	bool operator () (PII a, PII b) {
		return cnt[a.first][a.second] > cnt[b.first][b.second];
	}
} ;
bool vis[MAXN][MAXN];
std::priority_queue<PII, VI, cmp> q;
template<class T> void getmin(T & x, const T y) { x > y ? x = y : 0; }
int main() {
	std::ios_base::sync_with_stdio(false), std::cin.tie(0);
	std::cin >> n >> d1 >> d2; n <<= 1;
	for (int i = 0; i <= n; ++i) to[i * i] = i;
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < n; ++j) {
			V.clear();
			clr(i, j, d1);
			clr(i, j, d2);
			std::sort(V.begin(), V.end());
			V.erase(std::unique(V.begin(), V.end()), V.end());
			out[i][j] = V;
			for (auto t : V)
				ori[t.first][t.second].emplace_back(i, j);
			cnt[i][j] = V.size();
			q.emplace(i, j);
		}
	VI ans;
	while (!q.empty()) {
		auto t = q.top(); q.pop();
		if (vis[t.first][t.second]) continue;
		vis[t.first][t.second] = true;
		ans.push_back(t);
		if (ans.size() == n * n / 4) break;
		for (auto i : out[t.first][t.second]) {
			int x = i.first, y = i.second;
			if (vis[x][y]) continue;
			vis[x][y] = true;
			for (auto j : ori[x][y]) {
				int _x = j.first, _y = j.second;
				if (vis[_x][_y]) continue;
				--cnt[_x][_y];
				q.push(j);
			}
		}
	}
	std::cerr << "GET " << ans.size() << " EX " << n * n / 4 << std::endl;
	assert(ans.size() == n * n / 4);
	for (auto t : ans)
		std::cout << t.first << ' ' << t.second << '\n';
	return 0;
}

