	sort(can.begin(), can.end(), [](PII u, PII v) {
		return (u.x % 2 * 2 + u.y) % 4 < (v.x % 2 * 2 + v.y) % 4;
	});

	if (m == 2)
	sort(can.begin(), can.end(), [](PII u, PII v) {
		return u < v;
	});

	if (m == 3)
	sort(can.begin(), can.end(), [](PII u, PII v) {
		return u.x * u.y < v.x * v.y;
	});

	if (m == 4)
	sort(can.begin(), can.end(), [](PII u, PII v) {
		return (u.x + u.y) % 4 < (v.x + v.y) % 4;
	});

	if (m == 5)
	sort(can.begin(), can.end(), [](PII u, PII v) {
		return (u.x + u.y) % 3 < (v.x + v.y) % 3;
	});

	if (m == 6)
	sort(can.begin(), can.end(), [](PII u, PII v) {
		return (u.x + u.y) % 5 < (v.x + v.y) % 5;
	});

	if (m == 7)
	sort(can.begin(), can.end(), [](PII u, PII v) {
		return (u.x - u.y) % 4 < (v.x - v.y) % 4;
	});

	if (m == 8)
	sort(can.begin(), can.end(), [](PII u, PII v) {
