vector<pii> solve(int n1, int n2, int d1, int d2) {
    vector<pii> ret;
    if (!n1 || !n2) return ret;
    if (n1 == 1 && n2 == 1) {
        ret.push_back(pii(0, 0));
        return ret;
    }
    if (d1 % 4 != 0) swap(d1, d2);
    vector<pii> v;

    if (d1 % 4 != 0) {
        if (d1 % 4 == 3 && d2 % 4 == 3) {
            F0(i, n1) F0(j, n2) ret.push_back(pii(i, j));
        } else
        if (d1 % 4 != 3 && d2 % 4 != 3) {
            F0(i, n1) F0(j, n2) if ((i%2) == 0 && (j%2) == 0) ret.push_back(pii(i, j));
        } else {
            if (d1 % 4 == 3) swap(d1, d2);
            if (d1 % 4 == 1) {
                F0(i, n1) F0(j, n2) if ((i%2) == (j%2)) ret.push_back(pii(i, j));
            } else {
                F0(i, n1) F0(j, n2) if (j%2==0) ret.push_back(pii(i, j));
            }
        }
        return ret;
    }

    if (d2 % 4 == 0) {
        v = solve((n1 + 1) / 2, (n2 + 1) / 2, d1 / 4, d2 / 4);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second));
        v = solve((n1 + 1) / 2, (n2) / 2, d1 / 4, d2 / 4);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second + 1));
        v = solve((n1) / 2, (n2 + 1) / 2, d1 / 4, d2 / 4);
        for (pii p : v) ret.push_back(pii(2 * p.first + 1, 2 * p.second));
        v = solve((n1) / 2, (n2) / 2, d1 / 4, d2 / 4);
        for (pii p : v) ret.push_back(pii(2 * p.first + 1, 2 * p.second + 1));
    } else if (d2 % 4 == 1) {
        v = solve((n1 + 1) / 2, (n2 + 1) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second));
        v = solve((n1) / 2, (n2) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first + 1, 2 * p.second + 1));
    } else if (d2 % 4 == 2) {
        v = solve((n1 + 1) / 2, (n2 + 1) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second));
        v = solve((n1) / 2, (n2 + 1) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second + 1));
    } else if (d2 % 4 == 3) {
        v = solve((n1 + 1) / 2, (n2 + 1) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second));
        v = solve((n1 + 1) / 2, (n2) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first, 2 * p.second + 1));
        v = solve((n1) / 2, (n2 + 1) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first + 1, 2 * p.second));
        v = solve((n1) / 2, (n2) / 2, d1 / 4, 3);
        for (pii p : v) ret.push_back(pii(2 * p.first + 1, 2 * p.second + 1));
    }
    return ret;
}

