#include <bits/stdc++.h>

const int N=610;

struct Edge{ int to,next; }way[N*N*300];

int n,D1,D2,num[N*N],tot,sqrp[200010];

void Build(int x,int y) { ++tot; way[tot]=Edge{y,num[x]}; num[x]=tot; }

void add(int x,int y) { Build(x,y); Build(y,x); } 

void Init() {
	scanf("%d%d%d",&n,&D1,&D2);	
}

int Node(int x,int y) { return x*2*n+y; }

bool vis[N*N],chose[N*N];

void PrintDfs(int x,int &need) {
	int op=1;
	for (int i=num[x];i;i=way[i].next) {
		int v=way[i].to;
		if (chose[v]) op=0;
	}
	vis[x]=1;
	if (op && need) printf("%d %d\n",x/(2*n),x%(2*n)),need--,chose[x]=1;
	for (int i=num[x];i;i=way[i].next) {
		int v=way[i].to;
		if (vis[v]) continue;
		PrintDfs(v,need);
	}
}

void Solve() {
	for (int i=0;i<=200000;++i) sqrp[i]=-1;
	for (int i=1;i*i<=200000;++i) sqrp[i*i]=i;
	for (int i=0;i<2*n;++i) 
		for (int j=0;j<2*n;++j) {
			for (int k=0;k*k<=D1;++k) 
				if (sqrp[D1-k*k]!=-1) {
					int a=sqrp[D1-k*k],b=k;
					if (i+a<2*n && j+b<2*n) 
						add(Node(i+a,j+b),Node(i,j));
					if (i+b<2*n && j+a<2*n) 
						add(Node(i+a,j+b),Node(i,j));
					if (i+a<2*n && j-b>=0) 
						add(Node(i+a,j-b),Node(i,j));
					if (i+b<2*n && j-a>=0) 
						add(Node(i+a,j-b),Node(i,j));
				}
			for (int k=0;k*k<=D2;++k)
				if (sqrp[D2-k*k]!=-1) {
					int a=sqrp[D2-k*k],b=k;
					if (i+a<2*n && j+b<2*n) 
						add(Node(i+a,j+b),Node(i,j));
					if (i+b<2*n && j+a<2*n) 
						add(Node(i+a,j+b),Node(i,j));
					if (i+a<2*n && j-b>=0) 
						add(Node(i+a,j-b),Node(i,j));
					if (i+b<2*n && j-a>=0) 
						add(Node(i+a,j-b),Node(i,j));		
				}
		}
	int need=n*n;
	for (int i=0;i<2*n;++i) 
		for (int j=0;j<2*n;++j) if (need && !vis[Node(i,j)]) 
			PrintDfs(Node(i,j),need);
}

int main()
{
	Init();
	Solve();
	return 0;
}

