	F(i,N) if(i*i<=D2)
		F(j,N) if(i*i+j*j==D2)
			i2[t2]=i, j2[t2]=j, t2++;
	F(i,N) F(j,N) DFS1(i,j,0);
	F(i,N) F(j,N) DFS2(i,j,0);
	F(i,N) F(j,N)
		++s[c1[i][j]*2+c2[i][j]];
	F(k,4) if(s[k]>=n*n){
		int cnt=0;
		F(i,N) F(j,N) if(c1[i][j]*2+c2[i][j]==k&&cnt<n*n)
