void dfs(int u, bool c)
{
	col[u]=c, used[u]=1;
	for(int i=0; i<G[u].size(); i++)
		if(used[G[u][i]]==0) dfs(G[u][i], c^1);
}
void dfs2(int u, bool c)
{
	col2[u]=c, used2[u]=1;
	for(int i=0; i<G2[u].size(); i++)
		if(used2[G2[u][i]]==0) dfs2(G2[u][i], c^1);
}
bool check(int c1, int c2)
{
	int cnt=0;
	for(int i=0; i<2*n; i++)
		for(int j=0; j<2*n; j++) if(col[make(i, j)]==c1&&col2[make(i, j)]==c2) cnt++;
	if(cnt>=n*n)
	{
		cnt=0;
		for(int i=0; i<2*n; i++)
			for(int j=0; j<2*n; j++)
				if(cnt<n*n&&col[make(i, j)]==c1&&col2[make(i, j)]==c2) {cout<<i<<" "<<j<<endl; cnt++;}
		return true;
	}
	return false;
}

