    for(int i=0; i<2*n; i++)
		for(int j=0; j<2*n; j++)
			for(int ii=0; ii<2*n; ii++)
			{
				long long rez=d1-(ii-i)*1ll*(ii-i);
				if(rez>=0&&rez<4ll*n*n&&sq[rez]!=-1&&!(rez==0&&ii==i))
				{
					int jj=sq[rez];
					if(j-jj>=0)
					{
						G[make(i, j)].push_back(make(ii, j-jj));
						G[make(ii, j-jj)].push_back(make(i, j));
					}
					if(j+jj<2*n)
					{
						G[make(i, j)].push_back(make(ii, jj+j));
						G[make(ii, jj+j)].push_back(make(i, j));
					}
				} 

				rez=d2-(ii-i)*1ll*(ii-i);
				if(rez>=0&&rez<4ll*n*n&&sq[rez]!=-1&&!(rez==0&&ii==i))
				{
					int jj=sq[rez];
					if(j-jj>=0)
					{
						G2[make(i, j)].push_back(make(ii, j-jj));
						G2[make(ii, j-jj)].push_back(make(i, j));
					}
					if(j+jj<2*n)
					{
						G2[make(i, j)].push_back(make(ii, jj+j));
						G2[make(ii, jj+j)].push_back(make(i, j));
					}
				} 
			}
	for(int i=0; i<2*n; i++)
		for(int j=0; j<2*n; j++) if(used[make(i, j)]==0)  dfs(make(i, j), 0);
	for(int i=0; i<2*n; i++)
		for(int j=0; j<2*n; j++) if(used2[make(i, j)]==0)  dfs2(make(i, j), 0);

	/*for(int i=0; i<2*n; i++)
		for(int j=0; j<2*n; j++) if(col[make(i, j)]==0) cout<<i<<" "<<j<<endl;*/
	if(check(0, 0)) return;
	if(check(0, 1)) return;
	if(check(1, 0)) return;
	check(1, 1);
}

