inline void add(int from,int to) {
	e[++tot]=(Edge){to,head[from]}; head[from]=tot;
}

inline bool check(int x,int y) {
	if (x<1 || x>n) return 0;
	if (y<1 || y>n) return 0;
	return 1;
}

inline void init(int p) {
	tot=0; Set(head,0);
	for (int i=0;i*i<=d[p];++i) {
		int j=sqrt(d[p]-i*i);
		if (i*i+j*j==d[p]) {
			For (x,1,n)
				For (y,1,n) {
					int xx,yy;
					xx=x+i; yy=y+j;
					if (check(xx,yy)) add(id[x][y],id[xx][yy]);
					xx=x+i; yy=y-j;
					if (check(xx,yy)) add(id[x][y],id[xx][yy]);
					xx=x-i; yy=y+j;
					if (check(xx,yy)) add(id[x][y],id[xx][yy]);
					xx=x-i; yy=y-j;
					if (check(xx,yy)) add(id[x][y],id[xx][yy]);
				}
		}
	}
}

void dfs(int u,int c,int p) {
	vis[u]=1; col[u]|=c<<p;
	for (int i=head[u];i!=0;i=e[i].nxt) {
		int v=e[i].to;
		if (vis[v]) continue;
		dfs(v,c^1,p);
	}
}

inline void solve(int p) {
	Set(vis,0);
	For (i,1,n)
		For (j,1,n)
			if (!vis[id[i][j]]) dfs(id[i][j],0,p);
}

