vp raw(int h, int w) {
  vp res;
  rep(i,h)rep(j,w) res.pb(P(i,j));
  return res;
}
vp g(int h, int w, int a) {
  vp res;
  if (a%4 == 0) {
    rep(i,2)rep(j,2) {
      vp ps = g(d(h,i),d(w,j),a/4);
      for (P p : ps) {
        p.fi = p.fi*2+i;
        p.se = p.se*2+j;
        res.pb(p);
      }
    }
    return res;
  }
  if (a%2 == 1) {
    rep(i,2) {
      vp ps = raw(d(h,i),d(w,i));
      for (P p : ps) {
        p.fi = p.fi*2+i;
        p.se = p.se*2+i;
        res.pb(p);
      }
    }
    return res;
  }
  rep(i,2) {
    vp ps = raw(d(h,i),d(w,0));
    for (P p : ps) {
      p.fi = p.fi*2+i;
      p.se *= 2;
      res.pb(p);
    }
  }
  return res;
}
vp f(int h, int w, int a, int b) {
  vp res;
  if (a%4 == 0 && b%4 == 0) {
    rep(i,2)rep(j,2) {
      vp ps = f(d(h,i),d(w,j),a/4,b/4);
      for (P p : ps) {
        p.fi = p.fi*2+i;
        p.se = p.se*2+j;
        res.pb(p);
      }
    }
    return res;
  }
  if (a%4 == 0) swap(a,b);
  if (b%4) {
    vp ps = raw(d(h,0),d(w,0));
    for (P p : ps) {
      p.fi *= 2;
      p.se *= 2;
      res.pb(p);
    }
    return res;
  }
  if (a%2 == 1) {
    rep(i,2) {
      vp ps = g(d(h,i),d(w,i),b/4);
      for (P p : ps) {
        p.fi = p.fi*2+i;
        p.se = p.se*2+i;
        res.pb(p);
      }
    }
    return res;
  }
  rep(i,2) {
    vp ps = g(d(h,i),d(w,0),b/4);
    for (P p : ps) {
      p.fi = p.fi*2+i;
      p.se *= 2;
      res.pb(p);
    }
  }
  return res;
}

