int main() {
//	freopen("input.txt", "r", stdin);
	int n, d1, d2;
	ni(n); nii(d1, d2);
	for (int k = -n - n; k <= n + n; k++) {
		int dy = (int)(round(sqrt(d1 - k*k)) + 1e-9);
		if (dy*dy + k*k == d1) {
			if (abs(dy) < n + n)ds.emplace_back(k, dy);
			if (abs(dy)< n+n && dy != 0)ds.emplace_back(k, -dy);
		}

		dy = (int)(round(sqrt(d2 - k*k)) + 1e-9);
		if (dy*dy + k*k == d2) {
			if (abs(dy) < n + n)ds.emplace_back(k, dy);
			if (abs(dy)< n + n && dy != 0)ds.emplace_back(k, -dy);
		}

	}
	F(i, n+n)F(j, n+n) {
		for (auto &x : ds) {
			if (i + x.first >= 0 && i + x.first < n + n && j + x.second >= 0 && j + x.second < n + n) {
				adj[i][j].emplace_back(i + x.first, j + x.second);
			}
		}
	}
	F(i, n + n)F(j, n + n)v[adj[i][j].size()].emplace_back(i, j);
	vector<pii> ans;
	for (int k = 0; k <= 4*n;k++) {
			for (auto &x : v[k]) {
				if (chk[x.first][x.second])continue;
				ans.push_back(x);
				for (auto &y : adj[x.first][x.second]) {
					chk[y.first][y.second] = 1;
				}
			}
	}
	ans.resize(n*n);
	for (auto &x : ans)printf("%d %d\n", x.first, x.second);

}

