vector<pair<int, int>> getdeltas(int d1) {
	vector<pair<int, int>> ret;
	for (int i = 0; i * i <= d1; ++i) {
		int j = sqrt(d1 - i * i) + 1e-9;
		if (j * j + i * i == d1) {
			ret.push_back({i, j});
			ret.push_back({-i, -j});
			ret.push_back({-i, j});
			ret.push_back({i, -j});
		}
	}
	return ret;
}
