const int maxn = 600, maxm = maxn * maxn;
int n, tot, id[maxn + 3][maxn + 3], row[maxm + 3], col[maxm + 3];
int x, y, num[maxm + 3], res[maxm + 3], cnt[5];
bool vis[maxm + 3];
vector<int> G[maxm + 3];

void add(int u, int v) {
	G[u].push_back(v);
}

void dfs(int u) {
	vis[u] = true;
	for (int i = 0, v; i < G[u].size(); i++) {
		v = G[u][i];
		if (vis[v]) continue;
		num[v] = num[u] ^ 1;
		dfs(v);
	}
}

void solve(int x, int y) {
	for (int i = 1; i <= tot; i++) {
		vis[i] = false;
		vector<int>().swap(G[i]);
	}
	for (int a = 0; a < n * 2; a++) {
		for (int b = 0; b < n * 2; b++) {
			if (a * a + b * b == x) {
				for (int i = 0; i < n * 2 - a; i++) {
					for (int j = 0; j < n * 2 - b; j++) {
						add(id[i][j], id[i + a][j + b]);
						add(id[i + a][j + b], id[i][j]);
						add(id[i][j + b], id[i + a][j]);
						add(id[i + a][j], id[i][j + b]);
					}
				}
			}
		}
	}
	dfs(1);
	for (int i = 1; i <= tot; i++) {
		res[i] |= num[i] * y;
	}
}

int main() {
	scanf("%d %d %d", &n, &x, &y);
	for (int i = 0; i < n * 2; i++) {
		for (int j = 0; j < n * 2; j++) {
			id[i][j] = ++tot;
			row[tot] = i, col[tot] = j;
		}
	}
	solve(x, 1), solve(y, 2);
	for (int i = 1; i <= tot; i++) {
		cnt[res[i]]++;
	}
	int x = 0;
	for (int i = 0; i < 4; i++) {
		if (cnt[i] >= n * n) {
			x = i;
			break;
		}
	}
	int all = 0;
	for (int i = 1; i <= tot; i++) {
		if (res[i] == x) {
			printf("%d %d\n", row[i], col[i]);
			if (++all == n * n) break;
		}
	}
	return 0;
}

