vpii ans;

void kill() {
	for (pii z : ans) {
		printf("%d %d\n", z.first, z.second);
	}
	exit(0);
}

int sqr(int x) {
	return x * x;
}

int dist(int x1, int y1, int x2, int y2) {
	return sqr(x1 - x2) + sqr(y1 - y2);
}

bool canadd(int x, int y) {
	for (pii z : ans) {
		int d = dist(z.first, z.second, x, y);
		if (d == d1 || d == d2) return false;
	}
	return true;
}

void rec(int x, int y) {
	if (sz(ans) == nn) {
		kill();
	}		
	if (y == n2) return;
	if (x == n2) {		
		rec(0, y + 1);
		return;
	}
	if (canadd(x, y)) {
		ans.pb(mp(x, y));
		rec(x + 1, y);	
		ans.pop_back();
	}
	rec(x + 1, y);
}

void solve() {
	nn = n * n;
	n2 = n * 2;
	rec(0, 0);	
}

