			For(i,0,n-1) For(j,0,n-1)
				a[d][i][j]=(i+j+1)&1;
		}
		else{
			For(i,0,n-1) For(j,0,n-1)
				a[d][i][j]=(i+1)&1; 
		}
		return;
	}
	work(n,D/4,d+1);
	For(i,0,n-1) For(j,0,n-1)
		a[d][i][j]=a[d+1][i/2][j/2];
}
int main(){
	scanf("%d%d%d",&n,&D1,&D2);
	work(2*n,D1,0);
	For(i,0,2*n-1) For(j,0,2*n-1)
		ans[i][j]=a[0][i][j];
	work(2*n,D2,0);
	For(i,0,2*n-1) For(j,0,2*n-1)
		ans[i][j]&=a[0][i][j];
	int rest=n*n;
	For(i,0,2*n-1) For(j,0,2*n-1)
		if (rest&&ans[i][j])
			--rest,printf("%d %d\n",i,j);
}

