}

bool dfs(int v) {
    used[v] = true;
    for (int i = 0; i < G[v].size(); i++) {
        int u = G[v][i], w = match[u];
        if (w < 0 || !used[w] && dfs(w)) {
            match[v] = u;
            match[u] = v;
            return true;
        }
    }
    return false;
}

int bipartite_matching() {
    int res = 0;
    memset(match, -1, sizeof(match));
    for (int v = 0; v < V; v++) {
        if (match[v] < 0) {
            memset(used, 0, sizeof(used));
            if (dfs(v)) res++;
        }
    }
    return res;
}

bool is_square(int x2, int& x) {
    int ok = 0, ng = 10000;
    while (ng - ok > 1) {
        int mid = (ok + ng) / 2;
        if (mid * mid <= x2) ok = mid;
        else ng = mid;
    }
    x = ok;
    return x * x == x2;
}

