				for (int disX = 0; j - disX >= 0 || j+disX < 2*n; disX++){
					int rem = d - disX*disX;
					if (rem < 0 || sv[rem]==-1) continue;
					for (int ii = -1; ii <= 1; ii++)
						if (ii)
							for (int jj = -1; jj <= 1; jj++)
								if (jj) {
									pii u(i+sv[rem]*ii, j+disX*jj);
									if (!fit(u.F, u.S) || col[0][u.F][u.S] != good) continue;
									addEdge(i, j, i+sv[rem]*ii, j+disX*jj);
								}
				}
