namespace Problem {
using namespace std;

class Solver {
 public:
  int n, d1, d2;
  Solver(LL n) : n(n){};
  using Graph = vector<vector<vector<pair<int, int>>>>;
  Graph makeGraph(int d) {
    Graph ret(2 * n, vector<vector<pair<int, int>>>(2 * n));
    for (int a = -2 * n; a < 2 * n; ++a) {
      for (int b = -2 * n; b < 2 * n; ++b) {
        if (a * a + b * b == d) {
          for (int i = 0; i < 2 * n; ++i) {
            for (int j = 0; j < 2 * n; ++j) {
              int nx = i + a, ny = j + b;
              if (0 <= nx and nx < 2 * n and 0 <= ny and ny < 2 * n) {
                ret[i][j].emplace_back(nx, ny);
              }
            }
          }
        }
      }
    }
    return ret;
  }
  vector<vector<int>> divide(const Graph& g) {
    vector<vector<int>> ret(2 * n, vector<int>(2 * n, -1));
    for (int i = 0; i < 2 * n; ++i) {
      for (int j = 0; j < 2 * n; ++j) {
        if (ret[i][j] >= 0) continue;
        ret[i][j] = 0;
        dfs(i, j, g, ret);
      }
    }
    return ret;
  }
  void dfs(int x, int y, const Graph& g, vector<vector<int>>& b) {
    for (auto&& p : g[x][y]) {
      if (b[p.first][p.second] == -1) {
        b[p.first][p.second] = !b[x][y];
        dfs(p.first, p.second, g, b);
      }
    }
  }
  void solve() {
    cin >> d1 >> d2;
    Graph g1 = makeGraph(d1);
    Graph g2 = makeGraph(d2);
    auto res1 = divide(g1);
    auto res2 = divide(g2);
    vector<vector<pair<int, int>>> ans(4);
    for (int i = 0; i < 2 * n; ++i) {
      for (int j = 0; j < 2 * n; ++j) {
        ans[res1[i][j] * 2 + res2[i][j]].emplace_back(i, j);
      }
