void four(int A, int B) {
	n = N;
	int times = 1;
	while(A % 4 == 0 && B % 4 == 0) {
		A /= 4;
		B /= 4;
		times *= 2;
		n /= 2;
	}
	if(A % 4 == 0 || B % 4 == 0) return;
	for(int a = 0; a < 2 * n; ++a)
		for(int b = 0; b < 2 * n; ++b)
			if(a % 2 == 0 && b % 2 == 0) {
				for(int i = 0; i < times; ++i)
					for(int j = 0; j < times; ++j)
						taken[a*times+i][b*times+j] = true;
			}
	for(int a = 0; a < 2 * n; ++a)
		for(int b = 0; b < 2 * n; ++b)
			if(taken[a][b])
				for(pair<int,int> p : they) {
					int c = p.first + a;
					int d = p.second + b;
					if(0 <= min(c, d) && max(c, d) < 2 * n * times && taken[c][d])
						return;
				}
	//~ printf("4) :)\n");
	int cnt = 0;
	n *= times;
	for(int a = 0; a < 2 * n; ++a)
		for(int b = 0; b < 2 * n; ++b) if(taken[a][b]) {
			printf("%d %d\n", a, b);
			++cnt;
			if(cnt == n * n) exit(0);
		}
	exit(0);
}

