using namespace std;
using pii = pair<int,int>;
int n,used[700][700];
pii color[700][700];
void dfs1(int s,int t, int c,int x, vector<vector<vector<pii>>> &G ){
    //cout << s << " " << t << endl;
    used[s][t] = 1;
    if(x==1) color[s][t].first = c;
    if(x==2) color[s][t].second = c;
    for(auto&&p :G[s][t]){
        if(used[p.first][p.second]!=-1) continue;
        dfs1(p.first,p.second,3-c,x,G);
    }
}

void dfs2(int d,int x){
    vector<pii> v;
    vector<vector<vector<pii>>> G(2 * n, vector<vector<pii>>(2 * n));
    for(int i=0; i*i<=d;i++){
        int k = d - i*i;
        for(int j = 0;j*j<=k;j++){
            if(j*j==k){
                //cout <<x << " " <<  i << " " << j << endl;
                v.push_back(make_pair(i,j));
                if(i!=j) v.push_back(make_pair(j,i));
            }
        }
    }
    for(int i=0;i<2*n;i++){
        for(int j=0;j<2*n;j++){
            for(int k = 0;k<v.size();k++){
                int y = i+v[k].first, z = j+v[k].second;
                if(y<2*n && z<2*n){
                    //cout << i << j << x << y << endl;
                    G[i][j].push_back({y,z}); G[y][z].push_back({i,j});
                }
                y = i-v[k].first;
                if(y>=0 && z<2*n){
                    G[i][j].push_back({y,z}); G[y][z].push_back({i,j});
                }
                z = j-v[k].second;
                if(y>=0 && z>=0){
                    G[i][j].push_back({y,z}); G[y][z].push_back({i,j});
                }
                y = i+v[k].first;
                if(y<2*n && z>=0){
                    G[i][j].push_back({y,z}); G[y][z].push_back({i,j});
                }
            }
        }
    }
    for(int i=0;i<2*n;i++){
        for(int j=0;j<2*n;j++){
            used[i][j] = -1;
        }
    }
    for(int i=0;i<2*n;i++){
        for(int j=0;j<2*n;j++){
            if(used[i][j]==-1) dfs1(i,j,1,x,G);
        }
    }
}

int main(){
    int d,e;
    cin >> n >> d >> e;
    dfs2(d,1);
    dfs2(e,2);
    vector<pii> sum1, sum2, sum3, sum4;
    for(int i=0;i<2*n;i++){
        for(int j=0;j<2*n;j++){
            int x = color[i][j].first,y = color[i][j].second;
            //cout << i << " "<< j << " " << x << " " << y << endl;
            if(x==1 && y==1) sum1.push_back({i,j});
            if(x==2 && y==1) sum2.push_back({i,j});
            if(x==2 && y==2) sum3.push_back({i,j});
            if(x==1 && y==2) sum4.push_back({i,j});
