#define FILEIO(name) freopen(name".in", "r", stdin), freopen(name".out", "w", stdout);

using namespace std;

char buf[1000000], *p1 = buf, *p2 = buf;
inline char gc() {
  if (p1 == p2) p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin);
  return p1 == p2 ? EOF : *(p1++);
}
template <class T> inline void read(T &n) {
  n = 0; RI ch = gc(), f;
  while ((ch < '0' || ch > '9') && (ch != '-')) ch = gc();
  f = (ch == '-' ? ch = gc(), -1 : 1);
  while (ch >= '0' && ch <= '9') n = n * 10 + (ch ^ 48), ch = gc();
  n *= f;
}

int col[305][305];

void Solve(int n, int k) {
  int t = 0;
  while (!(k % 4)) k >>= 2, ++t;
  for (RI i = 1; i <= 2 * n; ++i)
    for (RI j = 1; j <= 2 * n; ++j) {
      if (k % 4 == 1) 
        if (((i >> t) + (j >> t)) & 1)
          col[i][j] = 1;
      if (k % 4 == 2)
        if ((i >> t) & 1)
          col[i][j] = 1;
    }
  // if t % 2 == 0 then t^2 % 4 = 0
  // if t % 2 == 1 then t^2 % 4 = 1
  // so if k = a^2 + b^2 then k % 4 != 3
}

int main() {

  FILEIO("a");

  int n, d1, d2; read(n), read(d1), read(d2);
  Solve(n, d1), Solve(n, d2);
  int cnt = 0;
  for (RI i = 1; i <= 2 * n && cnt < n * n; ++i)
    for (RI j = 1; j <= 2 * n && cnt < n * n; ++j)
      if (!col[i][j])
        printf("%d %d\n", i - 1, j - 1), ++cnt;

  cerr << (double)(clock()) / CLOCKS_PER_SEC * 1000 << "ms" << endl;

  return 0;
}

