int N;
int D0, D1, D[2];

bool H[666][666];
int F[666][666];

vector<pair<int, int> > E, ans;
bool in(int y, int x) {
    return 0 <= y && y < N*2 && 0 <= x && x <= N*2;
}

stack<pair<int, int> > st;
int cnt, rem;

void pick(int y, int x) {
    if (!H[y][x]) return;

    int one = 0;
    EACH (e, E) {
	int yy = y + e->first;
	int xx = x + e->second;
	if (in(yy, xx) && F[yy][xx] == 1) {
	    one++;
	}
    }
    if (one > 1) {
	H[y][x] = false;
	F[y][x]--;
	cnt--;
	EACH (e, E) {
	    int yy = y + e->first;
	    int xx = x + e->second;
	    if (in(yy, xx) && F[yy][xx] == 1) {
		F[yy][xx]--;
		if (F[yy][xx] == 0) st.emplace(yy, xx);
	    }
	}
    }
}

void put(int y, int x) {
    if (H[y][x]) return;

    if (F[y][x] == 0) {
	H[y][x] = true;
	F[y][x] = 1;
	cnt++;
	EACH (e, E) {
	    int yy = y + e->first;
	    int xx = x + e->second;
	    if (in(yy, xx)) {
		F[yy][xx]++;
	    }
	}

	return;
    }
}

void MAIN() {
    scanf("%d", &N);
    scanf("%d%d", &D0, &D1);
    if (D0 > D1) swap(D0, D1);

    D[0] = D0;
    D[1] = D1;

    for (int i=-N*2+1; i<N*2; i++) {
	for (int j=-N*2+1; j<N*2; j++) {
	    int tmp = i*i + j*j;
	    if (tmp == D0 || tmp == D1) {
		E.emplace_back(i, j);
	    }
	}
    }

    REP (i, N*2) REP (j, N*2) {
	st.emplace(i, j);
    }
    while (cnt < N*N && !st.empty()) {
	int y = st.top().first;
	int x = st.top().second;
	st.pop();
	pick(y, x);
	put(y, x);
    }


    REP (i, N*2) REP (j, N*2) if (H[i][j]) {
	ans.emplace_back(i, j);
    }

    if ((int)ans.size() < N*N) {
	puts("-1");
    } else {
	ans.resize(N*N);
	EACH (e, ans) printf("%d %d\n", e->first, e->second);
    }
}

int main() {
    int TC = 1;
//    scanf("%d", &TC);
    REP (tc, TC) MAIN();
    return 0;
}

