void work(int x,int y){
	int tx,ty; 
	for (int i=1;i<=tot;i++){
		tx=x+dx[i],ty=y+dy[i];
		WORK(tx,ty);
		tx=x+dx[i],ty=y-dy[i];
		WORK(tx,ty);
		tx=x-dx[i],ty=y+dy[i];
