		tx=x+dy[i],ty=y-dx[i];
		WORK(tx,ty);
		tx=x-dy[i],ty=y+dx[i];
		WORK(tx,ty);
		tx=x-dy[i],ty=y-dx[i];
		WORK(tx,ty);
	}
	vis[x][y]=1;

}
