pair<int,int> coloring(vector<vector<int>>& g, vector<int>& c, int pos, int color){
  c[pos] = color;
  pair<int,int> res( color==0, color==1 );
  for(int nx : g[pos]){
    if( c[nx] != -1 ) continue;
    auto tmp = coloring(g, c, nx, color^1);
    res.first += tmp.first;
    res.second += tmp.second;
  }
  return res;
}

