using namespace std;

typedef pair<int,int> pii;
const int mx = 605;

int mark[mx][mx];

vector<pii> adj[2];
vector<pii> P[4];

int D[2];
int n;

inline int dis(pii u, pii v){
    return (u.first - v.first) * (u.first - v.first) + (u.second - v.second) * (u.second - v.second);
}
void init(){
    #ifndef TAM
    cin >> n >> D[0] >> D[1];
    #endif // TAM
    #ifdef TAM
    srand((unsigned int)time(0));
    n = rand() % 300 + 1;
    D[0] = rand() * rand() % 200000 + 1;
    D[1] = rand() * rand() % 200000 + 1;
    printf("n = %d, D[0] = %d, D[1] = %d\n",n,D[0],D[1]);
    #endif // TAM
    for(int i = 0; i < 2 * n; i++) fill(mark[i],mark[i] + 2*n, -1);

    for(int b = 0; b < 2; b++){
        for(int i = (int)(sqrt(D[b])+1e-9); i >= 0; i--){
            for(int j = i; j >= 0; j--){
                if(i * i + j * j == D[b]){
                    adj[b].emplace_back(i,j);
                    adj[b].emplace_back(j,i);
                    adj[b].emplace_back(-i,j);
                    adj[b].emplace_back(j,-i);
                    adj[b].emplace_back(i,-j);
                    adj[b].emplace_back(-j,i);
                    adj[b].emplace_back(-i,-j);
                    adj[b].emplace_back(-j,-i);

                    break;
                }
            }
        }

        sort(adj[b].begin(),adj[b].end());
        adj[b].erase(unique(adj[b].begin(),adj[b].end()),adj[b].end());
/*
        for(pii &p : adj[b]){
            cout << p.first << ' ' << p.second << '\n';
        }
        cout << "-----------\n";
*/
    }
}

void dfs(int r, int c, int ty, int v, int tog, int bv){
    mark[r][c] = v;
    P[v].emplace_back(r,c);
    int nr, nc;
    for(pii &p : adj[ty]){
        nr = r + p.first;
        nc = c + p.second;
        if(nr < 0 || nr >= 2 * n || nc < 0 || nc >= 2 * n) continue;
        if(mark[nr][nc] != bv) continue;
        dfs(nr,nc,ty,tog,v,bv);
    }
}

void pro(){
    for(int i = 0; i < 2*n; i++){
        for(int j = 0; j < 2*n; j++){
            if(mark[i][j] != -1) continue;
            dfs(i,j,0,0,1,-1);
        }
    }
    int dom = (P[1].size() >= P[0].size() ? 1 : 0);
    for(pii &p : P[dom]){
        if(mark[p.first][p.second] != dom) continue;
        dfs(p.first,p.second,1,2,3,dom);
    }
    int ddom = (P[3].size() >= P[2].size() ? 3 : 2);

    assert(P[ddom].size() >= n * n);
    int C = n * n;
#ifdef TAM
    for(int i = 0; i < C; i++){
        for(int j = i+1; j < C; j++){
            int T = dis(P[ddom][i], P[ddom][j]);
            assert(T != D[0] && T != D[1]);
        }
    }
#endif
#ifndef TAM
    for(int i = 0; i < C; i++){
        cout << P[ddom][i].first << ' ' << P[ddom][i].second << '\n';
    }
#endif // TAM
}

int main(){
    ios_base::sync_with_stdio(false);cin.tie(0);
    init();
    pro();
}

