void ad(int a, int b, int x) {
    if (x == -1) {
        bes.erase({sz(adj[a][b]),{a,b}});
    }
    for (auto z: bad) for (int i = -1; i <= 1; i += 2) for (int j = -1; j <= 1; j += 2) {
        pi Z = {a+z.f*i,b+z.s*j};
