            adj[a][b].erase(Z);
            bes.erase({sz(adj[Z.f][Z.s]),Z});
            adj[Z.f][Z.s].erase({a,b});
            bes.insert({sz(adj[Z.f][Z.s]),Z});
        }
    }
    if (x == 1) {
        bes.insert({sz(adj[a][b]),{a,b}});
    } 
}

void process(pi x) {
    vpi al = {x};
    for (auto a: adj[x.f][x.s]) al.pb(a);
    for (auto x: al) ad(x.f,x.s,-1);
}

void solve() {
    bes.clear(); bad.clear();
    F0R(i,600) F0R(j,600) adj[i][j].clear();
    if (D1 > D2) swap(D1,D2);
    for (int i = 0; i <= 500; ++i) for (int j = 0; j <= 500; ++j) 
        if (i*i+j*j == D1 || i*i+j*j == D2) bad.pb({i,j});

    F0R(i,2*N) F0R(j,2*N) ad(i,j,1);
    F0R(i,N*N) {
        if (!sz(bes)) {
            cout << "OOPS " << D1 << " " << D2 << "\n";
            return;
        }
        auto a = *bes.begin(); process(a.s);
        cout << a.s.f << " " << a.s.s << "\n";
    }
}

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);
    cin >> N >> D1 >> D2; 
    solve();
}

