vector<int> dx, dy;
bool used[maxn][maxn];

void go(int x, int y, int n, bool to[maxn][maxn], int c = 0) {
  if (used[x][y]) {
    assert(c == to[x][y]);
    return;
  }
  used[x][y] = true;
  to[x][y] = c;
  for (int dir = 0; dir < (int) dx.size(); ++dir) {
    int nx = x + dx[dir];
    int ny = y + dy[dir];
    if (nx < 0 || nx >= n || ny < 0 || ny >= n) {
      continue;
    }
    go(nx, ny, n, to, c ^ 1);
  }
}

void solve(int n, int d, bool to[maxn][maxn]) {
  dx.clear();
  dy.clear();
  for (int x = -n; x <= n; ++x) {
    if (x * x > d) {
      continue;
    }
    int y = roundl(sqrtl(d - x * x));
    if (y * y + x * x != d) {
      continue;
    }
    dx.push_back(x);
    dy.push_back(y);

    dx.push_back(x);
    dy.push_back(-y);
  }
  memset(used, 0, sizeof(used));
  int sum = 0;
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      if (!used[i][j]) {
        go(i, j, n, to);
      }
      sum += to[i][j];
    }
  }
  if (sum < n * n / 2) {
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < n; ++j) {
        to[i][j] ^= 1;
      }
    }
  }

  //for (int i = 0; i < n; ++i) {
    //for (int j = 0; j < n; ++j) {
      //cerr << to[i][j];
    //}
    //cerr << '\n';
  //}
}

