                    }
                }
            }
        }
    }

    // ??
    Vector<i64> V1(4 * N * N, 0);
    REP (id, 4 * N * N) {
        if (V1[id] != 0) continue;

        std::stack<pair<i64, i64>> s;
        s.emplace(-1, id);
        while (!s.empty()) {
            auto elem = s.top();
            s.pop();
            auto prev = elem.first;
            auto x = elem.second;

            if (V1[x] != 0) {
                continue;
            }

            if (prev == -1) {
                V1[x] = 1;
            } else {
                V1[x] = -V1[prev];
            }

            EACH_V (edge, g_1.outgoings(x)) {
                s.emplace(get<0>(edge), get<1>(edge));
            }
        }
