const int SQRT = BUCK+9;

vector < pii > arr, ans;
int node[N][N];
pii val[M];
vi v[M];
bool vis[M];
int deg[M];
priority_queue < pii > pq;

void solve()
{
	int n, d1, d2, i, j, d, cnt = 0, a;
	pii z;
	cin >> n >> d1 >> d2;
	fo(i,0,n+n)
		fo(j,0,n+n)
		{
			int d = i*i + j*j;
			if(d == d1 || d == d2)
				arr.pb({i,j});
		}
	for(auto x : arr)
		cerr << x.F << "," << x.S << '\n';
	fo(i,0,n+n)
		fo(j,0,n+n)
		{
			node[i][j] = cnt;
			val[cnt] = {i,j};
			cnt++;
		}
	fo(i,0,n+n)
		fo(j,0,n+n)
		{
			for(auto x : arr)
				if(i+x.F < n+n && j+x.S < n+n)
				{
					v[node[i][j]].pb(node[i+x.F][j+x.S]);
					v[node[i+x.F][j+x.S]].pb(node[i][j]);
				}
		}
	fo(i,0,cnt)
	{
		deg[i] = sz(v[i]);
		pq.push({-sz(v[i]),i});
	}
	while(!pq.empty())
	{
		z = pq.top();
		a = z.S;
		pq.pop();
		if(vis[a])
			continue;
		ans.pb(val[a]);
		vis[a] = 1;
		for(auto x : v[a])
		{
			if(!vis[x])
				for(auto y : v[x])
				{
					deg[y]--;
					pq.push({-deg[y],y});
				}
			vis[x] = 1;
		}
	}
	assert(sz(ans) >= n*n);
	fo(i,0,n*n)
		cout << ans[i].F << " " << ans[i].S << '\n';
	return;
}

