int sqr(int x) {
	return x * x;
}

int dist(int x1, int y1, int x2, int y2) {
	return sqr(x1 - x2) + sqr(y1 - y2);
}

bool check(int x0, int y, int c) {
	if (c < 0) return true;
	int need = s[c];
	int x1 = need + x0;
	int x2 = x0 - need;
	if (x1 < n2) {
		if (have[x1][y]) return false;
	}			
	if (x2 < n2 && x2 >= 0) {
		if (have[x2][y]) return false;
	}
	return true;
}

bool canadd(int x, int y) {

	fi(0, y) {
		int c1 = d1 - sqr(y - i);
		if (!check(x, i, c1)) return false;

		int c2 = d2 - sqr(y - i);
		if (!check(x, i, c2)) return false;				
	}	
	return true;
}

void rec(int x, int y) {
	if (cnt == nn) {
		kill();
	}		
	if (y == n2) return;
	if (x == n2) {		
		rec(0, y + 1);
		return;
	}
	if (canadd(x, y)) {
		have[x][y] = 1;
		cnt++;
		rec(x + 1, y);	
		cnt--;
		have[x][y] = 0;		
	}
	rec(x + 1, y);
}

void solve() {
	nn = n * n;
	n2 = n * 2;
	rec(0, 0);	
}

