bool checkCell(int x, int y) {
	return min(x, y) >= 0 && max(x, y) < n;
}

void build(int d) {
	vector<pii> mv;
	int y = 0;
	while(y * y <= d) y++;
	for (int x = 0; x * x <= d; x++) {
		while(x * x + y * y > d) y--;
		if (x * x + y * y != d) continue;
		mv.push_back(mp(x, y));
		if (y != 0) mv.push_back(mp(x, -y));
		if (x != 0) mv.push_back(mp(-x, y));
		if (x != 0 && y != 0) mv.push_back(mp(-x, -y));
	}
	for (int i = 0; i < n * n; i++)
		g[i].clear();
	for (int x = 0; x < n; x++)
		for (int y = 0; y < n; y++) {
			int v = x * n + y;
			for (pii t : mv) {
				int xx = x + t.first, yy = y + t.second;
				if (!checkCell(xx, yy)) continue;
				g[v].push_back(xx * n + yy);
			}
		}
}

bool dfs(int v) {
//	cerr << "dfs " << v << endl;
	for (int u : g[v]) {
		if (col[u] == -2) continue;
		if (col[u] == -1) {
			col[u] = col[v] ^ 1;
			if (!dfs(u)) return false;
		}
		if (col[v] == col[u]) return false;
	}
	return true;
}

