    int j = round(sqrt(X - i * i));
    if (i * i + j * j == X)
    {
      F.push_back(P(i, j));
      F.push_back(P(-i, j));
      F.push_back(P(i, -j));
      F.push_back(P(-i, -j));
      F.push_back(P(j, i));
      F.push_back(P(j, -i));
      F.push_back(P(-j, i));
      F.push_back(P(-j, -i));
    }
  }
}

