int pp[500002];
int oz[] = {-1, 0, 1};
void proc(int L, int C, int d1, int d2)
{
    for(int i = 0; i <= 2; i += 2)
        if(L + d1 * oz[i] >= 0 && L + d1 * oz[i] < n+n)
            for(int p = 0; p <= 2; p += 2)
                if(C + d2 * oz[p] >= 0 && C + d2 * oz[p] < n+n)
                    bad[L + d1 * oz[i]][C + d2 * oz[p]] = 1;
    swap(d1, d2);
    for(int i = 0; i <= 2; i += 2)
        if(L + d1 * oz[i] >= 0 && L + d1 * oz[i] < n+n)
            for(int p = 0; p <= 2; p += 2)
                if(C + d2 * oz[p] >= 0 && C + d2 * oz[p] < n+n)
                    bad[L + d1 * oz[i]][C + d2 * oz[p]] = 1;
}
int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> n >> a >> b;
    pp[1] = 1;
    for(int i = 2; i <= 600; ++i)
        pp[i*i] = i;
    for(int i = 0; i < n+n; ++i)
        for(int j = 0; j < n+n; ++j)
        {
            if(bad[i][j])
                continue;
            if(counter == n * n)
                break;
            ++counter;
            pct[counter] = {i, j};
            for(int p = 0; p < 500; ++p)
            {
                int dif = a - p * p;
                if(dif == 0)
                    proc(i, j, p, 0);
                else
                    if(dif > 0 && pp[dif])
                        proc(i, j, p, pp[dif]);
                dif = b - p * p;
                if(dif == 0)
                    proc(i, j, p, 0);
                else
                    if(dif > 0 && pp[dif])
                        proc(i, j, p, pp[dif]);
            }
        }
    for(int i = 1; i <= counter; ++i)
        cout << pct[i].fi << " " << pct[i].se << '\n';
    return 0;
}

