vi bicolor(int N, int D) {
    vi root(D + 1, -1);
    for (int rt = 0; rt * rt <= D; rt++)
        root[rt * rt] = rt;

    int V = 2 * 2 * N * N;

    vvi adj(V);
    for (int i = 0; i < V; i++) {
        int x1 = i % (2 * N), y1 = i / (2 * N);
        for (int dx = 0; dx < 2 * N; dx++) {
            if (dx * dx > D) break;
            int dy = root[D - dx * dx];
            if (dy == -1) continue;

            if (x1 - dx >= 0 && y1 - dy >= 0) adj[i].push_back(x1 - dx + (2 * N) * (y1 - dy));
            if (x1 - dx >= 0 && y1 + dy < 2*N) adj[i].push_back(x1 - dx + (2 * N) * (y1 + dy));
            if (x1 + dx < 2*N && y1 - dy >= 0) adj[i].push_back(x1 + dx + (2 * N) * (y1 - dy));
            if (x1 + dx < 2*N && y1 + dy < 2*N) adj[i].push_back(x1 + dx + (2 * N) * (y1 + dy));
        }
    }

    vi res(V, -1);
    for (int rt = 0; rt < V; rt++) {
        if (res[rt] != -1) continue;
        for (queue<int> bfs({rt}); !bfs.empty(); bfs.pop()) {
            int loc = bfs.front();
            for (int nbr : adj[loc]) {
                if (res[nbr] == -1) {
                    res[nbr] = !res[loc];
                    bfs.push(nbr);
                }
                assert(res[nbr] == !res[loc]);
            }
        }
    }

    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int N, D1, D2;
    cin >> N >> D1 >> D2;

    vi c1 = bicolor(N, D1),
       c2 = bicolor(N, D2);

    for (int a = 0; a < 2; a++) {
        for (int b = 0; b < 2; b++) {
            int ct = 0;
            for (int i = 0; i < 2 * 2 * N * N; i++) {
                if (c1[i] == a && c2[i] == b)
                    ct++;
            }

            if (ct >= N * N) {
                int pr = 0;
                for (int i = 0; pr < N * N; i++) {
                    if (c1[i] == a && c2[i] == b) {
                        pr++;
                        cout << i % (2 * N) << " " << i / (2 * N) << "\n";
                    }
                }
                assert(pr == N * N);
                return 0;
            }
        }
    }

    assert(false);

    return 0;
}

