 * 可以证明网格图距离平方是 D 的点连边，形成的图一定是二分图。
 * 问题转化为给出两个 4N^2 个点的二分图，求一个大小为 N^2、在两个图中都是独立集的点。
 * 可以将点按两次染色的颜色分类（实际上是个“四分图”），取“四分图”最大的那个分量就行了。
 */

#include<bits/stdc++.h>
#define rep(i, n) for(int i = 1; i <= n; ++i)
using namespace std;
typedef long long ll;
typedef pair<int, int> pii;

const int MAXN = 91000;
vector<int> G[2][MAXN], box[4];
vector<pii> vecs[2];
int col[2][MAXN], n, D[2], *ccol;

void dfs(int v, int c, int o) {
    ccol[v] = c;
    for(auto g : G[o][v]) {
        if(ccol[g] == -1) dfs(g, c^1, o);
        else assert(ccol[g] != ccol[v]);
    }
}

int main() {
    memset(col, -1, sizeof col);
    map<int, int> sqrs;
    for(int i = 0; i < 500; ++i) sqrs[i*i] = i;

    scanf("%d%d%d", &n, &D[0], &D[1]);
    int n2 = n * 2;
    for(int o = 0; o < 2; ++o) {
        for(int i = -500; i <= 500; ++i) if(sqrs.count(D[o] - i * i)) {
            int res = sqrs[D[o] - i * i];
            vecs[o].emplace_back(i, res);
            if(res) vecs[o].emplace_back(i, -res);
        }
        for(int i = 0; i < n2; ++i)
            for(int j = 0; j < n2; ++j) {
                for(auto t : vecs[o]) {
                    int ni = i + t.first, nj = j + t.second;
                    if(min(ni, nj) >= 0 && max(ni, nj) < n2) {
                        G[o][i*n2+j].push_back(ni*n2+nj);
                        G[o][ni*n2+nj].push_back(i*n2+j);
                    }
                }
            }
        ccol = col[o];
        for(int i = 0; i < n2*n2; ++i) if(ccol[i] == -1)
            dfs(i, 0, o);
    }
    for(int i = 0; i < n2*n2; ++i) {
        int m = col[0][i] + col[1][i] * 2;
        box[m].push_back(i);
        if((int)box[m].size() == n*n) {
            for(auto g : box[m])
                printf("%d %d\n", g/n2+1, g%n2+1);
            return 0;
        }
    }
    return 0;
}

