int dx[] = {1, 1, -1, -1};
int dy[] = {-1, 1, -1, 1};

void add(pair<int, int> pr) {
    for (int i = 0; i < 4; ++i) {
        auto cur = pr;
        cur.first *= dx[i];
        cur.second *= dy[i];
        dir.push_back(cur);
    }
    swap(pr.first, pr.second);
    for (int i = 0; i < 4; ++i) {
        auto cur = pr;
        cur.first *= dx[i];
        cur.second *= dy[i];
        dir.push_back(cur);
    }   
}

bool good(int a, int n) {
    int b = sqrt(n - a * a);
    return b * b == n - a * a;
}

pair<int, int> get_dir(int a) {
    for (int i = 0; i <= a; ++i) {
        if (good(i, a)) {
            add({i, a - i});
        }
    }
}

