vector<vector<int>> make_graph(int n, int d){
  int w = ceil( sqrt(d) );
  vector<vector<int>> g(n*n*4);
  for(int i=0; i<2*n; i++) for(int j=0; j<2*n; j++){
    for(int y=i; y<min(i+w+1, 2*n); y++){
      int dy = i-y;
      int dx = d - dy*dy;
      if(dx < 0) continue;
      dx = sqrt(dx);
      if( dx*dx + dy*dy != d ) continue;
      int x = j+dx;
      if( 0<=x && x<2*n ){
        g[ i*2*n + j ].push_back( y*2*n + x );
        g[ y*2*n + x ].push_back( i*2*n + j );
      }
      // x = j-dx;
      // if( dx!=0 && 0<=x && x<=2*n ){
      //   g[ i*2*n + j ].push_back( y*2*n + x );
      // }
    }
  }

  return g;
}

pair<int,int> coloring(vector<vector<int>>& g, vector<int>& c, int pos, int color){
  c[pos] = color;
  pair<int,int> res( color==0, color==1 );
  for(int nx : g[pos]){
    if( c[nx] != -1 ) continue;
    c[pos] = color^1;
    auto tmp = coloring(g, c, nx, color^1);
    res.first += tmp.first;
    res.second += tmp.second;
  }
  return res;
}

int main(){
