void solve()
{
	typedef complex<int> P;
	READ(int, N, D1, D2);

	vector<P> ng;

	REP(i, 2 * N) REP(j, 2 * N)
	{
		if (i * i + j * j == D1 || i * i + j * j == D2)
		{
			ng.push_back(P(i, j));
			ng.push_back(P(i, -j));
			ng.push_back(P(-i, j));
			ng.push_back(P(-i, -j));
		}
	}

	vevector<int> mp(2 * N, 2 * N);
	int count = 0;
	REP(i, 2 * N)
	{
		REP(j, 2 * N)
		{
			if (!mp[i][j])
			{
				WRITE(i, j);
				if (++count == N * N)
				{
					goto end;
				}
				mp[i][j] = true;

				for(auto &&x : ng)
				{
					int xx = i + x.real();
					int yy = j + x.imag();
					if (xx>=0 && xx < 2 * N && yy >= 0 && yy < 2 * N)
					{
						mp[xx][yy] = true;
					}
				}

