bool in(int x, int y) { return 0 <= x && x < (n << 1) && 0 <= y && y < (n << 1);}
int idx(int x, int y) { return x * (n << 1) + y;}
void connect(int x, int y, int k)
{
	for(int i = 0; i < (n << 1); ++i)
		for(int j = 0; j < (n << 1); ++j)
			if(in(i + x, j + y))
			{
				int u = idx(i, j), v = idx(i + x, j + y);
				E[k][u].push_back(v);
				E[k][v].push_back(u);
			}
}
void dfs(int x, int k, int c)
{
	col[k][x] = c;
	for(auto v : E[k][x])
		if(col[k][v] == -1)
			dfs(v, k, c ^ 1);
}
void solve(int d, int k)
{
	int a = sqrt(d) + 0.5;
	for(int i = -a; i <= a; ++i)
	{
		if(i * i > d) continue;
		int j = sqrt(d - i * i) + 0.5;
		if(i * i + j * j == d)
			connect(i, j, k);
	}
	memset(col[k], -1, sizeof col[k]);
	for(int i = 0; i < m; ++i)
		if(col[k][i] == -1)
			dfs(i, k, 0);
}
