    for(int i = 0; i <= 601; i++) {
      int k = d[j] - i * i;
      if(k < 0) continue;
      int kk = sqrt(k);
      if(kk * kk != k) continue;
      ddx[j].emplace_back(i);
      ddy[j].emplace_back(kk);
    }
  }
  for(int k = 0; k < 2; k++) {
    for(int i = 0; i < 2*n; i++) for(int j = 0; j < 2*n; j++) if(f[k][i][j] == 0) {
      f[k][i][j] = 1;
      queue<pair<int, int>> q;
      q.emplace(i, j);
      while(q.size()) {
        int ii = q.front().first, jj = q.front().second;
        q.pop();
        for(int t = 0; t < ddx[k].size(); t++) {
          for(int d = 0; d < 4; d++) {
            int ni = ii + dx[d] * ddx[k][t];
            int nj = jj + dy[d] * ddy[k][t];
            if(ni < 0 || nj < 0 || ni >= 2*n || nj >= 2*n) continue;
            assert(f[k][ni][nj] != f[k][ii][jj]);
            if(f[k][ni][nj] != 0) continue;
            f[k][ni][nj] = 3 - f[k][ii][jj];
            q.emplace(ni, nj);
          }
        }
      }
    }
  }
  vector<pair<int, int>> ans;
  for(int k = 1; k <= 2; k++) for(int l = 1; l <= 2; l++) {
    ans.clear();
    for(int i = 0; i < 2*n; i++) for(int j = 0; j < 2*n; j++) {
