	if(i < 0 || i > 2 * N || j < 0 || j > 2 * N)return;
	ban[i][j] = true;
}
struct p{
	int x, y;
	bool operator < (const p &rhs)const{
		return x == rhs.x ? y < rhs.y : x < rhs.x;
	}
};
int main(){
	int D1, D2;
	scanf("%d %d %d", &N, &D1, &D2);
	for(int i = 0; i <= 2 * N; i += 1){
		int j = sqrt(D1 - i * i);
		if(j * j + i * i == D1)
			d.push_back({i, j}), d.push_back({i, -j}),
			d.push_back({-i, j}), d.push_back({-i, -j});
	}
	for(int i = 0; i <= 2 * N; i += 1){
		int j = sqrt(D2 - i * i);
		if(j * j + i * i == D2)
			d.push_back({i, j}), d.push_back({i, -j}),
			d.push_back({-i, j}), d.push_back({-i, -j});
	}
	for(int i = 0; i <= 4 * N; i += 1)
		for(int j = 0; j <= 2 * N; j += 1)
