const int dx[4] = {1, 1, -1, -1}, dy[4] = {-1, 1, -1, 1};

int n, d1, d2;

vector <pii> c[2], ans;

int col[2][maxn][maxn], sum[4], tmp = -1;

void dfs(int x, int y, int typ, int pos)
{
	if(col[pos][x][y] != -1) return ;
	col[pos][x][y] = typ;
	for(pii i : c[pos])
	{
		rep(j, 0, 3)
		{
			int tx = x + dx[j] * i.fi, ty = y + dy[j] * i.se;
			if(tx < 0 || ty < 0 || tx >= 2 * n || ty >= 2 * n) continue;
			dfs(tx, ty, !typ, pos);
		}
	}
}

int dis(pii a, pii b)
{
	return (a.fi - b.fi) * (a.fi - b.fi) + (a.se - b.se) * (a.se - b.se);
}

