#include <bits/stdc++.h>
using namespace std;
const double EPS=1e-7;

int main()
{
  int n,d1,d2;
  scanf("%d%d%d",&n,&d1,&d2);
  vector<pair<int,int> > V;
  for(int t=0;t<2;t++){
    int dt=(t==0?d1:d2);
    for(int i=0;i*i<=dt;i++){
      int d=dt-i*i,j=(int)(sqrt((double)d)+EPS);
      if(j*j!=d)continue;
      V.push_back(make_pair(i,j));
      if(i>0){
	V.push_back(make_pair(-i,j));
	if(j>0){
	  V.push_back(make_pair(-i,-j));
	}
      }
      if(j>0){
	V.push_back(make_pair(i,-j));
      }
    }
  }
  vector<pair<int,int> > ans;
  vector<vector<bool> > B(2*n,vector<bool>(2*n,0));
  for(int D=0;D<4*n&&ans.size()<n*n;D++){
    for(int j=max(0,D-2*n+1);j<=min(D,2*n-1)&&ans.size()<n*n;j++){
      int i=D-j;
      if(!B[i][j]){
	ans.push_back(make_pair(i,j));
	for(int t=0;t<V.size();t++){
	  int k=i+V[t].first,l=j+V[t].second;
	  if(0<=k&&k<2*n&&0<=l&&l<2*n){
	    B[k][l]=1;
	  }
	}
      }
    }
  }
  assert(ans.size()==n*n);
  for(int t=0;t<n*n;t++){
    printf("%d %d\n",ans[t].first,ans[t].second);
  }
  return 0;
}

