	while (!(d%4))d/=4,tmp++;
	if (d&1){
		for (int i=0;i<n*2;i++)
			for (int j=0;j<n*2;j++)
				if ((i>>tmp)+(j>>tmp)&1)s[i][j]=1;
	}else{
		for (int i=0;i<n*2;i++)
			for (int j=0;j<n*2;j++)
				if ((i>>tmp)&1)s[i][j]=1;
	}
}
int main(){
	scanf("%d%d%d",&n,&d1,&d2);
	run(d1),run(d2);
	for (int i=0;i<2*n;i++)
		for (int j=0;j<2*n;j++)
			if (ans<n*n&&!s[i][j])
				printf("%d %d\n",i,j),ans++;
	return 0;
}

