int n,D1,D2,sign1[700][700],sign2[700][700];
int dir[4][2]={{1,-1},{1,1},{-1,1},{-1,-1}},ct[4];
vector<pair<int,int> > V1,V2;
int main()
{
	cin >> n >> D1 >> D2;
	for(int j=0;j*j<=D1;j++)
	{
		int t=D1-j*j;
		int x=sqrt(t);
		while((x+1)*(x+1)<=t) x++;
		while(x*x>t) x--;
		if(x*x==t) V1.push_back(make_pair(j,x));
	}
	for(int j=0;j*j<=D2;j++)
	{
		int t=D2-j*j;
		int x=sqrt(t);
		while((x+1)*(x+1)<=t) x++;
		while(x*x>t) x--;
		if(x*x==t) V2.push_back(make_pair(j,x));
	}
	for(int i=0;i<2*n;i++) for(int j=0;j<2*n;j++)
	{
		for(int t=0;t<V1.size();t++) for(int k=0;k<4;k++)
		{
			int vx=dir[k][0]*V1[t].first+i;
			int vy=dir[k][1]*V1[t].second+j;
			if(vx<0||vy<0||vx>2*n||vy>2*n) continue;
			sign1[vx][vy]=sign1[i][j]^1;
		}
		for(int t=0;t<V2.size();t++) for(int k=0;k<4;k++)
		{
			int vx=dir[k][0]*V2[t].first+i;
			int vy=dir[k][1]*V2[t].second+j;
			if(vx<0||vy<0||vx>2*n||vy>2*n) continue;
			sign2[vx][vy]=sign2[i][j]^1;
		}
		ct[sign1[i][j]*2+sign2[i][j]]++;
	}
	for(int z=0;z<=3;z++) if(ct[z]>=n*n)
	{
		int cnt=0; for(int i=0;i<2*n&&cnt<n*n;i++) 
			for(int j=0;j<2*n&&cnt<n*n;j++)
				if(sign1[i][j]*2+sign2[i][j]==z) 
					printf("%d %d\n",i,j);
		return 0;
	}
	return 0;
}

