#include<bits/stdc++.h>
using namespace std;
const int N=2e5+10;
struct T
{
	int x,y;
	bool operator<(T b)const 
	{
		if(x!=b.x)return x<b.x;
		else return y<b.y;
	}
};
map<T,int>Q;
vector<T>G,H;
bool has[N];
void Init()
{
	for(int i=0;i*i<N;i++)has[i*i]=true;
}
const double eps=1e-9;
void f(int u)
{
	int op=sqrt(u);
	for(int i=0;i<=op;i++){
		int p=u-i*i;
		if(has[p]){
			int j=sqrt(p)+eps;
			T g={i,j},g1={j,i};
			Q[g]=Q[g1]=1;
		//	cerr<<i<<' '<<j<<'\n';
		}
	}
}
int vis[600][600];
int dir[4][2]={{1,1},{-1,1},{-1,-1},{1,-1}};
T ans[90010];
int main()
{
	//freopen("/home/zz7/CFInput","r",stdin);
	int n,a,b;scanf("%d%d%d",&n,&a,&b);
	Init();
	f(a),f(b);
	for(auto k:Q)G.push_back(k.first);//cout<<k.first.x<<' '<<k.first.y<<'\n';
	for(int i=0;i<2*n;i++)
		for(int j=0;j<2*n;j++)H.push_back({i,j});
	for(int i=0;i<2*n;i++){
		int l=4*n*n,idx=i;
		int cnt=n*n,c=0;
		memset(vis,0,sizeof(vis));
		while(cnt--){
			while(idx<l&&vis[H[idx].x][H[idx].y])idx++;
			if(idx>=l)break;
			T p=H[idx];
			ans[c++]=p;
			for(auto k:G){
				for(int j=0;j<4;j++){
					int x=p.x+dir[j][0]*k.x,y=p.y+dir[j][1]*k.y;
					if(x<0||y<0||x>=2*n||y>=2*n)continue;
					vis[x][y]=true;
				}
			}idx++;
		}if(cnt==-1)break;
	}
	for(int i=0;i<n*n;i++)cout<<ans[i].x<<' '<<ans[i].y<<'\n';
}

