	init(); 
	scanf("%d %d %d", &n, &d1, &d2);

	solve();		


#ifdef LOCAL
	err("ELAPSED TIME: %.3Lf\n", (ld) clock() / CLOCKS_PER_SEC);
#endif	

	return 0;
}

