}

void dfs(int x, int y, int value, int board[610][610], vector<pair<int, int>> &P) {
	if (board[y][x]) return;
	board[y][x] = value;
	for (auto &pr : P) {
		int nx = x + pr.first;
		int ny = y + pr.second;
		if (!inBoard(nx, ny)) continue;
		if (board[ny][nx]) continue;
		dfs(nx, ny, 3 - value, board, P);
	}
}

