int n, D[2], col[360005], fa[360005];
bool d[360005];
vector<pair<int, int>> ans[4];

int Sqrt(int x) {
	int y = sqrt(x);
	while (y * y <= x) ++y;
	while (y * y > x) --y;
	return y;
}

int find(int x) {
	if (fa[x] == x) return x;
	int ff = find(fa[x]);
	d[x] ^= d[fa[x]];
	return fa[x] = ff;
}
void merge(int x, int y) {
	int s = find(x), t = find(y);
	if (s == t) return;
	fa[s] = t, d[s] = d[x] ^ d[y] ^ 1;
}

int main() {
	scanf("%d", &n);
	for (int c = 0; c < 2; ++c) {
		scanf("%d", D + c);
		for (int i = 0; i < 4 * n * n; ++i) fa[i] = i, d[i] = 0;
		for (int i = 0; i * i <= D[c]; ++i) {
			int j = Sqrt(D[c] - i * i);
			if (i * i + j * j != D[c]) continue;
			for (int a = 0; a + i < 2 * n; ++a)
				for (int b = 0; b + j < 2 * n; ++b)
					merge(a * 2 * n + b, (a + i) * 2 * n + b + j);
		}
		for (int i = 0; i < 4 * n * n; ++i)
			find(i), col[i] |= d[i] << c;
	}
	for (int i = 0; i < 2 * n; ++i)
		for (int j = 0; j < 2 * n; ++j)
			ans[col[i * 2 * n + j]].emplace_back(i, j);
	for (int c = 0; c < 4; ++c)
		if (ans[c].size() >= n * n) {
			for (int i = 0; i < n * n; ++i)
				printf("%d %d\n", ans[c][i].first, ans[c][i].second);
			return 0;
		}
}

