    scanf("%lld%lld%lld", &n, &d1, &d2);
    solve(d1, 1);
    solve(d2, 2);

    for (i = 0; i < 2 * n; i++) {
        for (j = 0; j < 2 * n; j++) {
            wh[gr[i][j]].pb(mp(i, j));
        }
    }

    int tp = 0;
    while (wh[tp].size() < n * n) tp++;
    wh[tp].resize(n * n);
    for (auto e : wh[tp])
        printf("%d %d\n", e.first, e.second);

    return 0;
}

