#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using P = pair<int, int>;

const int MAX_V = 400000;

int V;
vector<int> G[MAX_V];
int match[MAX_V];
bool used[MAX_V];

void add_edge(int u, int v) {
    G[u].push_back(v);
    G[v].push_back(u);
}

bool dfs(int v) {
    used[v] = true;
    for (int i = 0; i < G[v].size(); i++) {
        int u = G[v][i], w = match[u];
        if (w < 0 || !used[w] && dfs(w)) {
            match[v] = u;
            match[u] = v;
            return true;
        }
    }
    return false;
}

int bipartite_matching() {
    int res = 0;
    memset(match, -1, sizeof(match));
    for (int v = 0; v < V; v++) {
        if (match[v] < 0) {
            memset(used, 0, sizeof(used));
            if (dfs(v)) res++;
        }
    }
    return res;
}

bool is_square(int x2, int& x) {
    int ok = 0, ng = 10000;
    while (ng - ok > 1) {
        int mid = (ok + ng) / 2;
        if (mid * mid <= x2) ok = mid;
        else ng = mid;
    }
    x = ok;
    return x * x == x2;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, d1, d2;
    cin >> n >> d1 >> d2;
    vector<P> v;
    for (int i = 0; i * i <= d1; i++) {
        int j = 0;
        if (is_square(d1 - i * i, j)) {
            v.emplace_back(i, j);
            v.emplace_back(i, -j);
            v.emplace_back(-i, j);
            v.emplace_back(-i, -j);
        }
    }

    for (int i = 0; i * i <= d2; i++) {
        int j = 0;
        if (is_square(d2 - i * i, j)) {
            v.emplace_back(i, j);
            v.emplace_back(i, -j);
            v.emplace_back(-i, j);
            v.emplace_back(-i, -j);
        }
    }

    V = 4 * n * n;
    for (int i = 0; i < 2 * n; i++) {
        for (int j = 0; j < 2 * n; j++) {
            for (P& p : v) {
                int h = i + p.first, w = j + p.second;
                if (h < 0 || h >= 2 * n || w < 0 || w >= 2 * n) continue;
                add_edge(i * 2 * n + j, h * 2 * n + w);
            }
        }
    }

    bipartite_matching();

    int cnt = 0;
    vector<int> used(4 * n * n, false);
    for (int i = 0; i < 4 * n * n; i++) {
        if (used[i]) continue;
        cout << i / (2 * n) << " " << i % (2 * n) << endl;
        cnt++;
        used[i] = true;
        if (cnt == n * n) break;
        if (match[i] >= 0) {
            used[match[i]] = true;
        }
    }
    return 0;
}

