		M=0;
		memset(h,0,sizeof(h));
		memset(v,0,sizeof(v));
		memset(col,0,sizeof(col));
	}
	void ins(int a,int b){
		M++;
		if(M>=27000010)while(1);
		to[M]=b;
		nex[M]=h[a];
		h[a]=M;
	}
	void add(int a,int b){
		ins(a,b);
		ins(b,a);
