}

int N, D1, D2;

std::vector<std::pair<int, int>> prohibit;

auto comp = [](const std::pair<int, int>& p1, const std::pair<int, int>& p2) { 
    if (p1.first != p2.first) {
        return p1.first < p2.first;
    }
    return p1.second < p2.second;
};

std::set<std::pair<int, int>, std::function<bool (const std::pair<int, int>&, const std::pair<int, int>&)>> pp(comp);

