  for (int x = 0; x < 2*n; x++) {
    for (int y = 0; y < 2*n; y++) {
      col[x][y] = color(x, y, d1) | (color(x, y, d2) << 1);
    }
  }

  int c[4] = {};
  for (int x = 0; x < 2*n; x++)
    for (int y = 0; y < 2*n; y++)
