int main() {
	int64_t N,D1,D2;
	cin >> N >> D1 >> D2;
	struct Phash{
		size_t operator() (const pair<int64_t, int64_t>& p) const{
			hash<int64_t> h;
			return (h(p.first) & h(p.second));
		}
	};
	unordered_set< pair<int64_t, int64_t>, Phash>offsList;
	for (int64_t i = 0; i  < 2 * N ; i++)
	{
		for (int64_t j = 0; j < 2 * N; j++)
		{
			if (D1 == i * i + j * j) {
				offsList.insert(make_pair<>(i, j));
				offsList.insert(make_pair<>(i, -j));
			}
			if (D2 == i * i + j * j) {
				offsList.insert(make_pair<>(i, j));
				offsList.insert(make_pair<>(i, -j));
			}
		}
	}
	int64_t c = 0;
	vector<bool>bannedPos(4 * N * N);
	for (int64_t i = 0; i < 4 * N * N; i++)
	{
		bannedPos[i] = false;
	}
	auto banPos = [&](int64_t x, int64_t y)->void {
		if (x >= 2 * N)return;
		if (y >= 2 * N)return;
		bannedPos[x + y * 2 * N] = true;
	};
	auto isBanned = [&](int64_t x, int64_t y)->bool {
		return bannedPos[x + y * 2 * N];
	};
	for (int64_t i = 0; i < 2 * N; i++)
	{
		for (int64_t j = 0; j < 2 * N; j++)
		{
			if (isBanned(i, j)) continue;
			else {
				for (auto n : offsList) {
					banPos(i + n.first, j + n.second);
				}
				cout << i << " " << j << endl;
				++c;
				if (c == N * N)goto END;
			}
		}
	}
END:
	return 0;
}

