inline void work(int d, int op) {
    int c = 0;
    while (d % 4 == 0) d >>= 2, ++c;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if ((d & 1) == 0) a[i][j] = op * a[i][j] + ((i >> c) & 1);
            else a[i][j] = op * a[i][j] + (((i >> c) + (j >> c)) & 1);
        }
}

