    int n, d1, d2;
    cin >> n >> d1 >> d2;
    vi di, dj;
    fori (i, 2 * n) {
        fori (j, 2 * n) {
            int dst = sqr(i) + sqr(j);
            if (dst == d1) {
                di.push_back(i);
                dj.push_back(j);
            }
        }
    }

    fori (i, 2 * n) {
        fori (j, 2 * n) {
            fori (dir, SZ(di)) {
                int ii = i + di[dir], jj = j + dj[dir];
                if (ii >= 0 && ii < 2 * n && jj >= 0 && jj < 2 * n) {
                    g[1][i * n + j].push_back(ii * n + jj);
                    g[1][ii * n + jj].push_back(i * n + j);
                }
            }
        }
    }

    di.clear();
    dj.clear();

    fori (i, 2 * n) {
        fori (j, 2 * n) {
            int dst = sqr(i) + sqr(j);
            if (dst == d2) {
                di.push_back(i);
                dj.push_back(j);
            }
        }
    }

    fori (i, 2 * n) {
        fori (j, 2 * n) {
            fori (dir, SZ(di)) {
                int ii = i + di[dir], jj = j + dj[dir];
                if (ii >= 0 && ii < 2 * n && jj >= 0 && jj < 2 * n) {
                    g[2][i * n + j].push_back(ii * n + jj);
                    g[2][ii * n + jj].push_back(i * n + j);
                }
            }
        }
    }


    fori (i, 4 * n * n) {
        if (used[i])
            continue;
        dfs(i, 0, 1);
    }

    vi a, b;
    fori (i, 4 * n * n) {
        if (col[i])
            a.push_back(i);
        else
            b.push_back(i);
    }

    if (SZ(a) < SZ(b))
        swap(a, b);

