bool Exist(int r, int c)
{
	return 0 <= r && r < 2 * n && 0 <= c && c < 2 * n && tk[r][c];
}

bool Check(int r, int c)
{
	for (int i = 0; i * i <= d1 || i * i <= d2; i++) {
		if (i * i <= d1) {
			int j = sqr[d1 - i * i];
			if (j != -1 && (Exist(r - i, c - j) || Exist(r - i, c + j) || Exist(r + i, c - j) || Exist(r + i, c + j)))
				return false;
		}
		if (i * i <= d2) {
			int j = sqr[d2 - i * i];
			if (j != -1 && (Exist(r - i, c - j) || Exist(r - i, c + j) || Exist(r + i, c - j) || Exist(r + i, c + j)))
				return false;
		}
	}
	return true;
}

void Gen(int r, int c)
