int sqr(int);
void bfs(int ,int ,int ,int [N][N]);
void solve(int ,int [N][N]);

int main(){
	scanf("%d%d%d", &n, &d1, &d2);
	solve(d1, vis1); solve(d2, vis2);
	for(int i = 0; i < 2 * n && cnt < n * n; ++i)
		for(int j = 0; j < 2 * n && cnt < n * n; ++j)
			if(vis1[i][j] && vis2[i][j])
				printf("%d %d\n", i, j), ++cnt;
	return 0;
}

int sqr(int x){
	return x * x;
}

void solve(int d, int vis[N][N]){
	memset(vis, -1, (N * N) << 2);
	sz[0] = sz[1] = 0;
	for(int i = 0; i < 2 * n; ++i)
		for(int j = 0; j < 2 * n; ++j)
			if(vis[i][j] == -1) bfs(i, j, d, vis);
	int p = 0;
	if(sz[0] < sz[1]) p = 1;
	for(int i = 0; i < 2 * n; ++i)
		for(int j = 0; j < 2 * n; ++j)
			if(vis[i][j] == p) vis[i][j] = 1;
			else vis[i][j] = 0;
	return ;
}

void bfs(int X, int Y, int d, int vis[N][N]){
	queue<pi> Q; Q.push(mkp(X, Y)); vis[X][Y] = 0;
	while(!Q.empty()){
		pi tmp = Q.front(); Q.pop();
		int x = tmp.fi, y = tmp.se;
		++sz[vis[x][y]];
		for(int i = 0; i < 2 * n; ++i){
			int dy = d - sqr(i - x);
			if(dy < 0) continue;
			int sy = sqrt(dy);
			if(sqr(sy) != dy) continue;
			if(y - sy >= 0 && vis[i][y - sy] == -1)
				vis[i][y - sy] = vis[x][y] ^ 1, Q.push(mkp(i, y - sy));
			if(y + sy < 2 * n && vis[i][y + sy] == -1)
				vis[i][y + sy] = vis[x][y] ^ 1, Q.push(mkp(i, y + sy));
		}
	}
	return ;
}

