void coloring(int y, int x, int c, int depth, vector<vector<LL>>& color, vector<pair<LL,LL>>& ng, LL n2, vector<vector<LL>>& memo){
    if(y < 0 || n2 <= y) return;
    if(x < 0 || n2 <= x) return;
    if(memo[y][x]) return;
    memo[y][x] = 1;
    if(depth & 1){
        color[y][x] |= c;
    }
    for(auto p: ng){
        coloring(y + p.first, x + p.second, c, depth+1, color, ng, n2, memo);
        coloring(y + p.second, x + p.first, c, depth+1, color, ng, n2, memo);
        coloring(y - p.first, x + p.second, c, depth+1, color, ng, n2, memo);
        coloring(y - p.second, x + p.first, c, depth+1, color, ng, n2, memo);
        coloring(y + p.first, x - p.second, c, depth+1, color, ng, n2, memo);
        coloring(y + p.second, x - p.first, c, depth+1, color, ng, n2, memo);
        coloring(y - p.first, x - p.second, c, depth+1, color, ng, n2, memo);
        coloring(y - p.second, x - p.first, c, depth+1, color, ng, n2, memo);
    }
}

