vector<ll> solve(ll n, ll d) {
    vector<vector<ll>> g(4*n*n);
    REP(i, n*2) REP(j, n*2) {
        // (i,j)から距離がsqrt(D1)のマス
        ll x = n*2-1;
        FOR(y, i, n*2) {
            while(x > j && (y-i)*(y-i)+(x-j)*(x-j) > d) x--;
            if((y-i)*(y-i)+(x-j)*(x-j) == d) {
                g[y*2*n+x].push_back(i*n*2+j);
                g[i*2*n+j].push_back(y*n*2+x);
            }
        }
        x = 0;
        FOR(y, i+1, n*2) {
            while(x < j && (y-i)*(y-i)+(x-j)*(x-j) > d) x++;
            if((y-i)*(y-i)+(x-j)*(x-j) == d) {
                g[y*2*n+x].push_back(i*n*2+j);
                g[i*2*n+j].push_back(y*n*2+x);
            }
        }
    }

    // REP(i, 4*n*n) {
    //     cout << "(" << i%(n*2) << "," << i/(n*2) << "): ";
    //     for(auto j: g[i]) {
    //         cout << "(" << j%(n*2) << "," << j/(n*2) << ") ";
    //     }
    //     cout << endl;
    // }

    vector<ll> col(4*n*n);
    function<void(ll, ll)> dfs = [&](ll v, ll c) {
        col[v] = c;
        for(auto to: g[v]) {
            assert(col[to] != c);
            if(col[to] == 0) {
                dfs(to, -c);
            }
        }
    };

    REP(i, 4*n*n) {
        if(col[i] == 0) dfs(i, 1);
    }
    return col;
}

