void solve(int N, int D1, int D2) {
    int W = N*2;
    set<ii> avoid;
    rep(x,W+1) {
        int xx = x*x;
        rep(y,W+1){
            int yy = y*y;
            if (xx + yy == D1) avoid.insert(ii(x,y));
            if (xx + yy == D2) avoid.insert(ii(x,y));
        }
    }
    vector<ii> avoid_(ALL(avoid));
    vvi a(W, vi(W, 1));
    rep(r,W) rep(c,W) {
        if (a[r][c] == 0) continue;
        for (ii& p: avoid_) {
            int dr=p.first, dc=p.second;
            if (IN(r+dr,0,W-1) && IN(c+dc,0,W-1))
                a[r+dr][c+dc] = 0;
            if (IN(r+dr,0,W-1) && IN(c-dc,0,W-1))
                a[r+dr][c-dc] = 0;
            if (IN(r-dr,0,W-1) && IN(c+dc,0,W-1))
                a[r-dr][c+dc] = 0;
            if (IN(r-dr,0,W-1) && IN(c-dc,0,W-1))
                a[r-dr][c-dc] = 0;
