bool chk(pii p){
	for (int cas=0;cas<2;++cas){
		int w=sqrt(d1+0.5);
		for (int i=0;i<=p.fi&&i*i<=d1;++i){
			for (;w*w+i*i>d1;) --w;
			if (w*w+i*i==d1){
				if (used(p.fi-i,p.se-w)) return 0;
				if (used(p.fi-i,p.se+w)) return 0;
			}
		}
		swap(d1,d2);
	}
	return 1;
}

