void dfs(int i, int j, int c, int col) {
    marked[i][j] = flag;
    color[i][j][c] = col;
    for (auto& p : edge)
        REPU(t, 4) {
            int ii = i + dx[t] * p.F;
            int jj = j + dy[t] * p.S;
            if (ii >= 0 && ii <= 2 * n && jj >= 0 && jj <= 2 * n)
                if (marked[ii][jj] != flag) dfs(ii, jj, c, 1 - col);
        }
