void f(ll d){
	DX.clear();
	DY.clear();
	ll I=d;
	for(ll i=0;i<=d;i++){
		while(I>0&&(I-1)*(I-1)+i*i>=d) I--;
		if(I*I+i*i==d*d){
			DX.push_back(i);DY.push_back(I);
			DX.push_back(i);DY.push_back(-I);
			DX.push_back(-i);DY.push_back(I);
			DX.push_back(-i);DY.push_back(-I);
		}
	}
	for(int i=0;i<N;i++) for(int j=0;j<N;j++) if(!a[i][j]){
		queue<P> q;
		q.push({i,j});
		a[i][j]=1;
		while(!q.empty()){
			P p=q.front();q.pop();
			int x=p.first,y=p.second;
			for(int k=0;k<(int)DX.size();k++){
				int X=x+DX[k],Y=y+DY[k];
				if(X>=0&&X<N&&Y>=0&&Y<N&&!a[X][Y]){
					a[X][Y]=-a[x][y];
					q.push({X,Y});
				}
			}
		}
	}
	int t=0;
	for(auto i:a) for(auto j:i) if(abs(j)==1) t+=j;
	for(int i=0;i<N;i++) for(int j=0;j<N;j++) if(abs(a[i][j])==1){
		if(t>=0^a[i][j]<0) a[i][j]=0;
		else a[i][j]=2;
	}
}

