void solve(int d,int f){
	memset(vis,0,sizeof(vis));
	for(int i=0;i<n*n;i++)e[i].clear();
	for(int i=0;i*i<=d;i++){
		int j=sqrt(d-i*i);
		if(i*i+j*j==d){
			for(int x=0;x<n;x++)for(int y=0;y<n;y++){
				int X=x+i,Y=y+j;
				if(0<=X&&X<n&&0<=Y&&Y<n)add(hx(x,y),hx(X,Y));
				Y=y-j;
				if(0<=X&&X<n&&0<=Y&&Y<n)add(hx(x,y),hx(X,Y));
			}
		}
	}
	for(int i=0;i<n*n;i++)if(!vis[i])dfs(i,f,0);
}
