#define show(x) cerr << #x << " = " << x << endl
using namespace std;
using ll = long long;
template <typename Functor>
struct fix_type
{
    Functor functor;
    template <typename... Args>
    decltype(auto) operator()(Args&&... args) const& { return functor(functor, std::forward<Args>(args)...); }
};
template <typename Functor>
fix_type<typename std::decay<Functor>::type> fix(Functor&& functor) { return {std::forward<Functor>(functor)}; }
template <typename T>
constexpr T INF = numeric_limits<T>::max() / 16;
class Flow
{
public:
    using T = ll;
    struct Edge
    {
        int from, to, revind;
        T capacity, flow;
        bool reversed;
    };
    Flow(const int v) : V{v}, edge(v) {}
    void addEdge(const int from, const int to, const T capacity)
    {
        edge[from].push_back(Edge{from, to, (int)edge[to].size(), capacity, 0, false});
        edge[to].push_back(Edge{to, from, (int)edge[from].size() - 1, capacity, capacity, true});
    }
    T FordFulkerson(const int s, const int t)
    {
        vector<bool> checked(V);
        auto dfs = fix([&](auto&& self, const int pos, const T& flow) -> T {
            if (pos == t) { return flow; }
            checked[pos] = true;
            for (auto& e : edge[pos]) {
                if (not checked[e.to]) {
                    const T res = e.capacity - e.flow;
                    if (res > 0) {
                        const T d = self(self, e.to, min(flow, res));
                        if (d > 0) {
                            e.flow += min(d, res), edge[e.to][e.revind].flow -= min(d, res);
                            return d;
                        }
                    }
                }
            }
            return 0;
        });
        T flow = 0;
        while (true) {
            for (int i = 0; i < V; i++) { checked[i] = false; }
            const T f = dfs(s, INF<T>);
            if (f == 0) { break; }
            flow += f;
        }
        return flow;
    }
    const int V;
    vector<vector<Edge>> edge;
};

int main()
{
    int N, D1, D2;
    cin >> N >> D1 >> D2;
    vector<int> sq(4 * N * N + 1, -1);
    for (int i = 0; i <= 2 * N; i++) { sq[i * i] = i; }
    using P = pair<int, int>;
    vector<P> d;
    for (int i = 0; i <= 2 * N; i++) {
        if (i * i <= D1 and sq[D1 - i * i] >= 0) { d.push_back({i, sq[D1 - i * i]}); }
        if (i * i <= D2 and sq[D2 - i * i] >= 0) { d.push_back({i, sq[D2 - i * i]}); }
    }
    Flow flow(4 * N * N + 2);
    const int S = 4 * N * N, T = 4 * N * N + 1;
    for (int i = 0; i < 2 * N; i++) {
        for (int j = 0; j < 2 * N; j++) {
            if ((i + j) % 2 == 0) {
                flow.addEdge(S, i + j * 2 * N, 1);
            } else {
                flow.addEdge(i + j * 2 * N, T, 1);
            }
            for (const auto& p : d) {
                const int dx = p.first, dy = p.second;
                if (i + dx < 2 * N and j + dy < 2 * N) {
                    if ((i + j) % 2 == 0) {
                        flow.addEdge(i + j * 2 * N, (i + dx) + (j + dy) * 2 * N, 1);
                    } else {
                        flow.addEdge((i + dx) + (j + dy) * 2 * N, i + j * 2 * N, 1);
                    }
                }
            }
        }
    }
    flow.FordFulkerson(S, T);
    vector<int> ans;
    for (const auto& e : flow.edge[S]) {
        if (not e.reversed and e.flow == 1) { ans.push_back(e.to); }
    }
    for (int i = 0; i < N * N; i++) { cout << ans[i] % (2 * N) << " " << ans[i] / (2 * N) << endl; }
    return 0;
}

