void work(int mpi,int n,int d)
{
	std::vector<std::pair<int,int> > all;
	for(int i = 0;i * i <= d;++i) {
		int j = d-i*i, k = sqrt(j);
		if(k*k==j) all.emplace_back(i,j);
	}
	for(int i = 0;i < n;++i) {
		for(int j = 0;j < n;++j) {
			if(mp[mpi][i][j]==0) mp[mpi][i][j]=1;
			for(int k = 0;k < all.size();++k) {
				int a = all[k].first, b = all[k].second;
				if(i-a>=0 && j-b>=0) mp[mpi][i-a][j-b] = 3-mp[mpi][i][j];
