int arr[305][305], app[5]; 
void work(int n, int d, int mask)
{
	int cnt = 0; 
	while (!(d & 3))
	{
		d >>= 1; 
		cnt++; 
	}
	if (d & 1)
	{
		for (int i = 0; i < n; i++)
		{
			for (int j = 0; j < n; j++)
			{
				if ((i >> cnt) ^ (j >> cnt))
					arr[i][j] |= mask;
			}
		}
	}
	else
	{
		for (int i = 0; i < n; i++)
		{
			for (int j = 0; j < n; j++)
			{
				if ((i >> cnt) & 1)
					arr[i][j] |= mask; 
			}
		}
	}
}
