vector<pair<int,int> > con;
bool ok[611][611];
void un(int x,int y)
{
	x=gf(x);y=gf(y);
	f[x]=y;
}
void solve(int a)
{	
	for(int i=0;i<B*2;i++)f[i]=i;
	con.clear();
	for(int i=0;i*i<=a;i++)
	{
		if(sqrid[a-i*i]!=-1)
		{
			con.PB(MP(i,sqrid[a-i*i]));
			con.PB(MP(i,-sqrid[a-i*i]));
		}
	}
	for(int i=0;i<N;i++)
	{
		for(int j=0;j<N;j++)
		{
			for(int t=0;t<con.size();t++)
			{
				int ni=i+con[t].FF,nj=j+con[t].SS;
				if(ni<N&&nj<N&&nj>=0)
				{
			//		cerr<<i<<","<<j<<" "<<ni<<","<<nj<<endl;
					un(getid(i,j),B+getid(ni,nj));
					un(B+getid(i,j),getid(ni,nj));
					assert(gf(getid(i,j))!=gf(getid(i,j)+B));
				}
			}
		}
	}
	int cur=-1;
	for(int i=0;i<N;i++)
	{
		for(int j=0;j<N;j++)
		{
			if(ok[i][j])
			{
				if(cur==-1)
				{
					cur=getid(i,j);
				}
				if(gf(getid(i,j)+B)==gf(cur))ok[i][j]=0;
				else un(getid(i,j),cur);
			}
		}
	}
}
