		if (a * a + b * b == D[id]) {
			Dir.push_back(make_pair(a, b));
			Dir.push_back(make_pair(-a, -b));
			Dir.push_back(make_pair(a, -b));
			Dir.push_back(make_pair(-a, b));
		}
	}
