void go(int n,int d){
	REP(i,n*n) child[i].clear();
	for(int i=0;i*i+i*i<=d;i++){
		int dx=i,dy=sq[d-i*i];
		if(dy==-1) continue;
		//cout<<dx<<' '<<dy<<endl;	
		REP(x,n) REP(y,n){
			if(0<=x+dx&&x+dx<n&&0<=y+dy&&y+dy<n){
				child[x*n+y].pb((x+dx)*n+y+dy);
				child[(x+dx)*n+y+dy].pb(x*n+y);
			}
			if(0<=x+dy&&x+dy<n&&0<=y+dx&&y+dx<n){
				child[x*n+y].pb((x+dy)*n+y+dx);
				child[(x+dy)*n+y+dx].pb(x*n+y);
			}
			if(0<=x-dx&&x-dx<n&&0<=y+dy&&y+dy<n){
				child[x*n+y].pb((x-dx)*n+y+dy);
				child[(x-dx)*n+y+dy].pb(x*n+y);
			}
			if(0<=x-dy&&x-dy<n&&0<=y+dx&&y+dx<n){
				child[x*n+y].pb((x-dy)*n+y+dx);
				child[(x-dy)*n+y+dx].pb(x*n+y);
			}
		}
	}
	//cout<<"OAO"<<endl;
	vis=0;
	REP(i,n*n) if(!vis[i]) dfs(i,0);
	//cout<<"OAO"<<endl;
}

