const int maxn = 302;

vector<int> E1[4*maxn*maxn];
vector<int> E2[4*maxn*maxn];
bool vis[4*maxn*maxn];
int color[4*maxn*maxn][2];
int sqr[220001];

int encode(int x, int y, int N) {
  return x * N + y;
}

vector<int> dx[2];
vector<int> dy[2];
int mx[4] = {1, -1, 1, -1};
int my[4] = {1, -1, -1, 1};
bool valid(int x, int y, int N) {
  return 0 <= x && x < 2 * N && 0 <= y && y < 2 * N;
}
void build_graph(int e12, int D, int N, vector<int> E[4*maxn*maxn]) {
  for(int x = 0; x < 2 * N; x ++) {
    for(int y = 0; y < 2 * N; y++){
      for(int j = 0; j < dx[e12].size(); j++) {
        for(int k = 0;k < 4; k++) {
          int nx = x + mx[k] * dx[e12][j];
          int ny = y + my[k] * dy[e12][j];
          if(valid(nx, ny, N)) {
            int u = encode(x, y, 2 * N);
            int v = encode(nx, ny, 2 * N);
            E[u].pb(v);
            E[v].pb(u);
          }
        }
      }
    }
  }
}

void dfs(int n, int e12, int c, vector<int> E[4*maxn*maxn]) {
  vis[n] = 1;
  color[n][e12] = c == 1 ? 2 : 1;
  for(auto to : E[n]) {
    if(vis[to]) continue;
    dfs(to, e12, c ^ 1, E);
  }
}

void prep(int i, int D, int N) {
for(int xx = 0; xx < 2 * N; xx ++){
    for(int yy = 0; yy < 2 * N; yy ++) {
      if(xx * xx + yy * yy == D) {
        dx[i].pb(xx);
        dy[i].pb(yy);
      }
    }
  }
}

