struct dpro{
  ll r;
  ll l;
  ll a;
  ll b;
};

ll dmax = -1;

dpro analyze(ll d){
  dpro dp;
  dp.r = -1;
  dp.a = -1;
  dp.b = -1;
  dp.l = -1;
  ll t = sqrt(d);
  if(t*t==d){
    if(dmax < t){
      dmax = t;
    }
    dp.r = t;
    dp.l = 0;
    //cerr<<"found"<<t<<",0"<<endl;
  }


  for(ll i = 1; i <sqrt(d); ++i){
    ll t2 = sqrt(d-i*i);
    if(t2 * t2 == d-i*i){
      dp.a = t2;
      dp.b = i;
      if(dmax < t2){
	dmax = t2;
      }
      if(dmax < i){
	dmax = i;
      }
      //cerr<<"found"<<dp.a<<","<<dp.b<<endl;
    }
  }
  return dp;
}

bool check(dpro dp, ll dx, ll dy){
  if( (dp.l == dx && dp.r == dy) || (dp.a == dx && dp.b == dy) || (dp.l == dy && dp.r == dx) || (dp.a == dy && dp.b == dx) ){
    return false;
  }
  return true;
}

int main(){
  ll n,d1,d2;
  cin >> n >> d1 >>d2;
  ll okcnt = 0;
  ll cnt = 0;
  dpro dp1 = analyze(d1);
  dpro dp2 = analyze(d2);
  bool used[n*n*4];
  for(int i=0;i<n*n*4;++i){
    used[i]=false;
  }

