    for(int j=0;j<n*2;++j){
      bool ok = true;
      ll stk = j-dmax;
      ll stl = i-dmax;
      ll st = cnt- dmax-dmax*2*n;
      if (st<0) st = 0;
      for(int k=st; k<cnt;++k){
	if(used[k]){
	  ll dx = abs(i-(k/n/2));
	  ll dy = abs(j-(k%(n*2)));
	  bool ch = check(dp1, dx, dy) && check(dp2, dx, dy);
	  if(!ch){
	    ok = false;
	    break;
	  }
	}
      }
      if(ok){
	used[cnt]=true;
	//cerr<<"o";
