template <class T>
void read (T &x) {
	int sgn = 1;
	char ch;
	x = 0;
	for (ch = getchar(); (ch < '0' || ch > '9') && ch != '-'; ch = getchar()) ;
	if (ch == '-') ch = getchar(), sgn = -1;
	for (; '0' <= ch && ch <= '9'; ch = getchar()) x = x * 10 + ch - '0';
	x *= sgn;
}
template <class T>

void write (T x) {
	if (x < 0) putchar('-'), write(-x);
	else if (x < 10) putchar(x + '0');
	else write(x / 10), putchar(x % 10 + '0');
}

int n, d1, d2, t1 = 0, t2 = 0, col1[N << 1][N << 1], col2[N << 1][N << 1];

int main () {
	read(n), read(d1), read(d2);

	while (d1 & 1 ^ 1) t1++, d1 >>= 1;
	while (d2 & 1 ^ 1) t2++, d2 >>= 1;
	for (int i = 0; i < (n << 1); i++) {
		for (int j = 0; j < (n << 1); j++) {
			if (t1 & 1) col1[i][j] = (i % (1 << (t1 + 1 >> 1)) < (1 << (t1 >> 1)));
			else col1[i][j] = ((i + j) % (1 << (t1 + 2 >> 1)) < (1 << (t1 >> 1)));
			if (t2 & 1) col2[i][j] = (i % (1 << (t2 + 1 >> 1)) < (1 << (t2 >> 1)));
			else col2[i][j] = ((i + j) % (1 << (t2 + 2 >> 1)) < (1 << (t2 >> 1)));

		}
	}

	int mx = 0, posi = -1, posj = -1;
	for (int i = 0; i <= 1; i++) {
		for (int j = 0; j <= 1; j++) {
			int cnt = 0;
			for (int x = 0; x < (n << 1); x++) {
				for (int y = 0; y < (n << 1); y++) {
					if (col1[x][y] == i && col2[x][y] == j) cnt++;
				}
			}

			if (mx < cnt) mx = cnt, posi = i, posj = j;
		}
	}

	vector<pair<int, int> > s;
	for (int i = 0; i < (n << 1); i++) {
		for (int j = 0; j < (n << 1); j++) {
			if (col1[i][j] == posi && col2[i][j] == posj) s.push_back(make_pair(i, j));
		}
	}

