#include <bits/stdc++.h>

using namespace std;

struct UnionFind {
  vector< int > data;

  UnionFind(int sz) {
    data.assign(sz, -1);
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k) {
    return (-data[find(k)]);
  }
};

struct Bipartite_Graph : UnionFind {
  vector< int > color;

  Bipartite_Graph(int v) : color(v + v, -1), UnionFind(v + v) {}

  bool bipartite_graph_coloring() {
    for(int i = 0; i < color.size() / 2; i++) {
      int a = find(i);
      int b = find(i + (int) color.size() / 2);
      if(a == b) return (false);
      if(color[a] < 0) color[a] = 0, color[b] = 1;
    }
    return (true);
  }

  void unite_diff(int x, int y) {
    unite(x, y + color.size() / 2);
    unite(y, x + color.size() / 2);
  }

  bool operator[](int k) {
    return (bool(color[find(k)]));
  }
};

int main() {
  int N, D1, D2;
  cin >> N >> D1 >> D2;
  vector< pair< int, int > > xs, ys;
  for(int i = -2 * N; i <= 2 * N; i++) {
    for(int j = -2 * N; j <= 2 * N; j++) {
      int sum = i * i + j * j;
      if(sum == D1) xs.emplace_back(i, j);
      if(sum == D2) ys.emplace_back(i, j);
    }
  }
  auto isin = [&](int x, int y) {
    return 0 <= x && x < 2 * N && 0 <= y && y < 2 * N;
  };
  Bipartite_Graph latte(4 * N * N), malta(4 * N * N);
  for(int i = 0; i < 2 * N; i++) {
    for(int j = 0; j < 2 * N; j++) {
      for(auto &x : xs) {
        if(isin(i + x.first, j + x.second)) {
          latte.unite_diff(i * (2 * N) + j, (i + x.first) * (2 * N) + (j + x.second));
        }
      }
      for(auto &y : ys) {
        if(isin(i + y.first, j + y.second)) {
          malta.unite_diff(i * (2 * N) + j, (i + y.first) * (2 * N) + (j + y.second));
        }
      }
    }
  }
  assert(latte.bipartite_graph_coloring());
  assert(malta.bipartite_graph_coloring());
  for(int i = 0; i < 2; i++) {
    for(int j = 0; j < 2; j++) {
      vector< int > lis;
      for(int k = 0; k < 4 * N * N; k++) {
        if(latte[k] == i && malta[k] == j) lis.emplace_back(k);
      }
      if(lis.size() >= N * N) {
        lis.resize(N * N);
        for(auto &p : lis) {
          cout << p / (2 * N) << " " << p % (2 * N) << endl;
        }
        return 0;
      }
    }
  }
}

