int cnt;
void precalcMatrix()
{
    for(int i = 0; i< N * 2; i++)
        for(int j = 0; j < N * 2; j++)
        {
            if(i * i + j * j == D1 || i * i + j * j == D2)
            {
                Matrix[i][j] = 1;
                V.push_back(make_pair(i, j));
            }

        }
}

void Solve()
{
    cnt = 0;
    for(int dist = 0; dist < N * 4; dist++)
        for(int i = 0; i <= min(dist, N * 2); i++)
        {
            int j = dist - i;
            if(j >= N * 2)
                continue;
            bool ok = 1;
            for(int k = 0; k < V.size(); k++)
            {
                int newi = i - V[k].first, newj = j - V[k].second;
                if(newi >= 0 && newj >= 0 && newi < 2 * N && newj < 2 * N && Choosed[newi][newj] == 1)
                {
                    ok = 0;break;
                }
                newj = j + V[k].second;
                if(newi >= 0 && newj >= 0 && newi < 2 * N && newj < 2 * N && Choosed[newi][newj] == 1)
                {
                    ok = 0;
                    break;
                }
                newj = j - V[k].second;
                newi = i + V[k].first;
                if(newi >= 0 && newj >= 0 && newi < 2 * N && newj < 2 * N && Choosed[newi][newj] == 1)
                {
                    ok = 0;
                    break;
                }
                newj = j + V[k].second;
                if(newi >= 0 && newj >= 0 && newi < 2 * N && newj < 2 * N && Choosed[newi][newj] == 1)
                {
                    ok = 0;
                    break;
                }
            }
            if(ok == 1)
            {
                Choosed[i][j] = 1;
                ++cnt;
                if(cnt <= N * N)
                    cout << i << " " << j << "\n";
            }

        }
}
int main()
{
    cin >> N >> D1 >> D2;
    precalcMatrix();
    Solve();
    //cout << cnt << "\n";
    return 0;
}

