vector<pair<int, int>> get_points(int d) {
  vector<pair<int, int>> points;
  for (int a = 0; a <= min(d, 1000); ++a) {
    int t = d - a * a;
    int b = sqrt(t);
    if (a * a + b * b == d) {
      points.push_back({a, b});
    }
  }

  return points;
}

int main() { IO;
  int n, d1, d2;
  cin >> n >> d1 >> d2;

  vector<pair<int, int>> points1 = get_points(d1);
  vector<pair<int, int>> points2 = get_points(d2);

  vector<pair<int, int>> points = points1;
  points.insert(points.end(), points2.begin(), points2.end());
  sort(points.begin(), points.end());
  points.erase(unique(points.begin(), points.end()), points.end());

  //cout << "points:"; for (const auto &p : points) cout << " " << p.first << "," << p.second; cout << endl;

  int grid[2 * n + 1][2 * n + 1];
  memset(grid, 0, sizeof grid);

  vector<pair<int, int>> ans;

  for (int i = 0; i < 2 * n and ans.size() < n * n; ++i) {
    for (int j = 0; j < 2 * n and ans.size() < n * n; ++j) {
      if (grid[i][j] == 0) {
        ans.push_back({i, j});
        for (const auto &p : points) {
          int ii = i + p.first;
          int jj = j + p.second;
          if (ii <= 2 * n and jj <= 2 * n) {
            grid[ii][jj] = 1;
          }
        }
      }
    }
  }

  for (const auto &p : ans) {
    cout << p.first << " " << p.second << endl;
  }

