const int MAXD = 300228;

using Lst = vector<pair<int, int>>;

int k;

int sq[MAXD];

Lst g[2];

bool wa[MAXN][MAXN];
bool wb[MAXN][MAXN];
Lst mvs;

void dfs(int x, int y, int id) {
    if (wb[x][y]) {
        return;
    }

    wb[x][y] = true;
    if (wa[x][y]) {
        g[id].emplace_back(x, y);
    }

    for (auto ed : mvs) {
        int nx = x + ed.first, ny = y + ed.second;
        if (nx >= 0 && ny >= 0 && nx < k && ny < k) {
            dfs(nx, ny, id ^ 1);
        }
    }
}

Lst sep(Lst a, int d) {
    mvs.clear();
    for (int i = 0; i * i <= d; ++i) {
        int j = sq[d - i * i];
        if (j != -1) {
            mvs.emplace_back(i, j);
            mvs.emplace_back(i, -j);
            mvs.emplace_back(-i, j);
            mvs.emplace_back(-i, -j);
        }
    }


    memset(wa, 0, sizeof(wa));
    memset(wb, 0, sizeof(wb));
    g[0].clear();
    g[1].clear();

    for (auto& val : a) {
        wa[val.first][val.second] = true;
    }


    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < k; ++j) {
            dfs(i, j, 0);
        }
    }

    return g[g[0].size() < g[1].size()];
}

