void proc(ll x,ll y,data d)
{
    ll r,c;
    r = x + d.x;
    c = y + d.y;
    if(r>=0 && r<2*n && c>=0 && c<2*n) visi[r][c]=1;
    c = y - d.y;
    if(r>=0 && r<2*n && c>=0 && c<2*n) visi[r][c]=1;

    r = x + d.y;
    c = y + d.x;
    if(r>=0 && r<2*n && c>=0 && c<2*n) visi[r][c]=1;
    c = y - d.x;
    if(r>=0 && r<2*n && c>=0 && c<2*n) visi[r][c]=1;

    r = x - d.x;
    c = y + d.y;
    if(r>=0 && r<2*n && c>=0 && c<2*n) visi[r][c]=1;
    c = y - d.y;
    if(r>=0 && r<2*n && c>=0 && c<2*n) visi[r][c]=1;

    r = x - d.y;
    c = y + d.x;
    if(r>=0 && r<2*n && c>=0 && c<2*n) visi[r][c]=1;
    c = y - d.x;
    if(r>=0 && r<2*n && c>=0 && c<2*n) visi[r][c]=1;
}

