void make_graph(int d) {
	v.clear();
	int k = sqrt(d);
	for (int i = -k-1; i <= k + 1;i++) {
		int r = d - i * i;
		if (r < 0)continue;
		int rk = sqrt(r + 0.1);
		if (rk*rk == r) {
			v.push_back({ i,rk });
			v.push_back({ i,-rk });
		}
	}
	rep(i, n*n) {
		G[i].clear();
	}
	rep(i, n) {
		rep(j, n) {
			rep(l, v.size()) {
				int nx = v[l].first + i; int ny = v[l].second + j;
				if (nx < 0 || ny < 0 || nx >= n || ny >= n)continue;
				int to = nx * n + ny; int cur = i * n + j;
				G[cur].push_back(to);
			}
		}
	}

}
bool used[300][300];
void dfs(int id) {
	rep(i, n) {
		rep(j, n) {
			used[i][j] = false;
		}
	}
	queue<int> q;
	rep(i, n) {
		rep(j, n) {
			if (used[i][j])continue;
			m[id][i][j] = 0;
			q.push(i*n+j); used[i][j] = true;
			while (!q.empty()) {
				int cur = q.front(); q.pop();
				rep(k, G[cur].size()) {
					int to = G[cur][k];
					int nx = to / n, ny = to % n;
					if (used[nx][ny])continue;
					used[nx][ny] = true; q.push(to);
					m[id][nx][ny] = m[id][cur / n][cur%n] ^ 1;
				}
			}
		}
	}
}
