using namespace std;
int id[600][600],n,d1,d2,R;
vector<int> e[360000];
int id2[600][600];
int col[360000],px[360000],py[360000];
vector<int> A,B;
void add_edge(int dx,int dy){
	for(int i=0; i<R; i++)for(int j=0; j<R; j++){
		if(id[i][j] == -1)continue;
		int i2 = i+dx, j2 = j+dy;
		if(i2>=0 && i2<R && j2>=0 && j2<R && id[i2][j2] !=-1){
			e[id[i][j]].push_back(id[i2][j2]);
		}
	}
}
void dfs(int x,int c){
	if(col[x] == 0){
		if(c==1){
			A.push_back(x);
		}else
			B.push_back(x);
		col[x] = c;
		for(auto y : e[x]){
			dfs(y, -c);
		}
	}
}
void proc(int&m,int X){
	for(int i=0; i<m; i++){
		e[i].clear();
		col[i] = 0;
	}
	for(int i=0; i<R; i++)for(int j=0; j<R; j++)if(id[i][j]!=-1){
		px[id[i][j]] = i;
		py[id[i][j]] = j;
	}
	for(int i=0; i*i<=X; i++){
		int z=X-i*i;
		int j=(int)sqrt(z+.5);
		if(j*j==z){
			add_edge(i,j);
			if(j>0)add_edge(i,-j);
			if(i>0)add_edge(-i,j);
			if(i>0&&j>0)add_edge(-i,-j);
		}
	}
	int m2 = 0;
	for(int i=0; i<R; i++)for(int j=0; j<R; j++)if(id[i][j] != -1 && col[id[i][j]] == 0){
		A.clear();
		B.clear();
		dfs(id[i][j],1);
		if(A.size() < B.size())swap(A,B);
		for(auto cur : A){
			id2[px[cur]][py[cur]] = m2++;
		}
		for(auto cur : B){
			id2[px[cur]][py[cur]] = -1;
		}
	}
	memcpy(id,id2,sizeof(id));
	m = m2;
}
int main(){
	scanf("%d%d%d",&n,&d1,&d2);
	R = 2 * n;
	int t=0;
	for(int i=0; i<R; i++)
	for(int j=0; j<R; j++)
		id[i][j] = t++;
	proc(t,d1);
	proc(t,d2);
	for(int i=0,t=n*n; i<R&&t>0; i++)
		for(int j=0; j<R&&t>0; j++)
			if(id[i][j] != -1){
				printf("%d %d\n",i,j);
				--t;
			}
	return 0;
}

