void do_ban(int x){
    int m = 1;
    while(x % 4 == 0){
        m *= 2;
        x /= 4;
    }
    if(x % 4 == 3) return;
    if(x % 4 == 1){
        for(int i=0;i<2*n;i++){
            for(int j=0;j<2*n;j++){
                if((i % (2 * m) >= m) ^ (j % (2 * m) >= m)){
                    bd[i][j] = 0;
                }
            }
        }
    }else if(x % 4 == 2){
        for(int i=0;i<2*n;i++){
            for(int j=0;j<2*n;j++){
                if(i % (2 * m) >= m){
                    bd[i][j] = 0;
                }
            }
        }
    }
}

