		col[x]=c;
		v[x]=1;
		int i,j;
		for(i=h[x];i;i=nex[i]){
			if(!v[to[i]]){
				v[to[i]]=1;
				for(j=h[to[i]];j;j=nex[j]){
					if(!v[to[j]])dfs(to[j],c);
				}
			}
		}
