}
void build(int f,int x,int y){
	if(y>=2*n)return;
	int i,j;
	for(i=0;i+x<2*n;i++){
		for(j=0;j+y<2*n;j++)g[f].add(p(i,j),p(i+x,j+y));
	}
	for(i=0;i+x<2*n;i++){
		for(j=2*n-1;j-y>=0;j--)g[f].add(p(i,j),p(i+x,j-y));
	}
}
