vpii cal(int d, int n) {
	vpii ret;
	int sd = sqrt(d);
	rep(dx, sd+1) {
		if (dx >= n*2) continue;
		int dy = sqrt(d - dx*dx);
		if (dy >= n*2) continue;
		if (dy * dy + dx * dx == d) {
			ret.emplace_back(dx, dy);
		}
	}
	return ret;
}

void pr(const vpii &ans) {
	forr(a, ans) {
		print(a.fst, a.snd);
	}
}

