vii getind(vii vec,int val){
	vii vec1,vec2,vec3,vec4,vec00,vec11,vec22,vec33,vec0;

	vec1.clear();
	int i;
	int haha[3];
	int wow[2][2];
	rep(i,2){
		haha[i]=0;
	}
	int j;
	rep(i,2){
		rep(j,2){
			wow[i][j]=0;
		}
	}

	if(val%2){
		rep(i,vec.size()){
			haha[(vec[i].ff+vec[i].ss)%2]++;
		}
		val=0;
		if(haha[1]>haha[0]){
			val=1;
		}
		rep(i,vec.size()){
			if((vec[i].ff+vec[i].ss)%2==val){
				vec1.pb(vec[i]);
			}
		}
		return vec1;
	}
	if(val%4==2){
		rep(i,vec.size()){
			wow[vec[i].ff%2][vec[i].ss%2]++;
		}
		if(wow[0][0]>wow[1][1]){
			rep(i,vec.size()){
				if(vec[i].ff%2==0 && vec[i].ss%2==0){
					vec1.pb(vec[i]);
				}
			}
		}
		else{
			rep(i,vec.size()){
				if(vec[i].ff%2==1 && vec[i].ss%2==1){
					vec1.pb(vec[i]);
				}
			}
		}
		if(wow[1][0]>wow[0][1]){
			rep(i,vec.size()){
				if(vec[i].ff%2==1 && vec[i].ss%2==0){
					vec1.pb(vec[i]);
				}
			}
		}
		else{
