				if(vec[i].ff%2==0 && vec[i].ss%2==1){
					vec1.pb(vec[i]);
				}
			}
		}
		return vec1;

	}
	if(val%4==0){
		val/=4;
		rep(i,vec.size()){
			int hahal=(vec[i].ff%2)*2+vec[i].ss%2;
			vec[i].ff/=2;
			vec[i].ss/=2;
			if(hahal==0){

				vec0.pb(vec[i]);
			}
			else if(hahal==1){
				vec1.pb(vec[i]);
			}
			else if(hahal==2){
				vec2.pb(vec[i]);
			}
			else if(hahal==3){
				vec3.pb(vec[i]);
			}

		}
		vec00=getind(vec0,val);
		vec11=getind(vec1,val);
		vec22=getind(vec2,val);
		vec33=getind(vec3,val);
		vec1.clear();
		rep(i,vec00.size()){
			vec00[i].ff*=2;
			vec00[i].ss*=2;
			vec1.pb(vec00[i]);
		}
		rep(i,vec11.size()){
			vec11[i].ff*=2;
			vec11[i].ss*=2;
			//vec00[i].ff++;
			vec11[i].ss++;
			vec1.pb(vec11[i]);
		}
		rep(i,vec22.size()){
			vec22[i].ff*=2;
			vec22[i].ss*=2;
			vec22[i].ff++;
			vec1.pb(vec22[i]);
		}
