void body() {
    auto N = read<i64>();
    auto D1 = read<i64>();
    auto D2 = read<i64>();

    SimpleAdjacencyList g_1(4 * N * N);
    SimpleAdjacencyList g_2(4 * N * N);

    auto to_id = [N](i64 x, i64 y) -> i64 { return 2 * N * x + y; };
    auto to_p = [N](i64 id) -> pair<i64, i64> {
        i64 y = id % (2 * N);
        i64 x = (id - y) / (2 * N);
        return make_pair(x, y);
    };

    // グラフの構築
    REP (x, 2 * N) {
        REP (y, 2 * N) {
            auto id1 = to_id(x, y);
            FOR (i, x, 2 * N) {
                auto d = i - x;
                i64 j_1 = std::sqrt(D1 - d * d);
                i64 j_2 = std::sqrt(D2 - d * d);

                if (d * d + j_1 * j_1 == D1 && y + j_1 < 2 * N) {
                    g_1.add_edge(make_tuple(id1, to_id(i, y + j_1)));
                }
                if (d * d + j_2 * j_2 == D2 && y + j_2 < 2 * N) {
                    g_2.add_edge(make_tuple(id1, to_id(i, y + j_2)));
                }
            }
        }
    }
    dump("fin construct graph");

    // 彩色
    Vector<i64> V1(4 * N * N, 0);
    REP (id, 4 * N * N) {
        if (V1[id] != 0) continue;

        std::stack<pair<i64, i64>> s;
        s.emplace(-1, id);
        while (!s.empty()) {
            auto elem = s.top();
            s.pop();
            auto prev = elem.first;
            auto x = elem.second;

            if (V1[x] != 0) {
                continue;
            }

            if (prev == -1) {
                V1[x] = 1;
            } else {
                V1[x] = -V1[prev];
            }

            EACH_V (edge, g_1.outgoings(x)) {
                s.emplace(get<0>(edge), get<1>(edge));
            }
        }
    }
    dump("fin grouping g1");

    Vector<i64> V2(4 * N * N, 0);
    REP (id, 4 * N * N) {
        if (V2[id] != 0) continue;

        std::stack<pair<i64, i64>> s;
        s.emplace(-1, id);
        while (!s.empty()) {
            auto elem = s.top();
            s.pop();
            auto prev = elem.first;
            auto x = elem.second;

            if (V2[x] != 0) continue;

            if (prev == -1) {
                V2[x] = 1;
            } else {
                V2[x] = -V2[prev];
            }

            EACH_V (edge, g_2.outgoings(x)) {
                s.emplace(get<0>(edge), get<1>(edge));
            }
        }
    }
    dump("fin grouping g2");

    auto dump = [&](auto v1, auto v2) -> bool {
        Vector<pair<i64, i64>> ps;
        REP (i, 4 * N * N) {
            if (V1[i] == v1 && V2[i] == v2) {
                ps.push_back(to_p(i));
                if (ps.size() >= N * N) {
                    break;
                }
            }
        }
        if (ps.size() >= N * N) {
            REP (i, N * N) {
                auto p = ps[i];
                cout << p.first << " " << p.second << endl;
            }
            return true;
        }
        return false;
    };

    // よい集合の抽出
    if (dump(1, 1)) {
        return ;
    }
    if (dump(1, -1)) {
        return ;
    }
    if (dump(-1, 1)) {
        return ;
    }
    if (dump(-1, 1)) {
        return;
    }
}

