void prepare() {
  for (int x = -600; x <= 600; ++x) {
    for (int y = -600; y <= 600; ++y) {
      int dist = x*x + y*y;
      if (dist == d1 || dist == d2) {
        bad.emplace_back(x, y);
      }
    }
  }
}

void perform(const vector<pair<int,int>>& pts) {
  s.clear();
  for (auto& p: pts) {
    if ((int)s.size() == n*n)
      break;
    if (check(s, p))
      s.insert(p);
  }
}

void easy() {
  if ((int)s.size() == n*n)
    return;

  vector<pair<int,int>> pts;

  for (int i = 0; i < 2*n; ++i) 
    for (int j = 0; j < 2*n; ++j) 
      pts.emplace_back(i, j);

  perform(pts);
}

void strange() {
  int len = 2*n;

  int x = 0, y = 0;
  int bx = 2*n, by = 2*n;
  vector<pair<int,int>> pts;

  while (len > 0) {
    for (int i = x; i < bx-1; ++i)
      pts.emplace_back(i, y);
    for (int i = y; i < by-1; ++i)
      pts.emplace_back(bx-1, i);
    for (int i = bx-1; i >= x-1; --i)
      pts.emplace_back(i, by-1);
    for (int i = by-1; i >= y-1; --i)
      pts.emplace_back(x, i);
    len -= 2;
    ++x; ++y;
    --bx; --by;
  }

  perform(pts);
}

