int N;
int D0, D1, D[2];

bool H[666][666];
int F[666][666];

vector<pair<int, int> > E, ans;
bool in(int y, int x) {
    return 0 <= y && y < N*2 && 0 <= x && x <= N*2;
}

int cnt, rem;
bool rec(int z) {
//    printf("%d %d:\n", cnt, rem);
//    REP (t, N*2) rprintf("%d", F[t], F[t]+N*2);
//    puts("");
    if (z == 4 * N * N) {
	return false;
    }

    int i = z / (2*N), j = z - i*(2*N);


    if (F[i][j] == 0) {
	H[i][j] = true;
	F[i][j]++;
	cnt++;
	rem--;
	EACH (e, E) {
	    int y = i + e->first;
	    int x = j + e->second;
	    if (in(y, x)) {
		if (F[y][x] == 0) rem--;
		F[y][x]++;
	    }
	}

	if (cnt == N*N) return true;
	if (cnt + rem >= N*N && rec(z+1)) return true;

	EACH (e, E) {
	    int y = i + e->first;
	    int x = j + e->second;
	    if (in(y, x)) {
		F[y][x]--;
		if (F[y][x] == 0) rem++;
	    }
	}
	rem++;
	cnt--;
	F[i][j]--;
	H[i][j] = false;
    }

    if (F[i][j] == 0) rem--;
    F[i][j]++;
    if (cnt + rem >= N*N && rec(z+1)) return true;
    F[i][j]--;
    if (F[i][j] == 0) rem++;

    return false;
}

void MAIN() {
    scanf("%d", &N);
