    for (int i=-N*2+1; i<N*2; i++) {
	for (int j=-N*2+1; j<N*2; j++) {
	    int tmp = i*i + j*j;
	    if (tmp == D0 || tmp == D1) {
		E.emplace_back(i, j);
	    }
	}
    }

    rem = 4*N*N;
    rec(0);
    REP (i, N*2) REP (j, N*2) if (H[i][j]) {
	ans.emplace_back(i, j);
    }

    if ((int)ans.size() < N*N) {
	puts("-1");
    } else {
	ans.resize(N*N);
	EACH (e, ans) printf("%d %d\n", e->first, e->second);
    }
}

