void AddShifts(int c, auto &v) {
    int cnt = 0;
    for (int a = 0; a * 1ll * a <= c; a++) {
        int64_t  val = c - a * 1ll * a;
        int64_t sq = sqrt(val);
        if (sq * sq == val) {
