} Random;

struct Timer {

    double CYCLE_PER_SEC = 2800000000.0;
    unsigned long long BEGIN_CYCLE = 0;

    Timer() {}
    Timer(double cycle) : CYCLE_PER_SEC(cycle) {}

    unsigned long long int getCycle() {
        unsigned int low, high;
        __asm__ volatile ("rdtsc" : "=a" (low), "=d" (high));
        return ((unsigned long long int)low) | ((unsigned long long int)high << 32);
    }

    void start(void) {
        BEGIN_CYCLE = getCycle();
    }

    double get_time(void) {
        return (double)(getCycle() - BEGIN_CYCLE) / CYCLE_PER_SEC;
    }

} timer;

const double TIME_LIMIT = 1.8;
const double TEMP_START = 10.0;
const double TEMP_END   = 0.001;
const double TEMP_DIFF  = (TEMP_START - TEMP_END) / TIME_LIMIT;

ll N;
ll D1,D2;

ll score;
ll best_score;
vector < pair < int,int > > ans;
vector < pair < int,int > > non_used;
vector < pair < int,int > > best_ans;
vector < pair < int,int > > diff_cnd;

bool used[610][610];

ll get_diff (pair < int,int > pre, pair < int,int > nxt) {
	ll ret = 0;
	REP(i,diff_cnd.size()) {
		int x = pre.first + diff_cnd[i].first;
		int y = pre.second + diff_cnd[i].second;
		if (x < 0 || y < 0 || x >= 2 * N || y >= 2 * N) continue;
		if (used[x][y]) ret--;
	}
	used[pre.first][pre.second] = false;
	REP(i,diff_cnd.size()) {
		int x = nxt.first + diff_cnd[i].first;
		int y = nxt.second + diff_cnd[i].second;
		if (x < 0 || y < 0 || x >= 2 * N || y >= 2 * N) continue;
		if (used[x][y]) ret++;
	}
	used[pre.first][pre.second] = true;
	return -ret;
}

bool accept (double diff, double temp) {
    if (diff >= 0) return true;
    double P = exp(diff / temp) * 4294967295.0;
    return Random.rand() < P;
}

void simulated_annealing () {
	int cnt = 0;
	while (true) {
		REP(i,ans.size()) {
			double cur_time = timer.get_time();
			double cur_temp = TEMP_START - TEMP_DIFF * cur_time;
			if (cur_time > TIME_LIMIT) return;
			int r = Random.rand() % non_used.size();
			ll diff = get_diff(ans[i], non_used[r]);
			if (accept((double) diff, cur_temp)) {
				used[ans[i].first][ans[i].second] = false;
				used[non_used[r].first][non_used[r].second] = true;
				swap(ans[i].first, non_used[r].first);
				swap(ans[i].second, non_used[r].second);
				score -= diff;
				if (best_score > score) {
					best_score = score;
					best_ans = ans;
				}
			}
		}
	}
}

int main() {

	timer.start();

	cin >> N >> D1 >> D2;

	set < pair < int,int > > koho;
	for (int i = 0; i <= D1; i++) {
		int A = i;
		int B = D1 - i;
		int sqA = (int) sqrt(A);
		int sqB = (int) sqrt(B);
		if (A != sqA * sqA) continue;
		if (B != sqB * sqB) continue;
		koho.insert(make_pair(sqA, sqB));
		koho.insert(make_pair(-sqA, sqB));
		koho.insert(make_pair(sqA, -sqB));
		koho.insert(make_pair(-sqA, -sqB));
	}
	for (int i = 0; i <= D2; i++) {
		int A = i;
		int B = D2 - i;
		int sqA = (int) sqrt(A);
		int sqB = (int) sqrt(B);
		if (A != sqA * sqA) continue;
		if (B != sqB * sqB) continue;
		koho.insert(make_pair(sqA, sqB));
		koho.insert(make_pair(-sqA, sqB));
		koho.insert(make_pair(sqA, -sqB));
		koho.insert(make_pair(-sqA, -sqB));
	}

	for (auto itr : koho) {
		diff_cnd.push_back(itr);
	}

	REP(i,N * N) {
		used[i / N][i % N] = true;
		ans.push_back(make_pair(i / N, i % N));
	}

	REP(i,2*N) REP(j,2*N) {
		if (!used[i][j]) {
			non_used.push_back(make_pair(i, j));
		}
	}

	REP(i,ans.size()) {
		REP(j,diff_cnd.size()) {
			int x = ans[i].first + diff_cnd[j].first;
			int y = ans[i].second + diff_cnd[j].second;
			if (x < 0 || y < 0 || x >= 2 * N || y >= 2 * N) continue;
			if (used[x][y]) score++;
		}
	}

	score /= 2;
	best_score = score;
	best_ans = ans;

	simulated_annealing();

	REP(i,best_ans.size()) {
		cout << best_ans[i].first << " " << best_ans[i].second << endl;
	}

	return 0;
}

