		random_shuffle(priors.begin(), priors.end());
		for (int i = 0; i < priors.size(); i++)
			my[priors[i].first][priors[i].second] = i;
		while (!Q.empty()) Q.pop();
		for (int i = 0; i < 2 * n; i++)
			for (int j = 0; j < 2 * n; j++) {
				tk[i][j] = false;
				neigh[i][j].clear();
				for (int z = 0; z < delt.size(); z++)
					if (Inbounds(i + delt[z].first, j + delt[z].second))
						neigh[i][j].push_back(ii(i + delt[z].first, j + delt[z].second));
				st[i][j] = neigh[i][j].size();
				Q.push(ii(-st[i][j], my[i][j]));
			}
		seq.clear();
		while (!Q.empty() && seq.size() < n * n) {
			ii v = priors[Q.top().second]; int s = -Q.top().first; Q.pop();
			if (st[v.first][v.second] != s || tk[v.first][v.second]) continue;
			tk[v.first][v.second] = true; seq.push_back(v);
			for (int i = 0; i < neigh[v.first][v.second].size(); i++)
				Delete(neigh[v.first][v.second][i]);
		}
		if (seq.size() >= n * n) {
			for (int i = 0; i < seq.size(); i++)
				printf("%d %d\n", seq[i].first, seq[i].second);
			break;
		}
	}
	return 0;
}

