int f[700][700];

int dx[] = {1, 0, -1, 0, 1, 1, -1, -1};
int dy[] = {0, -1, 0, 1, -1, 1, -1, 1};

inline int dist(P a, P b) {
  return
  abs(a.X - b.X) *
  abs(a.X - b.X) +
  abs(a.Y - b.Y) *
  abs(a.Y - b.X);
}

int c[300][300];
int ddx[2];
int ddy[2];

int main() {
  ios::sync_with_stdio(false), cin.tie(0);
  int n, k[2]; cin >> n >> k[0] >> k[1];

  auto comp = [&](P a, P b) {
    int aa = min({dist(a, P(n - 1, n - 1)), dist(a, P(n - 1, n)), dist(a, P(n, n -1)), dist(a, P(n, n))});
    int bb = min({dist(b, P(n - 1, n - 1)), dist(b, P(n - 1, n)), dist(b, P(n, n -1)), dist(b, P(n, n))});
    return aa < bb;
  };
  priority_queue<P, vector<P>, decltype(comp)> pq(comp);
  for(int i = 0; i < 300; i++) {
    for(int j = 0; j < 2; j++) {
      int kt = k[j] - i * i;
      if(kt < 0) continue;
      int kk = sqrt(kt);
      if(kk * kk != kt) continue;
      ddx[j] = i;
      ddy[j] = kk;
    }
  }
  for(int i = 0; i < 2 * n; i++)
    for(int j = 0; j < 2 * n; j++) {
      pq.emplace(i, j);
    }
  vector<P> ans;
  while(pq.size()) {
    auto p = pq.top();
    pq.pop();
    int fl = 1;
    for(int i = 0; i < 2; i++) {
      for(int d = 0; d < 8; d++) {
        int nx = p.X + dx[d] * ddx[i];
        int ny = p.Y + dy[d] * ddy[i];
        if(nx < 0 || ny < 0 || nx >= n * 2 || ny >= n * 2) continue;
        fl &= !f[nx][ny];
      }
    }
    if(fl) ans.emplace_back(p.X, p.Y), f[p.X][p.Y] = 1;
  }
  // 適当
  dump(ans.size());
  for(int i = 0; i < n * n; i++) {
    cout << ans[i].first << " " << ans[i].second << endl;
  }
}

