void init() {
	memset(s, 255, sizeof(s));
	fi(0, M - 1) {
		if (i * i >= M) break;
		s[i * i] = i;
	}
	fi(1, M - 1) {
		if (s[i] == -1) s[i] = s[i - 1];
	}
}

void kill() {
	vpii res;
	fi(0, n2 - 1) {
		fj(0, n2 - 1) {
			if (have[i][j]) {
				cnt--;				
				have[i][j]--;
