const int N = 310;
int tot;
vector<pair<int, int> > ans[2][2];

void dfs(int c[N * 2][N * 2], int x, int y, int n, int d, int col) {
	if (x > n || y > n || x < 0 || y < 0 || c[x][y] != -1) return;
	c[x][y] = col;
	for (int i = 0; i * i <= d && i <= n; i++) {
		int j = sqrt(d + 0.0 - i * i);
		while (j * j <= d - i * i) j++;
		j--;
		if (i * i + j * j != d) continue;
		dfs(c, x + i, y + j, n, d, col ^ 1);
		dfs(c, x + i, y - j, n, d, col ^ 1);
		dfs(c, x - i, y + j, n, d, col ^ 1);
		dfs(c, x - i, y - j, n, d, col ^ 1);
	}
}

int c[2][N * 2][N * 2];
void solve(int n, int d, int t) {
	for (int i = 0; i < n * 2; i++)
		for (int j = 0; j < n * 2; j++)
			if (c[t][i][j] == -1) dfs(c[t], i, j, n * 2 - 1, d, 0);
}

