void make_graph(int d) {
	v.clear();
	int k = sqrt(d);
	for (int i = -k-1; i <= k + 1;i++) {
		int r = d - i * i;
		if (r < 0)continue;
		int rk = sqrt(r + 0.1);
		if (rk*rk == r) {
			v.push_back({ i,rk });
			v.push_back({ i,-rk });
		}
	}
	rep(i, n*n) {
		G[i].clear();
	}
	rep(i, n) {
		rep(j, n) {
			rep(l, v.size()) {
				int nx = v[l].first + i; int ny = v[l].second + j;
				if (nx < 0 || ny < 0 || nx >= n || ny >= n)continue;
				int to = nx * n + ny; int cur = i * n + j;
				G[cur].push_back(to);
			}
		}
	}

}
