		rep(j, n) {
			used[i][j] = false;
		}
	}
	queue<int> q;
	rep(i, n) {
		rep(j, n) {
			if (used[i][j])continue;
			m[id][i][j] = 0;
			q.push(i*n+j); used[i][j] = true;
			while (!q.empty()) {
				int cur = q.front(); q.pop();
				rep(k, G[cur].size()) {
					int to = G[cur][k];
					int nx = to / n, ny = to % n;
					if (used[nx][ny])continue;
					used[nx][ny] = true; q.push(to);
					m[id][nx][ny] = m[id][cur / n][cur%n] ^ 1;
				}
			}
		}
	}
}
