typedef pair<int, int> P;
int clr[605][605];
int dx[] = { 1,-1,1,-1 }, dy[] = { 1,1,-1,-1 };
vector<P>v1, v2; int n;

void dfs(int nx, int ny,vector<P>V) {
	rep(i, V.size()) {
		rep(j, 4) {
			int mx = nx + V[i].first*dx[j], my = ny + V[i].second*dy[j];
			if (0 <= mx&&mx < 2 * n && 0 <= my&&my < 2 * n&&clr[mx][my]==0) {
				clr[mx][my] = clr[nx][ny] * -1;
				dfs(mx, my,V);
			}
		}
	}
}

signed main() {
	int d1, d2; cin >> n >> d1 >> d2;
	rep(i, d1 + 1) {
		int x = d1 - i*i;
		int Q = sqrt(x);
		if (x == Q*Q)v1.push_back(P(i, Q));
	}
	rep(i, d2 + 1) {
		int x = d2 - i*i;
		int Q = sqrt(x);
		if (x == Q*Q)v2.push_back(P(i, Q));
	}
	int cb = 0;
	rep(i, 2 * n) {
		rep(j, 2 * n) {
			if (!clr[i][j]) {
				clr[i][j] = 1; dfs(i, j,v1);
			}
			if (clr[i][j] == 1)cb++;
		}
	}
	int r = 1;
	if (cb < n*n * 2) r = -1;//-1を残す
	rep(i, 2 * n) {
		rep(j, 2 * n) {
			if (clr[i][j] == r)clr[i][j] = 0;
		}
	}

	rep(i, 2 * n) {
		rep(j, 2 * n) {
			if (!clr[i][j]) {
				clr[i][j] = 2; dfs(i, j, v2);
			}
		}
	}
	vector<P>ans1, ans2;
	rep(i, 2 * n) {
		rep(j, 2 * n) {
			if (clr[i][j] == 2)ans1.push_back(P(i, j));
			if (clr[i][j] == -2)ans2.push_back(P(i, j));
		}
	}
	if (ans1.size() < ans2.size()) {
		rep(i, n*n) {
			cout << ans2[i].first << ' ' << ans2[i].second << endl;
		}
	}
	else {
		rep(i, n*n) {
			cout << ans1[i].first << ' ' << ans1[i].second << endl;
		}
	}
}

