const int MAX_N = 301;
int N;
int D[2];
int MAP[2*MAX_N][2*MAX_N];
struct Point
{
    int x, y;
    Point(int x, int y) : x(x), y(y){}
};

void Traverse(int start_x, int start_y)
{
    std::deque<Point> q;
    q.emplace_back(start_x, start_y);
    int64_t count = 0;
    while(!q.empty())
    {
        Point pt = q.front(); q.pop_front();
        if(MAP[pt.y][pt.x] != 0)
            continue;
        for(int y = pt.y; y <= min(pt.y + D[1]+1, 2*N-1); ++y)
        {
            for(int x = pt.x; x <= min(pt.x + D[1]+1, 2*N-1); ++x)
            {
                if(MAP[y][x] != 0)
                    continue;
                const uint64_t sq_dist = (uint64_t(x - pt.x))*(x-pt.x) + (uint64_t(y-pt.y))*(y-pt.y);
                if(sq_dist == D[0] || sq_dist == D[1])
                    MAP[y][x] = -1;
                q.emplace_back(y, x);
                if(sq_dist > D[1]) break;
            }
        }
        MAP[pt.y][pt.x] = 1;
        cout << pt.y << " " << pt.x << endl;
        ++count;
        if(count == N*N)
            break;
    }
}


