void colour(int n, int d1, int deep) {
	if (d1 % 4) {
		if (d1 % 2) {
			for (int i = 0; i < 2 * n; i++) {
				for (int j = 0; j < 2 * n; j++) {
					d[deep][i][j] = (i + j + 1) & 1;
				}
			}
		} else {
			for (int i = 0; i < 2 * n; i++) {
				for (int j = 0; j < 2 * n; j++) {
					d[deep][i][j] = (i + 1) & 1;
				}	
			}
		}
	} else {
		colour(n, d1 / 4, deep + 1);
		for (int i = 0; i < 2 * n; i++) {
			for (int j = 0; j < 2 * n; j++) {
				d[deep][i][j] = d[deep + 1][i / 2][j / 2];
			}
		}
	}
}


