int n,d1,d2;
bool G[350][350];

void build(int d){
	int D=d,b=0;
	while (!(D&3)){b++;D=D>>2;}
	if ((d&3)==2){
		for (int i=0;i<n+n;i++)
			for (int j=0;j<n+n;j++) 
				G[i][j]|=((i>>b)&1);
	}
	else{
		for (int i=0;i<n+n;i++)
			for (int j=0;j<n+n;j++) 
				G[i][j]|=(((i>>b)+(j>>b))&1);
	}
}

int main(){
	scanf("%d%d%d",&n,&d1,&d2);
	build(d1);build(d2);
	int Counter=0;
	for (int i=0;i<n+n;i++)
		for (int j=0;j<n+n;j++)
			if (!G[i][j]){
				printf("%d %d\n",i,j);
				Counter++;
				if (Counter==n*n) return 0;
			}
}

