bool check(int x,int y){
	for(int i=x;i>=0;i--){
		int flag=0;
		{
			int j=d1-pf(x-i);
			if(pre[j]==-1||j<0){flag=1;}
			if(!flag){
			j=pre[j];
			j=y-j;
			if(j<0){flag=1;}
			if((!flag)&&mp[i][j])return false;
			j=y-j;
			j=j+y;
			if(j>=2*n){flag=1;}
			if((!flag)&&mp[i][j])return false;
			}
		}
		flag=0;
