int n, d1, d2;
vector<int> g[N];
bool used[N];
int c1[N], c2[N];

void read() {
  cin >> n >> d1 >> d2;
}

int enc(int i, int j) {
  return i + 2 * n * j;
}

void dfs(int x, int * c, int color) {
  if (used[x]) {
    assert(c[x] == color);
    return;
  }
  c[x] = color;
  used[x] = true;
  for (int y : g[x])
    dfs(y, c, color ^ 1);
}

void color(int d, int *c) {
  vector<int> dx, dy;
  for (int i = 0; i * i <= d; ++i) {
    for (int j = 0; j * j <= d; ++j) {
      if (i * i + j * j == d) {
        dx.push_back(i);
        dx.push_back(i);
        dx.push_back(-i);
        dx.push_back(-i);

        dy.push_back(j);
        dy.push_back(-j);
        dy.push_back(j);
        dy.push_back(-j);
      }
    }
  }

  for (int i = 0; i < 2 * n; ++i)
    for (int j = 0; j < 2 * n; ++j) {
      int cur = enc(i, j);
      g[cur].clear();
      for (int k = 0; k < (int) dx.size(); ++k) {
        int ti = i + dx[k];
        int tj = j + dy[k];
        if (0 <= min(ti, tj) && max(ti, tj) < 2 * n) {
          g[cur].push_back(enc(ti, tj));
        }
      }
    }

  fill(used, used + 4 * n * n, false);
  for (int i = 0; i < 4 * n * n; ++i)
    if (!used[i])
      dfs(i, c, 0);
}

int cnt[2][2];

void kill() {
  color(d1, c1);
  color(d2, c2);

  int m = 4 * n * n;
  for (int i = 0; i < m; ++i)
    cnt[c1[i]][c2[i]]++;
  for (int x = 0; x < 2; ++x)
    for (int y = 0; y < 2; ++y)
      if (cnt[x][y] >= m / 4) {
        int cur = 0;
        for (int i = 0; i < m && cur < n * n; ++i)
          if (c1[i] == x && c2[i] == y) {
            cout << (i % (2 * n)) << " " << (i / (2 * n)) << "\n";
            ++cur;
          }
        assert(cur == n * n);
        return;
      }
}

