int N, D1, D2, Sqrt[Max_D], C1[Max_N << 1][Max_N << 1], C2[Max_N << 1][Max_N << 1];
const int kx[] = {+1, -1, +0, +0};
const int ky[] = {+0, +0, +1, -1};
vector<pil> G1[Max_N << 1][Max_N << 1], G2[Max_N << 1][Max_N << 1];
vector<pil> All[4];

void dfs1(int x, int y)
{
	for (int i = 0, _x, _y;i < G1[x][y].size();++i)
	{
		_x = G1[x][y][i].fi, _y = G1[x][y][i].se;
		if (!C1[_x][_y])
			C1[_x][_y] = 3 - C1[x][y], dfs1(_x, _y);
	}
}

void dfs2(int x, int y)
{
	for (int i = 0, _x, _y;i < G2[x][y].size();++i)
	{
		_x = G2[x][y][i].fi, _y = G2[x][y][i].se;
		if (!C2[_x][_y])
			C2[_x][_y] = 3 - C2[x][y], dfs2(_x, _y);
	}
}

int main()
{
	gi(N), gi(D1), gi(D2);
	memset(Sqrt, -1, sizeof(Sqrt));
	for (int x = 0;x * x <= D1 || x * x <= D2;++x)
		Sqrt[x * x] = x;
	for (int x = 0;x < N + N;++x)
		for (int y = 0;y < N + N;++y)
		{
			for (int dx = 0, dy;dx * dx <= D1;++dx)
			{
				dy = Sqrt[D1 - dx * dx];
				if (dy != -1 && (dx != 0 || dy != 0))
					for (int k = 0, _x, _y;k < 4;++k)
					{
						_x = x + kx[k] * dx, _y = y + ky[k] * dy;
						if (0 <= _x && _x < N + N && 0 <= _y && _y < N + N)
							G1[x][y].push_back(mp(_x, _y));
					}
			}
			for (int dx = 0, dy;dx * dx <= D2;++dx)
			{
				dy = Sqrt[D2 - dx * dx];
				if (dy != -1 && (dx != 0 || dy != 0))
					for (int k = 0, _x, _y;k < 4;++k)
					{
						_x = x + kx[k] * dx, _y = y + ky[k] * dy;
						if (0 <= _x && _x < N + N && 0 <= _y && _y < N + N)
							G2[x][y].push_back(mp(_x, _y));
					}
			}
		}
	for (int x = 0;x < N + N;++x)
		for (int y = 0;y < N + N;++y)
		{
			if (!C1[x][y])
				C1[x][y] = 1, dfs1(x, y);
			if (!C2[x][y])
				C2[x][y] = 1, dfs2(x, y);
			All[(C1[x][y] - 1) * 2 + (C2[x][y] - 1)].push_back(mp(x, y));
