        }
        dfs(x + i, y + j, a, 3 - b); 
        dfs(x - i, y + j, a, 3 - b); 
        dfs(x + i, y - j, a, 3 - b); 
        dfs(x - i, y - j, a, 3 - b); 
    }
}

