#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using P = pair<int, int>;

const int MAX_V = 360000;

vector<int> G[MAX_V];

void add_edge(int u, int v) {
    G[u].push_back(v);
    G[v].push_back(u);
}

void dfs(int v, vector<int>& l, vector<int>& r, bool is_l, vector<int>& used) {
    if (is_l) l.push_back(v);
    else r.push_back(v);
    for (int nex : G[v]) {
        if (used[nex]) continue;
        used[nex] = true;
        dfs(nex, l, r, !is_l, used);
    }
}

bool is_square(int x2, int& x) {
    int ok = 0, ng = 10000;
    while (ng - ok > 1) {
        int mid = (ok + ng) / 2;
        if (mid * mid <= x2) ok = mid;
        else ng = mid;
    }
    x = ok;
    return x * x == x2;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, d1, d2;
    cin >> n >> d1 >> d2;
    vector<P> v;
    for (int i = 0; i * i <= d1; i++) {
        if (i >= 2 * n) break;
        int j = 0;
        if (is_square(d1 - i * i, j)) {
            if (j >= 2 * n) continue;
            v.emplace_back(i, j);
            v.emplace_back(i, -j);
        }
    }

    for (int i = 0; i * i <= d2; i++) {
        if (i >= 2 * n) break;
        int j = 0;
        if (is_square(d2 - i * i, j)) {
            if (j >= 2 * n) continue;
            v.emplace_back(i, j);
            v.emplace_back(i, -j);
        }
    }

    for (int i = 0; i < 2 * n; i++) {
        for (int j = 0; j < 2 * n; j++) {
            for (P& p : v) {
                int h = i + p.first, w = j + p.second;
                if (h < 0 || h >= 2 * n || w < 0 || w >= 2 * n) continue;
                add_edge(i * 2 * n + j, h * 2 * n + w);
            }
        }
    }

    int cnt = 0;
    vector<int> used(4 * n * n, false);
    vector<int> ans;
    for (int i = 0; i < 4 * n * n; i++) {
        if (used[i]) continue;
        used[i] = true;
        vector<int> l, r;
        dfs(i, l, r, true, used);
        if ((int)l.size() >= (int)r.size()) {
            while (!l.empty()) {
                ans.push_back(l.back());
                l.pop_back();
            }
        } else {
            while (!r.empty()) {
                ans.push_back(r.back());
                r.pop_back();
            }           
        }
    }

    for (int i = 0; i < n * n; i++) {
        cout << ans[i] / (2 * n) << " " << ans[i] % (2 * n) << endl;
    }
    return 0;
}

