void Solve(int D,int t[N][N])
{
	int i,j,k,K,len,x,y;
	K=0;
	while(D%2==0) K++,D>>=1;
	if(K&1)
	{
		len=1<<((K+1)>>1);
		for(i=0;i<2*n;i+=len)
		{
			for(j=0;j<(len>>1)&&i+j<2*n;j++)
			{
				for(k=0;k<n*2;k++)
				{
					t[i+j][k]=1;
				}
			}
		}
	}
	else
	{
		len=(1<<((K+2)>>1));
		for(i=0;i<2*n;i++)
		{
			for(j=0;j<2*n;j++)
			{
				x=((i%len)>=(len>>1));y=((j%len)>=(len>>1));
				if((x+y)&1) t[i][j]=1;
			}
		}
	}
}
