bool lcheck(const ll x, const ll y, const ll D){
  ll lposx = 0, lposy = y;
  while(true){
    if(lposx>x || lposy<0) break;
    ll distx = x-lposx;
    ll disty = y-lposy;
    ll dist2 = distx*distx + disty*disty;
    //debug_print(x, y, lposx, lposy, dist2, D);
    if(dist2==D){
      if(used_flag[lposx][lposy]) return false;
    }
    if(dist2>D){
      lposx++;
    }else{
      lposy--;
    }
  }
  return true;
}

bool rcheck(const ll x, const ll y, const ll D){
  ll rposx = 2*N-1, rposy = y;
  while(true){
    if(rposx<x || rposy<0) break;
    ll distx = x-rposx;
    ll disty = y-rposy;
    ll dist2 = distx*distx + disty*disty;
    //debug_print(x, y, rposx, rposy, dist2, D);
    if(dist2==D){
      if(used_flag[rposx][rposy]) return false;
    }
    if(dist2>D){
      rposx--;
    }else{
      rposy--;
    }
  }
  return true;
}

