const int N = 600 + 10, IT = 10;

vector<pii> g[N][N];
int seen[N][N];
bool pick[N][N];

void make_graph(int n, int d);

int main() {
	fast_cin();
	srand(time(NULL));
	int n, d1, d2;
	cin >> n >> d1 >> d2;
	int need = n * n;
	n *= 2;
	make_graph(n, d1);
	if (d1 != d2) {
		make_graph(n, d2);
	}
	for (int i = 0; i < need; ++i) {
		int x, y;
		bool ok = false;
		for (int j = 0; j < IT; ++j) {
			x = rand() % n;
			y = rand() % n;
			while (pick[x][y]) {
				x = rand() % n;
				y = rand() % n;
			}
			if (!seen[x][y]) {
				ok = true;
				pick[x][y] = true;
				++seen[x][y];
				for (auto &p : g[x][y]) {
					++seen[p.first][p.second];
				}
				break;
			}
		}
		if (!ok) {
			x = rand() % n;
			y = rand() % n;
			while (!pick[x][y]) {
				x = rand() % n;
				y = rand() % n;
			}
			pick[x][y] = false;
			--seen[x][y];
			for (auto &p : g[x][y]) {
				--seen[p.first][p.second];
			}
			i -= 2;
		}
	}
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			if (pick[i][j]) {
				cout << i << ' ' << j << '\n';
			}
		}
	}
}

void make_graph(int n, int d) {
	int sq = sqrt(d) + 10;
	for (int a = 0; a < sq; ++a) {
		if (a * a > d) {
			break;
		}
		int b = (sqrt(d - a * a) + 0.5);
		if (b > sq or a * a + b * b != d) {
			continue;
		}
		for (int x1 = 0; x1 < n; ++x1) {
			int x2 = x1 + a;
			if (x2 > n) {
				continue;
			}
			for (int y1 = 0; y1 < n; ++y1) {
				int y2 = y1 + b;
				if (y2 < n) {
					g[x1][y1].pb({x2, y2});
					g[x2][y2].pb({x1, y1});
				}
				y2 = y1 - b;
				if (x1 != x2 and y2 >= 0) {
					g[x1][y1].pb({x2, y2});
					g[x2][y2].pb({x1, y1});
				}
			}
		}
	}
}

