int tot;

void solve(int n, int d1, int d2, int mul, int add) {
    if (n < add) return;
	if (d1 % 2 && d2 % 2) {
		for (int i = 0; i <= n && tot; i += mul)
			for (int j = 0; j <= n && tot ; j += mul) {
				printf("%d %d\n", i + add, j + add);
				tot--;
			}
		return;
	}
    if (d1 % 2 == 0 && d2 % 2 == 0) {
		solve(n, d1 / 2, d2 / 2, mul * 2, add * 2);
		solve(n, d1 / 2, d2 / 2, mul * 2, add * 2 + 1);
        return;
	}
    if (d1 % 2 == 0) {
		solve(n, d1 / 2, d2, mul * 2, add * 2);
		solve(n, d1 / 2, d2, mul * 2, add * 2 + 1);
        return;
	}
	if (d2 % 2 == 0) {
		solve(n, d1, d2 / 2, mul * 2, add * 2);
		solve(n, d1, d2 / 2, mul * 2, add * 2 + 1);
	    return;
	}
}

