void work(int lim){
	int cnt=0,cnt1=0,cnt2=0;
	for(int i=0;i<2*n;i++){for(int j=0;j<2*n;j++){col[i][j]=0;}}
	for(int i=0;i*i<=lim;i++){if((sqrt(lim-i*i)*sqrt(lim-i*i)+i*i)==lim){++cnt;p[cnt].x=i;p[cnt].y=sqrt(lim-i*i);}}
	for(int i=0;i<2*n;i++){
		for(int j=0;j<2*n;j++){
			if(!ex[i][j]){continue;}
			if(col[i][j]==0) col[i][j]=1;
			for(int k=1;k<=cnt;k++){
				if(((i+p[k].x)<2*n)&&((j+p[k].y)<2*n)){
					col[i+p[k].x][j+p[k].y]=col[i][j]%2+1;
				}
			}
			if(col[i][j]==1){cnt1++;}
			if(col[i][j]==2){cnt2++;}
		}
	}
	if(cnt1>=cnt2){
		for(int i=0;i<2*n;i++){
			for(int j=0;j<2*n;j++){
				ex[i][j]=(ex[i][j]&&(col[i][j]==1));
