const int maxp=5e5+20;

int n,D1,D2;

int num[920][920],tot;
vector<int>ed[maxp];
int vis[maxp];

inline void init()
{
	n=read();D1=read();D2=read();
	REP(i,0,2*n-1)REP(j,0,2*n-1)num[i][j]=++tot;

}

int ok[maxp],dis[maxp];

void dfs(int u)
{
	vis[u]=1;
	for(int v:ed[u])
	{
		if(vis[v])continue;
		dis[v]=dis[u]^1;
		dfs(v);
	}
}


inline void doing()
{
	REP(i,1,tot)ed[i].clear(),dis[i]=vis[i]=0,ok[i]=1;
	REP(dx,0,sqrt(D1))
	{
		int dy=sqrt(D1-dx*dx);
		if(dy*dy+dx*dx==D1)
		{
			REP(i,0,2*n-1)REP(j,0,2*n-1)
			{
				int now=num[i][j];
				if(i+dx<2*n && j+dy<2*n && num[i+dx][j+dy])ed[now].push_back(num[i+dx][j+dy]),ed[num[i+dx][j+dy]].push_back(now);
				if(i+dx<2*n && j-dy>=0 && num[i+dx][j-dy])ed[now].push_back(num[i+dx][j-dy]),ed[num[i+dx][j-dy]].push_back(now);
			}
		}
	}
	REP(i,1,tot)if(!vis[i])dfs(i);
	REP(i,1,tot)ok[i]&=!dis[i];

	REP(i,1,tot)ed[i].clear(),dis[i]=vis[i]=0;
	REP(dx,1,sqrt(D2))
	{
		int dy=sqrt(D2-dx*dx);
		if(dy*dy+dx*dx==D2)
		{
			REP(i,0,2*n-1)REP(j,0,2*n-1)
			{
				int now=num[i][j];
				if(i+dx<2*n && j+dy<2*n && num[i+dx][j+dy])ed[now].push_back(num[i+dx][j+dy]),ed[num[i+dx][j+dy]].push_back(now);
				if(i+dx<2*n && j-dy>=0 && num[i+dx][j-dy])ed[now].push_back(num[i+dx][j-dy]),ed[num[i+dx][j-dy]].push_back(now);
			}
		}
	}
	REP(i,1,tot)if(!vis[i])dfs(i);
	REP(i,1,tot)ok[i]&=!dis[i];
	int num=n*n;
	REP(i,1,tot)
	{
		if(ok[i] && num>0)
		{
			printf("%d %d\n",(i-1)/(2*n),(i-1)%(2*n));
			--num;
		}
	}
}

int main()
{
	init();
	doing();
	return 0;
}

