vector<vector<int>> make_graph(int n, int d){
  int w = ceil( sqrt(d) );
  vector<vector<int>> g(n*n*4);
  for(int i=0; i<2*n; i++) for(int j=0; j<2*n; j++){
    for(int y=max(i-w, 0); y<min(i+w+1, 2*n); y++){
      int dy = i-y;
      int dx = d - dy*dy;
      if(dx < 0) continue;
      dx = sqrt(dx);
      if( dx*dx + dy*dy != d ) continue;
      int x = j+dx;
      if( 0<=x && x<2*n ){
        g[ i*2*n + j ].push_back( y*2*n + x );
      }
      x = j-dx;
      if( dx!=0 && 0<=x && x<=2*n ){
        g[ i*2*n + j ].push_back( y*2*n + x );
      }
    }
  }

  return g;
}

