#include <cmath>

void body() {
    auto N = read<i64>();
    auto D1 = read<i64>();
    auto D2 = read<i64>();

    SimpleAdjacencyList g_1(4 * N * N);
    SimpleAdjacencyList g_2(4 * N * N);

    auto to_id = [N](i64 x, i64 y) -> i64 {
        if (x < 0 || x >= 2 * N) return -1;
        if (y < 0 || y >= 2 * N) return -1;
        return 2 * N * x + y;
    };
    auto to_p = [N](i64 id) -> pair<i64, i64> {
        i64 y = id % (2 * N);
        i64 x = (id - y) / (2 * N);
        return make_pair(x, y);
    };

    // グラフの構築
    auto add_edge = [&](auto &g, auto s, auto t, auto i, auto j) {
        auto f = [&](auto from, auto to) {
            if (to < 0) return ;
            g.add_edge(make_tuple(from, to));
        };
        f(to_id(s, t), to_id(s+i, t+j));
        f(to_id(s, t), to_id(s+i, t-j));
        if (i != 0) {
            f(to_id(s, t), to_id(s-i, t+j));
            f(to_id(s, t), to_id(s-i, t-j));
        }
        f(to_id(s, t), to_id(s+j, t+i));
        f(to_id(s, t), to_id(s-j, t+i));
        if (i != 0) {
            f(to_id(s, t), to_id(s+j, t-i));
            f(to_id(s, t), to_id(s-j, t-i));
        }
        if (s != t) {
            f(to_id(t, s), to_id(t+i, s+j));
            f(to_id(t, s), to_id(t+i, s-j));
            if (i != 0) {
                f(to_id(t, s), to_id(t-i, s+j));
                f(to_id(t, s), to_id(t-i, s-j));
            }
            f(to_id(t, s), to_id(t+j, s+i));
            f(to_id(t, s), to_id(t-j, s+i));
            if (i != 0) {
                f(to_id(t, s), to_id(t+j, s-i));
                f(to_id(t, s), to_id(t-j, s-i));
            }
        }
    };

    REP (s, 2 * N) {
        FOR (t, s, 2 * N) {
            REP (i, 2 * N) {
                if (D1 - i * i < 0 && D2 - i * i < 0) break;
                i64 j_1 = static_cast<i64>(std::sqrt(D1 - i * i));
                i64 j_2 = static_cast<i64>(std::sqrt(D2 - i * i));

                if (j_1 < i && j_2 < i) break;

                if (j_1 >= i && i * i + j_1 * j_1 == D1) {
                    add_edge(g_1, s, t, i, j_1);
                }

                if (j_2 >= i && i * i + j_2 * j_2 == D2) {
                    add_edge(g_2, s, t, i, j_2);
                }
            }
        }
    }

    // 彩色
    Vector<i64> V1(4 * N * N, 0);
    REP (id, 4 * N * N) {
        if (V1[id] != 0) continue;

        std::stack<pair<i64, i64>> s;
        s.emplace(-1, id);
        while (!s.empty()) {
            auto elem = s.top();
            s.pop();
            auto prev = elem.first;
            auto x = elem.second;

            if (V1[x] != 0) {
                continue;
            }

            if (prev == -1) {
                V1[x] = 1;
            } else {
                V1[x] = -V1[prev];
            }

            EACH_V (edge, g_1.outgoings(x)) {
                s.emplace(get<0>(edge), get<1>(edge));
            }
        }
    }

    Vector<i64> V2(4 * N * N, 0);
    REP (id, 4 * N * N) {
        if (V2[id] != 0) continue;

        std::stack<pair<i64, i64>> s;
        s.emplace(-1, id);
        while (!s.empty()) {
            auto elem = s.top();
            s.pop();
            auto prev = elem.first;
            auto x = elem.second;

            if (V2[x] != 0) continue;

            if (prev == -1) {
                V2[x] = 1;
            } else {
                V2[x] = -V2[prev];
            }

            EACH_V (edge, g_2.outgoings(x)) {
                s.emplace(get<0>(edge), get<1>(edge));
            }
        }
    }

    auto dump = [&](auto v1, auto v2) -> bool {
        Vector<pair<i64, i64>> ps;
        REP (i, 4 * N * N) {
            if (V1[i] == v1 && V2[i] == v2) {
                ps.push_back(to_p(i));
                if (ps.size() >= N * N) {
                    break;
                }
            }
        }
        if (ps.size() >= N * N) {
            REP (i, N * N) {
                auto p = ps[i];
                cout << p.first << " " << p.second << endl;
            }
            return true;
        }
        return false;
    };

    // よい集合の抽出
    if (dump(1, 1)) {
        return ;
    }
    if (dump(1, -1)) {
        return ;
    }
    if (dump(-1, 1)) {
        return ;
    }
    if (dump(-1, 1)) {
        return;
    }
}

