bool check(int y, int x) {
	int xy = y + x;

	for (int sx = 0; sx <= xy; sx++) {
		if (sx >= 2 * n) break;
		if (d1 >= (x - sx) * (x - sx)) {
			int dy = Sqrt[d1 - (x - sx) * (x - sx)];
			if (dy >= 0 && y - dy >= 0 && s[y - dy][sx] == 'o') return false;
			if (dy >= 0 && y + dy < 2 * n && s[y + dy][sx] == 'o') return false;
		}
		if (d2 >= (x - sx) * (x - sx)) {
			int dy = Sqrt[d2 - (x - sx) * (x - sx)];
			if (dy >= 0 && y - dy >= 0 && s[y - dy][sx] == 'o') return false;
			if (dy >= 0 && y + dy < 2 * n && s[y + dy][sx] == 'o') return false;
		}
	}
	return true;
}

bool dfs(int x, int y, int xy, int cnt) {
	if (x == 2 * n) {
		if (cnt < n * n) return false;
		int i, j;
		/*for (i = 0; i < 2 * n; i++) {
			for (j = 0; j < 2 * n; j++)
				cout << s[i][j];
			cout << endl;
		}*/
		return true;
	}

	int nx = x - 1;
	int ny = y + 1;
	int nxy = xy;
	if (nx == -1) { nx = xy + 1; ny = 0; nxy = xy + 1; }

	//s[y][x]を決める.
