#define pii pair<int,int>
#define fi first
#define se second

int deg[444444], bk[444444], die[444444];
priority_queue<pii,vector<pii>,greater<pii> >q;
void gao(){
	ans.clear(); memset(in,0,sizeof in);
	for (int i=0;i<n*n;++i) bk[vec[i]]=i;
	while (q.size()) q.pop();
	for (int i=0;i<n*n;++i){
		deg[i]=G[vec[i]].size();
		q.push({deg[i],i});
	}
	memset(die,0,sizeof die);
	while (!q.empty()){
		pii p=q.top(); q.pop(); if (deg[p.se]!=p.fi||die[p.se]>>1) continue;
		//printf(" %d %d\n",p.fi,p.se);{ string s; cin>>s; }
		if (!die[p.se]){
			ans.push_back(p.se);
			for (auto y:G[vec[p.se]]){
				if (die[bk[y]]>>1) continue;
				die[bk[y]]|=1;
				--deg[bk[y]];
				q.push({deg[bk[y]],bk[y]});
			}
		}else{
			for (auto y:G[vec[p.se]]){
				if (die[bk[y]]>>1) continue;
				--deg[bk[y]];
				q.push({deg[bk[y]],bk[y]});
			}
