using ll = long long;
using vi = vector<int>;
using vvi = vector<vi>;
using vll = vector<ll>;
using vvll = vector<vll>;
using vb = vector<bool>;
using vs = vector<string>;

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int N, D1, D2;
    cin >> N >> D1 >> D2;

    int V = 2 * 2 * N * N;
    vvi adj(V);

    for (int D : { D1, D2 }) {
        vi root(D + 1, -1);
        for (int rt = 0; rt * rt <= D; rt++)
            root[rt * rt] = rt;

        for (int i = 0; i < V; i++) {
            int x1 = i % (2 * N), y1 = i / (2 * N);
            for (int dx = 0; dx < 2 * N; dx++) {
                if (dx * dx > D) break;
                int dy = root[D - dx * dx];
                if (dy == -1) continue;

                if (x1 - dx >= 0 && y1 - dy >= 0) adj[i].push_back(x1 - dx + (2 * N) * (y1 - dy));
                if (x1 - dx >= 0 && y1 + dy < 2*N) adj[i].push_back(x1 - dx + (2 * N) * (y1 + dy));
                if (x1 + dx < 2*N && y1 - dy >= 0) adj[i].push_back(x1 + dx + (2 * N) * (y1 - dy));
                if (x1 + dx < 2*N && y1 + dy < 2*N) adj[i].push_back(x1 + dx + (2 * N) * (y1 + dy));
            }
        }
    }

    vi order(V);
    for (int i = 0; i < V; i++) {
        order[i] = i;
    }

    while (true) {
        shuffle(all(order), rng);

        vi pick;
        vb taken(V);
        for (int i = 0; i < V && pick.size() < V / 4; i++) {
            bool take = true;
            for (int j : adj[i]) {
                if (taken[j]) {
                    take = false;
                    break;
                }
            }
            if (take) {
                pick.push_back(i);
                taken[i] = true;
            }
        }
        if (pick.size() == V / 4) {
            for (int v : pick) {
                cout << v % (2 * N) << " " << v / (2 * N) << "\n";
            }
            return 0;
        }
    }

    assert(false);
    return 0;
}

