inline void add_edge(int a, int b, int x, int y)
{
	if(x < 0 || x >= n+n || y < 0 || y >= n+n)
		return;
	v[node[a][b]].pb(node[x][y]);
	return;
}

void bfs(int cur)
{
	pii z;
	while(!q.empty())
		q.pop();
	vis[cur] = 1;
	q.push({cur,0});
	while(!q.empty())
	{
		z = q.front();
		q.pop();
		temp[z.S].pb(val[z.F]);
		for(auto x : v[z.F])
			if(!vis[x])
			{
				vis[x] = 1;
				q.push({x,1-z.S});
			}
	}
	return;
}

void solve()
{
	int d1, d2, i, j, d, cnt = 0, aa;
	cin >> n >> d1 >> d2;
	aa = n*n;
	fo(i,0,n+n)
		fo(j,0,n+n)
		{
			int d = i*i + j*j;
			if(d == d1 || d == d2)
				arr.pb({i,j});
		}
	fo(i,0,n+n)
		fo(j,0,n+n)
		{
			node[i][j] = cnt;
			val[cnt] = {i,j};
			cnt++;
		}
	fo(i,0,n+n)
		fo(j,0,n+n)
			for(auto x : arr)
			{
				add_edge(i,j,i+x.F,j+x.S);
				add_edge(i,j,i+x.F,j-x.S);
				add_edge(i,j,i-x.F,j+x.S);
				add_edge(i,j,i-x.F,j-x.S);
			}
	fo(i,0,cnt)
		if(!vis[i])
		{
			temp[0].clear();
			temp[1].clear();
			bfs(i);
			if(sz(temp[0]) >= sz(temp[1]))
			{
				for(auto x : temp[0])
					ans.pb(x);
			}
			else
			{
				for(auto x : temp[1])
					ans.pb(x);
			}
			if(sz(ans) >= aa)
				break;
		}
	assert(sz(ans) >= aa);
	fo(i,0,aa)
		cout << ans[i].F << " " << ans[i].S << '\n';
	return;
}

