const int max_n = 303, max_sq = 200222, inf = 1000111222;

int n, d1, d2, sq[max_sq], used[2 * max_n][2 * max_n];
vector<int> dx, dy;

void add(int x, int y) {
    if (abs(x) < 2 * n && abs(y) < 2 * n) {
        dx.push_back(x);
        dy.push_back(y);
    }
}

void add(int d) {
    for (int x = -500; x <= 500; ++x) {
        if (x * x <= d) {
            int y = d - x * x;
            if (sq[y]) {
                add(x, sq[y] - 1);
                if (sq[y] - 1) {
                    dx.push_back(x);
                    dy.push_back(1 - sq[y]);
                }
            }
        }
    }
}

bool is_in(int x, int y) {
    return 0 <= x && 0 <= y && x < 2 * n && y < 2 * n;
}

void dfs(int x, int y) {
    used[x][y] = 1;
    for (int i = 0; i < dx.size(); ++i) {
        if (is_in(x + dx[i], y + dy[i])) {
            used[x + dx[i]][y + dy[i]] = 2;
        }
    }
    for (int i = 0; i < dx.size(); ++i) {
        int nx = x + dx[i], ny = y + dy[i];
        if (is_in(nx, ny)) {
            for (int j = 0; j < dx.size(); ++j) {
                int tox = nx + dx[j], toy = ny + dy[j];
                if (is_in(tox, toy) && used[tox][toy] == 0) {
                    dfs(tox, toy);
                    break;
                }
            }
        }
    }
}

vector<pair<int, int>> solve() {
    srand(time(NULL));
    dx.clear();
    dy.clear();
    add(d1);
    add(d2);
    vector<pair<int, int>> ans, all;
    for (int i = 0; i < 2 * n; ++i) {
        for (int j = 0; j < 2 * n; ++j) {
            used[i][j] = 0;
            all.push_back({i, j});
        }
    }
    //random_shuffle(all.begin(), all.end());
    for (const auto &p : all) {
        if (used[p.first][p.second] == 0) {
            dfs(p.first, p.second);
        }
    }
    /*for (int i = 0; i < 2 * n; ++i) {
        for (int j = 0; j < 2 * n; ++j) {
            if (used[i][j] == 0) {
                dfs(i, j);
            }
        }
    }*/
    for (int i = 0; i < 2 * n; ++i) {
        for (int j = 0; j < 2 * n; ++j) {
            if (used[i][j] == 1) {
                ans.push_back({i, j});
                if (ans.size() == n * n) {
                    return ans;
                }
            }
        }
    }
    //cout << ans.size() << " " << n * n << endl;
    return {};
}

