int n, cnt, d[MAX_N][MAX_N];
pii tail[MAX_N], prv[MAX_N][MAX_N], nxt[MAX_N][MAX_N];
int erfen(int x) {
    int L = 0, R = sqrt(x) + 100, ans = 0;
    while (L <= R) {
        int mid = (L + R) / 2;
        if (mid * mid <= x) {
            ans = mid;
            L = mid + 1;
        }
        else R = mid - 1;
    }
    return ans;
}
void add(int pos, pii x) {
    //printf("Debug : add(%d, (%d, %d))\n", pos, x.fi, x.se);
    prv[x.fi][x.se] = tail[pos];
    if (tail[pos].fi != -1) nxt[tail[pos].fi][tail[pos].se] = x;
    tail[pos] = x;
    //printf("pos = %d\n", pos);
    //printf("prv = %d, %d; self = %d, %d, nxt = %d, %d\n", prv[x.fi][x.se].fi, prv[x.fi][x.se].se, x.fi, x.se, nxt[x.fi][x.se].fi, nxt[x.fi][x.se].se);
}
void del(int pos, pii x) {
    //printf("Debug : del(%d, (%d, %d))\n", pos, x.fi, x.se);
    if (prv[x.fi][x.se].fi != -1) {
        pii y = prv[x.fi][x.se];
        nxt[y.fi][y.se] = nxt[x.fi][x.se];
    }
    if (nxt[x.fi][x.se].fi != -1) {
        pii y = nxt[x.fi][x.se];
        prv[y.fi][y.se] = prv[x.fi][x.se];
    }
    else tail[pos] = prv[x.fi][x.se];
    prv[x.fi][x.se] = pr(-1, -1);
    nxt[x.fi][x.se] = pr(-1, -1);
    //printf("tail after del : %d, %d\n", tail[pos].fi, tail[pos].se);
    //printf("prv = %d, %d; self = %d, %d, nxt = %d, %d\n", prv[x.fi][x.se].fi, prv[x.fi][x.se].se, x.fi, x.se, nxt[x.fi][x.se].fi, nxt[x.fi][x.se].se);
}
void down(int i, int j) {
    //printf("Debug : down(%d, %d)\n", i, j);
    if (i < 0 || i >= 2 * n) return;
    if (j < 0 || j >= 2 * n) return;
    if (vis[i][j]) return;
    del(d[i][j], pr(i, j));
    d[i][j]--;
    add(d[i][j], pr(i, j));
}
void connect(int i, int j) {
    //printf("Debug : connect(%d, %d)\n", i, j);
    if (i < 0 || i >= 2 * n) return;
    if (j < 0 || j >= 2 * n) return;
    if (vis[i][j]) return;
    vis[i][j] = true;
    del(d[i][j], pr(i, j));
    for (int k = 0; k < mp.size(); k++) {
        int x = mp[k].fi, y = mp[k].se;
        down(i + x, j + y);
        if (x != 0) down(i - x, j + y);
        if (y != 0) down(i + x, j - y);
        if (x != 0 && y != 0) down(i - x, j - y);
    }
}
int main() {
    int d_1, d_2, rt_1, rt_2;
    scanf("%d%d%d", &n, &d_1, &d_2);
    for (int i = 0; i < 600; i++) tail[i] = pr(-1, -1);
    for (int i = 0; i < n * 2; i++) {
        for (int j = 0; j < n * 2; j++) {
            prv[i][j] = pr(-1, -1);
            nxt[i][j] = pr(-1, -1);
        }
    }
    rt_1 = erfen(d_1), rt_2 = erfen(d_2);
    for (int i = 0; i <= rt_1; i++) {
        int x = d_1 - i * i;
        if (i * i > x) break;
        int y = erfen(x);
        if (y * y == x) {
            mp.pb(pr(i, y));
            if (i != y) mp.pb(pr(y, i));
        }
    }
    if (d_1 != d_2) {
        for (int i = 0; i <= rt_2; i++) {
            int x = d_2 - i * i;
            if (i * i > x) break;
            int y = erfen(x);
            if (y * y == x) {
                mp.pb(pr(i, y));
                if (i != y) mp.pb(pr(y, i));
            }
        }
    }
    for (int i = 0; i < n * 2; i++) {
        for (int j = 0; j < n * 2; j++) {
            for (int k = 0; k < mp.size(); k++) {
                int x = mp[k].fi, y = mp[k].se, tx, ty;
                tx = i + x, ty = j + y;
                if (tx >= 0 && tx < 2 * n && ty >= 0 && ty < 2 * n)  d[i][j]++;
                if (x != 0) {
                    tx = i - x, ty = j + y;
                    if (tx >= 0 && tx < 2 * n && ty >= 0 && ty < 2 * n)  d[i][j]++;
                }
                if (y != 0) {
                    tx = i + x, ty = j - y;
                    if (tx >= 0 && tx < 2 * n && ty >= 0 && ty < 2 * n)  d[i][j]++;
                }
                if (x != 0 && y != 0) {
                    tx = i - x, ty = j - y;
                    if (tx >= 0 && tx < 2 * n && ty >= 0 && ty < 2 * n)  d[i][j]++;
                }
            }
            cnt = max(cnt, d[i][j]);
            //printf("!!!%d\n", d[i][j]);
            add(d[i][j], pr(i, j));
        }
    }
    while (ans.size() < n * n) {
        for (int i = 0; i <= cnt; i++) {
            if (tail[i].fi != -1) {
                pii p = tail[i];
                //printf("Debug : valid(%d, %d)\n", p.fi, p.se);
                del(i, p);
                ans.pb(p);
                vis[p.fi][p.se] = true;
                for (int k = 0; k < mp.size(); k++) {
                    int x = mp[k].fi, y = mp[k].se;
                    connect(p.fi + x, p.se + y);
                    if (x != 0) connect(p.fi - x, p.se + y);
                    if (y != 0) connect(p.fi + x, p.se - y);
                    if (x != 0 && y != 0) connect(p.fi - x, p.se - y);
                }
                break;
            }
        }
    }
    for (int i = 0; i < ans.size(); i++) {
        printf("%d %d\n", ans[i].fi, ans[i].se);
    }
    return 0;
}

