void check(int x,int y,int d)
{
	int b=-2*y,c,t,t2;
	for(int i=0;i<=m;++i)
	{
		c=y*y-d-2*i*x+i*i+x*x;
		t=b*b-4*c;
		if(t<0)
			continue;
		t2=sqrt(t);
		if(t2*t2!=t)
			continue;
		t=-b+t2;
		if(0<=t&&!(t&1)&&(t>>=1)<=m)
			mp[i][t]=false;
		t=-b-t2;
		if(0<=t&&!(t&1)&&(t>>=1)<=m)
			mp[i][t]=false;
	}
}

