void boji(T c, U& s, int x, int y) {
	for (auto p : s)
		for (int dx=-1; dx<=1; dx+=2)
			for (int dy=-1; dy<=1; dy+=2) {
				int xx = x + dx*p.first;
				int yy = y + dy*p.second;

