int tr[4000005],pos[1000005];
void build(int u,int L,int R) {
	if(L == R) {tr[u] = L - 1;pos[L - 1] = u;return;}
	int mid = (L + R) >> 1;
	build(u << 1,L,mid);build(u << 1 | 1,mid + 1,R);
	tr[u] = cmax(tr[u << 1],tr[u << 1 | 1]);
}
void Change(pii u) {
	int t = pos[u.fi * 2 * N + u.se] >> 1;
	while(t) {
		tr[t] = cmax(tr[t << 1],tr[t << 1 | 1]);
		t >>= 1;
	}
}
