    pq.pop();
    if (used[id]) {
      continue;
    }
    int x = id / (2 * n), y = id % (2 * n);
    ans.push_back(make_pair(x, y));
    used[id] = true;
    for (int i = 0; i < sz(g[id]); i++) {
      int nid = g[id][i];
      if (!used[nid]) {
        for (int j = 0; j < sz(g[nid]); j++) {
          int nnid = g[nid][j];
          if (!used[nnid]) {
            deg[nnid]--;
            pq.push(make_pair(make_pair(deg[nnid], dist[nnid]), nnid));
          }
        }
      }
      used[nid] = true;
    }
  }
  return true;
}

