      while ((y + 1) * (y + 1) <= y2) {
        y++;
      }
      if (y * y != y2) {
        continue;
      }
      vs.push_back(make_pair(x, y));
      vs.push_back(make_pair(x, -y));
      vs.push_back(make_pair(-x, y));
      vs.push_back(make_pair(-x, -y));
    }
  }
  sort(vs.begin(), vs.end());
  vs.erase(unique(vs.begin(), vs.end()), vs.end());
