			if (j != -1 && (Exist(r - i, c - j) || Exist(r - i, c + j) || Exist(r + i, c - j) || Exist(r + i, c + j)))
				return false;
		}
		if (i * i <= d2) {
			int j = sqr[d2 - i * i];
			if (j != -1 && (Exist(r - i, c - j) || Exist(r - i, c + j) || Exist(r + i, c - j) || Exist(r + i, c + j)))
				return false;
		}
	}
	return true;
}

void Gen(int r, int c)
{
	if (slen >= n * n) {
		found = true;
		for (int i = 0; i < slen; i++)
			printf("%d %d\n", seq[i].first, seq[i].second);
		return;
	}
	if (c >= 2 * n) Gen(r + 1, 0);
	else if (r >= 2 * n) return;
	else {
		if (Check(r, c)) {
			seq[slen++] = ii(r, c); tk[r][c] = true;
			Gen(r, c + 1);
			slen--; tk[r][c] = false;
		}
		if (!found) Gen(r, c + 1);
	}
}

int main()
{
	fill(sqr, sqr + Maxn, -1);
	for (int i = 0; i * i < Maxn; i++)
		sqr[i * i] = i;
	cin >> n >> d1 >> d2;
	Gen(0, 0);
	return 0;
}

