int c2[N][N];
int cnt[2][2];

void add(vector<pii>& go, int dx, int dy)
{
	go.emplace_back(dx, dy);
	go.emplace_back(-dx, dy);
	go.emplace_back(dx, -dy);
	go.emplace_back(-dx, -dy);
}

bool in_f(int x, int y)
{
	return 0 <= x && x < 2 * n &&
		0 <= y && y < 2 * n;
}

void color(int x, int y, vector<pii>& go, int col[][N], int c)
{
	col[x][y] = c;
	for (auto g : go)
	{
		int dx, dy;
		tie(dx, dy) = g;
		int nx = x + dx;
		int ny = y + dy;
		if (!in_f(nx, ny) || col[nx][ny] != -1)
			continue;
		color(nx, ny, go, col, 1 - c);
	}
}

void solve()
{
	scanf("%d%d%d", &n, &d1, &d2);
	memset(c1, -1, sizeof c1);
	memset(c2, -1, sizeof c2);
	vector<pii> go1, go2;
	for (int dx = 0; dx < 2 * n; ++dx)
		for (int dy = 0; dy < 2 * n; ++dy)
			if (dx * dx + dy * dy == d1)
				add(go1, dx, dy);
			else if (dx * dx + dy * dy == d2)
				add(go2, dx, dy);
	for(int x = 0; x < 2 * n; ++x)
		for (int y = 0; y < 2 * n; ++y)
		{
			if (c1[x][y] == -1)
				color(x, y, go1, c1, 0);
			if (c2[x][y] == -1)
				color(x, y, go2, c2, 0);
			++cnt[c1[x][y]][c2[x][y]];
		}
	int d1 = 0;
	int d2 = 0;
	for (int i : {0, 1})
		for (int j : {0, 1})
			if (cnt[i][j] > cnt[d1][d2])
			{
				d1 = i;
				d2 = j;
			}
	int count = 0;
	for (int x = 0; x < 2 * n; ++x)
		for (int y = 0; y < 2 * n; ++y)
			if (c1[x][y] == d1 && c2[x][y] == d2 && count < n * n)
			{
				printf("%d %d\n", x, y);
				++count;
			}
}

