	graph_m.reserve(edge_count);
	weights_m.reserve(edge_count);
}

template<class T>
void WeightedGraph<T>::add(int from, int to, T&& weight, bool directed) {
	if (!directed) {
		add(from, to, std::move(weight), true);
		add(to, from, std::move(weight), true);
		return;
	}

	graph_m.add(from, to);
	weights_m.push_back(std::move(weight));
}

template<class T>
void WeightedGraph<T>::add(int from, int to, const T& weight, bool directed) {
	if (!directed) {
		add(from, to, weight, true);
		add(to, from, weight, true);
		return;
	}

	graph_m.add(from, to);
	weights_m.push_back(weight);
}

