int N;
int A, B;

int ver(int i, int j) {
	return i * 2 * N + j;
}

vector<bool> sub(int d) {
	Graph g(4 * N * N);

	vector<PP> ps;
	REP(x, 0, N + 1) {
		int y_sqr = d - x * x;
		if (y_sqr < 0) continue;
		int y = sqrt(y_sqr) + 0.5;
		if (x * x + y * y != d) continue;
		ps.push_back(PP(x, y));
	}

	REP(i, 0, 2 * N) {
		REP(j, 0, 2 * N) {
			for (const PP& p : ps) {
				for (int s : { 1, -1 }) {
					for (int t : { 1, -1 }) {
						int ni = i + s * p.first;
						int nj = j + t * p.second;
						if (!Inside(ni, nj, 2 * N, 2 * N)) continue;
						g.add(ver(i, j), ver(ni, nj), false);
					}
				}
			}
		}
	}

	return colorBipartiteGraph(g);
}

int main() {
	cin >> N >> A >> B;
	auto v = sub(A);
	auto w = sub(B);

	for (int s : { 0, 1 }) {
		for (int t : { 0, 1 }) {
			int cnt = 0;
			REP(i, 0, v.size()) {
				if (v[i] == s && w[i] == t) {
					++cnt;
				}
			}

			if (cnt >= N * N) {
				int cur = 0;
				REP(i, 0, v.size()) {
					if (v[i] == s && w[i] == t) {
						int x = i / (2 * N);
						int y = i % (2 * N);
						cout << x << ' ' << y << endl;
						++cur;
						if (cur == N * N) {
							break;
						}
					}
				}
				return 0;
			}
		}
	}
	return 0;
}

