					if (sqrt(w - k * k)*sqrt(w - k * k) == (w - k * k)*(w - k * k)) {
						f[i + k][j + (LL)sqrt(w - k * k)] = 1;
						if (i - k >= 0)
							f[i - k][j + (LL)sqrt(w - k * k)] = 1;
						if (j - (LL)sqrt(w - k * k) >= 0)
							f[i + k][j - (LL)sqrt(w - k * k)] = 1;
						if (j - (LL)sqrt(w - k * k) >= 0 && i - k >= 0)
							f[i - k][j - (LL)sqrt(w - k * k)] = 1;
					}
				}
				rep(k, n * 2) {
					if (sqrt(h - k * k)*sqrt(h - k * k) == (h - k * k)*(h - k * k)) {
						f[i + k][j + (LL)sqrt(h - k * k)] = 1;
						if (i - k >= 0)
							f[i - k][j + (LL)sqrt(h - k * k)] = 1;
						if (j - (LL)sqrt(h - k * k) >= 0)
							f[i + k][j - (LL)sqrt(h - k * k)] = 1;
						if (j - (LL)sqrt(h - k * k) >= 0 && i - k >= 0)
							f[i - k][j - (LL)sqrt(h - k * k)] = 1;
					}
				}
			}
		}
	}
	rep(i, n*n) {
		cout << v[i].fir << " " << v[i].sec << endl;
	}
	return 0;
}

