int evenp (int d) {
  int ans = 0;
  while (d % 2 == 0) {
    ans++;
    d /= 2;
  }
  return ans;
}

bool fits (int x, int y, int d) {
  if (d % 2 == 0) {
    int pd = 1 << (d / 2);
    return (x / pd + y / pd) % 2 == 0;
  } else {
    int pd = 1 << ((d - 1) / 2);
    return (x / pd) % 2 == 0;
  }
}

int main () {
  ios::sync_with_stdio(false);

  int n, d1, d2;
  cin >> n >> d1 >> d2;

