  d2 = evenp(d2);

  vector<pair<int, int>> ans;
  for (int i = 0; i < 2 * n; i++) {
    for (int j = 0; j < 2 * n; j++) {
      if (fits(i, j, d1) && fits(i, j, d2)) {
        ans.push_back(make_pair(i, j));
      }
    }
  }

  while ((int) ans.size() > n * n) {
    ans.pop_back();
  }

  for (auto pr : ans) {
    cout << pr.first << " " << pr.second << '\n';
  }
}

