    REP(i, rd2) REP(j,rd2) if(i*i+j*j == d2) {
        db2.eb(i,j);
        db2.eb(i,-j);
        db2.eb(-i,j);
    }

    //cout << "0 0" << endl;
    table[0][0] = imos[0][0] = imos[n*2][n*2] = 1;
    imos[0][n*2] = imos[n*2][0] = -1;
    for (auto i: db1) taboo.push(i);
    for (auto i: db2) taboo.push(i);
    y++;
    ctr++;
    while (x < 3*n){
        //cerr << "debug: " <<  x << " " << y << endl;
        while(!taboo.empty() && taboo.top() < mp(x,y)) taboo.pop();
        if (taboo.empty() || taboo.top() != mp(x,y)){
            //cout << x << " " << y << endl;
            table[x][y]++;
            imos[x][y]++;
            imos[x+n*2][y]--;
            imos[x][y+n*2]--;
            imos[x+n*2][y+n*2]++;

            for (auto i: db1) {
                ix = i.first;
