                taboo.push(mp(ix+x,iy+y));
            }
            ctr++;
        }
        y++;
        if(y == 3*n){ y = 0; x++; }
    }

    FOR(i,1,5*n){
        REP(j,5*n){
            imos[i][j] += imos[i-1][j];
        }
    }    
    int offi,offj;
    REP(i,5*n){
        FOR(j,1,5*n){
            imos[i][j] += imos[i][j-1];
            if (i > 2*n && j > 2*n && imos[i][j] >= n*n ){
                offi = i-2*n;
                offj = j-2*n;
                goto OUTER;
            }
        }
    }
    OUTER:
    ctr = 0;
    FOR(i,offi,offi+2*n){
        FOR(j,offj,offj+2*n){
            if(table[i][j]) {
                cout << i-offi << " " << j-offj << endl;
                ctr++;
            }
            if(ctr == n*n) return 0;
        }
    }

}

