std::deque<std::pair<long long, long long>> find_py(long long a) {
    std::deque<std::pair<long long, long long>> ret;
    for (auto i = 0ll; i <= std::sqrt(a) + 1; i++) {
        for (auto j = 0ll; j <= std::sqrt(a) + 1; j++) {
            if (i * i + j * j == a) ret.push_back({i, j});
        }
    }
    return ret;
}

int main() {
    long long n, d1, d2;
    std::cin >> n >> d1 >> d2;
    std::deque<std::pair<long long, long long>> c;
    std::set<std::pair<long long, long long>> candidates;
    for (int i = 0; i < 2 * n; i++) {
        for (int j = 0; j < 2 * n; j++) candidates.insert({i, j});
    }

    auto p1 = find_py(d1), p2 = find_py(d2);

    for (auto i = 0ll; i < n * n; i++) {
        auto curr = *candidates.begin();
        c.push_back(curr);
        candidates.erase(candidates.begin());
        for (auto& el : p1) {
            auto it = candidates.find({curr.first + el.first, curr.second + el.second});
            if (it != candidates.end()) candidates.erase(it);
            it = candidates.find({curr.first + el.first, curr.second - el.second});
            if (it != candidates.end()) candidates.erase(it);
        }
        for (auto& el : p2) {
            auto it = candidates.find({curr.first + el.first, curr.second + el.second});
            if (it != candidates.end()) candidates.erase(it);
            it = candidates.find({curr.first + el.first, curr.second - el.second});
            if (it != candidates.end()) candidates.erase(it);
        }
    }

    for (auto& p : c) std::cout << p.first << " " << p.second << std::endl;

    return 0;
}

