void check(int d,int kind)
{
	for (int i=0;i<=1000;i++)
	{
		if (p[i]>d) continue;
		int pos=lower_bound(p,p+1001,d-p[i])-p;
		if (p[pos]+p[i]==d)
		{
			f[kind].push_back(m_k(pos,i));
			f[kind].push_back(m_k(pos,-i));
			f[kind].push_back(m_k(-pos,i));
			f[kind].push_back(m_k(-pos,-i));
		}
	}
}
bool judge(int x,int y)
{
	if (x<0 || y<0 || x>=2*n || y>=2*n) return 0;
	return 1;
}
int id(int x,int y){return x*2*n+y+1;}
void dfs(int x,int y,int kind)
{
	for (int i=0;i<(int)f[kind].size();i++)
	{
		int nx=x+f[kind][i].first,ny=y+f[kind][i].second;
		if (!judge(nx,ny)) continue;
		if (vi[id(nx,ny)][kind]) continue;
		vi[id(nx,ny)][kind]=3-vi[id(x,y)][kind];
		dfs(nx,ny,kind);
	}
}
