    {
        for(int i = 0; i < 2 * n; ++i)
            for(int j = 0; j < 2 * n; ++j)
            {
                if((i + j) & 1)
                    a[i][j] = 1;
                else
                    a[i][j] = 0;
            }
    }
    else
        if(dist % 4 == 2)
        {
            for(int i = 1; i < 2 * n; i += 2)
                for(int j = 0; j < 2 * n; ++j)
                    a[i][j] = 1;
        }
        else
        {
            vector<vector<int> > a2 = go(n / 2, dist / 4);
