int mySqrt(int x) {
    if (x < 0) return -1;
    int y = sqrt(x);
    while (y * y < x) y++;
    while (y * y > x) y--;
    if (y * y != x) return -1;
    return y;
}

vector<pair<int, int>> solve(int n, int d1, int d2) {
    vector<pair<int, int>> v;
    for (int i = -n; i <= n; i++) {
        int j = mySqrt(d1 - i * i);
        if (j != -1) {
            v.push_back({i, j});
            if (j != 0) v.push_back({i, -j});
        }

        j = mySqrt(d2 - i * i);
        if (j != -1) {
            v.push_back({i, j});
            if (j != 0) v.push_back({i, -j});
        }
    }
    sort(v.begin(), v.end());

    vector<vector<vector<pair<int, int>>>> e(n * 2, vector<vector<pair<int, int>>>(n * 2));
    for (int x = 0; x < 2 * n; x++) {
        for (int y = 0; y < 2 * n; y++) {
            for (auto d : v) {
                int nx = x + d.first;
                int ny = y + d.second;
                if (0 <= nx && nx < 2 * n && 0 <= ny && ny < 2 * n) {
                    e[x][y].push_back({nx, ny});
                }
            }
        }
    }

    vector<vector<int>> deg(2 * n, vector<int>(2 * n));
    for (int i = 0; i < 2 * n; i++) for (int j = 0; j < 2 * n; j++) deg[i][j] = e[i][j].size();

    vector<vector<char>> ctaken(2 * n, vector<char>(n));
    set<pair<int, pair<int, int>>> st;
    for (int i = 0; i < 2 * n; i++) for (int j = 0; j < 2 * n; j++) st.insert({deg[i][j], {i, j}});

    auto del = [&](int x, int y) {
        st.erase({deg[x][y], {x, y}});
        deg[x][y] = INF;
        for (auto o : e[x][y]) {
            if (deg[o.first][o.second] != INF) {
                st.erase({deg[o.first][o.second], o});
                deg[o.first][o.second]--;
                st.insert({deg[o.first][o.second], o});
            }
        }
    };

    vector<pair<int, int>> cans;
    while (!st.empty()) {
        auto o = st.begin()->second;
        cans.push_back(o);
        del(o.first, o.second);
        for (auto no : e[o.first][o.second]) del(no.first, no.second);
    }

    if (cans.size() >= n * n) {
        cans.resize(n * n);
        return cans;
    }

    vector<pair<int, int>> p;
    for (int i = 0; i < n * 2; i++) for (int j = 0; j < n * 2; j++) p.push_back({i, j});
    while (1) {
        vector<vector<char>> taken(n * 2, vector<char>(n * 2));
        vector<pair<int, int>> ans;
        for (auto o : p) {
            bool ok = 1;
            for (auto np : e[o.first][o.second]) {
                if (taken[np.first][np.second]) {
                    ok = 0;
                    break;
                }
            }
            if (ok) {
                taken[o.first][o.second] = 1;
                ans.push_back(o);
            }
        }
        if (ans.size() >= n * n) {
            ans.resize(n * n);
            return ans;
        }
        random_shuffle(p.begin(), p.end());
    }
}

