using namespace std;

const int max_n = 1e3 + 5;

int n, d1, d2;

int dobre[605][605];

vector<PII> zle;

vector<PII> greedy(vector<PII> v) {
	vector<PII> w;
	w.clear();
		FOR(i,0,2*n) FOR(j,0,2*n) dobre[i][j] = 0;
		int kutas = 0;
		FOR(ii,0,4*n*n) {
			int i = v[ii].st;
			int j = v[ii].nd;
			if (dobre[i][j] == -1) continue;
			w.pb(mp(i,j));
			dobre[i][j] = 1;
			FOR(u,0,2) FOR(w,0,2) {
				FORE(z, zle) { 
						int ni = (2*u-1)*z->st + i;
						int nj = (2*w-1)*z->nd + j;
						if (ni >= 0 && nj >= 0 && ni<2*n && nj<2*n) {
							if (dobre[ni][nj] != -1) kutas++;
							dobre[ni][nj] = -1;
						}
				}
			}
			if (kutas > 3*n*n) continue;
			if (w.size() == n*n) return w;
		}
	return w;
}

int cmp1(PII a, PII b) {
	return (a.st+a.nd < b.st+b.nd);
}

int cmp2(PII a, PII b) {
	double d1 = abs(a.st-(n-0.5))+abs(a.nd-(n-0.5));
	double d2 = abs(b.st-(n-0.5))+abs(b.nd-(n-0.5));
	return d1 < d2;
}



bool proba() {
	if (d1%4 != 0 && d2%4!=0) {
