			printf("%d %d\n", 2*i, 2*j);
		}
		return true;
	}
	int k = 1; int l = 1;
	int p1 = 0;
	int p2 = 0;
	int d11 = d1; while (d11 % 4 == 0) { d11/=4; p1++;}
	int d22 = d2; while (d22 % 4 == 0) { d22/=4; p2++;}
	int x1 = (1<<p1); int x2 = (1<<p2);
	vector<PII> w;
	FOR(i,0,2*n) FOR(j,0,2*n) dobre[i][j] = 0;
	FOR(i,0,2*n) FOR(j,0,2*n) {
		if (i-x1>= 0 && dobre[i-x1][j] == 1) continue;
		if (j-x2>= 0 && dobre[i][j-x2] == 1) continue;
		dobre[i][j] = 1;
		w.pb(mp(i,j));
		if (w.size() == n*n) {
			FORE(i, w) {
				printf("%d %d\n", i->st, i->nd);
			}
			return true;	
		}
	}
}

