            }
        }
        return;
    }

    if (d1 % 3 > 0 && d2 % 3 > 0) {
        if (D) {
            cerr << n << " " << d1 << " " << d2 << " it = ez3\n";
            return;
        }
        int num = 0;
        for (int sum = 0; num < n * n; sum += 3) {
            for (int i = 0; i < m && num < n * n; i++) {
                int j = sum - i;
                if (j < 0 || j >= m) continue;
                num++;
                cout << i << " " << j << "\n";
            }
        }
        return;
    }

    int num = n * n;
    vector<pair<int, int>> v, badv;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            v.push_back(make_pair(i, j));
