            for (int j = 0; j < m; j++) {
                u[i][j] = false;
            }
        }

        int iq = -1;
        while (iq + 1 < (int)v.size()) {
            iq++;
            if (it > 1 && rand() % 50 == 0) {
                v.push_back(v[iq]);
                continue;
            }
            int xx = v[iq].second;
            int yy = v[iq].first;
            bool ok = true;

            for (auto w: badv) {
                for (int dir = 0; dir < 4; dir++) {
