void dfs(int x, int y, int n, const vector<pii> &dirs, vector<vector<bool>> &exist, vector<pii> & c0, vector<pii> &c1) {
  if (0 <= x && x < n && 0 <= y && y < n && exist[x][y]) {
    exist[x][y] = false;
    c0.push_back(pii(x, y));
    for (auto & dir : dirs) {
      int x1 = x + dir.first;
      int y1 = y + dir.second;
      dfs(x1, y1, n, dirs, exist, c1, c0);
    }
  }
}

vector<vector<bool>> build(vector<vector<bool>> exist, int d) {
  vector<pii> dir;
  int n = int(exist.size());
  for (int x = 0, y = n; x <= n; ++x) {
    while (y > 0 && x * x + y * y > d) { --y; }
    if (x * x + y * y == d) {
      dir.push_back(pii(x, y));
      if (x != 0) {
        dir.push_back(pii(-x, y));
      }
      if (y != 0) {
        dir.push_back(pii(x, -y));
      }
      if (x != 0 && y != 0) {
        dir.push_back(pii(-x, -y));
      }
    }
  }

  for (auto & d : dir) {
    //dbg("%d %d\n", d.first, d.second);
  }

  vector<vector<bool>> res(n, vector<bool>(n, false));
  for (int x = 0; x < n; ++x) {
    for (int y = 0; y < n; ++y) {
      if (!exist[x][y]) { continue; }
      vector<pii> c0, c1;
      dfs(x, y, n, dir, exist, c0, c1);
      if (c0.size() < c1.size()) {
        c0.swap(c1);
      }
      for (auto & p : c0) {
        res[p.first][p.second] = true;
      }
    }
  }
  return res;
}

bool solve() {
  int n, d1, d2;
  if (scanf("%d%d%d", &n, &d1, &d2) != 3) { return false; }
  vector<vector<bool>> exist(2 * n, vector<bool>(2 * n, true));
  exist = build(exist, d1);
  exist = build(exist, d2);
  int cnt = 0;
  for (int i = 0; i < 2 * n; ++i) {
    for (int j = 0; j < 2 * n; ++j) {
      if (exist[i][j] && cnt < n * n) {
        printf("%d %d\n", i, j);
        cnt++;
      }
    }
  }
  return true;  
}

int main() {
  while (solve());
  return 0;
}

