int board[610][610];

vector<pair<int, int>> calc(int D) {
	vector<pair<int, int>> ret;

	int limit = sqrt(D);
	rep(i, limit + 1) {
		int tmp = D - i * i;
		int tmp2 = sqrt(tmp);
		if (tmp2 * tmp2 == tmp) {
			ret.push_back(mp(i, tmp2));
		}
	}

	int n = ret.size();
	rep(i, n) {
		ret.push_back(mp(-ret[i].first, ret[i].second));
		ret.push_back(mp(ret[i].first, -ret[i].second));
		ret.push_back(mp(-ret[i].first, -ret[i].second));
	}

	return ret;
}

int N;

vector<pair<int, int>> ret;
set<pair<int, int>> st;

bool inBoard(int x, int y) {
	return x >= 0 && x < 2 * N && y >= 0 && y < 2 * N;
}

bool put(int x, int y) {
	if (board[y][x]) {
		return false;
	}

	ret.push_back(mp(x, y));

	board[y][x] = 1;

	for (auto &pr : st) {
		int nx = x + pr.first;
		int ny = y + pr.second;
		if (!inBoard(nx, ny)) continue;
		board[ny][nx] = 2;
	}

	return true;
}

char hoge(int num) {
	if (num == 0) return '.';
	if (num == 1) return 'o';
	return 'x';
}

void display() {
	cerr << "--" << endl;
	rep(y, 2 * N) {
		rep(x, 2 * N) cerr << hoge(board[y][x]);
		cerr << endl;
	}
}

void dfs(int x, int y) {
	if (board[y][x]) return;

	if (!put(x, y)) return;

	rep(dir, 4) {
		int nx = x + dx[dir];
		int ny = y + dy[dir];
		if (!inBoard(nx, ny)) continue;
		if (board[ny][nx]) continue;
		dfs(nx, ny);
	}
}

bool solve(int N, int D1, int D2) {
	ret.clear();
	memset(board, 0, sizeof board);

	vector<pair<int, int>> tmp = calc(D1);
	for (auto &pr : tmp) st.insert(pr);
	tmp = calc(D2);
	for (auto &pr : tmp) st.insert(pr);

	if (N == 1) {
		put(0, 0);
	} else {
		rep(y, 2 * N) rep(x, 2 * N) {
			if (board[y][x]) continue;
			dfs(x, y);
		}
	}

	return ret.size() >= N * N;
}

