vector < pair<int,int> > Do(vector < pair<int,int> > v, int d)
{
    vector < pair<int,int> > dis ;
    for(int i=0 ; i*i <= d ; i++)
    {
        int j = sqrt( d - i*i ) ;
        for( int k = max(j-2,0) ; k<=j+2 ; k++ )
        {
            if( k*k + i*i == d ) j = k ;
        }
        if( j*j + i*i == d ) dis.pb(mp(i,j)) ;
    }

//    for(auto dd: dis) printf("%d: %d %d\n",d,dd.xx,dd.yy) ;

    memset(Map,0,sizeof(Map)) ;

    for(int i=0 ; i<v.size() ; i++)
    {
        Map[ v[i].xx ][ v[i].yy ] = i+1 ;
        g[i+1].clear() ;
    }

    vector < pair<int,int> > Answer ;
    for(int i=0 ; i<v.size() ; i++)
    {
        for(int j=0 ; j<dis.size() ; j++)
        {
            int x = v[i].xx+dis[j].xx  , y = v[i].yy+dis[j].yy ;
            if( x>=0 && y>=0 && Map[x][y] )
            {
                int k = Map[x][y] ;
                g[i+1].pb(k) ; g[k].pb(i+1) ;
            }
            y = v[i].yy-dis[j].yy ;
            if( x>=0 && y>=0 && Map[x][y]  )
            {
                int k = Map[x][y] ;
                g[i+1].pb(k) ; g[k].pb(i+1) ;
            }
        }
    }
    int n = (int)v.size() ;
    for(int i=1 ; i<=n ; i++) vis[i] = 0 ;
    for(int i=1 ; i<=n ; i++)
    {
        if(vis[i] ) continue ;
        col[0].clear() ; col[1].clear() ;
        dfs(i,0) ;
        if( col[0].size() > col[1].size() ) {
            for(int j=0 ; j<col[0].size() ; j++) Answer.pb( v[ col[0][j] - 1 ] ) ;
        }
        else for(int j=0 ; j<col[1].size() ; j++) Answer.pb( v[ col[1][j] -1 ] ) ;
    }

    return Answer;
}

