inline ll eud(pl a, pl b) {
	ll dx = a.first-b.first;
	ll dy = a.second-b.second;
	return dx*dx+dy*dy;
}
void bfs(int a, int b, int bs, int n) {
	queue<pl> q;
	q.push({a,b});
	while(!q.empty()) {
		pl co = q.front();q.pop();
		int i = co.first,j = co.second;
		int cv = (col[i][j]&(1<<bs))>>bs;
		for(int k=0;k<da[bs].size();k++) {
			int u = i+da[bs][k].first;
			int v = j+da[bs][k].second;
			if(u < 0 || u >= 2*n) {continue;}
			if(v < 0 || v >= 2*n) {continue;}
			if(vs[u][v]&(1<<bs)) {
				//if(col[u][v] == col[i][j]) {cout << "wtf detected\n";}
				continue;
			} else {
				vs[u][v] |= (1<<bs);
				col[u][v] |= (1-cv)<<bs;
				q.push({u,v});
			}
		}
	}
}
