vpii cal(int d, int n) {
	vpii ret;
	int sd = sqrt(d);
	rep(dx, sd+1) {
		if (dx >= n*2) continue;
		int dy = sqrt(d - dx*dx);
		if (dy >= n*2) continue;
		if (dy * dy + dx * dx == d) {
			ret.emplace_back(dx, dy);
		}
	}
	return ret;
}

void pr(const vpii &ans) {
	forr(a, ans) {
		print(a.fst, a.snd);
	}
}

void Main() {
	int n = ri(), d1 = ri(), d2 = ri();

	vpii e1 = cal(d1, n);
	vpii e2 = cal(d2, n);

	vpii E;
	forr(e, e1) E.emplace_back(e);
	forr(e, e2) E.emplace_back(e);

	vvb dame(2*n, vb(2*n));

	vpii ans;

	rep(y, 2*n) {
		rep(x, 2*n) {
			if (dame[y][x]) continue;
			ans.emplace_back(y, x);
			if (sz(ans) == n*n) {
				pr(ans);
				return;
			}
			forr(e, E) {
				if (y+e.fst < 0) continue;
				if (y+e.fst > 2*n) continue;
				if (x+e.snd < 0) continue;
				if (x+e.snd > 2*n) continue;
				dame[y+e.fst][x+e.snd] = 1;
			}
		}
	}
}

