bool query(int x,int y){
	int res = 0;
	for(int i=0;i<2*n;i++){
		for(int j=0;j<2*n;j++){
			if(arr[(2*i*n)+j] == make_pair(x,y)){res++;}
		}
	}
	if(res>=(n*n)){return true;}
	return false;
}

