	int c = n*n;
	for(int i=0;i<2*n;i++){
		for(int j=0;j<2*n;j++){
			if(c==0){return;}
			if(arr[(2*i*n)+j] == make_pair(x,y)){cout<<i<<" "<<j<<endl;c--;}
		}
	}
}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	cin>>n>>d1>>d2;

	for(int i=0;i<2*n;i++){
		for(int j=0;j<2*n;j++){
			arr[i*(2*n)+j] = make_pair(0,0);
		}
	}

	for(int i=0;i<2*n;i++){
		for(int j=0;j<2*n;j++){
			for(int k=0;(k+i)<2*n;k++){
				int a = d1 - (k*k);
				if((ceil(sqrt((float)a)) == floor(sqrt((float)a)))){
					a = (int)sqrt((float)a);
					if((a+j)>=0 && (a+j)<2*n){arr[((i+k)*2*n)+(j+a)].first = 1-arr[(i*2*n)+j].first;}
				}
			}
		}
	}

	for(int i=0;i<2*n;i++){
		for(int j=0;j<2*n;j++){
			for(int k=0;(k+i)<2*n;k++){
				int a = d2 - (k*k);
				if((ceil(sqrt((float)a)) == floor(sqrt((float)a)))){
					a = (int)sqrt((float)a);
					if((a+j)>=0 && (a+j)<2*n){arr[((i+k)*2*n)+(j+a)].second = 1-arr[(i*2*n)+j].second;}
				}
			}
		}
	}

	if(query(0,0)){
		print(0,0);
	}else if(query(0,1)){
		print(0,1);
	}else if(query(1,0)){
		print(1,0);
	}else{
		print(1,1);
	}
}

