#define N 605
using namespace std;
int n,dx[N],dy[N],d1,d2,x[100000],y[100000],tot;
bool vis[N][N];
void WORK(int x,int y){
	if (x<0||x>=2*n||y<0||y>=2*n) return;
	vis[x][y]=1;
}
void work(int x,int y){
	int tx,ty; 
	for (int i=1;i<=tot;i++){
		tx=x+dx[i],ty=y+dy[i];
		WORK(tx,ty);
		tx=x+dx[i],ty=y-dy[i];
		WORK(tx,ty);
		tx=x-dx[i],ty=y+dy[i];
		WORK(tx,ty);
		tx=x-dx[i],ty=y-dy[i];
		WORK(tx,ty);

		tx=x+dy[i],ty=y+dx[i];
		WORK(tx,ty);
		tx=x+dy[i],ty=y-dx[i];
		WORK(tx,ty);
		tx=x-dy[i],ty=y+dx[i];
		WORK(tx,ty);
		tx=x-dy[i],ty=y-dx[i];
		WORK(tx,ty);
	}
	vis[x][y]=1;

}
int main(){
	scanf("%d%d%d",&n,&d1,&d2);
	for (int i=0;i*i*2<=d1;i++){
		int tmp=int(sqrt(d1-i*i)+0.5);
		if (tmp*tmp+i*i==d1){
			dx[++tot]=i;
			dy[tot]=tmp;
		}
	}
	for (int i=0;i*i*2<=d2;i++){
		int tmp=int(sqrt(d2-i*i)+0.5);
