	{
		if (d1-k*k>=0 && ~sq[d1-k*k]) 
		{
			v1[++cnt1]=make_pair(k,sq[d1-k*k]);
		}
		if (d2-k*k>=0 && ~sq[d2-k*k]) 
		{
			v2[++cnt2]=make_pair(k,sq[d2-k*k]);
		}
