		{
			id=get(i,j);
			for (int k=1;k<=cnt1;k++)
			{
				xx=i+v1[k].first;yy=j+v1[k].second;
				if (In(xx,yy)) addedge(id,get(xx,yy));
				xx=i-v1[k].first;yy=j+v1[k].second;
				if (In(xx,yy)) addedge(id,get(xx,yy));
			}
		}
	}
	for (int i=1;i<=n*n;i++)
	{
		root(i);
		col[i]=val[i];
	}
	for (int i=1;i<=n*n;i++) msk[i]=col[i];
	for (int i=1;i<=n*n;i++)
