typedef vector<vector<LL>> Edge;


struct BipertiteMatching{
    // O(E * V_left)
    // edge中の[0, left_cnt) を左側のノードとみなす
    vector<pair<LL,LL>> solve(const Edge& edge, LL left_cnt = -1){
        LL n = edge.size();
        if(left_cnt < 0) left_cnt = n; // もし左右に分かれていなければすべて増加道を探す

        vector<LL> match_to(n, -1);
        for(LL i = 0; i < left_cnt; ++i){
            vector<LL> visited(n);
            if(match_to[i] == -1) pathArgument(edge, i, match_to, visited);
        }
        vector<pair<LL,LL>> res;
        for(LL i = 0; i < n; ++i){
            if(match_to[i] < 0) continue;
            if(i > match_to[i]) continue;
            res.emplace_back(i, match_to[i]);
        }
        return res;
    }

private:
    bool pathArgument(const Edge& edge, LL cur, vector<LL>& match_to, vector<LL>& visited){
        if(cur < 0) return true;
        for(int to: edge[cur]){
            if(visited[to]) continue;
            visited[to] = 1;
            if(pathArgument(edge, match_to[to], match_to, visited)){
                match_to[cur] = to;
                match_to[to] = cur;
                return true;
            }
        }
        return false;
    }
};



void search_solve(LL n, LL y, LL x, LL depth, vector<vector<LL>>& memo, vector<pair<LL,LL>>& ng){
    if(y < 0 || x < 0) return;
    if(y >= n*2 || x >= n*2) return;
    LL type = 1 + depth % 2;
    if(memo[y][x] & type) return;
    memo[y][x] |= type;
    for(auto ng_p: ng){
        search_solve(n, y + ng_p.first, x + ng_p.second, depth+1, memo, ng);
        search_solve(n, y - ng_p.first, x + ng_p.second, depth+1, memo, ng);
        search_solve(n, y + ng_p.first, x - ng_p.second, depth+1, memo, ng);
        search_solve(n, y + ng_p.second, x + ng_p.first, depth+1, memo, ng);
        search_solve(n, y - ng_p.second, x + ng_p.first, depth+1, memo, ng);
        search_solve(n, y + ng_p.second, x - ng_p.first, depth+1, memo, ng);
    }
}


LL n2 = -1;
void add_edge(Edge& edge, int y1, int x1, int y2, int x2){
    if(y2 < 0 || x2 < 0 || y2 >= n2 || x2 >= n2) return;
    LL node1 = y1*n2 + x1;
    LL node2 = y1*n2 + x1;
    edge[node1].push_back(node2);
    edge[node2].push_back(node1);
}


int main(){
    LL n, d1, d2;
    cin >> n >> d1 >> d2;
    vector<pair<LL,LL>> ng;
    for(LL dy = 0; dy < n*2; ++dy){
        for(LL dx = dy; dx < n*2; ++dx){
            LL d = dy*dy + dx*dx;
            if(d == d1*d1){
                ng.push_back(pair<LL,LL>(dy, dx));
                cerr << "ng1 " << dy << ", " << dx << endl;
            }
            if(d == d2*d2){
                ng.push_back(pair<LL,LL>(dy, dx));
                cerr << "ng2 " << dy << ", " << dx << endl;
            }
        }
    }

    cerr << "debug1" << endl;
    n2 = n*2;
    Edge edge(n2*n2);
    for(LL y = 0; y < n*2; ++y){
        for(LL x = 0; x < n*2; ++x){
            for(auto ng_p: ng){
                add_edge(edge, y, x, y+ng_p.first, x+ng_p.second);
                add_edge(edge, y, x, y+ng_p.second, x+ng_p.first);
            }
        }
    }
    for(LL i = 0; i < edge.size(); ++i){
        set<LL> node_set(edge[i].begin(), edge[i].end());
        vector<LL> uniq(node_set.begin(), node_set.end());
        edge[i] = uniq;
    }
    cerr << "debug2" << endl;
    vector<pair<LL,LL>> match = BipertiteMatching().solve(edge);
    for(auto p : match){
        LL x = p.first % n2;
        LL y = p.first / n2;
        cerr << x << " " << y << endl;
    }
    return 0;
}

