void crossAll(VVI &M, int N, int D) {
	int sx[] = {1, 1};
	int sy[] = {1, -1};
	for (int x = 0; x*x <= D; ++x) {
		int rN = D - x*x;
		int y = sqrt(rN) + 1e-9;
		if (y * y != rN) continue;
		for (int k = 0; k < 2; ++k) {
			int yy = sy[k] * y;

			for (int i = 0; i < M.size(); ++i) {
				for (int j = 0; j < M[i].size(); ++j) {
					if (!M[i][j]) continue;
					int nx = j + x;
					int ny = i + yy;
					if (nx < 0 || nx >= M[i].size()) continue;
					if (ny < 0 || ny >= M.size()) continue;
					M[ny][nx] = 0;
				}
			}

		}

	}
}


int main(int argc, char *argv[]) {

