vector<int> mem_sqrt(1e5, -1);

vector<pii> inters(pii center, int r2) {
	vector<pii> rez;
	for (int h = 0; h * h <= r2; h++) {
		int l = r2 - h * h;
		if (mem_sqrt[l] != -1) {
			l = mem_sqrt[l];
			rez.emplace_back(mp(center.x + l, center.y + h));
			rez.emplace_back(mp(center.x + l, center.y - h));
			rez.emplace_back(mp(center.x - l, center.y + h));
			rez.emplace_back(mp(center.x - l, center.y - h));
		}
	}
	return rez;
}

pair<int, pii> calc(const pii &p) {
	return mp(min(p.x, 2 * n - p.x - 1) + min(p.y, 2 * n - p.y - 1), p); 
}

struct ultra {
    bool operator() (const pii &a, const pii &b) const {
    	return calc(a) < calc(b);
    }
};

vector<pii> tryCock() {
	set<pii, ultra> free;
	vector<pii> rez;
	f(i, 2 * n) {
		f(j, 2 * n) {
			free.emplace(i, j);
		}
	}
	while (!free.empty()) {
		int best = 0;
