		auto it = free.begin();
		advance(it, rand() % min(len(free), 4));

		pii base = *it;
		// print base;
		free.erase(base);
		rez.pb(base);

		for (pii err : inters(base, d1)) {
			assert(!norm(base, err));
			free.erase(err);
		}	
		for (pii err : inters(base, d2)) {
			assert(!norm(base, err));
			free.erase(err);
		}
	}	
	return rez;
}

