const int MAXN = 610;

int used[MAXN][MAXN];

vector<pair<int, int>> ds;

void init_dxdy(int d) {
  ds.clear();
  for (int i = 0; i * i <= d; i++) {
    int t = d - i * i;
    int tt = (int)sqrt(t);
    tt = max(tt, 0);
    while (tt * tt <= t) tt++;
    while (tt * tt > t) tt--;
    if (tt * tt + i * i == d) {
      ds.push_back({i, tt});
      ds.push_back({-i, tt});
      ds.push_back({i, -tt});
      ds.push_back({-i, -tt});
    }
  }
  sort(ds.begin(), ds.end());
  ds.erase(unique(ds.begin(), ds.end()), ds.end());
}

int n;

void dfs(int x, int y, int c) {
  if (used[x][y] != -1) {
    assert(used[x][y] == c || used[x][y] == -2);
    return;
  }
  used[x][y] = c;
  for (auto d : ds) {
    int nx = x + d.first;
    int ny = y + d.second;
    if (0 <= nx && nx < n && 0 <= ny && ny < n) {
      dfs(nx, ny, c ^ 1);
    }
  }
}

