    init_dxdy(d1);
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (used[i][j] == -1) {
          dfs(i, j, 0);
        }
        cnt[used[i][j]]++;
      }
    }

    int c = 1;
    if (cnt[0] > cnt[1]) {
      c = 0;
    }

    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (used[i][j] == c) {
          used[i][j] = -1;
        } else {
