int vis[605][605],vst[605][605],dx[4]={1,1,-1,-1},dy[4]={1,-1,1,-1},num[5][5];
void dfs(int x,int y,int D)
{
	for(int i=0;i*i<=D;i++)
	{
		int len=D-i*i;
		int j=sqrt(len);if(j*j!=len) continue;
		for(int k=0;k<4;k++)
		{
			int nx=x+i*dx[k],ny=y+j*dy[k];
			if(nx<1||nx>n||ny<1||ny>n) continue;
			if(!vis[nx][ny])
			{
				vis[nx][ny]=3-vis[x][y];
				dfs(nx,ny,D);
			}
		}
	}
}
