	for(int j=1;j<=n;j++)
	{
		if(!vis[i][j])
		{
			vis[i][j]=1;
			dfs(i,j,D1);
		}
	}
	for(int i=1;i<=n;i++)
	for(int j=1;j<=n;j++) vst[i][j]=vis[i][j];
