	for(int b=1;b<=2&&flag;b++)
	{
		if(num[a][b]<n*n/4) continue;
		int nums=0;
		for(int i=1;i<=n;i++)
		for(int j=1;j<=n;j++)
		{
			if(nums==n*n/4) break;
			if(vis[i][j]==a&&vst[i][j]==b) printf("%d %d\n",i-1,j-1),nums++;
		}
		flag=0;
	}
	return 0;
}

