#include <bits/stdc++.h>
using namespace std;
#define pb push_back
#define pr make_pair
#define fi first
#define se second
typedef pair<int, int> pii;
const int MAX_N = 6e2 + 5;
bool vis[MAX_N][MAX_N];
vector<pii> mp, ans;
set<pii> st[MAX_N];
int n, cnt, d[MAX_N][MAX_N];
int erfen(int x) {
    int L = 0, R = sqrt(x) + 100, ans = 0;
    while (L <= R) {
        int mid = (L + R) / 2;
        if (mid * mid <= x) {
            ans = mid;
            L = mid + 1;
        }
        else R = mid - 1;
    }
    return ans;
}
void down(int i, int j) {
    //printf("Debug : down(%d, %d)\n", i, j);
    if (i < 0 || i >= 2 * n) return;
    if (j < 0 || j >= 2 * n) return;
    if (vis[i][j]) return;
    st[d[i][j]].erase(pr(i, j));
    d[i][j]--;
    st[d[i][j]].insert(pr(i, j));
}
void connect(int i, int j) {
    //printf("Debug : connect(%d, %d)\n", i, j);
    if (i < 0 || i >= 2 * n) return;
    if (j < 0 || j >= 2 * n) return;
    if (vis[i][j]) return;
    vis[i][j] = true;
    st[d[i][j]].erase(pr(i, j));
    for (int k = 0; k < mp.size(); k++) {
        int x = mp[k].fi, y = mp[k].se;
        down(i + x * x, j + y * y);
        if (x != 0) down(i - x * x, j + y * y);
        if (y != 0) down(i + x * x, j - y * y);
        if (x != 0 && y != 0) down(i - x * x, j - y * y);
    }
}
int main() {
    int d_1, d_2, rt_1, rt_2;
    scanf("%d%d%d", &n, &d_1, &d_2);
    rt_1 = erfen(d_1), rt_2 = erfen(d_2);
    for (int i = 0; i <= rt_1; i++) {
        int x = d_1 - i * i;
        if (i * i > x) break;
        int y = erfen(x);
        if (y * y == x) {
            mp.pb(pr(i, y));
            if (i != y) mp.pb(pr(y, i));
        }
    }
    if (d_1 != d_2) {
        for (int i = 0; i <= rt_2; i++) {
            int x = d_2 - i * i;
            if (i * i > x) break;
            int y = erfen(x);
            if (y * y == x) {
                mp.pb(pr(i, y));
                if (i != y) mp.pb(pr(y, i));
            }
        }
    }
    for (int i = 0; i < n * 2; i++) {
        for (int j = 0; j < n * 2; j++) {
            for (int k = 0; k < mp.size(); k++) {
                int x = mp[k].fi, y = mp[k].se, tx, ty;
                tx = i + x * x, ty = j + y * y;
                if (tx >= 0 && tx < 2 * n && ty >= 0 && ty < 2 * n)  d[i][j]++;
                if (x != 0) {
                    tx = i - x * x, ty = j + y * y;
                    if (tx >= 0 && tx < 2 * n && ty >= 0 && ty < 2 * n)  d[i][j]++;
                }
                if (y != 0) {
                    tx = i + x * x, ty = j - y * y;
                    if (tx >= 0 && tx < 2 * n && ty >= 0 && ty < 2 * n)  d[i][j]++;
                }
                if (x != 0 && y != 0) {
                    tx = i - x * x, ty = j - y * y;
                    if (tx >= 0 && tx < 2 * n && ty >= 0 && ty < 2 * n)  d[i][j]++;
                }
            }
            cnt = max(cnt, d[i][j]);
            st[d[i][j]].insert(pr(i, j));
        }
    }
    while (ans.size() < n * n) {
        for (int i = 0; i <= cnt; i++) {
            if (st[i].size() > 0) {
                pii p = *st[i].begin();
                //printf("Debug : valid(%d, %d)\n", p.fi, p.se);
                st[i].erase(p);
                ans.pb(p);
                vis[p.fi][p.se] = true;
                for (int k = 0; k < mp.size(); k++) {
                    int x = mp[k].fi, y = mp[k].se;
                    connect(p.fi + x * x, p.se + y * y);
                    if (x != 0) connect(p.fi - x * x, p.se + y * y);
                    if (y != 0) connect(p.fi + x * x, p.se - y * y);
                    if (x != 0 && y != 0) connect(p.fi - x * x, p.se - y * y);
                }
                break;
            }
        }
    }
    for (int i = 0; i < ans.size(); i++) {
        printf("%d %d\n", ans[i].fi, ans[i].se);
    }
    return 0;
}

