  stack<int> st;
  rep (u, 4*n*n) {
    if (color[k][u] != -1) {
      continue;
    }
    color[k][u] = 0;
    st.push(u);
    int i, j;
    while (!st.empty()) {
      i = st.top();
      st.pop();
      for (j = 0; j < G[i].size(); j++) {
        if (color[k][G[i][j]] == color[k][i]) {
          //cout << "NO" << endl;
          return false;
        }
        else {
          if (color[k][G[i][j]] == -1) {
            color[k][G[i][j]] = 1 - color[k][i];
            st.push(G[i][j]);
          }
        }
      }
    }
  }
  //cout << "YES" << endl;
  return true;
}


