int n, d1, d2;

struct GRAPH
{
	vector<pair<int, int> > dir;
	int col[MX][MX], num[3];

	void bfs(int x, int y)
	{
		queue<pair<int, int> > que;
		que.push(make_pair(x, y));
		col[x][y] = 1;
		while(!que.empty())
		{
			auto a = que.front();
			que.pop();
			for(auto d : dir)
			{
				auto b = a;
				b.first += d.first;
				b.second += d.second;
				if(b.first>=0 && b.first<n*2 && b.second>=0 && b.second<n*2 && !col[b.first][b.second])
				{
					col[b.first][b.second] = 3-col[a.first][a.second];
					num[col[b.first][b.second]]++;
					que.push(b);
				}
			}
		}
	}

	void color()
	{
		for(int i=0; i<n*2; i++)
			for(int j=0; j<n*2; j++)
				if(!col[i][j])
					bfs(i, j);
	}
} G1, G2;

void build(GRAPH &g, int d)
{
	g.dir.clear();
	for(int i=0; i*i<=d; i++)
		for(int j=0; j*j<=d; j++)
			if(i*i + j*j == d)
			{
				g.dir.push_back(make_pair(i, j));
				g.dir.push_back(make_pair(i, -j));
				g.dir.push_back(make_pair(-i, j));
				g.dir.push_back(make_pair(-i, -j));
			}
}

