bool vis[605][605];
vector<pair<int, int> > vec;
inline bool inrange(int x, int y) { return x >= 0 && x < 2 * n && y >= 0 && y < 2 * n; }
void go(int x, int y, int cur, int D, int C[][605]) {
	C[x][y] = cur;
	vis[x][y] = true;
	for (auto &P : vec) {
		int nx = x + P.first, ny = y + P.second;
		if (inrange(nx, ny) && !vis[nx][ny]) go(nx, ny, cur ^ 1, D, C);
		nx = x + P.first, ny = y - P.second;
		if (inrange(nx, ny) && !vis[nx][ny]) go(nx, ny, cur ^ 1, D, C);
		nx = x - P.first, ny = y + P.second;
		if (inrange(nx, ny) && !vis[nx][ny]) go(nx, ny, cur ^ 1, D, C);
		nx = x - P.first, ny = y - P.second;
		if (inrange(nx, ny) && !vis[nx][ny]) go(nx, ny, cur ^ 1, D, C);
	}
}
inline void work(int D, int C[][605]) {
	memset(vis, false, sizeof(vis));
	vec.clear();
	for (int i = 0; i * i <= D; i++) {
		int j = round(sqrt((double)(D - i * i)));
		if (i * i + j * j == D) vec.push_back(make_pair(i, j));
	}
	for (int i = 0; i < 2 * n; i++) {
		for (int j = 0; j < 2 * n; j++) if (!vis[i][j]) go(i, j, 0, D, C);
	}
}
