  for (int i = 0; i < 2 * m; i++) {
    for (int j = 0; j < 2 * m; j++) {
      s[i + 1][j + 1] = s[i][j + 1] + s[i + 1][j] - s[i][j] + b[i][j];
    }
  }

  int p = -1, q = -1;
  for (int i = 0; i < 2 * m - 2 * n; i++) {
    for (int j = 0; j < 2 * m - 2 * n; j++) {
      int t =
          s[i + 2 * n][j + 2 * n] - s[i][j + 2 * n] - s[i + 2 * n][j] + s[i][j];
      if (t >= n * n) {
        p = i;
        q = j;
        break;
      }
    }
    if (p != -1) {
      break;
    }
  }

  if (p == -1) {
    return 1;
  }

  vector<pair<int, int>> v;
  for (int i = 0; i < 2 * n; i++) {
    for (int j = 0; j < 2 * n; j++) {
      if (b[p + i][q + j]) {
        v.push_back(make_pair(i, j));
      }
    }
  }
  for (int i = 0; i < n * n; i++) {
    cout << v[i].first << " " << v[i].second << endl;
  }
  return 0;
}

