int main() {
  cin.tie(NULL); ios::sync_with_stdio(false);
  int n; V<> d(2); cin >> n >> d[0] >> d[1];
  VV< pair<int, int> > adj(2);
  VV<> col; assign(col, 2, 4 * n * n);
  auto f = [&](int i, int j) { return i * 2 * n + j; };
  auto g = [&](int v) { return make_pair(v / (2 * n), v % (2 * n)); };
  for (int k = 0; k < 2; k++) {
    for (int i = 0; i < 2 * n; i++) for (int j = 0; j < 2 * n; j++) if (i * i + j * j == d[k]) {
      for (int s0 : {-1, 1}) for (int s1 : {-1, 1}) adj[k].emplace_back(s0 * i, s1 * j);
    }
    sort(adj[k].begin(), adj[k].end());
    adj[k].erase(unique(adj[k].begin(), adj[k].end()), adj[k].end());
    for (int s = 0; s < 4 * n * n; s++) if (!col[k][s]) {
      queue<int> que;
      col[k][s] = 1; que.push(s);
      while (!que.empty()) {
        int v = que.front(); que.pop();
        for (auto&& e : adj[k]) {
          int wi = g(v).first + e.first, wj = g(v).second + e.second;
