using namespace std; typedef long long ll; const int INF=1e9;
typedef pair<int,int> P;
struct d{int c,x,y,r;
  bool operator>(const d e) const {if (c!=e.c) return c>e.c; if (r!=e.r) return r>e.r; if (x!=e.x) return x>e.x; return y>e.y;}
};
int main() {
  int n,d1,d2; cin>>n>>d1>>d2; int m=n*n;
  vector<P> v;
  for(int x=-2*n+1;x<2*n;x++) {
    int y1 = sqrt(double(d1 - x*x) + 0.001);
    int y2 = sqrt(double(d2 - x*x) + 0.001);
    if (x * x + y1 * y1 == d1) v.push_back({x, y1}), v.push_back({x, -y1});
    if (x * x + y2 * y2 == d2) v.push_back({x, y2}), v.push_back({x, -y2});
  }

  int vl[2*n][2*n]={}; // 関連付けされたoutの数

  for(int i=0;i<2*n;i++) {
    for(int j=0;j<2*n;j++) {
      for(P o:v) {
        int x = i + o.first, y = j + o.second;
        if (0 <= x && x < 2*n && 0 <= y && y < 2*n) vl[x][y]++;
      }
    }
  }

  random_device rd;
  mt19937 mt(rd());

  while(true) {
    priority_queue<d, vector<d>, greater<d>> que;
    for(int i=0;i<2*n;i++) {
      for(int j=0;j<2*n;j++) {
        que.push({vl[i][j],i,j,(int)mt()});
      }
    }
    int ii=0; P an[m]; bool u[2*n][2*n]={};
    while(ii < m && !que.empty()) {
      d o = que.top(); que.pop();
      if (u[o.x][o.y]) continue;
      an[ii] = {o.x, o.y}; ii++;

      for(P w:v) {
        int x = o.x + w.first, y = o.y + w.second;
        if (0 <= x && x < 2*n && 0 <= y && y < 2*n) {
          u[x][y]=true;
        }
      }
    }

    if (ii == m) {
      for(int i=0;i<m;i++) {
        cout<<an[i].first<<" "<<an[i].second<<endl;
      }
      break;
    }
  }
}

