int64_t root(int64_t n){
    int64_t ret = pow((long double)n, 0.5L);
    while(ret*ret > n) ret--;
    while((ret+1)*(ret+1) <= n) ret++;
    return ret;
}

int color[600][600][2];
int N, D[2];

void dfs(int i, int j, int k, int c){
    if(j<0 || j>=2*N || color[i][j][k]) return;
    color[i][j][k] = c;
    for(int x=0; x<2*N; x++){
        int y2 = D[k] - (x-i)*(x-i);
        if(y2 < 0) continue;
        int y = root(y2);
        if(y*y == y2){
            dfs(x, j-y, k, -c);
            dfs(x, j+y, k, -c);
        }
    }
}

