typedef long long ll;

const int maxn = 601;
vector<pair<int, int> > dir;
bool used[maxn][maxn], color[maxn][maxn];

double eps = 1e-9;

int get_sqr(int a, int b) {
    int c = sqrt(b - a * a) + eps;
    return c * c + a * a == b ? c : -1;
}

void get_dir(int n) {
    dir.clear();
    for (int i = 0; i * i <= n; i++) {
        int j = get_sqr(i, n);
        if (j != -1) {
            dir.push_back({i, j});
        }
    }
}

int n;

int dfs(pair<int, int> v, int col, vector<pair<int, int> > &path) {
    if (used[v.first][v.second]) {
        return 0;
    }
    used[v.first][v.second] = 1;
    color[v.first][v.second] = col;
    path.push_back(v);

    int sum = 0;
    for (auto &d : dir) {
        for (int dx : {-1, 1}) {
            for (int dy : {-1, 1}) {
                int x = v.first + d.first * dx;
                int y = v.second + d.second * dy;
                if (x < 0 || y < 0 || x >= n || y >= n) {
                    continue;
                }
                sum += dfs({x, y}, col ^ 1, path);
            }
        }
    }
    return (col ^ 1) + sum;
}

vector<pair<int, int> > good_vert(vector<pair<int, int> > vert) {
    memset(used, 1, sizeof(used));
    memset(color, 0, sizeof(color));

    for (auto &v : vert) {
        used[v.first][v.second] = 0;
    }

    for (auto &v : vert) {
        if (!used[v.first][v.second]) {
            vector<pair<int, int> > path;
            int cnt = dfs(v, 0, path);
            if (cnt < (int) path.size() - cnt) {
                for (auto &u : path) {
                    color[u.first][u.second] ^= 1;
                }
            }
        }
    }

    vector<pair<int, int> > res;
    for (auto v : vert) {
        if (!color[v.first][v.second]) {
            res.push_back(v);
        }
    }
    return res;
}

