    vector<pair<int, int> > vert;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            vert.push_back({i, j});
        }
    }

    get_dir(d1);
    vert = good_vert(vert);
    get_dir(d2);
    vert = good_vert(vert);
    assert((int)vert.size() >= n * n / 4);
    vert.resize(n * n / 4);
    for (auto v : vert) {
        cout << v.first << ' ' << v.second << '\n';
    }

    return 0;
}

