int U[600][600];
bool XX[600][600];

vector<PP> r;

void make(int a, int b) {
    r.push_back(make_pair(a, b));
    r.push_back(make_pair(a, -b));
    r.push_back(make_pair(-a, b));
    r.push_back(make_pair(-a, -b));
    return;
}

map<int, set<PP> > G;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    int N, A, B;
    cin >> N >> A >> B;
    for (int i = 1;i <= sqrt(A);i++) {
        int j = sqrt(A - i * i);
        if (i * i + j * j == A) {
            make(i, j);
            make(j, i);
        }
    }
    for (int i = 1;i <= sqrt(B);i++) {
        int j = sqrt(B - i * i);
        if (i * i + j * j == B) {
            make(i, j);
            make(j, i);
        }
    }
    memset(U, 0, sizeof(U));
    memset(XX, 0, sizeof(XX));
    vector<PP> res;
    for (int i = 0;i < 2 * N;i++) {
        for (int j = 0;j < 2 * N;j++) {
            G[0].insert(make_pair(i, j));
        }
    }
    while (res.size() < N * N) {
        map<int, set<PP>>::iterator it;
        set<PP>::iterator itx;
        it = G.end();
        it--;
        while ((it->second).size() == 0) {
            int u = it->first;
            it--;
            G.erase(u);
        }
        itx = (it->second).begin();
        PP nex = *itx; // Put here.
        (it->second).erase(nex);
        // Delete all effected nodes.
        set<PP> D;
        int x = nex.first;
        int y = nex.second;
        XX[x][y] = 1;
        res.push_back(nex);
        for (auto a : r) {
            int X = x + a.first;
            int Y = y + a.second;
            if (X >= 0 && X < 2 * N && Y >= 0 && Y < 2 * N) {
                D.insert(make_pair(X, Y));
            }
        }
        for (auto a : D) {
            XX[a.first][a.second] = 1;
            int u = U[a.first][a.second];
            G[u].erase(a);
        }
        // Update scores.
        for (auto a : D) {
            for (auto b : r) {
                int X = a.first + b.first;
                int Y = a.second + b.second;
                if (X >= 0 && X < 2 * N && Y >= 0 && Y < 2 * N) {
                    if (XX[X][Y] == 1) continue;
                    int q = U[X][Y];
                    G[q].erase(make_pair(X, Y));
                    G[q + 1].insert(make_pair(X, Y));
                    U[X][Y]++;
                }
            }
        }
    }
    for (int i = 0;i < N * N;i++) {
        cout << res[i].first << ' ' << res[i].second << endl;
    }
    return 0;
}

