void add(int i, int j, int x, int y,vector<vector<vector<pii>>> &G){
	if(x>=0 && x<2*n && y>=0 && y<2*n){
		G[i][j].push_back({x,y});
		G[x][y].push_back({i,j});
	}
}

void dfs1(int s,int t, int c,int x, vector<vector<vector<pii>>> &G){
    used[s][t] = 1;
    if(x==1) color[s][t].first = c;
    if(x==2) color[s][t].second = c;
    for(auto&& p :v){
    	for(int i=0;i<4;i++){
    		int nx = s + dx[i]*p.first, ny = t + dy[i]*p.second;
        	if(nx<0 || nx>=2*n || ny<0 || nx>=2*n || used[nx][ny]!=-1) continue;
        	dfs1(nx,ny,3-c,x,G);
    	}
    }
}

