vector<pii> solve(int d) {
	vector<pii> ans;
	for (int i = 0; i <= int(sqrt(d)); i++) {
		int j = int(sqrt(d - i * i));
		if (i * i + j * j == d) {
			ans.push_back({ i, j });
		}
	}
	return ans;
}

//ProblemC
void Solve() {
	int n, d1, d2;
	cin >> n >> d1 >> d2;

	auto s1 = solve(d1);
	auto s2 = solve(d2);
	for (auto& p : s2) s1.push_back(p);

	vector<vector<bool>> ng(n * 2, vector<bool>(n * 2, false));
	vector<pii> ans;

	vector<pii> xxx;
	xxx.reserve(4 * n * n);
	for (int i = 0; i < 2 * n; i++) for (int j = 0; j < 2 * n; j++) xxx.push_back({ i,j });
	std::random_device rd;
	std::mt19937 g(rd());
	std::shuffle(xxx.begin(), xxx.end(), g);

	for (int j = 0; j < (int)xxx.size() && (int)ans.size() < n * n; j++) {
		pii &p = xxx[j];
		if (!ng[p.first][p.second]) {
			ans.push_back(p);
			for (auto &z : s2) {
				int xng = p.first + z.first;
				int yng = p.second + z.second;
				if (xng < 2 * n && yng < 2 * n) ng[xng][yng] = true;

				xng = p.first - z.first;
				yng = p.second - z.second;
				if (xng >= 0 && yng >= 0) ng[xng][yng] = true;
			}
