void f_insert(set<t2> &g, const set<t2> &lg, ll n)
{
    for (auto p : lg) {
        ll x = get<0>(p) * 2LL;
        ll y = get<1>(p) * 2LL;
        if (x < n * 2 && y < n * 2) g.insert(t2(x, y));
        if (x < n * 2 && y + 1 < n * 2) g.insert(t2(x, y + 1));
        if (x + 1 < n * 2 && y < n * 2) g.insert(t2(x + 1, y));
        if (x + 1< n * 2 && y + 1 < n * 2) g.insert(t2(x + 1, y + 1));
    }
}


void f_group(ll n, ll d, set<t2> &ga, set<t2> &gb)
{
    if (d & 1LL) {
        rep (i, 2LL * n) rep (j, 2LL * n) {
            if ((i + j) & 1LL) ga.insert(t2(i, j));
            else gb.insert(t2(i, j));
        }
        return;
    }

    if (d % 4LL == 2LL) {
        rep (i, 2LL * n) rep (j, 2LL * n) {
            if (i & 1LL) ga.insert(t2(i, j));
            else gb.insert(t2(i, j));
        }
        return;
    }

    set<t2> lga;
    set<t2> lgb;
    f_group(n, d / 4LL, lga, lgb);
    f_insert(ga, lga, n);
    f_insert(gb, lgb, n);
}

