typedef pair <int, int> ii;

const int Maxm = 605;
const int Maxn = 3000005;

int sqr[Maxn];
int n, d1, d2;
vector <ii> delt;
vector <ii> neigh[Maxm][Maxm];
vector <ii> priors; 
int my[Maxm][Maxm];
priority_queue <ii> Q;
int st[Maxm][Maxm];
bool tk[Maxm][Maxm];
vector <ii> seq;
vector <ii> gen;

bool Inbounds(int r, int c) { return 0 <= r && r < 2 * n && 0 <= c && c < 2 * n; }

void Delete(const ii &v)
{
	if (tk[v.first][v.second]) return;
	tk[v.first][v.second] = true;
	for (int i = 0; i < neigh[v.first][v.second].size(); i++) {
		ii u = neigh[v.first][v.second][i];
		if (tk[u.first][u.second]) continue;
		st[u.first][u.second]--;
		Q.push(ii(-st[u.first][u.second], my[u.first][u.second]));
	}
}

bool Check(int r, int c)
{
	for (int i = 0; i < neigh[r][c].size(); i++) {
		ii u = neigh[r][c][i];
		if (tk[u.first][u.second]) return false;
	}
	return true;
}

bool Check()
{
	for (int i = 0; int(gen.size()) - i + seq.size() > n * n && seq.size() < n * n && i < gen.size(); i++)
		if (Check(gen[i].first, gen[i].second)) {
			seq.push_back(gen[i]); tk[gen[i].first][gen[i].second] = true;
		}
	printf("got %d\n", int(seq.size()));
	printf("n = %d\n", n);
	if (seq.size() >= n * n) {
		for (int i = 0; i < seq.size(); i++)
			printf("%d %d\n", seq[i].first, seq[i].second);
		return true;
	} else {
		for (int i = 0; i < seq.size(); i++)
			tk[seq[i].first][seq[i].second] = false;
		seq.clear();
		return false;
	}
}

int main()
{
	fill(sqr, sqr + Maxn, -1);
	for (int i = 0; i * i < Maxn; i++)
		sqr[i * i] = i;
	cin >> n >> d1 >> d2;
	if (d1 % 2 && d2 % 2) {
		for (int i = 0; i < 2 * n; i += 2)
			for (int j = 0; j < 2 * n; j += 2)
				printf("%d %d\n", i, j);
		return 0;
	}
	for (int i = 0; i * i <= d1; i++)
		if (sqr[d1 - i * i] != -1) {
			int j = sqr[d1 - i * i];
			for (int a = -1; a <= 1; a += 2) if (a == -1 || i != 0)
				for (int b = -1; b <= 1; b += 2) if (b == -1 || j != 0)
					delt.push_back(ii(a * i, b * j));
		}
	if (d1 != d2)
		for (int i = 0; i * i <= d2; i++)
			if (sqr[d2 - i * i] != -1) {
				int j = sqr[d2 - i * i];
				for (int a = -1; a <= 1; a += 2) if (a == -1 || i != 0)
					for (int b = -1; b <= 1; b += 2) if (b == -1 || j != 0)
						delt.push_back(ii(a * i, b * j));
			}
	while (true) {
		priors.clear();
		for (int i = 0; i < 2 * n; i++)
			for (int j = 0; j < 2 * n; j++)
				priors.push_back(ii(i, j));
		random_shuffle(priors.begin(), priors.end());
		for (int i = 0; i < priors.size(); i++)
			my[priors[i].first][priors[i].second] = i;
		while (!Q.empty()) Q.pop();
		for (int i = 0; i < 2 * n; i++)
			for (int j = 0; j < 2 * n; j++) {
				tk[i][j] = false;
				neigh[i][j].clear();
				for (int z = 0; z < delt.size(); z++)
					if (Inbounds(i + delt[z].first, j + delt[z].second))
						neigh[i][j].push_back(ii(i + delt[z].first, j + delt[z].second));
				st[i][j] = neigh[i][j].size();
				Q.push(ii(-st[i][j], my[i][j]));
			}
		seq.clear();
		while (!Q.empty() && seq.size() < n * n) {
			ii v = priors[Q.top().second]; int s = -Q.top().first; Q.pop();
			if (st[v.first][v.second] != s || tk[v.first][v.second]) continue;
			tk[v.first][v.second] = true; seq.push_back(v);
			for (int i = 0; i < neigh[v.first][v.second].size(); i++)
				Delete(neigh[v.first][v.second][i]);
		}
		if (seq.size() >= n * n) {
			for (int i = 0; i < seq.size(); i++)
				printf("%d %d\n", seq[i].first, seq[i].second);
			return 0;
		}
		break;
	}
	for (int i = 0; i < 2 * n; i++)
		for (int j = 0; j < 2 * n; j++) {
			tk[i][j] = false;
			gen.push_back(ii(i, j));
		}
	seq.clear();
	while (!Check()) random_shuffle(gen.begin(), gen.end());
	return 0;
}

