    for(int i=0; i<2*N; ++i){
        for(int j=0; j<2*N; ++j){
            int d = i*i + j*j;
            if(d == D1){
                move1.push_back(P(i, j));
                move1.push_back(P(-i, j));
                move1.push_back(P(i, -j));
                move1.push_back(P(-i, -j));
            }
            if(d == D2){
                move2.push_back(P(i, j));
                move2.push_back(P(-i, j));
                move2.push_back(P(i, -j));
