                        if(col[x+dx][y+dy] == 0){
                            q.push(array<int, 3>({x+dx, y+dy, c}));
                        }
                    }
                }
            }
        }
    }
    memset(used, false, sizeof(used));
    for(int i=0; i<2*N; ++i){
        for(int j=0; j<2*N; ++j){
            if(col[i][j] != 0) continue;
            // dfs
            queue<array<int, 3>> q;
            q.push(array<int, 3>({i, j, 0}));
            while(!q.empty()){
                auto s = q.front(); q.pop();
                int x = s[0]; int y = s[1]; int c = s[2];
                col[x][y] += c<<1;
                c = 1 - c; // 隣接する色は異なる
                for(auto step: move2){
                    int dx = step.first; int dy = step.second;
                    if(x+dx < 2*N && 0 <= x+dx && y+dy < 2*N && 0 <= y+dy){
                        if(col[x+dx][y+dy] == 0){
                            q.push(array<int, 3>({x+dx, y+dy, c}));
                        }
                    }
                }
            }
        }
    }
    int cnt = 0;
    for(int i=0; i<2*N; ++i){
        for(int j=0; j<2*N; ++j){
            if(col[i][j] == 0){
                cout << i << ' ' << j << endl;
                if(++cnt > N) break;
            }
        }
    }
    return 0;
}

