using namespace std;

const int maxn = 610;

int n, col[2][maxn][maxn], d[2];
vector<pair<int, int> > all[2][2];

void dfs(int i, int j, int c, int col[maxn][maxn], int d) {
	if(i < 0 || j < 0 || i >= n || j >= n || col[i][j]) {
		return;
	}
	col[i][j] = c;
	c = -c;
	for (int x = 0, y = d; x * x <= d; ++x) {
		while(x * x + y * y > d) {
			--y;
		}
		if(x * x + y * y == d) {
			dfs(i + x, j + y, c, col, d);
			dfs(i - x, j + y, c, col, d);
			dfs(i + x, j - y, c, col, d);
			dfs(i - x, j - y, c, col, d);
		}
	}
	return;
}

void work(int col[maxn][maxn], int d) {
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			if(!col[i][j]) {
				dfs(i, j, 1, col, d);
			}
		}
	}
}

int main() {
	scanf("%d%d%d", &n, d, d + 1);
	n <<= 1;
	work(col[0], d[0]);
	work(col[1], d[1]);
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			all[col[0][i][j] > 0][col[1][i][j] > 0].push_back(make_pair(i, j));
		}
	}
	n >>= 1;
	n *= n;
	for (int i = 0; i < 2; ++i) {
		for (int j = 0; j < 2; ++j) {
			if(all[i][j].size() >= n) {
				for (int k = 0; k < n; ++k) {
					printf("%d %d\n", all[i][j][k].first, all[i][j][k].second);
				}
				return 0;
			}
		}
	}
}

