pii d[N], ans[N*N];

void prelude() {
	for( int i = 0; i*i <= D; ++i )
		for( int j = 0; i*i+j*j <= D; ++j ) {
			int x = i*i+j*j;
			if( x == d1 || x == d2 )
				d[dn++] = pii(i, j);
		}
}

int vis[N][N];

bool inside( int x, int y ) {
	return x < n+n && y < n+n;
}

void mark( int x, int y, int dx, int dy ) {
	int nx = x + dx;
	int ny = y + dy;
	if( inside(nx, ny) ) vis[nx][ny] = 1;
	nx = x + dy;
	ny = y + dx;
	if( inside(nx, ny) ) vis[nx][ny] = 1;
}

void solve() {
	for( int i = 0; i < n+n; ++i )
		for( int j = 0; j < n+n; ++j )
			if( !vis[i][j] ) {
				ans[an++] = pii(i, j);
				for( int t = 0; t < dn; ++t )
					mark(i, j, d[t].first, d[t].second);
			}
	if( an < n*n ) vis[N*N][N*N] = 1;
	for( int i = 0; i < n*n; ++i )
		printf( "%d %d\n", ans[i].first, ans[i].second );
}

