#include <bits/stdc++.h>

using namespace std;

namespace {

#define VEVE(i, a, b) for (ll i = a, __##i = b; i < __##i; ++i)
#define DYDY(i, a, b) for (ll i = a, __##i = b; i > __##i; --i)
#define RARA(x, seq) for (auto &x : seq)
#define SIZE(x) ((ll)(x.size()))
#define ALL(x) x.begin(), x.end()

typedef int ll;
typedef double dd;

void Solve(ll) {
  ll n, d1, d2;
  cin >> n >> d1 >> d2;
  auto oob = [&](ll x, ll y) {
    return min(x, y) < 0 or max(x, y) >= 2 * n;
  };
  auto make_graph = [&](ll dist) {
    vector<pair<ll, ll>> diffs;
    VEVE(i, -2 * n, 2 * n + 1) VEVE(j, -2 * n, 2 * n + 1) if (i * i + j * j == dist)
          diffs.emplace_back(i, j);
    vector<vector<ll>> color(2 * n, vector<ll>(2 * n, -1));
    queue<pair<ll, ll>> que;
    auto go = [&](ll sx, ll sy) {
      if (~color[sx][sy])
        return;
      que.emplace(sx, sy);
      color[sx][sy] = 0;
      while (not que.empty()) {
        ll x, y;
        tie(x, y) = que.front();
        que.pop();
        RARA(di, diffs) {
          const ll nx = x + di.first, ny = y + di.second;
          if (not oob(nx, ny) and color[nx][ny] == -1) {
            color[nx][ny] = color[x][y] ^ 1;
            que.emplace(nx, ny);
          }
        }
      }
    };
    VEVE(i, 0, 2 * n) VEVE(j, 0, 2 * n) go(i, j);
    return color;
  };
  auto color1 = make_graph(d1);
  auto color2 = make_graph(d2);
  map<pair<ll, ll>, ll> freq;
  VEVE(i, 0, 2 * n) VEVE(j, 0, 2 * n) ++freq[{color1[i][j], color2[i][j]}];
  RARA(f, freq) if (f.second >= n * n) {
      ll rem = n * n;
      VEVE(x, 0, 2 * n) VEVE(y, 0, 2 * n) if (f.first == make_pair(color1[x][y], color2[x][y])) {
            cout << x << " " << y << "\n";
            if (--rem == 0)
              return;
          }
    }
  assert(false);
}

void Init() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
}
}

