void make_graph(int n, int d) {
	int sq = sqrt(d) + 10;
	for (int a = 0; a < sq; ++a) {
		if (a * a > d) {
			break;
		}
		int b = (sqrt(d - a * a) + 0.5);
		if (b > sq or a * a + b * b != d) {
			continue;
		}
		for (int x1 = 0; x1 < n; ++x1) {
			int x2 = x1 + a;
			if (x2 > n) {
				continue;
			}
			for (int y1 = 0; y1 < n; ++y1) {
				int y2 = y1 + b;
				if (y2 < n) {
					g[x1][y1].pb({x2, y2});
					g[x2][y2].pb({x1, y1});
				}
				y2 = y1 - b;
				if (x1 != x2 and y2 >= 0) {
					g[x1][y1].pb({x2, y2});
					g[x2][y2].pb({x1, y1});
				}
			}
		}
	}
}

