		if(col[x][y]) return;
		else col[x][y] = c, num[c]++;
		for(auto t : dir)
			dfs(x+t.first, y+t.second, 3-c);
	}

	void color()
	{
		for(int i=0; i<n*2; i++)
			for(int j=0; j<n*2; j++)
				if(!col[i][j])
					dfs(i, j, 1);
	}
