			ans1.first++;
			r_ans.push_back(ans1);
			ans1.second--;
			r_ans.push_back(ans1);
		}
		return r_ans;
	}
	if (d1 % 4 == 0) { swap(d1, d2); }
	V<pin> ans = ret((n + 1) / 2, d2/4, d2/4);
	int sz = ans.size();
	V<pin> r_ans;
	if (d1 % 4 == 1) {
