    vector<vector<int>> res(2 * n, vector<int>(2 * n, 0));
    vector<int> ds(2);
    cin >> ds[0] >> ds[1];
    for (int par1 = 0; par1 < 2; ++par1) {
        for (int par2 = 0; par2 < 2; ++par2) {
            for (int w = 0; w < 2; ++w) {
                vector<vector<int>> cur_res(2 * n, vector<int>(2 * n, 0));
                int d = ds[w];
                int step = 1;
                while (d % 4 == 0) {
                    step *= 2;
                    d /= 4;
                }
                if (d % 4 == 3) {
                    continue;
                }
                if (step > cur_res.size()) continue;
                if (d % 4 == 1) {
                    for (int i = 0; i * step < cur_res.size(); ++i) {
                        for (int j = 0; j * step < cur_res.size(); ++j) {
                            if ((i + j) % 2 == par1) {
                                cur_res[i][j] = 1;
                            }
                        }
                    }
                } else {
                    assert(d % 4 == 2);
                    for (int i = par2; i * step < cur_res.size(); i += 2) {
                        for (int j = 0; j * step < cur_res.size(); ++j) {
                            cur_res[i][j] = 1;
                        }
                    }
                }
                for (int i = 0; i < cur_res.size(); ++i) {
                    for (int j = 0; j < cur_res.size(); ++j) {
                        res[i][j] += cur_res[i / step][j / step];
                    }
                }
            }
            vector<pair<int, int>> ans;
            for (int i = 0; i < res.size(); ++i) {
                for (int j = 0; j < res.size(); ++j) {
                    if (res[i][j] == 2) {
                        ans.push_back({i, j});
                    }
                }
            }
            if (ans.size() >= n * n) {
                for (int i = 0; i < n * n; ++i) {
                    cout << ans[i].first << " " << ans[i].second << "\n";
                }
                return;
            }
        }
    }

    assert(false);


}

