V ans;
int O(pa x){
	return ((x.fi+x.se)%2+2)%2;
}
pa r45(pa x){
	if (O(x)==0) return mp((x.fi+x.se)/2,(x.fi-x.se)/2);
	else return mp((x.fi+x.se+1)/2,(x.fi-x.se+1)/2);
}
pa r045(pa x){
	return mp(x.fi+x.se,x.fi-x.se);
}
pa r145(pa x){
	return mp(x.fi+x.se-1,x.fi-x.se);
}
V solve(V a,int d1,int d2){
	if (d1>d2) swap(d1,d2);
	if (d1==0 && d2==0) return a;
	if (d1==0){
		if (d2&1){
			int cnt[2];
			cnt[0]=cnt[1]=0;
			FOR(i,0,SZ(a)-1) ++cnt[O(a[i])];
			int t=((cnt[0]>=cnt[1])?0:1);
			V ans;
			ans.clear();
			FOR(i,0,SZ(a)-1) if (O(a[i])==t) ans.pb(a[i]);
			return ans;
		}
		else{
			V a0,a1;
			a0.clear();
			a1.clear();
			FOR(i,0,SZ(a)-1)
				if (O(a[i])==0) a0.pb(r45(a[i]));
				else a1.pb(r45(a[i]));
			V ans0=solve(a0,d1,d2/2);
			V ans1=solve(a1,d1,d2/2);
			V ans;
			ans.clear();
			FOR(i,0,SZ(ans0)-1) ans.pb(r045(ans0[i]));
			FOR(i,0,SZ(ans1)-1) ans.pb(r145(ans1[i]));
			return ans;
		}
	}
	if (d1%2==1 && d2%2==1){
		int cnt[2];
		cnt[0]=cnt[1]=0;
		FOR(i,0,SZ(a)-1) ++cnt[O(a[i])];
		int t=((cnt[0]>=cnt[1])?0:1);
		V ans;
		ans.clear();
		FOR(i,0,SZ(a)-1) if (O(a[i])==t) ans.pb(a[i]);
		return ans;
	}
	if (d1%2==0 && d2%2==0){
		V a0,a1;
		a0.clear();
		a1.clear();
		FOR(i,0,SZ(a)-1)
			if (O(a[i])==0) a0.pb(r45(a[i]));
			else a1.pb(r45(a[i]));
		V ans0=solve(a0,d1/2,d2/2);
		V ans1=solve(a1,d1/2,d2/2);
		V ans;
		ans.clear();
		FOR(i,0,SZ(ans0)-1) ans.pb(r045(ans0[i]));
		FOR(i,0,SZ(ans1)-1) ans.pb(r145(ans1[i]));
		return ans;
	}
	if (d2%2!=0) swap(d1,d2);
	V a0,a1;
	a0.clear();
	a1.clear();
	FOR(i,0,SZ(a)-1)
		if (O(a[i])==0) a0.pb(r45(a[i]));
		else a1.pb(r45(a[i]));
	V ans0=solve(a0,0,d2/2);
	V ans1=solve(a1,0,d2/2);
	V ans;
	ans.clear();
	if (SZ(ans0)>=SZ(ans1)){
		FOR(i,0,SZ(ans0)-1) ans.pb(r045(ans0[i]));
	}
	else{
		FOR(i,0,SZ(ans1)-1) ans.pb(r145(ans1[i]));
	}
	return ans;
}
