							}
						}
					}
				}
			}
		}
tot++;
		for(i=1;i<=n*n;i++)
		{
			if(vis[i]) continue;
			dfs(i);
		}
	}
}h1,h2;
bool cmp(const int &a,const int &b){return f[a].s[0].size()+f[a].s[1].size()>f[b].s[0].size()+f[b].s[1].size();}
void dfs(int xh,int nas)
{
	if(nas<B) return ;
	if(xh==tot+1)
	{
		int num=0;
		for(int i=1;i<=n;i++)
		{
			for(int j=1;j<=n;j++)
			{
				if(del[p(i,j)]==0) num++,printf("%d %d\n",i-1,j-1);
				if(num==B) exit(0);
			}
		}
		return ;
	}
	int val,i,id;
	for(i=0;i<2;i++)
	{
		id=pl[xh];
		val=nas;
		for(int x:f[id].s[i])
		{
			if(!del[x]) val--;
