void run(int d) {
	int dig = 0;
	while (d % 4 == 0) d >>= 2, ++dig;
	if (d & 1) {
		for (int i = 0; i < n; ++i)
			for (int j = 0; j < n; ++j)
				if ((i >> dig) + (j >> dig) & 1)
					A[i][j] = true;
	} else {
		for (int i = 0; i < n; ++i)
			for (int j = 0; j < n; ++j)
				if ((i >> dig) & 1)
					A[i][j] = true;
	}
}
