void dfs1(int x, int y) {
  if ( used1[y][x] ) return;
  used1[y][x] = true;  
  for ( P p : G1[y][x] ) {
    int nx = p.x, ny = p.y;
    if ( used1[ny][nx] ) continue;    
    color1[ny][nx] = !color1[y][x];
    dfs1(nx, ny);    
  }
}

void dfs2(int x, int y) {
  if ( used2[y][x] ) return;
  used2[y][x] = true;  
  for ( P p : G2[y][x] ) {
    int nx = p.x, ny = p.y;
    if ( used2[ny][nx] ) continue;    
    color2[ny][nx] = !color2[y][x];
    dfs2(nx, ny);    
  }
}

