  cin >> N >> D1 >> D2;

  for ( int i = 0; i < 2*N; i++ ) {
    for ( int j = 0; j < 2*N; j++ ) {
      for ( int x = 0; x <= sqrt(D1); x++ ) {
	int y = sqrt(D1-x*x);
	if ( x*x + y*y != D1 ) continue;
	for ( int a = 0; a < 2; a++ ) {
	  for ( int b = 0; b < 2; b++ ) {
	    int nx = j+dx[a]*x, ny = i+dy[b]*y;
