	    G1[i][j].emplace_back(P{nx, ny});
	  }
	}
      }
    }
  }

  for ( int i = 0; i < 2*N; i++ ) {
    for ( int j = 0; j < 2*N; j++ ) {
      for ( int x = 0; x <= sqrt(D2); x++ ) {
	int y = sqrt(D2-x*x);
	if ( x*x + y*y != D2 ) continue;
	for ( int a = 0; a < 2; a++ ) {
	  for ( int b = 0; b < 2; b++ ) {
	    int nx = j+dx[a]*x, ny = i+dy[b]*y;
	    if ( nx < 0 || ny < 0 || nx >= 2*N || ny >= 2*N ) continue;	    
	    G2[i][j].emplace_back(P{nx, ny});
	  }
	}
      }
    }
  }

  for ( int i = 0; i < 2*N; i++ ) {
    for ( int j = 0; j < 2*N; j++ ) {
      if ( !used1[i][j] ) dfs1(j, i);
      if ( !used2[i][j] ) dfs2(j, i);      
    }
