      if ( !color1[i][j] && color2[i][j] )  ans[2].emplace_back(P{j, i});
      if ( !color1[i][j] && !color2[i][j] ) ans[3].emplace_back(P{j, i});
    }
  }

  for ( int i = 0; i < 4; i++ ) {
