        }
        cout << "-----------\n";
*/
    }
}

void dfs(int r, int c, int ty, int v, int tog, int bv){
    mark[r][c] = v;
    P[v].emplace_back(r,c);
    int nr, nc;
    for(pii &p : adj[ty]){
        nr = r + p.first;
        nc = c + p.second;
        if(nr < 0 || nr >= 2 * n || nc < 0 || nc >= 2 * n) continue;
        if(mark[nr][nc] != bv) continue;
        dfs(nr,nc,ty,tog,v,bv);
    }
}

void pro(){
    for(int i = 0; i < 2*n; i++){
        for(int j = 0; j < 2*n; j++){
            if(mark[i][j] != -1) continue;
            dfs(i,j,0,0,1,-1);
        }
    }
    int dom = (P[1].size() >= P[0].size() ? 1 : 0);
    for(pii &p : P[dom]){
        if(mark[p.first][p.second] != dom) continue;
        dfs(p.first,p.second,1,2,3,1);
    }
    int ddom = (P[3].size() >= P[2].size() ? 3 : 2);

    assert(P[ddom].size() >= n * n);
    int C = n * n;
    for(int i = 0; i < C; i++){
        cout << P[ddom][i].first << ' ' << P[ddom][i].second << '\n';
    }
}

