#include <bits/stdc++.h>
using namespace std;
int n,col1[605][605],col2[605][605];
vector<pair<int,int>>s[2];
void Init(int d,vector<pair<int,int>>&v){
    for(int i=0;i<=d;i++){
        int j=sqrt(d-i*i);
        if(i*i+j*j!=d)continue;
        v.emplace_back(+i,+j);
        v.emplace_back(+i,-j);
        v.emplace_back(-i,+j);
        v.emplace_back(-i,-j);
    }
}
void dfs(int x,int y,int c,vector<pair<int,int>>&v,int col[][605]){
    col[x][y]=c;
    for(auto d:v){
        int dx,dy;tie(dx,dy)=d;
        dx+=x,dy+=y;
        if(dx<0||dy<0||dx>=2*n||dy>=2*n)continue;
        if(!col[dx][dy])
            dfs(dx,dy,-c,v,col);
    }
}
void Solve(vector<pair<int,int>>&v,int col[][605]){
    for(int i=0;i<2*n;i++)
        for(int j=0;j<2*n;j++)
            if(!col[i][j])
                dfs(i,j,1,v,col);
}
int main(){
    int d1,d2;
    cin>>n>>d1>>d2;
    Init(d1,s[0]);
    Init(d2,s[1]);
    Solve(s[0],col1);
    Solve(s[1],col2);
    vector<pair<int,int>>ans;
    for(int i=0;i<2*n;i++)
        for(int j=0;j<2*n;j++)
            if(col1[i][j]==col1[0][0]&&col2[i][j]==col2[0][0])
                ans.emplace_back(i,j);
    for(int i=0;i<n*n;i++)
        cout<<ans[i].first<<" "<<ans[i].second<<"\n";
    return 0;
}

