		for(x=0;x<2*n;++x)
			for(y=0;y<2*n;++y)
			{
				if(i==0)
				{
					if(y+j<2*n)
						Addedge(Id(x,y),Id(x,y+j));
				}
				else
				{
					if(x+i<2*n)
					{
						if(y+j<2*n)
							Addedge(Id(x,y),Id(x+i,y+j));
						if(y-j>=0&&j)
							Addedge(Id(x,y),Id(x+i,y-j));
					}
				}
			}
	}
	for(i=0;i*i<=d2;++i)
	{
		j=(int)sqrt(d2-i*i);
