    cin>>n>>d1>>d2;
    n*=2;

    build(n, d1, adj1);
    build(n, d2, adj2);

    bicolor(n, adj1);
    bicolor(n, adj2);

    vector<pair<int, int>> ans;
    for (int i=0; i<n; i++)
        for (int j=0; j<n; j++)
            if (!bad[i*n+j])
                ans.push_back({i, j});

    for (int i=0; i<n*n/4; i++) cout<<ans[i].first<<" "<<ans[i].second<<"\n";
}

