		DFS1(x-i1[k],y+j1[k],!c);
		DFS1(x-i1[k],y-j1[k],!c);
	}
}
void DFS2(int x,int y,bool c){
	if(x<0||y<0||x>=N||y>=N) return;
	if(v2[x][y]) return;
	v2[x][y]=1, c2[x][y]=c;
	F(k,t1){
		DFS2(x+i2[k],y+j2[k],!c);
		DFS2(x+i2[k],y-j2[k],!c);
		DFS2(x-i2[k],y+j2[k],!c);
		DFS2(x-i2[k],y-j2[k],!c);
	}
}
