  build_graph(D1, N, E1);
  build_graph(D2, N, E2);
  rep(i,0,2) {
    memset(vis, 0, sizeof(vis));
    rep(n,0,4*N*N) {
      if(!vis[n]) {
        if(i == 0) dfs(n, 0, 1, 0, E1);
        else dfs(n, 0, 2, 0, E2);
      }
    }
  }

  int cnt[4] = {0, 0, 0, 0};

  int c = -1;
  for(int i = 0; i < 4*N*N; i++) {
