int main(){
	scanf("%d%d%d", &n, &d1, &d2);
	for(int i = 1; i <= max(d1, d2); ++i) sq[i] = sqrt(i);
	solve(d1, vis1); solve(d2, vis2);
	for(int i = 0; i < 2 * n && cnt < n * n; ++i)
		for(int j = 0; j < 2 * n && cnt < n * n; ++j)
