void del ( int d )
{
	int t = 0;
	while ( d % 4 == 0 ) d /= 4, ++t;

	if ( d & 1 ) {
		lp ( i, 0, m ) lp ( j, 0, m ) if ( ( i >> t & 1 ) ^ ( j >> t & 1 ) ) g[i][j] = false;
	} else {
		lp ( i, 0, m ) if ( i >> t & 1 ) lpi ( j, 1, m ) g[i][j] = false;
	}
}

