using namespace std;

typedef long long ll;

const int maxn = 301;
int a[maxn][maxn];
vector<pair<int, int> > dir;

int dx[] = {1, 1, -1, -1};
int dy[] = {-1, 1, -1, 1};

void add(pair<int, int> pr) {
    for (int i = 0; i < 4; ++i) {
        auto cur = pr;
        cur.first *= dx[i];
        cur.second *= dy[i];
        dir.push_back(cur);
    }
    swap(pr.first, pr.second);
    for (int i = 0; i < 4; ++i) {
        auto cur = pr;
        cur.first *= dx[i];
        cur.second *= dy[i];
        dir.push_back(cur);
    }   
}

pair<int, int> get_dir(int a) {
    for (int i = 0; i <= a; ++i) {
        if (i * 1ll * i + (a - i) * 1ll * (a - i) == a) {
            add({i, a - i});
        }
    }
}

int n;

void apply(int x, int y, pair<int, int> dir) {
    x += dir.first;
    y += dir.second;
    if (x < 0 || y < 0 || x >= 2 * n || y >= 2 * n) {
        return;
    }
    a[x][y] = -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.precision(10);
    cout << fixed;

    cin >> n;
    memset(a, 0, sizeof(a));
    int d1, d2;
    cin >> d1 >> d2;
    get_dir(d1);
    get_dir(d2);
    sort(dir.begin(), dir.end());
    dir.resize(unique(dir.begin(), dir.end()) - dir.begin());

    for (int i = 0; i < 2 * n; ++i) {
        for (int j = 0; j < 2 * n; ++j) {
            if (a[i][j] == 0) {
                a[i][j] = 1;
                for (auto d : dir) {
                    apply(i, j, d);
                }
            }
        }
    }

    int have = 0;
    int need = n * n;
    for (int i = 0; i < 2 * n; ++i) {
        for (int j = 0; j < 2 * n; ++j) {
            if (a[i][j] == 1) {
                cout << i << ' ' << j << '\n';
                have++;
            }
            if (have == need) {
                return 0;
            }
        }
    }

    return 0;
}

