		if (x >= 2 * N)return;
		if (y >= 2 * N)return;
		if (x < 0)return;
		if (y < 0)return;
		bannedPos[x + y * 2 * N] = true;
	};
	auto isBanned = [&](int64_t x, int64_t y)->bool {
		return bannedPos[x + y * 2 * N];
	};
	for (int64_t i = 0; i < 2 * N; i++)
	{
		for (int64_t j = 0; j < 2 * N; j++)
		{

			if (isBanned(i, j)) continue;
			else {
				for (auto n : offsList) {
					banPos(i + n.first, j + n.second);
				}
				cout << i << " " << j << endl;
				++c;
				if (c == N * N)goto END;
			}
		}
	}
