const int N = 605;

int n, p, q, col[N][N], ans[N][N];
vector <pii> trs;

inline void DFS(int x, int y) {
  for (auto e : trs) {
    int p = x + e.X, q = y + e.Y;
    if (p >= 0 && p < n && q >= 0 && q < n) {
      if (!~col[p][q]) {
        col[p][q] = !col[x][y], DFS(p, q);
      }
    }
  }
}


inline void SFD(int x, int y) {
  for (auto e : trs) {
    int p = x + e.X, q = y + e.Y;
    if (p >= 0 && p < n && q >= 0 && q < n && !ans[p][q]) {
      if (!~col[p][q]) {
        col[p][q] = !col[x][y], SFD(p, q);
      }
    } else if (p >= n && p < n << 1 && q >= 0 && q < n && ans[p - n][q]) {
      if (!~col[p][q]) {
        col[p][q] = !col[x][y], SFD(p, q);
      }
    }
  }
}

