					if(vx<0||vy<0||vx>2*n||vy>2*n) continue;
					if(sign2[vx][vy]!=-1) continue;
					sign2[vx][vy]=1; q.push(vx); q.push(vy);
				}
			}
		}

	for(int i=0;i<2*n;i++) for(int j=0;j<2*n;j++) 
		ct[sign1[i][j]*2+sign2[i][j]]++;
	for(int z=0;z<=3;z++) if(ct[z]>=n*n)
	{
		int cnt=0; for(int i=0;i<2*n&&cnt<n*n;i++) 
			for(int j=0;j<2*n&&cnt<n*n;j++)
				if(sign1[i][j]*2+sign2[i][j]==z) 
					printf("%d %d\n",i,j),cnt++;
		if(cnt!=n*n) assert(0); 
		return 0;
	}
	return 0;
}

