bool u[N][N];
int dx[] = {1, 1, -1, -1};
int dy[] = {-1, 1, -1, 1};

void _solve(int n, int d1, int d2, bool D = true) {
    int m = n * 2;

    if (d1 % 4 > 0 && d2 % 4 > 0) {
        if (D) {
            cerr << n << " " << d1 << " " << d2 << " it = ez4\n";
            return;
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                cout << i * 2 << " " << j * 2 << "\n";
            }
        }
        return;
    }

    if (d1 % 3 > 0 && d2 % 3 > 0) {
        if (D) {
            cerr << n << " " << d1 << " " << d2 << " it = ez3\n";
            return;
        }
        int num = 0;
        for (int sum = 0; num < n * n; sum += 3) {
            for (int i = 0; i < m; i++) {
                int j = sum - i;
                if (j < 0 || j >= m) continue;
                num++;
                cout << i << " " << j << "\n";
            }
        }
        return;
    }

    int num = n * n;
    vector<pair<int, int>> v, badv;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < m; j++) {
            v.push_back(make_pair(i, j));
            int dist = i * i + j * j;
            if (dist == d1 || dist == d2) {
                badv.push_back(make_pair(i, j));
                //cerr << "bad: " << i << " " << j << "\n";
            }
        }
    }

    int it = 0;
    while (true) {
        it++;
        //random_shuffle(v.begin(), v.end());
        vector<int> x, y;
        int num = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                u[i][j] = false;
            }
        }

        int iq = -1;
        while (iq + 1 < (int)v.size()) {
            iq++;
            if (it > 1 && rand() % 50 == 0) {
                v.push_back(v[iq]);
                continue;
            }
            int xx = v[iq].second;
            int yy = v[iq].first;
            bool ok = true;

            for (auto w: badv) {
                for (int dir = 0; dir < 4; dir++) {
                    int nx = xx + dx[dir] * w.first;
                    int ny = yy + dy[dir] * w.second;
                    if (nx >= 0 && ny >= 0 && nx < m && ny < m && u[ny][nx]) {
                        ok = false;
                        break;
                    }
                }
            }

            if (ok) {
                u[yy][xx] = true;
                num++;
                x.push_back(xx);
                y.push_back(yy);
            }
        }
        while ((int)v.size() > m * m) v.pop_back();

        //cerr << it << " " << num << " " << n * n << "\n";

        if (num >= n * n) {
            if (D) {
                cerr << n << " " << d1 << " " << d2 << " it = " << it << "\n";
                break;
            }
            for (int i = 0; i < n * n; i++) {
                cout << x[i] << " " << y[i] << "\n";
            }
            break;
        }

        //if (it > 100) random_shuffle(v.begin(), v.end());
    }
}

void solve() {
    int n, d1, d2;
    cin >> n >> d1 >> d2;
    _solve(n, d1, d2, false);
}

