vector<pair<int,int>> solve(int n, int d1, int d2, int w){
  vector<pair<int,int>> ans;

  vector<vector<int>> p(2*n, vector<int>(2*n, 0));
  for(int ii=0; ii<w && ii<2*n; ii++){
    for(int jj=0; jj<w && jj<2*n; jj++){
      for(int ik=0; ;ik++){
        int i = w*ik + ii;
        if( i>= 2*n ) break;
        for(int jk=0; ; jk++){
          int j = w*jk + jj;
          if(j >= 2*n) break;
          if( p[i][j] < 0 ) continue;
          p[i][j] = 1;
          ans.push_back( {i,j} );
          for(int yy=0; yy<2*n; yy++){
            int dy = i - yy;
            int dx2 = d1 - dy*dy;
            if(dx2 < 0) continue;
            int dx = sqrt(dx2);

            if( dx*dx + dy*dy != d1 ) continue;

            if( dx*dx == dx2 ){
              int xx = j + dx;
              if( 0<= xx && xx < 2*n ){
                p[yy][xx] -= 1;
              }
              xx = j-dx;
              if( 0<= xx && xx < 2*n ){
                p[yy][xx] -= 1;
              }
            }
          }

          for(int yy=0; yy<2*n; yy++){
            int dy = i - yy;
            int dx2 = d2 - dy*dy;
            if(dx2 < 0) continue;
            int dx = sqrt(dx2);
            if( dx*dx + dy*dy != d2 ) continue;
            if( dx*dx == dx2 ){
              int xx = j + dx;
              if( 0<= xx && xx < 2*n ){
                p[yy][xx] -= 1;
              }
              xx = j-dx;
              if( 0<= xx && xx < 2*n ){
                p[yy][xx] -= 1;
              }
            }
          }

          // for(int yy=0; yy<2*n; yy++){
          //   eprintln(p[yy]);
          // }
          // eprintln("");
        }
      }
    }
  }

  return ans;
}

int main(){
  int n, d1, d2;
  cin >> n, d1, d2;


  vector<pair<int,int>> ans = solve(n, d1, d2, floor(sqrt(d1) + sqrt(d2)));
  for(int k=1; k<2*n && ans.size() < n*n; k++){
    ans = solve(n, d1, d2, mt()%(2*n)+1 );
  }

