#define abs(a,b) ((a)-(b)>0?(a)-(b):(b)-(a))

using vec_t = std::vector<std::pair<int,int>>;

bool f(vec_t &vec,int D1,int D2,int idx,int N)
{
	if(vec.size()==N*N)return true;
	for(int ij=idx+1;ij<4*N*N;++ij){
		int i=ij/(N*2);
		int j=ij%(N*2);
		bool flag =true;
		for(auto& pair:vec)
		{
			auto dist = abs(pair.first,i)*abs(pair.first,i)+abs(pair.second,j)*abs(pair.second,j);
			if(dist==D1 || dist==D2){
				flag=false;
				break;
			}
		}
		if(flag)
		{
			vec.emplace_back(i,j);
			auto result = f(vec,D1,D2,ij,N);
			if(result)
				return true;
			vec.pop_back();
		}
	}
	return false;
}


int main()
{
	int N,D1,D2;
	std::cin>>N>>D1>>D2;
	vec_t vec;
	f(vec,D1,D2,-1,N);
	for(auto& pair:vec)
		std::cout<<pair.first<<" "<<pair.second<<std::endl;
}

#include <iostream>
