vector<int>v[N*N];
vector<pair<int,int> >vc;
unordered_map<int,pair<int,int> >mp;
vector<int>v1,v2,ans;
bool iq[N];
void solve(int u)
{
    memset(iq,false,sizeof(iq));
    queue<pair<int,int> >q;
    q.push({u,0});
    iq[u]=true;
    while(!q.empty())
    {
        int u=q.front().first,st=q.front().second;q.pop();
        vv[u]=true;
        if(st==0) v1.push_back(u);
        for(int i=0;i<v[u].size();i++)
        {
            int x=v[u][i];if(iq[x]) continue;
            iq[x]=true;
            q.push({x,st^1});
        }
    }
    if(v[u].size()==0) return;
    memset(iq,false,sizeof(iq));
    q.push({v[u][0],0});
    iq[v[u][0]]=true;
    while(!q.empty())
    {
        int u=q.front().first,st=q.front().second;q.pop();
        if(st==0) v2.push_back(u);
        for(int i=0;i<v[u].size();i++)
        {
            int x=v[u][i];if(iq[x]) continue;
            iq[x]=true;
            q.push({x,st^1});
        }
    }
}
void solve(int i,int j,int x,int y)
{
    if(x<0||x>=2*n||y<0||y>=2*n) return;
    int a=id[i][j],b=id[x][y];
    if(vis[a][b]) return;
    vis[a][b]=vis[b][a]=true;
    v[a].push_back(b);
    v[b].push_back(a);
}
int main()
{
    scanf("%d%d%d",&n,&d1,&d2);
    for(int i=0;i*i<=d1;i++)
    {
        int x=sqrt(d1-i*i);
        if(x*x==d1-i*i&&!vis[i][x])
        {
            vc.push_back({i,x});
            vis[i][x]=vis[x][i]=true;
        }
    }
    for(int i=0;i*i<=d2;i++)
    {
        int x=sqrt(d2-i*i);
        if(x*x==d2-i*i&&!vis[i][x])
        {
            vc.push_back({i,x});
            vis[i][x]=vis[x][i]=true;
        }
    }
    memset(vis,false,sizeof(vis));
    for(int i=0;i<2*n;i++)
        for(int j=0;j<2*n;j++)
        id[i][j]=++tot,mp[tot]={i,j};
    for(int i=0;i<2*n;i++)
        for(int j=0;j<2*n;j++)
    {
        for(int k=0;k<vc.size();k++)
        {
            for(int h=0;h<=1;h++)
                for(int s=0;h<=1;h++)
                solve(i,j,i+(h?1:-1)*vc[k].first,j+(s?1:-1)*vc[k].second);
            swap(vc[k].first,vc[k].second);
            for(int h=0;h<=1;h++)
                for(int s=0;h<=1;h++)
                solve(i,j,i+(h?1:-1)*vc[k].first,j+(s?1:-1)*vc[k].second);
        }
    }
    for(int i=1;i<=tot;i++)
        if(!vv[i])
    {
        v1.clear();v2.clear();
        solve(i);
        if(v1.size()>v2.size()) ans.insert(ans.end(),v1.begin(),v1.end());
        else ans.insert(ans.end(),v2.begin(),v2.end());
    }
    if(ans.size()<n*n){printf("-1\n");return 0;}
    for(int i=0;i<n*n;i++)
        printf("%d %d\n",mp[ans[i]].first,mp[ans[i]].second);
}

