void makemkj(rs g[],mkj x[],int n){
    int i,ms=0,nst=g[0].st;
    for(i=1;i<n;i++){
        if(g[i].st!=g[i-1].st){
            x[nst].kz=i-ms;
            x[nst].st=ms;
            nst=g[i].st;ms=i;
        }
    }
    x[nst].kz=n-ms;
    x[nst].st=ms;
}

int mlis(int d,int sl[],int tl[]){
  int c=0,i,j;
  for(i=0;i<=600;i++){
    for(j=0;j<=600;j++){
      if(i*i+j*j==d){
        sl[c]=i;tl[c]=j;
        c++;
      }
    }
  }
  return c;
}

