void clbig(int ver,int pc,int col[],rs g[],mkj x[]){
  int i;
  if(col[ver]!=0){return;}
  col[ver]=3-pc;
  for(i=x[ver].st;i<x[ver].st+x[ver].kz;i++){
    clbig(g[i].fi,col[ver],col,g,x);
  }
}

