typedef struct{
    int st;
    int fi;
}rs;

typedef struct{
    int st;
    int kz;
}mkj;

int sortfnc(const void *a,const void *b){
if(((rs*)a)->st == ((rs*)b)->st){return 0;}
if(((rs*)a)->st < ((rs*)b)->st){return -1;}
return 1;
}

void makemkj(rs g[],mkj x[],int n){
    int i,ms=0,nst=g[0].st;
    for(i=1;i<n;i++){
        if(g[i].st!=g[i-1].st){
            x[nst].kz=i-ms;
            x[nst].st=ms;
            nst=g[i].st;ms=i;
        }
    }
    x[nst].kz=n-ms;
    x[nst].st=ms;
}

int mlis(int d,int sl[],int tl[]){
  int c=0,i,j;
  for(i=0;i<=600;i++){
    for(j=0;j<=600;j++){
      if(i*i+j*j==d){
        sl[c]=i;tl[c]=j;
        c++;
      }
    }
  }
  return c;
}

int n;
int vid(int a,int b){
  return 2*n*a+b;
}

//coloring bipartite graph
//color:1 or 2,nocolor = 0
void clbig(int ver,int pc,int col[],rs g[],mkj x[]){
  int i;
  if(col[ver]!=0){return;}
  col[ver]=3-pc;
  for(i=x[ver].st;i<x[ver].st+x[ver].kz;i++){
    clbig(g[i].fi,col[ver],col,g,x);
  }
}

