int match(int i, int j, int num, int x[], int y[], int d, int e) {
  int k;
  for (k=0; k<num; k++) {
    int dx = i-x[k];
    int dy = j-y[k];
    if (dx*dx + dy*dy == d) return 1;
    if (dx*dx + dy*dy == e) return 1;
  }
  return 0;
}


