void makemkj(rs g[],mkj x[],int n){
    int i,ms=0,nst=g[0].st;
    for(i=1;i<n;i++){
        if(g[i].st!=g[i-1].st){
            x[nst].kz=i-ms;
            x[nst].st=ms;
            nst=g[i].st;ms=i;
        }
    }
    x[nst].kz=n-ms;
    x[nst].st=ms;
}

int mlis(int d,int sl[],int tl[]){
  int c=0,i,j,st,fi,te;
  for(i=0;i<=600;i++){
    if(i*i>d){break;}
    if(i*i+600*600<d){continue;}
    st=0;fi=600;
    while(st<=fi){
      te=(st+fi)/2;
      if(i*i+te*te==d){
        sl[c]=i;
        tl[c]=te;
        c++;
        break;
      }
      else if(i*i+te*te>d){fi=te-1;}
      else{st=te+1;}
    }
  }
  return c;
}

