ll mpow(ll x,ll n){
  ll ans = 1;
  while(n!=0){
    if(n&1) ans=ans*x%M;
    x = x*x%M;
    n=n>>1;
  }
  return ans;
}

ll combi(ll n,ll r){
  if(n==0&&r==0)return 1;
  if(n<r||n<0)return 0;
  ll tmp = ifact[r]*ifact[n-r]%M;
  return fact[n]*tmp%M;
}

