class BooleanArray2D(val size1: Int, val size2: Int) {
  val innerArray = BooleanArray(size1 * size2)

  operator fun get(i1: Int, i2: Int): Boolean = innerArray[i2 + size2 * i1]

  operator fun set(i1: Int, i2: Int, v: Boolean) {
    innerArray[i2 + size2 * i1] = v
  }
}

data class Int2D(val x: Int, val y: Int)

fun addVs(d: Int, mutableVs: MutableList<Int2D>) {
  for (x in 0..d) {
    if (x * x > d) break
    val dy = Math.sqrt((d - x * x).toDouble())
    val y = Math.round(dy).toInt()
    if (x * x + y * y != d) continue
    mutableVs.add(Int2D(x, y))
  }
}

