    for (int i = 0; i < two / 2; i ++) {
      cell *= 2;
    }

    boolean[][] ret = new boolean[n * 2][n * 2];
    for (int i = 0; i < n * 2; i ++) {
      for (int j = 0; j < n * 2; j ++) {
        if (two % 2 == 0 && (i / cell + j / cell) % 2 == 0) {
          ret[i][j] = true;
        } else if (two % 2 == 1 && i / cell % 2 == 0) {
          ret[i][j] = true;
        }
      }
    }
    //dump(ret);
    return ret;
  }

