			Random random = new Random(1);
			int k = 0;
			boolean[][] used = new boolean[2 * n][2 * n];

			while (k < n * n) {
				int bestX = 0;
				int bestY = 0;
				int bestBad = -1;
				int bestR = 0;
				for (int it = 0; it < 10; it++) {
					int x = random.nextInt(2 * n);
					int y = random.nextInt(2 * n);
					while (used[x][y]) {
						x = random.nextInt(2 * n);
						y = random.nextInt(2 * n);
					}
					int bad = 0;
					for (Point p : forbidden) {
						int nx = x + p.x;
						int ny = y + p.y;
						if (nx >= 0 && nx < 2 * n && ny >= 0 && ny < 2 * n && used[nx][ny]) {
							++bad;
						}
					}
					int dx = x - n;
					int dy = y - n;
					int r = dx * dx + dy * dy;
					if (bestBad < 0 || bestBad > bad || bestBad == bad && bestR < r) {
						bestBad = bad;
						bestX = x;
						bestY = y;
						bestR = r;
					}
				}
				int x = bestX;
				int y = bestY;
				for (Point p : forbidden) {
					int nx = x + p.x;
					int ny = y + p.y;
					if (nx >= 0 && nx < 2 * n && ny >= 0 && ny < 2 * n && used[nx][ny]) {
						--k;
						used[nx][ny] = false;
					}
				}
				++k;
				used[x][y] = true;
			}

			for (int x = 0; x < 2 * n; x++) {
				for (int y = 0; y < 2 * n; y++) {
					if (used[x][y]) {
						out.println(x + " " + y);
					}
				}
			}
		}

		class Point {
			int x;
			int y;

			Point(int x, int y) {
				this.x = x;
				this.y = y;
			}

		}

	}

