                        ++count;
                    }
                }

                counts[i][j] = count;
            }
        }

        int[] is = new int[size * size];
        int[] js = new int[size * size];
        int[][] vs = new int[size][size];

        for (int i = 0, index = 0; i < size; ++i) {
            for (int j = 0; j < size; ++j, ++index) {
                is[index] = i;
                js[index] = j;
                vs[i][j] = index;
            }
        }

        List<Integer> order = order(size * size);
        Collections.shuffle(order);

        NavigableSet<Integer> countSet = new TreeSet<>();
        Queue<Integer>[] byCounts = new Queue[badDeltas.length + 1];
        for (int count = 0; count <= badDeltas.length; ++count) {
            byCounts[count] = new ArrayDeque<>();
        }

        for (int index : order) {
            int i = is[index], j = js[index];
            int count = counts[i][j];
            byCounts[count].add(index);
            countSet.add(count);
        }

        boolean[][] used = new boolean[size][size];

        List<Point> answer = new ArrayList<>();
        for (int i = 0; i < n * n; ++i) {
            int count = countSet.first();

            int index = byCounts[count].poll();
            if (byCounts[count].size() == 0) countSet.pollFirst();

            int px = is[index], py = js[index];
            if (used[px][py]) {
                --i;
                continue;
            }

            answer.add(new Point(px, py));
            used[px][py] = true;

            for (Point delta : badDeltas) {
                int x = px + delta.x;
                int y = py + delta.y;

                if (!checkCell(x, size, y, size)) continue;

                if (!used[x][y]) {
                    used[x][y] = true;

                    for (Point badDelta : badDeltas) {
                        int xx = x + badDelta.x;
                        int yy = y + badDelta.y;

                        if (!checkCell(xx, size, yy, size)) continue;
                        if (used[xx][yy]) continue;

                        int goodCount = counts[xx][yy];
                        --goodCount;
                        counts[xx][yy] = goodCount;

                        byCounts[goodCount].add(vs[xx][yy]);
                        countSet.add(goodCount);
                    }
                }
            }
        }

        return answer;
    }

    long inverse(long x) {
        return binpow(x, MODULO - 2);
    }

    long binpow(long base, long power) {
        if (power == 0) return 1;
        if ((power & 1) == 0) {
            long half = binpow(base, power >> 1);
            return mult(half, half);
        } else {
            long prev = binpow(base, power - 1);
            return mult(prev, base);
        }
    }

    /////////////////////////////////////////////////////////////////////

    private static long add(long a, long b) { return (a + b) % MODULO; }
    private static long subtract(long a, long b) { return add(a, MODULO - b % MODULO); }
    private static long mult(long a, long b) { return (a * b) % MODULO; }

