/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		ProblemD solver = new ProblemD();
		solver.solve(1, in, out);
		out.close();
	}

	static class ProblemD {
		int n;
		Point[] ans;
		int k;
		boolean[][] used;
		List<Point>[] forbidden;
		Random random = new Random(0);

		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			n = in.nextInt();
			int d1 = in.nextInt();
			int d2 = in.nextInt();
			List<Point> p1 = new ArrayList<>();
			List<Point> p2 = new ArrayList<>();
			for (int x = -2 * n; x <= 0; x++) {
				for (int y = -2 * n; y <= 2 * n; y++) {
					Point p = new Point(x, y);
					if (x * x + y * y == d1) {
						p1.add(p);
					}
					if (x * x + y * y == d2) {
						p2.add(p);
					}
				}
			}
			forbidden = new List[2];
			forbidden[0] = p1;
			forbidden[1] = p2;
			ans = new Point[n * n];
			used = new boolean[2 * n][2 * n];
			for (double prob = 0; ; prob += 0.05) {
				solve(prob);
				if (k == ans.length) {
					break;
				}
			}
			for (int i = 0; i < k; i++) {
				out.println(ans[i].x + " " + ans[i].y);
			}
		}

		private void solve(double prob) {
			k = 0;
			for (int x = 0; x < 2 * n; x++) {
				for (int y = 0; y < 2 * n; y++) {
					if (k == ans.length) {
						return;
					}
					if (random.nextDouble() < prob && k < 100) {
						continue;
					}
					boolean ok = true;
					outer:
					for (List<Point> l : forbidden) {
						for (Point p : l) {
							int nx = x + p.x;
							int ny = y + p.y;
							if (nx >= 0 && nx < 2 * n && ny >= 0 && ny < 2 * n && used[nx][ny]) {
								ok = false;
								break outer;
							}
						}
					}

					if (ok) {
						used[x][y] = true;
						ans[k++] = new Point(x, y);
					}
				}
			}
		}

		class Point {
			int x;
			int y;

			Point(int x, int y) {
				this.x = x;
				this.y = y;
			}

		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

