				inner:
				for(int k = 0;k < 2;k++){
					for(int l = 0;l < 2;l++){
						if(pex(i*2+k, j*2+l, n, map, s1) == 0 && 
								pex(i*2+k, j*2+l, n, map, s2) == 0){
							map[i*2+k][j*2+l] = true;
							put++;
							break inner;
						}
					}
				}
			}
		}

		for(int i = 0;i < 2*n;i++){
			for(int j = 0;j < 2*n;j++){
				if(put < n*n && !map[i][j]){
