//			}
//		}
		int pe = 0;
		for(int i = 0;i < 2*n;i++){
			for(int j = 0;j < 2*n;j++){
				if(map[i][j]){
					pe += pe(i, j, n, map, s1);
					pe += pe(i, j, n, map, s2);
				}
			}
