	static boolean[][] greedy1(int n, int[][] s1, int[][] s2)
	{
		boolean[][] map = new boolean[2*n][2*n];
		int put = 0;
		for(int i = 0;i < 2*n;i++){
			for(int j = 0;j < 2*n;j++){
				if(pex(i, j, n, map, s1) == 0 && 
						pex(i, j, n, map, s2) == 0){
					map[i][j] = true;
					if(++put == n*n)return map;
