                    edge[i*2*n+j].add(new int[]{k,j+d});
                    edge[i*2*n+rj].add(new int[]{k, rj-d});
                    edge[ri*2*n+j].add(new int[]{ri-(k-i),j+d});
                    edge[ri*2*n+rj].add(new int[]{ri-(k-i),rj-d});

