                    seen[cur[0]][cur[1]] = true;
                    map[cur[0]][cur[1]] = cur[2];
                    for(int[] r : edge[cur[0]*2*n+cur[1]]){
                        if(seen[r[0]][r[1]]) continue;
                        que.add(new int[]{r[0],r[1],1-cur[2]});
                        seen[r[0]][r[1]]=true;
                    }
                }
            }
        }
