    static class agc025d {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();

            int d1 = in.nextInt();

            int d2 = in.nextInt();

            Set<point> points = new HashSet<>();

            for (int i = 0; i * i <= d1; i++) {
                int sq = i * i;

                int rem = d1 - sq;

                int root = in.squareRoot(rem);

                if (root * root == rem) {
                    points.add(new point(i, root));
                }
            }

            int[][] isp = new int[2 * n][2 * n];

            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    if (isp[i][j] == 0) {
                        for (point point : points) {
                            for (int a = -1; a <= 1; a += 2) {
                                for (int b = -1; b <= 1; b += 2) {
                                    int x = i + a * point.x;
                                    int y = j + b * point.y;

                                    if (x >= 0 && x < 2 * n && y >= 0 && y < 2 * n) {
                                        isp[x][y] = 1;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            points.clear();

            for (int i = 0; i * i <= d2; i++) {
                int sq = i * i;

                int rem = d2 - sq;

                int root = in.squareRoot(rem);

                if (root * root == rem) {
                    points.add(new point(i, root));
                }
            }

            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    if ((isp[i][j] & 2) == 0) {
                        for (point point : points) {
                            for (int a = -1; a <= 1; a += 2) {
                                for (int b = -1; b <= 1; b += 2) {
                                    int x = i + a * point.x;
                                    int y = j + b * point.y;

                                    if (x >= 0 && x < 2 * n && y >= 0 && y < 2 * n) {
                                        isp[x][y] |= 2;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            int[] cnt = new int[4];
            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    cnt[isp[i][j]]++;
                }
            }

            int di = -1;

            int n2 = n * n;

            if (cnt[0] >= n2) {
                di = 0;
            } else if (cnt[1] >= n2) {
                di = 1;
            } else if (cnt[2] >= n2) {
                di = 2;
            } else {
                di = 3;
            }

            int cc = 0;
            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    if (isp[i][j] == di) {
                        out.println(i + " " + j);
                        cc++;

                        if (cc == n2) {
                            return;
                        }
                    }
                }
            }
        }

        class point {
            int x;
            int y;

            public point(int x, int y) {
                this.x = x;
                this.y = y;
            }

            public boolean equals(Object o) {
                if (this == o) return true;
                if (o == null || getClass() != o.getClass()) return false;
                point point = (point) o;
                return x == point.x &&
                        y == point.y;
            }

            public int hashCode() {
                return Objects.hash(x, y);
            }

        }

    }

