		}
		Queue<int[]> q = new ArrayDeque<>();
		for(int i = 0;i < n;i++){
			for(int j = 0;j < n;j++){
				if(color[i][j] == -1){
					q.add(new int[]{i, j});
					color[i][j] = 0;
					while(!q.isEmpty()){
						int[] cur = q.poll();
						int x = cur[0], y = cur[1];
						for(int[] nei : neis){
							int nx = x + nei[0], ny = y + nei[1];
							if(nx >= 0 && nx < n && ny >= 0 && ny < n && color[nx][ny] == -1){
