    static class TaskD {
        ArrayList<int[]> svd1 = new ArrayList<>();
        ArrayList<int[]> svd2 = new ArrayList<>();
        int[][] data;

        public void solve(int testNumber, MyScan in, PrintWriter out) {
            int n = in.nextInt();
            int d1 = in.nextInt();
            int d2 = in.nextInt();
            svd1 = fillSq(d1);
            svd2 = fillSq(d2);

            data = new int[n * 2][n * 2];
            boolean[][] vis = new boolean[n * 2][n * 2];
            for (int s = 0; s < n * 2; s++) {
                for (int x = 0; x < n * 2; x++) {
                    if (vis[s][x]) continue;
                    vis[s][x] = true;
                    fillf(vis, 0, 0, svd1, 1, 1);
                }
            }


            vis = new boolean[n * 2][n * 2];
            for (int s = 0; s < n * 2; s++) {
                for (int x = 0; x < n * 2; x++) {
                    if (vis[s][x]) continue;
                    vis[s][x] = true;
                    fillf(vis, 0, 0, svd2, 2, 2);
                }
            }
//        for(int [] r : data) {
//            System.out.println(Arrays.toString(r));
//        }
            for (int s = 0; s < 4; s++) {
                int sum = 0;
                for (int l = 0; l < n * 2; l++) {
                    for (int l1 = 0; l1 < n * 2; l1++) {
                        if (data[l][l1] == s) {
                            sum++;
                        }
                    }
                }

                if (sum >= n * n) {
                    sum = 0;
                    for (int l = 0; l < n * 2; l++) {
                        for (int l1 = 0; l1 < n * 2; l1++) {
                            if (data[l][l1] == s) {
                                out.println(l + " " + l1);
                                sum++;
                            }
                            if (sum == n * n) return;
                        }
                    }
                }
            }

        }

        private ArrayList<int[]> fillSq(int d) {
            ArrayList<int[]> ans = new ArrayList<>();
            int mm = (int) Math.sqrt(d);
            for (int r = -mm; r <= mm; r++) {
                int off = d - r * r;
                int l = (int) Math.sqrt(off);
                if (l * l == off) {
                    if (l == 0) {
                        ans.add(new int[]{0, r});
                    } else {
                        ans.add(new int[]{-l, r});
                        ans.add(new int[]{l, r});
                    }
                }
            }
            return ans;
        }

        private void fillf(boolean[][] vis, int posx, int posy, ArrayList<int[]> svd, int point, int meta) {
            for (int[] p : svd) {
                int nx = posx + p[0];
                int ny = posy + p[1];
                if (nx >= vis.length || ny >= vis.length || nx < 0 || ny < 0 || vis[nx][ny]) {
                    continue;
                }
                vis[nx][ny] = true;
                data[nx][ny] += point;
                fillf(vis, nx, ny, svd, meta - point, meta);

            }
        }

    }

