    static class D {
        List<D.Point> getCircle(int sqDist) {
            List<D.Point> list = new ArrayList<>();
            for (int x = floorSqrt(sqDist); x >= 0; x--) {
                int sqY = sqDist - x * x;
                int y = ceilSqrt(sqY);
                if (y * y == sqY) {
                    list.add(new D.Point(x, y));
                    if (y > 0) list.add(new D.Point(x, -y));
                    if (x > 0) list.add(new D.Point(-x, y));
                    if (x > 0 && y > 0) list.add(new D.Point(-x, -y));
                }
            }
            return list;
        }

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int d1 = in.readInt();
            int d2 = in.readInt();
            List<D.Point> list1 = getCircle(d1);
            List<D.Point> list2 = getCircle(d2);
//        System.err.println(list1);
//        System.err.println(list2);

            int[] deg = new int[4 * n * n];
            int[][] g = new int[4 * n * n][300];
            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    int v1 = i * 2 * n + j;
                    for (D.Point p : list1) {
                        int x = i + p.x;
                        int y = j + p.y;
                        if (0 <= x && x < 2 * n && 0 <= y && y < 2 * n) {
//                        System.err.println(new Point(i, j) + " <-> " + new Point(x, y));
                            int v2 = x * 2 * n + y;
                            g[v1][deg[v1]++] = v2;
                            g[v2][deg[v2]++] = v1;
                        }
                    }
//                for (Point p : list2) {
//                    int x = i + p.x;
//                    int y = j + p.y;
//                    if (0 <= x && x < 2 * n && 0 <= y && y < 2 * n) {
////                        System.err.println(new Point(i, j) + " <-> " + new Point(x, y));
//                        int v2 = x * 2 * n + y;
//                        g[v1][deg[v1]++] = v2;
//                        g[v2][deg[v2]++] = v1;
//                    }
//                }
                }
            }

            int[] color1 = new int[g.length];
            for (int i = 0; i < g.length; i++) {
                if (color1[i] == 0) {
                    dfs(g, deg, i, color1, 1);
                }
            }
            int[] cnts1 = new int[3];
            for (int i = 0; i < g.length; i++) {
                cnts1[color1[i]]++;
            }
            int bestColor1 = cnts1[1] > cnts1[2] ? 1 : 2;

            // part 2
            Arrays.fill(deg, 0);
            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    int v1 = i * 2 * n + j;
//                for (Point p : list1) {
//                    int x = i + p.x;
//                    int y = j + p.y;
//                    if (0 <= x && x < 2 * n && 0 <= y && y < 2 * n) {
////                        System.err.println(new Point(i, j) + " <-> " + new Point(x, y));
//                        int v2 = x * 2 * n + y;
//                        g[v1][deg[v1]++] = v2;
//                        g[v2][deg[v2]++] = v1;
//                    }
//                }
                    for (D.Point p : list2) {
                        int x = i + p.x;
                        int y = j + p.y;
                        if (0 <= x && x < 2 * n && 0 <= y && y < 2 * n) {
//                        System.err.println(new Point(i, j) + " <-> " + new Point(x, y));
                            int v2 = x * 2 * n + y;
                            g[v1][deg[v1]++] = v2;
                            g[v2][deg[v2]++] = v1;
                        }
                    }
                }
            }

            int[] color2 = new int[g.length];
            for (int i = 0; i < g.length; i++) {
                if (color1[i] == bestColor1) {
                    if (color2[i] == 0) {
                        dfs(g, deg, i, color2, color1[i]);
                    }
                }
            }
            int[] cnts2 = new int[3];
            for (int i = 0; i < g.length; i++) {
                cnts2[color2[i]]++;
            }
            int bestColor2 = cnts2[1] > cnts2[2] ? 1 : 2;
            int cntRes = 0;
            finish:
            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    int v = i * 2 * n + j;
//                System.err.println(color1[v] + " " + color2[v]);
                    if (color1[v] == bestColor1 && color2[v] == bestColor2) {
