					Point p = new Point(x, y);
					if (x * x + y * y == d1) {
						p1.add(p);
					}
					if (x * x + y * y == d2) {
						p2.add(p);
					}
				}
			}
			forbidden = new List[2];
			forbidden[0] = p1;
			forbidden[1] = p2;
			ans = new Point[n * n];
			used = new boolean[2 * n][2 * n];
			for (double prob = 0; ; prob = Math.min(0.3, prob + 0.05)) {
				solve(prob);
				if (k == ans.length) {
					break;
				}
			}
			for (int i = 0; i < k; i++) {
				out.println(ans[i].x + " " + ans[i].y);
			}
