								int ny = y + p.y;
								if (nx >= 0 && nx < 2 * n && ny >= 0 && ny < 2 * n && used[nx][ny]) {
									ok = false;
									break outer;
								}
							}
						}

						if (ok) {
							used[x][y] = true;
							ans[k++] = new Point(x, y);
						}
					}
				}
			}
		}

