        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();

            int d1 = in.nextInt();

            int d2 = in.nextInt();

            Set<point> points = new HashSet<>();

            for (int i = 0; i * i <= d1; i++) {
                int sq = i * i;

                int rem = d1 - sq;

                int root = in.squareRoot(rem);

                if (root * root == rem) {
                    points.add(new point(i, root));
                }
            }

            int[][] isp = new int[2 * n][2 * n];

            boolean[][] vis = new boolean[2 * n][2 * n];
            int[][] l = new int[2 * n][2 * n];

            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    if (!vis[i][j]) {
                        bfs(isp, i, j, vis, points, 1, l, n);
                    }
                }
            }

            points = new HashSet<>();

            for (int i = 0; i * i <= d2; i++) {
                int sq = i * i;

                int rem = d2 - sq;

                int root = in.squareRoot(rem);

                if (root * root == rem) {
                    points.add(new point(i, root));
                }
            }

            vis = new boolean[2 * n][2 * n];
            l = new int[2 * n][2 * n];

            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    if (!vis[i][j]) {
                        bfs(isp, i, j, vis, points, 2, l, n);
                    }
                }
            }

            int[] cnt = new int[4];
            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    cnt[isp[i][j]]++;
                }
            }

            int di = -1;

            int n2 = n * n;

            for (int i = 0; i < 4; i++) {
                if (cnt[i] >= n2) {
                    di = i;
                    break;
                }
            }

            int cc = 0;
            for (int i = 0; i < 2 * n; i++) {
                for (int j = 0; j < 2 * n; j++) {
                    if (isp[i][j] == di) {
                        out.println(i + " " + j);
                        cc++;

                        if (cc == n2) {
                            return;
                        }
                    }
                }
            }
        }

        void bfs(int[][] isp, int sr, int sc, boolean[][] vis, Set<point> points, int add, int[][] l, int n) {
            vis[sr][sc] = true;

            ArrayDeque<point> q = new ArrayDeque<>();

            q.addLast(new point(sr, sc));

            while (!q.isEmpty()) {
                point p = q.removeFirst();

                int i = p.x;
                int j = p.y;

                for (point point : points) {
                    for (int a = -1; a <= 1; a += 2) {
                        for (int b = -1; b <= 1; b += 2) {
                            int x = i + a * point.x;
                            int y = j + b * point.y;

                            if (x >= 0 && x < 2 * n && y >= 0 && y < 2 * n) {
                                if (!vis[x][y]) {
                                    vis[x][y] = true;
                                    if (l[i][j] % 2 == 0) {
                                        isp[x][y] |= add;
                                    }

                                    l[x][y] = l[i][j] + 1;
                                    q.addLast(new point(x, y));
                                }
                            }
                        }
                    }
                }
            }
        }

        class point {
            int x;
            int y;

            public point(int x, int y) {
                this.x = x;
                this.y = y;
            }

            public boolean equals(Object o) {
                if (this == o) return true;
                if (o == null || getClass() != o.getClass()) return false;
                point point = (point) o;
                return x == point.x &&
                        y == point.y;
            }

            public int hashCode() {
                return Objects.hash(x, y);
            }

        }

    }

