				for (int sx = 0; sx < 2 * n; sx++) {
					for (int sy = 0; sy < 2 * n; sy++) {
						int sc = (col[sx][sy] / p3) % 3;
						if (sc != 0) {
							continue;
						}
						qx[0] = sx;
						qy[0] = sy;
						int qt = 0;
						int qh = 1;
						col[sx][sy] += p3;
						while (qt < qh) {
							int x = qx[qt];
							int y = qy[qt];
							int c = (col[x][y] / p3) % 3;
							++qt;
							for (Point p : ps) {
								int nx = x + p.x;
								int ny = y + p.y;
								if (nx < 0 || nx >= 2 * n || ny < 0 || ny >= 2 * n) {
									continue;
								}
								int nc = (col[nx][ny] / p3) % 3;
								if (nc != 0) {
									if (nc != 3 - c) {
										throw new AssertionError();
									}
									continue;
								}
								col[nx][ny] += p3 * (3 - c);
								qx[qh] = nx;
								qy[qh] = ny;
								++qh;
							}
						}
					}
				}
			}

			int[] colSize = new int[9];
			for (int x = 0; x < 2 * n; x++) {
				for (int y = 0; y < 2 * n; y++) {
					++colSize[col[x][y]];
				}
			}
			int bestCol = 0;
			for (int i = 0; i < colSize.length; i++) {
				if (colSize[bestCol] < colSize[i]) {
					bestCol = i;
				}
			}
			int k = n * n;
			for (int x = 0; x < 2 * n; x++) {
				for (int y = 0; y < 2 * n; y++) {
					if (k > 0 && col[x][y] == bestCol) {
						out.println(x + " " + y);
						--k;
					}
				}
			}
			if (k != 0) {
				throw new AssertionError();
			}
		}

		class Point {
			int x;
			int y;

			Point(int x, int y) {
				this.x = x;
				this.y = y;
			}

		}

	}

