  private static int[][] circle(int d, int n) {
    List<int[]> ret = new ArrayList<>();
    for (int x = -n * 2; x <= n * 2; x++) {
      for (int y = -n * 2; y <= n * 2; y++) {
        if (x * x + y * y == d) {
          ret.add(new int[] {y, x});
        }
      }
    }
    return ret.stream().toArray(size -> new int[size][]);
  }

