//        System.out.println(a);
//        System.out.println(b);
        List<Pair> ans = new ArrayList<>();
        boolean[][] b = new boolean[2 * n][2 * n];
        int required = n * n;

        loop:
        for (int i = 0; i < 2 * n; i++) {
            for (int j = 0; j < 2 * n; j++) {
                if (!b[i][j]) {
                    ans.add(new Pair(i, j));
                    if (ans.size() == required) {
                        break loop;
                    }
                    for (Pair p : t) {
                        int toX = i + p.x;
                        int toY = j + p.y;
                        if (toX >= 0 && toY >= 0 && toX < b.length && toY < b.length) {
                            b[toX][toY] = true;
                        }
                    }
                }
            }
        }
        if (ans.size() < required) {
            System.out.println("fail");
        } else {
            for (Pair p : ans) {
                System.out.println(p.x + " " + p.y);
            }
        }
    }

    private List<Pair> find(int d) {
        List<Pair> r = new ArrayList<>();
        for (int x = 0; x <= d; x++) {
            int sqrY = d - x * x;
            int y = (int) round(sqrt(sqrY));
            if (y * y == sqrY) {
                r.add(new Pair(x, y));
                r.add(new Pair(x, -y));
                r.add(new Pair(-x, y));
                r.add(new Pair(-x, -y));
            }
        }
        return r;
    }

    static class Pair {
        final int x, y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "Pair{" +
                    "x=" + x +
                    ", y=" + y +
                    '}';
        }
