    static int[][] doit(int n, int d) {
        List<int[]> p = checkPair(n, d);
        int[][] map = new int[n][n];
        for (int i = 0; i < n ; i++) {
            Arrays.fill(map[i], -1);
        }

        Queue<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < n ; i++) {
            for (int j = 0; j < n ; j++) {
                if (map[i][j] != -1) {
                    continue;
                }
                q.add(new int[]{i, j});
                map[i][j] = 0;
                while (q.size() >= 1) {
                    int[] now = q.poll();
                    int y = now[0];
                    int x = now[1];
                    for (int[] dd : p) {
                        int ti = y + dd[0];
                        int tj = x + dd[1];
                        if (ti < 0 || tj < 0 || ti >= map.length || tj >= map[0].length) {
                            continue;
                        }
                        if (map[ti][tj] == -1) {
                            map[ti][tj] = map[y][x] ^ 1;
                            q.add(new int[]{ti, tj});
                        }
                    }
                }
            }
        }
        debug(System.currentTimeMillis()-time);

        return map;
    }

