public class Main {

	int root(int x) {
		if (x < 0) {
			return -1;
		}
		int y = (int) Math.sqrt(x);
		if (y * y == x) {
			return y;
		}
		return -1;
	}

	int[][] gen(int dist) {
		ArrayList<Integer> ret = new ArrayList<>();
		for (int i = 0; i * i <= dist; i++) {
			int j = root(dist - i * i);
			if (j == -1) {
				continue;
			}
			ret.add(i);
			ret.add(j);
			ret.add(i);
			ret.add(-j);
			ret.add(-i);
			ret.add(j);
			ret.add(-i);
			ret.add(-j);
		}
		int[][] a = new int[2][ret.size() / 2];
		for (int i = 0; i < ret.size(); i += 2) {
			a[0][i / 2] = ret.get(i);
			a[1][i / 2] = ret.get(i + 1);
		}
		return a;
	}

	int[] dx;
	int[] dy;

	void dfs(int x, int y, int n, int color, int[][] f) {
		f[x][y] = color;

		for (int i = 0; i < dx.length; i++) {
			int cx = x + dx[i];
			int cy = y + dy[i];
			if (cx < 0 || cy < 0 || cx >= n || cy >= n) {
				continue;
			}
			if (f[cx][cy] == color) {
				throw new AssertionError();
			}
			if (f[cx][cy] == 0) {
				dfs(cx, cy, n, 3 - color, f);
			}
		}
	}

	int[][] color(int n, int dist) {
		// delta = gen(dist);
		int[][] tmp = gen(dist);
		dx = tmp[0];
		dy = tmp[1];
		int[][] f = new int[n][n];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (f[i][j] == 0) {
					dfs(i, j, n, 1, f);
				}
			}
		}
		return f;
	}

	void solve(int n, int d1, int d2) {
		int[][] a = color(2 * n, d1);
		int[][] b = color(2 * n, d2);

		int[] cnt = new int[4];
		for (int i = 0; i < 2 * n; i++) {
			for (int j = 0; j < 2 * n; j++) {
				int val = (a[i][j] - 1) * 2 + (b[i][j] - 1);
				cnt[val]++;
			}
		}

		int pick = 0;
		while (cnt[pick] < n * n) {
			pick++;
		}

		int left = n * n;

		for (int i = 0; i < 2 * n; i++) {
			for (int j = 0; j < 2 * n; j++) {
				int val = (a[i][j] - 1) * 2 + (b[i][j] - 1);
				if (val == pick) {
					out.println(i + " " + j);
					left--;
					if (left == 0) {
						return;
					}
				}
			}
		}
	}

	void submit() {
		solve(nextInt(), nextInt(), nextInt());
	}

