    static List<Point> f(int n, int d1, int d2) {
        List<Point> deltas1 = new ArrayList<>(), deltas2 = new ArrayList<>();

        int size = 2 * n;
        for (int dx = -size + 1; dx <= size - 1; ++dx) {
            for (int dy = -size + 1; dy <= size - 1; ++dy) {
                int sum = dx * dx + dy * dy;
                if (sum == d1) deltas1.add(new Point(dx, dy));
                if (sum == d2) deltas2.add(new Point(dx, dy));
            }
        }

        GraphBuilder
                graphBuilder1 = GraphBuilder.createInstance(size * size),
                graphBuilder2 = GraphBuilder.createInstance(size * size);

        for (int x = 0; x < size; ++x) {
            for (int y = 0; y < size; ++y) {
                int v = x * size + y;

                for (Point delta1 : deltas1) {
                    int xx = x + delta1.x;
                    int yy = y + delta1.y;

                    if (!checkCell(xx, size, yy, size)) continue;

                    int vv = xx * size + yy;
                    graphBuilder1.addEdge(v, vv);
                }

                for (Point delta2 : deltas2) {
                    int xx = x + delta2.x;
                    int yy = y + delta2.y;

                    if (!checkCell(xx, size, yy, size)) continue;

                    int vv = xx * size + yy;
                    graphBuilder2.addEdge(v, vv);
                }
            }
        }

        int[][] graph1 = graphBuilder1.build(), graph2 = graphBuilder2.build();
        int[][][] graphs = { graph1, graph2 };

        int[] colors = new int[size * size];

        for (int i = 0; i < graphs.length; ++i) {
            int[][] graph = graphs[i];

            int[] distances = new int[size * size];
            Arrays.fill(distances, -1);

            for (int v = 0; v < graph.length; ++v) {
                if (distances[v] != -1) continue;

                Queue<Integer> queue = new ArrayDeque<>();

                queue.add(v);
                distances[v] = 0;

                while (queue.size() > 0) {
                    int from = queue.poll();
                    colors[from] |= (distances[from] << i);
                    for (int to : graph[from]) {
                        if (distances[to] != -1) continue;
                        distances[to] = distances[from] ^ 1;
                        queue.add(to);
                    }
                }
            }
        }

        int[] sizes = new int[4];
        for (int color : colors) sizes[color]++;

        for (int color = 0; color < 4; ++color) {
            if (sizes[color] >= n * n) {
                List<Point> answer = new ArrayList<>();
                for (int v = 0; answer.size() < n * n && v < colors.length; ++v) {
                    if (colors[v] == color) {
                        answer.add(new Point(v / size, v % size));
                    }
                }

                return answer;
            }
        }

        throw new UnsupportedOperationException();
    }

