        int[][] listarr = new int[list.size()][2];
        int t = 0;
        for(int[] i : list){
            listarr[t][0] = i[0];
            listarr[t][1] = i[1];
            t++;
        }
        int count = 0;
        long start = System.currentTimeMillis();
        for(int i = 0; i < n; i++){
