public class Main {
    public interface IJPredicator {
        boolean shouldSkip(int i, int j);
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int d1 = in.nextInt();
        int d2 = in.nextInt();

        char[][] map1 = doit(n*2, d1);
        char[][] map2 = doit(n*2, d2);

        int[][] d0 = new int[map1.length][map1[0].length];

        int[] cnt = new int[4];
        for (int i = 0; i < d0.length ; i++) {
            for (int j = 0; j < d0[0].length ; j++) {
                int a = map1[i][j] == '@' ? 1 : 0;
                int b = map2[i][j] == '@' ? 2 : 0;
                d0[i][j] = a+b;
                cnt[a+b]++;
            }
        }

        List<int[]> ans = new ArrayList<>();
        for (int k = 0; k < 4 ; k++) {
            if (cnt[k] >= n*n) {
                sch: for (int i = 0; i < d0.length ; i++) {
                    for (int j = 0; j < d0[0].length; j++) {
                        if (d0[i][j] == k) {
                            ans.add(new int[]{i, j});
                            if (ans.size() == n*n) {
                                break sch;
                            }
                        }
                    }
                }
                break;
            }
        }
        printAndFlush(out, ans);
    }

    static void paint(char[][] map, List<int[]> p, int i, int j, char c) {
        if (map[i][j] != 0) {
            return;
        }
        map[i][j] = c;
        for (int[] dd : p) {
            int ti = i + dd[0];
            int tj = j + dd[1];
            if (ti < 0 || tj < 0 || ti >= map.length || tj >= map[0].length) {
                continue;
            }
            paint(map, p, ti, tj, c == '@' ? '.' : '@');
        }
    }

    static char[][] doit(int n, int d) {
        List<int[]> p = checkPair(n, d);
        char[][] map = new char[n][n];

        for (int i = 0; i < n ; i++) {
            for (int j = 0; j < n ; j++) {
                if (map[i][j] != 0) {
                    continue;
                }
                paint(map, p, i, j, '@');
            }
        }
        return map;
    }

    static void printAndFlush(PrintWriter out, List<int[]> ans) {
        for (int[] a : ans) {
            out.println(String.format("%d %d", a[0], a[1]));
        }
        out.flush();
    }

    static List<int[]> checkPair(int n, int d) {
        List<int[]> wo = new ArrayList<>();
        for (int i = 0; i < 2*n ; i++) {
            for (int j = 0; j < 2*n; j++) {
                int ii = i*i;
                int jj = j*j;
                if (ii + jj == d) {
                    for (int dy = -1 ; dy <= 1 ; dy += 2) {
                        for (int dx = -1 ; dx <= 1 ; dx += 2) {
                            wo.add(new int[]{i * dy, j * dx});
                        }
                    }
                }
            }
        }
        return wo;
    }

    static int dist(int[] a, int[] b) {
        int dx = Math.abs(a[0]-b[0]);
        int dy = Math.abs(a[1]-b[1]);
        return dx*dx+dy*dy;
    }

    static List<List<int[]>> pairs;

    private static List<int[]> solve(int n, int d1, int d2, IJPredicator pred) {
        boolean[][] tbl = new boolean[2*n][2*n];
        List<int[]> selected = new ArrayList<>();
        sch: for (int i = 0; i < 2*n ; i++) {
            for (int j = 0; j < 2*n ; j++) {
                if (pred.shouldSkip(i, j)) {
                    continue;
                }
                if (canPlace(tbl, i, j, d1, d2)) {
                    tbl[i][j] = true;
                    selected.add(new int[]{i, j});
                    if (selected.size() == n*n) {
                        break sch;
                    }
                }
            }
        }
        return selected;
    }

    private static boolean canPlace(boolean[][] tbl, int y, int x, int d1, int d2) {
        int n = tbl.length;
        for (List<int[]> pa : pairs) {
            for (int[] f : pa) {
                int ty = y + f[0];
                int tx = x + f[1];
                if (ty < 0 || tx < 0 || ty >= n || tx >= n) {
                    continue;
                }
                if (tbl[ty][tx]) {
                    return false;
                }
            }
        }
        return true;
    }

