import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    public interface IJPredicator {
        boolean shouldSkip(int i, int j);
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int d1 = in.nextInt();
        int d2 = in.nextInt();

        char[][] map1 = doit(n*2, d1);
        char[][] map2 = doit(n*2, d2);

        int[][] d0 = new int[map1.length][map1[0].length];

        int[] cnt = new int[n*2];
        for (int i = 0; i < d0.length ; i++) {
            for (int j = 0; j < d0[0].length ; j++) {
                int a = map1[i][j] == '@' ? 1 : 0;
                int b = map2[i][j] == '@' ? 2 : 0;
                d0[i][j] = a+b;
                cnt[a+b]++;
            }
        }

        List<int[]> ans = new ArrayList<>();
        for (int k = 0; k < 4 ; k++) {
            if (cnt[k] >= n*n) {
                sch: for (int i = 0; i < d0.length ; i++) {
                    for (int j = 0; j < d0[0].length; j++) {
                        if (d0[i][j] == k) {
                            ans.add(new int[]{i, j});
                            if (ans.size() == n*n) {
                                break sch;
                            }
                        }
                    }
                }
                break;
            }
        }
        printAndFlush(out, ans);
    }

    static char[][] doit(int n, int d) {
        List<int[]> p = checkPair(n, d);
        char[][] map = new char[n][n];
        for (int i = 0; i < n ; i++) {
            for (int j = 0; j < n ; j++) {
                boolean isok = true;
                sch: for (int[] dd : p) {
                    int ti = i + dd[0];
                    int tj = j + dd[1];
                    if (ti < 0 || tj < 0 || ti >= map.length || tj >= map[0].length) {
                        continue;
                    }
                    if (map[ti][tj] == '@') {
                        isok = false;
                        break sch;
                    }
                }
                map[i][j] = isok ? '@' : '.';
            }
        }
//        System.out.println(String.format("d=%d", d));
//        for (int i = 0 ; i < n ; i++) {
//            System.out.println(String.valueOf(map[i]));
//        }
        return map;
    }

    static void printAndFlush(PrintWriter out, List<int[]> ans) {
        for (int[] a : ans) {
            out.println(String.format("%d %d", a[0], a[1]));
        }
        out.flush();
    }

    static List<int[]> checkPair(int n, int d) {
        List<int[]> wo = new ArrayList<>();
        for (int i = 0; i < 2*n ; i++) {
            for (int j = 0; j < 2*n; j++) {
                int ii = i*i;
                int jj = j*j;
                if (ii + jj == d) {
                    for (int dy = -1 ; dy <= 1 ; dy += 2) {
                        for (int dx = -1 ; dx <= 1 ; dx += 2) {
                            wo.add(new int[]{i * dy, j * dx});
                        }
                    }
                }
            }
        }
        return wo;
    }

    static int dist(int[] a, int[] b) {
        int dx = Math.abs(a[0]-b[0]);
        int dy = Math.abs(a[1]-b[1]);
        return dx*dx+dy*dy;
    }

    static List<List<int[]>> pairs;

    private static List<int[]> solve(int n, int d1, int d2, IJPredicator pred) {
        boolean[][] tbl = new boolean[2*n][2*n];
        List<int[]> selected = new ArrayList<>();
        sch: for (int i = 0; i < 2*n ; i++) {
            for (int j = 0; j < 2*n ; j++) {
                if (pred.shouldSkip(i, j)) {
                    continue;
                }
                if (canPlace(tbl, i, j, d1, d2)) {
                    tbl[i][j] = true;
                    selected.add(new int[]{i, j});
                    if (selected.size() == n*n) {
                        break sch;
                    }
                }
            }
        }
        return selected;
    }

    private static boolean canPlace(boolean[][] tbl, int y, int x, int d1, int d2) {
        int n = tbl.length;
        for (List<int[]> pa : pairs) {
            for (int[] f : pa) {
                int ty = y + f[0];
                int tx = x + f[1];
                if (ty < 0 || tx < 0 || ty >= n || tx >= n) {
                    continue;
                }
                if (tbl[ty][tx]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }

    public static class InputReader {
        private static final int BUFFER_LENGTH = 1 << 12;
        private InputStream stream;
        private byte[] buf = new byte[BUFFER_LENGTH];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int next() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            return (char) skipWhileSpace();
        }

        public String nextToken() {
            int c = skipWhileSpace();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = skipWhileSpace();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        int skipWhileSpace() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            return c;
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    private final int n;
    private final long d1;
    private final long d2;

    public Main(final int n, final long d1, final long d2) {
        this.n = n;
        this.d1 = d1;
        this.d2 = d2;
    }

    static class Pos {
        final long x;
        final long y;

        public Pos(final long x, final long y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return x + " " + y;
        }

        public long getX() {return this.x;}

        public long getY() {return this.y;}

        @Override
        public boolean equals(final Object o) {
            if (o == this) { return true; }
            if (!(o instanceof Pos)) { return false; }
            final Pos other = (Pos) o;
            if (!other.canEqual((Object) this)) { return false; }
            if (this.getX() != other.getX()) { return false; }
            if (this.getY() != other.getY()) { return false; }
            return true;
        }

        @Override
        public int hashCode() {
            final int PRIME = 59;
            int result = 1;
            final long $x = this.getX();
            result = result * PRIME + (int) ($x >>> 32 ^ $x);
            final long $y = this.getY();
            result = result * PRIME + (int) ($y >>> 32 ^ $y);
            return result;
        }

        protected boolean canEqual(final Object other) {return other instanceof Pos;}
    }

    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final long d1 = scanner.nextLong();
        final long d2 = scanner.nextLong();

        final Main main = new Main(n, d1, d2);
        final List<Pos> positions = main.main();
        positions.forEach(item -> System.out.println(item));
    }

    public List<Pos> main() {
        final long d1arr[] = new long[n * 2];
        final long d2arr[] = new long[n * 2];

        final int[][] ints = new int[n * 2][n * 2];
        for (int i = 0; i < ints.length; ++i) {
            ints[i] = new int[n * 2];
        }

        for (int i = 0; i < n * 2; ++i) {
            final long intsqrt1 = intsqrt(d1 - i * i);
            d1arr[i] = intsqrt1;

            final long intsqrt2 = intsqrt(d2 - i * i);
            d2arr[i] = intsqrt2;
        }

        final List<Pos> positions = new ArrayList<>();
        for (int x = 0; x < n * 2; ++x) {
            for (int y = 0; y < n * 2; ++y) {
                if (ints[x][y] < 0) {
                    continue;
                }
                positions.add(new Pos(x, y));

                for (int yd = 0; yd < n * 2 - y; yd++) {
                    if (d1arr[yd] >= 0 && (x + d1arr[yd] < n * 2)) {
                        ints[x + (int) d1arr[yd]][y + yd] = -1;
                    }
                    if (d2arr[yd] >= 0 && (x + d2arr[yd] < n * 2)) {
                        ints[x + (int) d2arr[yd]][y + yd] = -1;
                    }
                }
                if (positions.size() == n * n) {
                    break;
                }
            }
            if (positions.size() == n * n) {
                break;
            }
        }
        return positions;

    }

    static long intsqrt(final long i) {
        for (long k = 0; k < i + 1; ++k) {
            if (i == k * k) {
                return k;
            }
            if (i < k * k) {
                return -1;
            }
        }
        return -1;
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.List;
import java.util.StringTokenizer;
import java.util.Random;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		ProblemD solver = new ProblemD();
		solver.solve(1, in, out);
		out.close();
	}

	static class ProblemD {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int d1 = in.nextInt();
			int d2 = in.nextInt();
			List<Point> forbidden = new ArrayList<>();
			for (int x = -2 * n; x <= 2 * n; x++) {
				for (int y = -2 * n; y <= 2 * n; y++) {
					Point p = new Point(x, y);
					int d = x * x + y * y;
					if (d == d1 || d == d2) {
						forbidden.add(p);
					}
				}
			}

			Random random = new Random(0);
			int k = 0;
			boolean[][] used = new boolean[2 * n][2 * n];

			while (k < n * n) {
				int bestX = 0;
				int bestY = 0;
				int bestBad = -1;
				for (int it = 0; it < 5; it++) {
					int x = random.nextInt(2 * n);
					int y = random.nextInt(2 * n);
					while (used[x][y]) {
						x = random.nextInt(2 * n);
						y = random.nextInt(2 * n);
					}
					int bad = 0;
					for (Point p : forbidden) {
						int nx = x + p.x;
						int ny = y + p.y;
						if (nx >= 0 && nx < 2 * n && ny >= 0 && ny < 2 * n && used[nx][ny]) {
							++bad;
						}
					}
					if (bestBad < 0 || bestBad > bad) {
						bestBad = bad;
						bestX = x;
						bestY = y;
					}
				}
				int x = bestX;
				int y = bestY;
				for (Point p : forbidden) {
					int nx = x + p.x;
					int ny = y + p.y;
					if (nx >= 0 && nx < 2 * n && ny >= 0 && ny < 2 * n && used[nx][ny]) {
						--k;
						used[nx][ny] = false;
					}
				}
				++k;
				used[x][y] = true;
			}

			for (int x = 0; x < 2 * n; x++) {
				for (int y = 0; y < 2 * n; y++) {
					if (used[x][y]) {
						out.println(x + " " + y);
					}
				}
			}
		}

		class Point {
			int x;
			int y;

			Point(int x, int y) {
				this.x = x;
				this.y = y;
			}

		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
