namespace AGC025D
{
    internal class Program
    {
        public static void Main(string[] args)
        {
            long[] input = Array.ConvertAll(Console.ReadLine().Split(' '), long.Parse);
            long N = input[0];
            long n = N * 2;
            Distance d1 = new Distance(input[1]);
            Distance d2 = new Distance(input[2]);
            List<Pair> pairs = d1.P;
            pairs.AddRange(d2.P);

            Point[] ps = new Point[n * n];
            for (long i = 0; i < n; i++)
            {
                for (long j = 0; j < n; j++)
                {
                    ps[i * n + j] = new Point(i, j);
                }
            }

            for (long i = 0; i < n; i++)
            {
                for (long j = 0; j < n; j++)
                {
                    if (!ps[i * n + j].Can)
                    {
                        continue;
                    }

                    pairs.ForEach(pair =>
                    {
                        long ii;
                        long jj;
                        ii = i + pair.A;
                        jj = j + pair.B;
                        if (ii < n && jj < n) ps[ii * n + jj].Can = false;

                        ii = i + pair.B;
                        jj = j + pair.A;
                        if (ii < n && jj < n) ps[ii * n + jj].Can = false;

                        ii = i + pair.A;
                        jj = j - pair.B;
                        if (ii < n && jj >= 0) ps[ii * n + jj].Can = false;

                        ii = i + pair.B;
