        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        int D1 = re.i();
        int D2 = re.i();
        List<int> X = new List<int>();
        List<int> Y = new List<int>();
        for(int i=0;i<2*N;i++){
            for(int j=0;j<2*N;j++){
                int dist = i*i+j*j;
                if(dist == D1 || dist == D2){
                    X.Add(i);
                    Y.Add(j);
                }
            }
        }
        bool[,] Map = new bool[2*N,2*N];
        for(int i=0;i<2*N;i++){
            for(int j=0;j<2*N;j++){
                if(Map[i,j]){
                    continue;
                }
                for(int k=0;k<X.Count;k++){
                    int x = X[k];
                    int y = Y[k];
                    if(i+x < 2*N && j+y < 2*N){
                        Map[i+x,j+y] = true;
                    }
                    if(i+x < 2*N && y-j >= 0){
                        Map[i+x,y-j] = true;
                    }
                }
            }
        }
        int count = N*N;
        for(int i=0;i<2*N;i++){
            for(int j=0;j<2*N;j++){
                if(!Map[i,j]){
                    sb.Append(i+" "+j+"\n");
                    count--;
                    if(count == 0){
                        return;
                    }
                }
            }
        }

    }
}
