class Program
{
    static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
    static Scan sc = new Scan();
    const int M = 1000000007;
    // const int M = 998244353;
    const long LM = (long)1e18;
    const double eps = 1e-11;
    static readonly int[] dd = { 0, 1, 0, -1, 0 };
    const string dstring = "RDLU";
    static void Main()
    {
        sc.Multi(out n, out d1, out d2);
        m = n * n * 4;
        delt = new List<P>();
        for (int i = -n * 2 + 1; i < n * 2; i++)
        {
            for (int j = - n * 2 + 1; j < n * 2; j++)
            {
                if (i * i + j * j == d1 || i * i + j * j == d2) {
                    delt.Add(new P(i, j));
                }
            }
        }
        r = new Random();
        while (!sol());
        sw.Flush();
    }
    static int n, d1, d2, m;
    static Random r;
    static List<P> delt;
    static bool sol() {
        var sg = new Segtree<long>(m, Math.Max, -LM);
        for (int i = 0; i < m; i++)
        {
            sg.assign(i, i);
        }
        long d = 1 << 29;
        sg.all_update();
        var ans = new P[n * n];
        for (int i = 0; i < n * n; i++)
        {
            var pp = sg.run(0, m);
            if (pp < 0) return false;
            int p = (int)(pp % (1 << 20));
            int ti = p / (n * 2), tj = p % (n * 2);
            ans[i] = new P(ti, tj);
            sg.update(p, -LM);
            foreach (var item in delt)
            {
                int si = ti + item.v1, sj = tj + item.v2;
                if (inside(si, sj, n * 2, n * 2)) {
                    var sp = sg.look(si * n * 2 + sj);
                    if (sp < 0) continue;
                    sg.update(si * n * 2 + sj, -LM);
                    if (r.Next(2) == 0)
                        foreach (var j in delt)
                        {
                            int ui = si + j.v1, uj = sj + j.v2;
                            if (inside(ui, uj, n * 2, n * 2)) {
                                var up = sg.look(ui * n * 2 + uj);
                                if (up < 0) continue;
                                sg.update(ui * n * 2 + uj, up + d);
                            }
                        }
                }
            }
        }
        foreach (var item in ans)
        {
            Prt(item);
        }
        return true;
    }

