                if (d2 - j == 0 || sq[d2 - j] > 0)
                    lst.Add(Tuple.Create(i, sq[d2 - j]));
            var plane = Create2DArray<int>(2 * n, 2 * n);
            for (int i = 0; i < 2 * n; ++i)
                for (int j = 0; j < 2 * n; ++j)
                    if (plane[i][j] == 0)
                    {
                        plane[i][j] = 1;
                        for (int c1 = -1; c1 <= 1; c1 += 2)
                            for (int c2 = -1; c2 <= 1; c2 += 2)
                                foreach (var ot in lst)
                                {
                                    if (i + ot.Item1 * c1 >= 0 && i + ot.Item1 * c1 < 2 * n
                                        && j + ot.Item2 * c2 >= 0 && j + ot.Item2 * c2 < 2 * n)
                                        plane[i + ot.Item1 * c1][j + ot.Item2 * c2] = 2;
                                }
                    }
            var z = n * n;
            for (int i = 0; i < 2 * n && z > 0; ++i)
                for (int j = 0; j < 2 * n && z > 0; ++j)
                    if (plane[i][j] == 1)
                    {
                        write.WriteLine(i + " " + j);
                        --z;
                    }
            if (z > 0)
                throw new Exception();
        }
    }
}

