        {
            double droot = Math.Sqrt(D);
            for (long i = 0; i <= droot; i++)
            {
                for (long j = i; j <= droot; j++)
                {
                    long l = i * i + j * j;
                    if (l == D)
                    {
                        if (i == 0 || j == 0)
                        {
                            Pitagoras = Math.Max(i, j);
                            IsPitagoras = true;
                        }
                        else
                        {
                            Can = true;
                            Min = Math.Min(i, j);
                            Max = Math.Max(i, j);
                        }
                    }

                    if (l > D)
                    {
                        break;
                    }
                }
            }
        }
    }

