namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int[][] Solve(int N, int D1, int D2)
        {
            var bads = new List<int[]>();
            for (int i = 0; i < N * 2; ++i)
            {
                for (int j = 0; j < N * 2; ++j)
                {
                    int d = i * i + j * j;
                    if (d == D1 || d == D2) { bads.Add(new int[] { i, j }); }
                }
            }
            var ng = new bool[N * 2][];
            for (int i = 0; i < N * 2; ++i) { ng[i] = new bool[N * 2]; }
            var dots = new List<int[]>();
            for (int i = 0; i < N * 2; ++i)
            {
                for (int j = 0; j < N * 2; ++j)
                {
                    if (!ng[i][j])
                    {
                        dots.Add(new[] { i, j });
                        if (dots.Count == N * N) { return dots.ToArray(); }
                        foreach (var bad in bads)
                        {
                            int x = i + bad[0];
                            int y = j + bad[1];
                            if (0 <= x && x < N * 2 && 0 <= y && y < N * 2)
                            {
                                ng[x][y] = true;
                            }
                        }
                    }
                }
            }
            return Enumerable.Repeat(new[] { 0, 0 }, N * N).ToArray();
        }
        static void Main(string[] args)
        {
            var V = ReadInts();
            foreach (var ans in Solve(V[0], V[1], V[2]))
            {
                Console.WriteLine(string.Join(" ", ans));
            }
        }
