def gcd(a, b):
    """greatest common divisor"""
    if b == 0:
        return a
    else:
        return gcd(b, a % b)


def solve(f):
    n, d1, d2 = f.read_int_list()

    def seek_size():
        x, y = 0, 0
        ddmin = float('inf')
        for i1 in xrange(5):
            for i2 in xrange(5):
                if i1 == i2 == 0: continue
                dd = i1**2 + i2**2
                if dd != d1 and dd != d2 and d1 % dd != 0 and d2 % dd != 0:
                    if dd < ddmin:
                        ddmin = dd
                        x, y = i1, i2
        return x, y

    x, y = seek_size()
    ans = []
    for xx in xrange(-5*n, 5*n):
        for yy in xrange(-5*n, 5*n):
            xi = xx*x + yy*y
            yi = xx*y - yy*x
            if 0 <= xi < 2*n and 0 <= yi < 2*n:
                ans.append("%d %d"%(xi, yi))
            if len(ans) == n**2: break
        if len(ans) == n**2: break

    return "\n".join(ans)


