        ddmin = float('inf')
        for i1 in xrange(3):
            for i2 in xrange(3):
                if i1 == i2 == 0: continue
                dd = i1**2 + i2**2
                if d1 == dd or d2 == dd: continue
                if d1 % dd == 0: continue
                if d2 % dd == 0: continue
                if dd < ddmin:
                    ddmin = dd
                    x, y = i1, i2
        return x, y

