        ii = i**2
        for j in range(i, n*2):
            jj = j**2
            if ii+jj == d1 or ii+jj == d2:
                t.append((i,j))
                t.append((i,-j))
                t.append((-i,j))
                t.append((-i,-j))
                if i != j:
                    t.append((j,i))
                    t.append((j,-i))
                    t.append((-j,i))
                    t.append((-j,-i))
    t = list(set(t))

