def isqrt(n):
    """integer sqrt: the maximum integer less than or equal to sqrt(n)"""
    x = n
    y = (x + 1) // 2
    while y < x:
        x = y
        y = (x + n // x) // 2
    return x

def solve(f):
    n, d1, d2 = f.read_int_list()

    def seek_size():
        x, y = 0, 0
        ddmin = float('inf')
        for i1 in xrange(3):
            for i2 in xrange(3):
                if i1 == i2 == 0: continue
                dd = i1**2 + i2**2
                if d1 == dd or d2 == dd: continue
                if d1 % dd == 0: continue
                if d2 % dd == 0: continue
                if dd < ddmin:
                    ddmin = dd
                    x, y = i1, i2
        return x, y

    x, y = seek_size()
    ans = []
    for xx in xrange(-10*n, 10*n):
        for yy in xrange(-10*n, 10*n):
            xi = xx*x + yy*y
            yi = xx*y - yy*x
            if 0 <= xi < 2*n and 0 <= yi < 2*n:
                ans.append((xi, yi))
            if len(ans) == n**2: break
        if len(ans) == n**2: break
    if len(ans) != n**2:
        for i in ans:
            if 0 <= i[0]+1 < 2*n:
                ans.append((i[0]+1, i[1]))
            if len(ans) == n**2: break
    if len(ans) != n**2: raise RuntimeError

