def isqrt(n):
    """integer sqrt: the maximum integer less than or equal to sqrt(n)"""
    x = n
    y = (x + 1) // 2
    while y < x:
        x = y
        y = (x + n // x) // 2
    return x

def solve(f):
    n, d1, d2 = f.read_int_list()

    a = [[0] * (2*n) for _ in xrange(2*n)]
    g = [collections.defaultdict(list) for _ in xrange(2)]
    d = [d1, d2]

    for i in xrange(2):
        for dx in xrange(2*n):
            dy2 = d[i] - dx**2
            if dy2 < 0: continue
            dy = isqrt(dy2)
            if dy**2 != dy2: continue

            for x in xrange(2*n):
                for y in xrange(2*n):
                    for sgn in [1, -1]:
                        if dx*dy == 0 and sgn == -1: continue
                        if 0 <= x+dx < 2*n and 0 <= y+sgn*dy < 2*n:
                            g[i][(x, y)].append((x+dx, y+sgn*dy))
                            g[i][(x+dx, y+sgn*dy)].append((x, y))

        vis = [[False] * (2*n) for _ in xrange(2*n)]
        for x in xrange(2*n):
            for y in xrange(2*n):
                if not vis[x][y]:
                    c = 2**i
