    let mut graph1 = vec![vec![]; n];
    let mut graph2 = vec![vec![]; n];
    for from in 0..n {
        for dx in 0..n {
            if d1 >= dx * dx {
                let dy = ((d1 - dx * dx) as f64).sqrt().floor() as usize;
                add_edge(from, dx, dy, &mut graph1, &map, &points);
            }
            if d2 >= dx * dx {
                let dy = ((d2 - dx * dx) as f64).sqrt().floor() as usize;
                add_edge(from, dx, dy, &mut graph2, &map, &points);
            }
        }
    }

    let mut color1 = vec![0; n];
