        if color2[i] == 0 {
            color2[0] = 1;
            let result2 = coloring(i, &graph2, &mut color2);
            assert!(result2);
        }
    }

    let mut count = vec![vec![0; 2]; 2];
    for i in 0..m {
        count[color1[i] - 1][color2[i] - 1] += 1;
    }

    let (mut c1, mut c2) = (0, 0);
    for i in 0..2 {
        for j in 0..2 {
            if count[i][j] >= w * w {
                c1 = i + 1;
                c2 = j + 1;
                break;
            }
        }
    }

    assert!(c1 != 0);
    assert!(c2 != 0);
    let mut count = w * w;
    for i in 0..m {
        if color1[i] == c1 && color2[i] == c2 {
            count -= 1;
            let (x, y) = points[i];
            println!("{} {}", x, y);
        }
        if count == 0 {
