}

fn coloring(v: usize, graph: &Vec<Vec<usize>>, color: &mut Vec<usize>) -> bool {
    for &next in graph[v].iter() {
        if color[next] == 0 {
            color[next] = if color[v] == 1 { 2 } else { 1 };
            coloring(next, graph, color);
        } else if color[next] == color[v] {
            return false;
        }
    }
    true
}

fn add_edge(
    from: usize,
    dx: usize,
    dy: usize,
    graph: &mut Vec<Vec<usize>>,
    map: &Vec<Vec<usize>>,
    points: &Vec<(usize, usize)>,
) {
    let (x, y) = points[from];
    let x = x as i64;
    let y = y as i64;
    let dx = dx as i64;
    let dy = dy as i64;
    let next = vec![
        (x + dx, y + dy),
        (x - dx, y + dy),
        (x + dx, y - dy),
        (x - dx, y - dy),
    ];

    let mut to = vec![];
    for &(x, y) in next.iter() {
        if x < 0 || y < 0 {
            continue;
        }

        let x = x as usize;
        let y = y as usize;
        if x >= map.len() || y >= map[x].len() {
            continue;
        }

        to.push(map[x][y]);
    }
    to.sort();
    to.dedup();

    for &to in to.iter() {
        graph[from].push(to);
    }
}

