use io::*;
use std::cmp::{max, min};

#[derive(Debug)]
struct Tree {
    have: bool,
    child: Vec<Box<Tree>>,
}

fn dist(x1: i64, y1: i64, x2: i64, y2: i64) -> i64 {
    (x1 - x2).pow(2) + (y1 - y2).pow(2)
}

impl Tree {
    fn new() -> Tree {
        Tree {
            have: false,
            child: vec![],
        }
    }

    fn find(&self, x: i64, y: i64, di: i64, l: i64, u: i64, r: i64, d: i64) -> bool {
        // println!("{} {} {}: {} {} {} {}", x, y, di, l, u, r, d);

        if r - l == 0 {
            unreachable!()
        }

        if !(l <= x && x < r && u <= y && y < d) {
            let mut max_d = 0;
            let mut min_d = 999999999999;

            let d0 = dist(x, y, l, u);
            let d1 = dist(x, y, l, d - 1);
            let d2 = dist(x, y, r - 1, u);
            let d3 = dist(x, y, r - 1, d - 1);

            max_d = max(max_d, d0);
            max_d = max(max_d, d1);
            max_d = max(max_d, d2);
            max_d = max(max_d, d3);

            min_d = min(min_d, d0);
            min_d = min(min_d, d1);
            min_d = min(min_d, d2);
            min_d = min(min_d, d3);

            if !(min_d <= di && di <= max_d) {
                return false;
            }
        }

        if r - l == 1 {
            return self.have && dist(x, y, l, u) == di;
        }

        let mx = (l + r) / 2;
        let my = (u + d) / 2;

        if self.child.len() > 0 {
            self.child[0].find(x, y, di, l, u, mx, my) || self.child[1].find(x, y, di, l, my, mx, d)
                || self.child[2].find(x, y, di, mx, u, r, my)
                || self.child[3].find(x, y, di, mx, my, r, d)
        } else {
            false
        }
    }

    fn add(&mut self, x: i64, y: i64, l: i64, u: i64, r: i64, d: i64) {
        if r - l == 0 {
            unreachable!()
        }

        if !(l <= x && x < r && u <= y && y < d) {
            return;
        }

        if r - l == 1 {
            assert_eq!(d - u, 1);
            assert_eq!((x, y), (l, u));
            self.have = true;
            return;
        }

        if self.child.len() == 0 {
            for _ in 0..4 {
                self.child.push(Box::new(Tree::new()));
            }
        }

        let mx = (l + r) / 2;
        let my = (u + d) / 2;

        self.child[0].add(x, y, l, u, mx, my);
