                }
            }
        }
    }
}

use std::collections::BTreeSet;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };

    let w: usize = sc.read();
    let d1: usize = sc.read();
    let d2: usize = sc.read();

    let mut map = vec![vec![0; 2 * w]; 2 * w];
    let mut points = vec![];
    for i in 0..(2 * w) {
        for j in 0..(2 * w) {
            map[i][j] = points.len();
            points.push((i, j));
        }
    }

    let m = points.len();
    let mut graph1 = vec![vec![]; m];
    let mut graph2 = vec![vec![]; m];
    for from in 0..m {
        for dx in 0..w {
            if d1 >= dx * dx {
                let dy = ((d1 - dx * dx) as f64).sqrt().floor() as usize;
                add_edge(from, dx, dy, &mut graph1, &map, &points);
            }
            if d2 >= dx * dx {
                let dy = ((d2 - dx * dx) as f64).sqrt().floor() as usize;
                add_edge(from, dx, dy, &mut graph2, &map, &points);
            }
        }
    }

    let mut color1 = vec![0; m];
    color1[0] = 1;
    let result1 = coloring(0, &graph1, &mut color1);
    assert!(result1);

    let mut color2 = vec![0; m];
    color2[0] = 1;
    let result2 = coloring(0, &graph2, &mut color2);
    assert!(result2);

    let mut count = vec![vec![0; 2]; 2];
    for i in 0..m {
        count[color1[i] - 1][color2[i] - 1] += 1;
    }

    let (mut c1, mut c2) = (0, 0);
    for i in 0..2 {
        for j in 0..2 {
            if count[i][j] >= w * w {
                c1 = i + 1;
                c2 = j + 1;
                break;
            }
        }
    }

    assert!(c1 != 0);
    assert!(c2 != 0);
    let mut count = w * w;
    for i in 0..m {
        if color1[i] == c1 && color2[i] == c2 {
            count -= 1;
            let (x, y) = points[i];
            println!("{} {}", x, y);
        }
        if count == 0 {
            break;
        }
    }

    assert_eq!(count, 0);
}

fn coloring(v: usize, graph: &Vec<Vec<usize>>, color: &mut Vec<usize>) -> bool {
    for &next in graph[v].iter() {
        if color[next] == 0 {
            color[next] = if color[v] == 1 { 2 } else { 1 };
            coloring(next, graph, color);
        } else if color[next] == color[v] {
            return false;
        }
    }
    true
}

fn add_edge(
    from: usize,
    dx: usize,
    dy: usize,
    graph: &mut Vec<Vec<usize>>,
    map: &Vec<Vec<usize>>,
    points: &Vec<(usize, usize)>,
) {
    let (x, y) = points[from];
    let x = x as i64;
    let y = y as i64;
    let dx = dx as i64;
    let dy = dy as i64;
    let next = vec![
        (x + dx, y + dy),
        (x - dx, y + dy),
        (x + dx, y - dy),
        (x - dx, y - dy),
    ];

    let mut to = vec![];
    for &(x, y) in next.iter() {
        if x < 0 || y < 0 {
            continue;
        }

        let x = x as usize;
        let y = y as usize;
        if x >= map.len() || y >= map[x].len() {
            continue;
        }

        to.push(map[x][y]);
    }
    to.sort();
    to.dedup();

    for &to in to.iter() {
        graph[from].push(to);
    }
}

pub struct Scanner<R> {
    reader: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .reader
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn read_vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

