                d2s.push((i,-k));
                d2s.push((-i,-k));
            }
        }
    }
    for i in 0..2*n {
        for k in 0..2*n {
            dfs(&mut field1, &d1s, i, k, false);
            dfs(&mut field2, &d2s, i, k, false);
        }
    }
    let mut xs = vec![vec![]; 4];
    for y in 0..2*n {
        for x in 0..2*n {
            let t1 = field1[y][x].unwrap();
            let t2 = field2[y][x].unwrap();
            let i = tf!(t1, 2, 0) + tf!(t2, 1, 0);
            xs[i].push((y, x));
        }
    }
    for i in 0..4 {
        if xs[i].len() >= n * n {
            for &(y,x) in xs[i].iter().take(n*n) {
                println!("{} {}", x, y);
            }
            break;
        }
    }
}

