fn traversal(
    n: usize,
    x: i32,
    y: i32,
    xy: &Vec<(i32, i32)>,
    counts: &mut Vec<Vec<i32>>,
    used: &mut Vec<Vec<bool>>,
    que: &mut BinaryHeap<(i32, i32, i32)>,
    depth: usize,
) {
    for &(dx, dy) in xy.iter() {
        for &ysign in [-1, 1].iter() {
            if dy == 0 && ysign == 1 {
                continue;
            }
            for &xsign in [-1, 1].iter() {
                if dx == 0 && xsign == 1 {
                    continue;
                }
                let nx = x as i32 + dx * xsign;
                let ny = y as i32 + dy * ysign;
                if nx < 0 || nx >= 2 * n as i32 || ny < 0 || ny >= 2 * n as i32
                    || used[ny as usize][nx as usize]
                {
                    continue;
                }
                if depth == 0 {
                    used[ny as usize][nx as usize] = true;
                    traversal(n, nx, ny, xy, counts, used, que, 1)
                } else if depth == 1 {
                    counts[ny as usize][nx as usize] -= 1;
                    assert!(counts[ny as usize][nx as usize] >= 0);
                    que.push((-counts[ny as usize][nx as usize], nx, ny));
                }
            }
        }
    }
}

fn solve(n: usize, ds: Vec<i32>) {
    let mut xy = vec![];
    for iter in 0..2 {
        for x in 0..ds[iter] + 1 {
            if x * x > ds[iter] {
                break;
            }
            let rest = ds[iter] - x * x;
            let y = (rest as f64).sqrt() as i32;
            if y * y == rest {
                xy.push((x, y));
            }
        }
    }
    // println!("{:?}", xy);

    let mut counts = vec![vec![0; 2 * n]; 2 * n];
    for y in 0..2 * n {
        for x in 0..2 * n {
            let mut cnt = 0;
            for &(dx, dy) in xy.iter() {
                for &ysign in [-1, 1].iter() {
                    if dy == 0 && ysign == 1 {
                        continue;
                    }
                    for &xsign in [-1, 1].iter() {
                        if dx == 0 && xsign == 1 {
                            continue;
                        }
                        let nx = x as i32 + dx * xsign;
                        let ny = y as i32 + dy * ysign;
                        if nx < 0 || nx >= 2 * n as i32 || ny < 0 || ny >= 2 * n as i32 {
                            continue;
                        }
                        counts[ny as usize][nx as usize] += 1;
                    }
                }
            }
        }
    }
    let mut anss = vec![];
    let mut used = vec![vec![false; 2 * n]; 2 * n];
    let mut que = BinaryHeap::<(i32, i32, i32)>::new();
    for y in 0..2 * n {
        for x in 0..2 * n {
            que.push((-counts[y][x], x as i32, y as i32));
        }
    }
    while let Some((_, x, y)) = que.pop() {
        if used[y as usize][x as usize] {
            continue;
        }
        used[y as usize][x as usize] = true;
        anss.push((x, y));
        traversal(n, x, y, &xy, &mut counts, &mut used, &mut que, 0);
        if anss.len() == n * n {
            break;
        }
    }

    // WA
    // 'yloop: for y in 0..2 * n {
    //     for x in 0..2 * n {
    //         if used[y][x] {
    //             continue;
    //         }
    //         anss.push((x as i32, y as i32));
    //         for &(dx, dy) in xy.iter() {
    //             for xsign in [-1, 1].iter() {
    //                 let nx = x as i32 + dx as i32 * xsign;
    //                 let ny = y as i32 + dy;
    //                 if nx < 0 || nx >= 2 * n as i32 || ny >= 2 * n as i32 {
    //                     continue;
    //                 }
    //                 used[ny as usize][nx as usize] = true;
    //             }
    //         }
    //         if anss.len() == n * n {
    //             break 'yloop;
    //         }
    //     }
    // }
    if anss.len() != n * n {
        anss = vec![];
        let mut used = vec![vec![false; 2 * n]; 2 * n];
        'y2loop: for y in 0..2 * n {
            for x in 0..2 * n {
                if used[y][x] || (x + y) % 2 == 1 {
                    continue;
                }
                anss.push((x as i32, y as i32));
                for &(dx, dy) in xy.iter() {
                    for xsign in [-1, 1].iter() {
                        let nx = x as i32 + dx as i32 * xsign;
                        let ny = y as i32 + dy;
                        if nx < 0 || nx >= 2 * n as i32 || ny >= 2 * n as i32 {
                            continue;
                        }
                        used[ny as usize][nx as usize] = true;
                    }
                }
                if anss.len() == n * n {
                    break 'y2loop;
                }
            }
        }
    }

    // print_field(n, &anss);
    // println!("{} {}", n * n, anss.len());
    assert!(anss.len() == n * n);
    for i in 0..n * n {
        println!("{} {}", anss[i].0, anss[i].1);
    }
}

