fn construct_graph(
    vertices: &Vec<(usize, usize)>,
    n: usize,
    distance: i64,
    map: &Vec<Vec<usize>>,
) -> Vec<Vec<usize>> {
    let num_v = vertices.len();
    assert_eq!(num_v, 4 * n * n);
    let mut graph = vec![vec![]; num_v];
    for from in 0..num_v {
        let (i, j) = vertices[from];
        let i = i as i64;
        let j = j as i64;
        let n = n as i64;
        for x in 0..(2 * n) {
            let dx = i - x;
            let dy2 = distance - dx * dx;
            if dy2 < 0 {
                continue;
            }
            let dy = (dy2 as f64).sqrt() as i64;
            if dy * dy + dx * dx != distance {
                continue;
            }

            let y1 = dy + j;
            if y1 >= 0 && y1 < 2 * n {
                let to = map[x as usize][y1 as usize];
                graph[from].push(to);
            }

            let y2 = j - dy;
            if y2 >= 0 && y2 < 2 * n {
                let to = map[x as usize][y2 as usize];
                graph[from].push(to);
            }
        }
    }
    graph
