fn color(mut d1: i64, mut d2: i64, mut x: i64, mut y: i64) -> i64 {
    while d1 % 4 == 0 && d2 % 4 == 0 {
        d1 /= 4;
        d2 /= 4;
        x /= 2;
        y /= 2;
    }
    if d1 % 4 != 0 && d2 % 4 != 0 {
        return (x % 2) + 2 * (y % 2);
    }
    let (mut d1, d2) = if d2 % 4 == 0 {
        (d2, d1)
    } else {
        (d1, d2)
    };
    let tmp = match d2 % 4 {
        1 => (x + y) % 2,
        2 => x % 2,
        _ => panic!(),
    };
    while d1 % 4 == 0 {
        d1 /= 4;
        x /= 2;
        y /= 2;
    }
    tmp + 2 * match d1 % 4 {
        1 => (x + y) % 2,
        2 => x % 2,
        _ => panic!(),
    }
}

