        if cnt[k] >= n * n {
            break;
        }
        k += 1;
    }
    let mut count = 0;
    for i in 0..grid_size {
        for j in 0..grid_size {
            if grid[i][j] == k {
                println!("{} {}", i, j);
                count += 1;
                if count == n * n {
                    return;
                }
            }
        }
    }
}

